window.songs=[{"order":1,"id":"01-dedicace","title":"Dédicace","titleZh":"献词","lines":[{"id":"le-petit-prince-2cd-01-001","lineIndex":1,"speaker":"","original":"Je demande pardon aux enfants","ipa":"/ʒə dəmɑ̃d paʁdɔ̃ oz ɑ̃fɑ̃/","zh":"我要请求孩子们原谅","en":"I ask the children to forgive me","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-01-002","lineIndex":2,"speaker":"","original":"D'avoir dédié cette histoire à une grande personne","ipa":"/davwaʁ dedje sɛt istwaʁ a yn ɡʁɑ̃d pɛʁsɔn/","zh":"因为我把这个故事献给了一个大人","en":"For dedicating this story to a grown-up","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-01-003","lineIndex":3,"speaker":"","original":"Mais cette grande personne","ipa":"/mɛ sɛt ɡʁɑ̃d pɛʁsɔn/","zh":"可是这个大人","en":"But this grown-up","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-01-004","lineIndex":4,"speaker":"","original":"Est le meilleur ami que j'ai au monde","ipa":"/ɛ lə mɛjœʁ ami kə ʒe o mɔ̃d/","zh":"是我在世上最好的朋友","en":"is my best friend in the world","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-01-005","lineIndex":5,"speaker":"","original":"J'ai d'autres excuses","ipa":"/ʒe dotʁz ɛkskyz/","zh":"我还有别的理由","en":"I have other reasons","note":"","sourceLineIndex":5},{"id":"le-petit-prince-2cd-01-006","lineIndex":6,"speaker":"","original":"Cette grande personne peut tout comprendre","ipa":"/sɛt ɡʁɑ̃d pɛʁsɔn pø tu kɔ̃pʁɑ̃dʁ/","zh":"这个大人什么都能理解","en":"This grown-up can understand everything","note":"","sourceLineIndex":6},{"id":"le-petit-prince-2cd-01-007","lineIndex":7,"speaker":"","original":"Même les livres pour enfants","ipa":"/mɛm le livʁ puʁ ɑ̃fɑ̃/","zh":"甚至连儿童读物也能理解","en":"Even children's books","note":"","sourceLineIndex":7},{"id":"le-petit-prince-2cd-01-008","lineIndex":8,"speaker":"","original":"De plus elle vit dans un pays","ipa":"/də plyz ɛl vi dɑ̃z œ̃ pɛi/","zh":"此外，这个人住在一个国家","en":"Besides, this person lives in a country","note":"","sourceLineIndex":8},{"id":"le-petit-prince-2cd-01-009","lineIndex":9,"speaker":"","original":"Où je sais qu'elle a faim et froid","ipa":"/u ʒə sɛ kɛl a fɛ̃ e fʁwa/","zh":"我知道她在那里挨饿受冻","en":"Where I know they are hungry and cold","note":"","sourceLineIndex":9},{"id":"le-petit-prince-2cd-01-010","lineIndex":10,"speaker":"","original":"Si vous saviez à quel point","ipa":"/si vu savjez a kɛl pwɛ̃/","zh":"如果你们知道","en":"If only you knew how much","note":"","sourceLineIndex":10},{"id":"le-petit-prince-2cd-01-011","lineIndex":11,"speaker":"","original":"Cette personne a besoin","ipa":"/sɛt pɛʁsɔn a bəzwɛ̃/","zh":"这个人非常需要","en":"This person needs","note":"","sourceLineIndex":11},{"id":"le-petit-prince-2cd-01-012","lineIndex":12,"speaker":"","original":"De se sentir consolée","ipa":"/də sə sɑ̃tiʁ kɔ̃sole/","zh":"得到安慰","en":"to feel comforted","note":"","sourceLineIndex":12},{"id":"le-petit-prince-2cd-01-013","lineIndex":13,"speaker":"","original":"Si je peux avec ces mots","ipa":"/si ʒə pø avɛk se mo/","zh":"如果我能用这些话","en":"If, with these words, I can","note":"","sourceLineIndex":13},{"id":"le-petit-prince-2cd-01-014","lineIndex":14,"speaker":"","original":"Un peu la réconforter","ipa":"/œ̃ pø la ʁekɔ̃fɔʁte/","zh":"稍稍安慰她","en":"Comfort them a little","note":"","sourceLineIndex":14},{"id":"le-petit-prince-2cd-01-015","lineIndex":15,"speaker":"","original":"J'espère que vous comprendrez","ipa":"/ʒɛspɛʁ kə vu kɔ̃pʁɑ̃dʁe/","zh":"我希望你们能够理解","en":"I hope you will understand","note":"","sourceLineIndex":15},{"id":"le-petit-prince-2cd-01-016","lineIndex":16,"speaker":"","original":"Mais si, quoi qu'il en soit","ipa":"/mɛ si kwa kil ɑ̃ swa/","zh":"但如果无论如何","en":"But if, despite all this","note":"","sourceLineIndex":16},{"id":"le-petit-prince-2cd-01-017","lineIndex":17,"speaker":"","original":"Ces excuses ne suffisent pas","ipa":"/sez ɛkskyz nə syfiz pa/","zh":"这些理由仍不够充分","en":"These reasons are not enough","note":"","sourceLineIndex":17},{"id":"le-petit-prince-2cd-01-018","lineIndex":18,"speaker":"","original":"Je dédie cette histoire","ipa":"/ʒə dedi sɛt istwaʁ/","zh":"我要把这个故事献给","en":"I dedicate this story","note":"","sourceLineIndex":18},{"id":"le-petit-prince-2cd-01-019","lineIndex":19,"speaker":"","original":"À l'enfant que cet homme a été","ipa":"/a lɑ̃fɑ̃ kə sɛt ɔm a ete/","zh":"献给这个大人曾经是的那个孩子","en":"To the child this man once was","note":"","sourceLineIndex":19},{"id":"le-petit-prince-2cd-01-020","lineIndex":20,"speaker":"","original":"Toutes les grandes personnes ont d'abord été des enfants","ipa":"/tut le ɡʁɑ̃d pɛʁsɔnz ɔ̃ dabɔʁ ete dez ɑ̃fɑ̃/","zh":"所有大人最初都是孩子","en":"All grown-ups were children first","note":"","sourceLineIndex":20},{"id":"le-petit-prince-2cd-01-021","lineIndex":21,"speaker":"","original":"Toutes les grandes personnes ont d'abord été des enfants","ipa":"/tut le ɡʁɑ̃d pɛʁsɔnz ɔ̃ dabɔʁ ete dez ɑ̃fɑ̃/","zh":"所有大人最初都是孩子","en":"All grown-ups were children first","note":"","sourceLineIndex":21},{"id":"le-petit-prince-2cd-01-022","lineIndex":22,"speaker":"Chœur d'enfants","original":"Toutes les grandes personnes ont d'abord été des enfants","ipa":"/tut le ɡʁɑ̃d pɛʁsɔnz ɔ̃ dabɔʁ ete dez ɑ̃fɑ̃/","zh":"所有大人最初都是孩子","en":"All grown-ups were children first","note":"","sourceLineIndex":22},{"id":"le-petit-prince-2cd-01-023","lineIndex":23,"speaker":"Saint-Exupéry","original":"Toutes les grandes personnes","ipa":"/tut le ɡʁɑ̃d pɛʁsɔn/","zh":"所有的大人","en":"All grown-ups","note":"","sourceLineIndex":23},{"id":"le-petit-prince-2cd-01-024","lineIndex":24,"speaker":"Chœur d'enfants","original":"Toutes les grandes personnes ont d'abord été des enfants","ipa":"/tut le ɡʁɑ̃d pɛʁsɔnz ɔ̃ dabɔʁ ete dez ɑ̃fɑ̃/","zh":"所有大人最初都是孩子","en":"All grown-ups were children first","note":"","sourceLineIndex":24},{"id":"le-petit-prince-2cd-01-025","lineIndex":25,"speaker":"Saint-Exupéry","original":"Ont d'abord été des enfants","ipa":"/ɔ̃ dabɔʁ ete dez ɑ̃fɑ̃/","zh":"最初都是孩子","en":"Were children first","note":"","sourceLineIndex":25},{"id":"le-petit-prince-2cd-01-026","lineIndex":26,"speaker":"Saint-Exupéry","original":"Des enfants","ipa":"/dez ɑ̃fɑ̃/","zh":"小孩","en":"Children","note":"","sourceLineIndex":26},{"id":"le-petit-prince-2cd-01-027","lineIndex":27,"speaker":"Saint-Exupéry","original":"Mais peu d'entre elles s'en souviennent","ipa":"/mɛ pø dɑ̃tʁ ɛl sɑ̃ suvjɛn/","zh":"但是很少有人还记得","en":"But few of them remember it","note":"","sourceLineIndex":27},{"id":"le-petit-prince-2cd-01-028","lineIndex":28,"speaker":"Saint-Exupéry","original":"Peu d'entre elles s'en souviennent","ipa":"/pø dɑ̃tʁ ɛl sɑ̃ suvjɛn/","zh":"很少有人还记得","en":"Few of them remember it","note":"","sourceLineIndex":28}],"sourceOrder":1,"displayOrder":1},{"order":2,"id":"02-accident-d-avion-la-maison-de-l-enfance","title":"Accident D'avion / La Maison De L'enfance","titleZh":"飞机失事/童年之家","lines":[{"id":"le-petit-prince-2cd-02-001","lineIndex":1,"speaker":"L'Aviateur","original":"Moteur esquinté","ipa":"/motœʁ ɛskɛ̃te/","zh":"发动机损坏","en":"Engine damaged","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-02-002","lineIndex":2,"speaker":"L'Aviateur","original":"Avion enlisé en plein désert","ipa":"/avjɔ̃ ɑ̃lize ɑ̃ plɛ̃ dezɛʁ/","zh":"飞机陷在茫茫沙漠中","en":"Plane bogged down in the middle of the desert","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-02-003","lineIndex":3,"speaker":"L'Aviateur","original":"Peut-être à mille milles de toute région habitée.","ipa":"/pøtɛtʁ a mil mil də tut ʁeʒjɔ̃ abite/","zh":"大概离任何有人居住的地方都有一千英里。","en":"Perhaps a thousand miles from any inhabited region.","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-02-004","lineIndex":4,"speaker":"L'Aviateur","original":"30 décembre 1935.","ipa":"/tʁɑ̃t desɑ̃bʁ mil nœfsɑ̃ tʁɑ̃tsɛ̃k/","zh":"1935年12月30日。","en":"December 30, 1935.","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-02-005","lineIndex":5,"speaker":"L'Aviateur","original":"La réparation sera difficile.","ipa":"/la ʁepaʁasjɔ̃ səʁa difisil/","zh":"维修会很困难。","en":"The repair will be difficult.","note":"","sourceLineIndex":5},{"id":"le-petit-prince-2cd-02-006","lineIndex":6,"speaker":"L'Aviateur","original":"De l'eau pour 8 jours.","ipa":"/də lo puʁ yi ʒuʁ/","zh":"足够八天的水。","en":"Enough water for eight days.","note":"","sourceLineIndex":6},{"id":"le-petit-prince-2cd-02-007","lineIndex":7,"speaker":"L'Aviateur","original":"Eh bien, mon petit vieux, t'as voulu être aviateur, tu l'es.","ipa":"/ɛ bjɛ̃ mɔ̃ pəti vjø ta vuly ɛtʁ avjatœʁ ty lɛ/","zh":"好吧，老伙计，你想当飞行员—现在如愿了。","en":"Well, old boy, you wanted to be an aviator—now you are one.","note":"","sourceLineIndex":7},{"id":"le-petit-prince-2cd-02-008","lineIndex":8,"speaker":"L'Aviateur","original":"T'aurais mieux fait de continuer à dessiner des serpents boas.","ipa":"/toʁɛ mjø fɛ də kɔ̃tinye a dɛsine de sɛʁpɑ̃ boa/","zh":"你还不如继续画那些蟒蛇。","en":"You would have been better off continuing to draw boa constrictors.","note":"","sourceLineIndex":8},{"id":"le-petit-prince-2cd-02-009","lineIndex":9,"speaker":"L'Aviateur","original":"Vous savez ce que c'est, ça?","ipa":"/vu save sə kə sɛ sa/","zh":"你们知道这是什么吗？","en":"Do you know what this is?","note":"","sourceLineIndex":9},{"id":"le-petit-prince-2cd-02-010","lineIndex":10,"speaker":"Les Grandes Personnes","original":"Oh… C'est un chapeau.","ipa":"/ɔ sɛt œ̃ ʃapo/","zh":"哦……这是一顶帽子。","en":"Oh… It's a hat.","note":"","sourceLineIndex":10},{"id":"le-petit-prince-2cd-02-011","lineIndex":11,"speaker":"L'Aviateur","original":"Et ça?","ipa":"/e sa/","zh":"那这个呢？","en":"And this?","note":"","sourceLineIndex":11},{"id":"le-petit-prince-2cd-02-012","lineIndex":12,"speaker":"Les Grandes Personnes","original":"Euh…","ipa":"/œ/","zh":"呃……","en":"Um…","note":"","sourceLineIndex":12},{"id":"le-petit-prince-2cd-02-013","lineIndex":13,"speaker":"L'Aviateur","original":"C'est un boa.","ipa":"/sɛt œ̃ boa/","zh":"这是一条蟒蛇。","en":"It's a boa constrictor.","note":"","sourceLineIndex":13},{"id":"le-petit-prince-2cd-02-014","lineIndex":14,"speaker":"Les Grandes Personnes","original":"Ah…","ipa":"/a/","zh":"啊……","en":"Ah…","note":"","sourceLineIndex":14},{"id":"le-petit-prince-2cd-02-015","lineIndex":15,"speaker":"Grande Personne 1","original":"As-tu appris tes leçons de calcul?","ipa":"/aty apʁi te ləsɔ̃ də kalkyl/","zh":"你学过算术课了吗？","en":"Have you learned your arithmetic lessons?","note":"","sourceLineIndex":15},{"id":"le-petit-prince-2cd-02-016","lineIndex":16,"speaker":"Grande Personne 2","original":"Tiens. Où est la Chine, où est le Japon, l'Arizona?…","ipa":"/tjɛ̃ u ɛ la ʃin u ɛ lə ʒapɔ̃ laʁizona/","zh":"说说看，中国在哪里？日本呢？亚利桑那州呢？……","en":"Tell me: where are China, Japan, and Arizona?…","note":"","sourceLineIndex":16},{"id":"le-petit-prince-2cd-02-017","lineIndex":17,"speaker":"Grande Personne 3","original":"Tu ferais mieux de jouer à autre chose, au golf, au bridge…","ipa":"/ty fəʁɛ mjø də ʒwe a otʁ ʃɔz o ɡɔlf o bʁidʒ/","zh":"你最好玩点别的，比如高尔夫、桥牌……","en":"You would be better off playing something else—golf, bridge…","note":"","sourceLineIndex":17},{"id":"le-petit-prince-2cd-02-018","lineIndex":18,"speaker":"Grande Personne 5","original":"C'est un chapeau.","ipa":"/sɛt œ̃ ʃapo/","zh":"这就是一顶帽子。","en":"It's a hat.","note":"","sourceLineIndex":18},{"id":"le-petit-prince-2cd-02-019","lineIndex":19,"speaker":"Grande Personne 6","original":"N'oublie pas d'éteindre ta lampe.","ipa":"/nubli pa detɛ̃dʁ ta lɑ̃p/","zh":"别忘了把灯关掉。","en":"Don't forget to turn off your lamp.","note":"","sourceLineIndex":19},{"id":"le-petit-prince-2cd-02-020","lineIndex":20,"speaker":"Grande Personne 7","original":"On a dit: « Éteins ta lampe. »","ipa":"/ɔ̃n a di etɛ̃ ta lɑ̃p/","zh":"都说了：“把灯关掉。”","en":"We said, “Turn off your lamp.”","note":"","sourceLineIndex":20},{"id":"le-petit-prince-2cd-02-021","lineIndex":21,"speaker":"La Bonne","original":"Mon Dieu, mais quel malheur, cet enfant","ipa":"/mɔ̃ djø mɛ kɛl malœʁ sɛt ɑ̃fɑ̃/","zh":"天哪，这孩子真让人操心","en":"Good Lord, what a worry this child is","note":"","sourceLineIndex":21},{"id":"le-petit-prince-2cd-02-022","lineIndex":22,"speaker":"La Bonne","original":"Tu vas prendre froid, fais attention aux courants d'air et mets ton cache-nez.","ipa":"/ty va pʁɑ̃dʁ fʁwa fɛz atɑ̃sjɔ̃ o kuʁɑ̃ dɛʁ e mɛ tɔ̃ kaʃne/","zh":"你会着凉的，当心穿堂风，把围巾戴上。","en":"You'll catch cold; watch out for drafts and put on your scarf.","note":"","sourceLineIndex":22}],"sourceOrder":2,"displayOrder":2},{"order":3,"id":"03-c-est-un-chapeau","title":"C'est Un Chapeau!","titleZh":"这是一顶帽子！","lines":[{"id":"le-petit-prince-2cd-03-001","lineIndex":1,"speaker":"L'Aviateur","original":"Est-ce que mon dessin vous a fait peur?","ipa":"/ɛs kə mɔ̃ dɛsɛ̃ vuz a fɛ pœʁ/","zh":"我的画吓到你们了吗？","en":"Did my drawing frighten you?","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-03-002","lineIndex":2,"speaker":"Les Grandes Personnes","original":"Pourquoi un chapeau ferait-il peur?","ipa":"/puʁkwa œ̃ ʃapo fəʁɛtil pœʁ/","zh":"一顶帽子怎么会吓人呢？","en":"Why would a hat be frightening?","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-03-003","lineIndex":3,"speaker":"L'Aviateur","original":"Je ne comprends pas, personne ne voit","ipa":"/ʒə nə kɔ̃pʁɑ̃ pa pɛʁsɔn nə vwa/","zh":"我不明白，怎么没有人看见","en":"I don't understand; no one sees","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-03-004","lineIndex":4,"speaker":"L'Aviateur","original":"L'éléphant au fond de ce boa","ipa":"/lelefɑ̃ o fɔ̃ də sə boa/","zh":"这条蟒蛇肚子里的大象","en":"The elephant inside this boa constrictor","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-03-005","lineIndex":5,"speaker":"L'Aviateur","original":"Alors j'ai rangé tous mes crayons","ipa":"/alɔʁ ʒe ʁɑ̃ʒe tu me kʁɛjɔ̃/","zh":"于是我收起了所有铅笔","en":"So I put away all my pencils","note":"","sourceLineIndex":5},{"id":"le-petit-prince-2cd-03-006","lineIndex":6,"speaker":"L'Aviateur","original":"Mes drôles de dessins dans des cartons","ipa":"/me dʁoːl də dɛsɛ̃ dɑ̃ de kaʁtɔ̃/","zh":"把那些古怪的画也装进纸箱","en":"And my funny drawings in boxes","note":"","sourceLineIndex":6},{"id":"le-petit-prince-2cd-03-007","lineIndex":7,"speaker":"L'Aviateur","original":"J'ai trouvé enfin ma vocation","ipa":"/ʒe tʁuve ɑ̃fɛ̃ ma vokasjɔ̃/","zh":"我终于找到了自己的志业","en":"At last I found my calling","note":"","sourceLineIndex":7},{"id":"le-petit-prince-2cd-03-008","lineIndex":8,"speaker":"L'Aviateur","original":"Je suis devenu pilote d'avion","ipa":"/ʒə syi dəvny pilɔt davjɔ̃/","zh":"我成了一名飞行员","en":"I became an airplane pilot","note":"","sourceLineIndex":8},{"id":"le-petit-prince-2cd-03-009","lineIndex":9,"speaker":"L'Aviateur","original":"Les grandes personnes, c'est fatigant","ipa":"/le ɡʁɑ̃d pɛʁsɔn sɛ fatiɡɑ̃/","zh":"大人真让人疲惫","en":"Grown-ups are exhausting","note":"","sourceLineIndex":9},{"id":"le-petit-prince-2cd-03-010","lineIndex":10,"speaker":"L'Aviateur","original":"Elles ne comprennent plus tellement","ipa":"/ɛl nə kɔ̃pʁɛn ply tɛlmɑ̃/","zh":"他们已经不太能理解","en":"They no longer understand very much","note":"","sourceLineIndex":10},{"id":"le-petit-prince-2cd-03-011","lineIndex":11,"speaker":"L'Aviateur","original":"Elles ont besoin d'explications","ipa":"/ɛlz ɔ̃ bəzwɛ̃ dɛksplikasjɔ̃/","zh":"他们总需要别人解释","en":"They need explanations","note":"","sourceLineIndex":11},{"id":"le-petit-prince-2cd-03-012","lineIndex":12,"speaker":"L'Aviateur","original":"Toujours et toujours des explications","ipa":"/tuʒuʁz e tuʒuʁ dez ɛksplikasjɔ̃/","zh":"一遍又一遍地解释","en":"Explanations over and over again","note":"","sourceLineIndex":12},{"id":"le-petit-prince-2cd-03-013","lineIndex":13,"speaker":"L'Aviateur","original":"Depuis, j'ai croisé des tas de gens","ipa":"/dəpyi ʒe kʁwaze de ta də ʒɑ̃/","zh":"从那以后，我遇见过许多人","en":"Since then, I've met a great many people","note":"","sourceLineIndex":13},{"id":"le-petit-prince-2cd-03-014","lineIndex":14,"speaker":"L'Aviateur","original":"Mon avis n'a pas changé vraiment","ipa":"/mɔ̃n avi na pa ʃɑ̃ʒe vʁɛmɑ̃/","zh":"但我的看法始终没有真正改变","en":"My opinion has never really changed","note":"","sourceLineIndex":14},{"id":"le-petit-prince-2cd-03-015","lineIndex":15,"speaker":"L'Aviateur","original":"Je ne parle plus jamais d'étoiles","ipa":"/ʒə nə paʁl ply ʒamɛ detwal/","zh":"我再也不谈星星","en":"I never speak of stars anymore","note":"","sourceLineIndex":15},{"id":"le-petit-prince-2cd-03-016","lineIndex":16,"speaker":"L'Aviateur","original":"De serpents boas, de fleurs tropicales","ipa":"/də sɛʁpɑ̃ boa də flœʁ tʁopikal/","zh":"也不谈蟒蛇和热带花卉","en":"Or boa constrictors and tropical flowers","note":"","sourceLineIndex":16},{"id":"le-petit-prince-2cd-03-017","lineIndex":17,"speaker":"L'Aviateur","original":"J'ai quand même voulu faire l'essai","ipa":"/ʒe kɑ̃ mɛm vuly fɛʁ lesɛ/","zh":"我还是想再试一试","en":"Even so, I wanted to try once more","note":"","sourceLineIndex":17},{"id":"le-petit-prince-2cd-03-018","lineIndex":18,"speaker":"L'Aviateur","original":"De mon dessin à nouveau","ipa":"/də mɔ̃ dɛsɛ̃ a nuvo/","zh":"再拿出我的那幅画","en":"With my drawing again","note":"","sourceLineIndex":18},{"id":"le-petit-prince-2cd-03-019","lineIndex":19,"speaker":"L'Aviateur","original":"Mais les grandes personnes répondaient","ipa":"/mɛ le ɡʁɑ̃d pɛʁsɔn ʁepɔ̃dɛ/","zh":"可大人们总是回答","en":"But the grown-ups would answer","note":"","sourceLineIndex":19},{"id":"le-petit-prince-2cd-03-020","lineIndex":20,"speaker":"L'Aviateur","original":"Toujours et toujours: « C'est un chapeau! »","ipa":"/tuʒuʁz e tuʒuʁ sɛt œ̃ ʃapo/","zh":"一遍又一遍：“这是一顶帽子！”","en":"Over and over again: “It's a hat!”","note":"","sourceLineIndex":20},{"id":"le-petit-prince-2cd-03-021","lineIndex":21,"speaker":"L'Aviateur","original":"Alors je parlais de politique","ipa":"/alɔʁ ʒə paʁlɛ də politik/","zh":"于是我便谈论政治","en":"So I would talk about politics","note":"","sourceLineIndex":21},{"id":"le-petit-prince-2cd-03-022","lineIndex":22,"speaker":"L'Aviateur","original":"De cravates, de golf, de courses hippiques","ipa":"/də kʁavat də ɡɔlf də kuʁs ipik/","zh":"谈领带、高尔夫和赛马","en":"Ties, golf, and horse racing","note":"","sourceLineIndex":22},{"id":"le-petit-prince-2cd-03-023","lineIndex":23,"speaker":"L'Aviateur","original":"Et les grandes personnes se rassuraient","ipa":"/e le ɡʁɑ̃d pɛʁsɔn sə ʁasyʁɛ/","zh":"大人们便放下心来","en":"And the grown-ups would feel reassured","note":"","sourceLineIndex":23},{"id":"le-petit-prince-2cd-03-024","lineIndex":24,"speaker":"L'Aviateur","original":"De connaître un homme aussi sensé","ipa":"/də kɔnɛtʁ œ̃n ɔm osi sɑ̃se/","zh":"庆幸认识了一个如此通情达理的人","en":"To know such a sensible man","note":"","sourceLineIndex":24},{"id":"le-petit-prince-2cd-03-025","lineIndex":25,"speaker":"L'Aviateur","original":"Est-ce que mon dessin vous a fait peur?","ipa":"/ɛs kə mɔ̃ dɛsɛ̃ vuz a fɛ pœʁ/","zh":"我的画吓到你们了吗？","en":"Did my drawing frighten you?","note":"","sourceLineIndex":25},{"id":"le-petit-prince-2cd-03-026","lineIndex":26,"speaker":"Les Grandes Personnes","original":"Pourquoi un chapeau ferait-il peur?","ipa":"/puʁkwa œ̃ ʃapo fəʁɛtil pœʁ/","zh":"一顶帽子怎么会吓人呢？","en":"Why would a hat be frightening?","note":"","sourceLineIndex":26},{"id":"le-petit-prince-2cd-03-027","lineIndex":27,"speaker":"L'Aviateur","original":"Je ne comprends pas, personne ne voit","ipa":"/ʒə nə kɔ̃pʁɑ̃ pa pɛʁsɔn nə vwa/","zh":"我不明白，怎么没有人看见","en":"I don't understand; no one sees","note":"","sourceLineIndex":27},{"id":"le-petit-prince-2cd-03-028","lineIndex":28,"speaker":"L'Aviateur","original":"Au-delà des choses, au-delà de soi","ipa":"/odəla de ʃoz odəla də swa/","zh":"事物表象之外，也超越自我","en":"Beyond outward things, beyond oneself","note":"","sourceLineIndex":28}],"sourceOrder":3,"displayOrder":3},{"order":4,"id":"04-avion-dans-la-nuit-lever-de-soleil-dessine-moi-un-mouton-coucher-de-soleil","title":"Avion Dans La Nuit / Lever De Soleil / Dessine-Moi Un Mouton / Coucher De Soleil","titleZh":"夜航／日出／给我画只绵羊／日落","lines":[{"id":"le-petit-prince-2cd-04-001","lineIndex":1,"speaker":"L'Aviateur","original":"C'est un chapeau","ipa":"/sɛt œ̃ ʃapo/","zh":"这是一顶帽子","en":"It's a hat","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-04-002","lineIndex":2,"speaker":"L'Aviateur","original":"C'est un chapeau","ipa":"/sɛt œ̃ ʃapo/","zh":"这是一顶帽子","en":"It's a hat","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-04-003","lineIndex":3,"speaker":"L'Aviateur","original":"Les grandes personnes","ipa":"/le ɡʁɑ̃d pɛʁsɔn/","zh":"大人们","en":"Grown-ups","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-04-004","lineIndex":4,"speaker":"L'Aviateur","original":"Elles ne comprennent rien toutes seules","ipa":"/ɛl nə kɔ̃pʁɛn ʁiɛ̃ tut sœl/","zh":"他们独自什么也弄不懂","en":"They understand nothing on their own","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-04-005","lineIndex":5,"speaker":"L'Aviateur","original":"Et c'est très fatigant pour les enfants de toujours et toujours leur donner des explications","ipa":"/e sɛ tʁɛ fatiɡɑ̃ puʁ lez ɑ̃fɑ̃ də tuʒuʁz e tuʒuʁ lœʁ dɔne dez ɛksplikasjɔ̃/","zh":"孩子们总得一遍又一遍地向他们解释，实在很累","en":"And it is very tiring for children to have to explain things to them over and over again","note":"","sourceLineIndex":5},{"id":"le-petit-prince-2cd-04-006","lineIndex":6,"speaker":"Le Petit Prince","original":"S'il vous plaît… Dessine-moi un mouton!","ipa":"/sil vu plɛ dɛsinmwa œ̃ mutɔ̃/","zh":"请……给我画一只绵羊！","en":"Please… Draw me a sheep!","note":"","sourceLineIndex":6},{"id":"le-petit-prince-2cd-04-007","lineIndex":7,"speaker":"Le Petit Prince","original":"Dessine-moi un mouton","ipa":"/dɛsinmwa œ̃ mutɔ̃/","zh":"给我画一只绵羊","en":"Draw me a sheep","note":"","sourceLineIndex":7},{"id":"le-petit-prince-2cd-04-008","lineIndex":8,"speaker":"L'Aviateur","original":"Mais… qu'est-ce que tu fais là?","ipa":"/mɛ kɛskə ty fɛ la/","zh":"可是……你在这里做什么？","en":"But… what are you doing here?","note":"","sourceLineIndex":8},{"id":"le-petit-prince-2cd-04-009","lineIndex":9,"speaker":"Le Petit Prince","original":"S'il vous plaît, dessine-moi un mouton","ipa":"/sil vu plɛ dɛsinmwa œ̃ mutɔ̃/","zh":"请给我画一只绵羊","en":"Please draw me a sheep","note":"","sourceLineIndex":9},{"id":"le-petit-prince-2cd-04-010","lineIndex":10,"speaker":"L'Aviateur","original":"Oh! Tu sais","ipa":"/ɔ ty sɛ/","zh":"哦！你知道","en":"Oh! You know","note":"","sourceLineIndex":10},{"id":"le-petit-prince-2cd-04-011","lineIndex":11,"speaker":"L'Aviateur","original":"J'ai surtout étudié la géographie, l'histoire, le calcul","ipa":"/ʒe syʁtu etydje la ʒeɔɡʁafi listwaʁ lə kalkyl/","zh":"我主要学的是地理、历史和算术","en":"I mainly studied geography, history, and arithmetic","note":"","sourceLineIndex":11},{"id":"le-petit-prince-2cd-04-012","lineIndex":12,"speaker":"L'Aviateur","original":"Je ne sais pas dessiner","ipa":"/ʒə nə sɛ pa dɛsine/","zh":"我不会画画","en":"I don't know how to draw","note":"","sourceLineIndex":12},{"id":"le-petit-prince-2cd-04-013","lineIndex":13,"speaker":"Le Petit Prince","original":"Ça ne fait rien. Dessine-moi un mouton","ipa":"/sa nə fɛ ʁjɛ̃ dɛsinmwa œ̃ mutɔ̃/","zh":"没关系。给我画一只绵羊","en":"That doesn't matter. Draw me a sheep","note":"","sourceLineIndex":13},{"id":"le-petit-prince-2cd-04-014","lineIndex":14,"speaker":"L'Aviateur","original":"Écoute! Le seul dessin dont je sois capable, c'est ça","ipa":"/ekut lə sœl dɛsɛ̃ dɔ̃ ʒə swa kapabl sɛ sa/","zh":"听着！我唯一会画的就是这个","en":"Listen! This is the only drawing I can make","note":"","sourceLineIndex":14},{"id":"le-petit-prince-2cd-04-015","lineIndex":15,"speaker":"L'Aviateur","original":"Regarde. Viens, viens","ipa":"/ʁəɡaʁd vjɛ̃ vjɛ̃/","zh":"看。来，过来看看","en":"Look. Come, come here","note":"","sourceLineIndex":15},{"id":"le-petit-prince-2cd-04-016","lineIndex":16,"speaker":"Le Petit Prince","original":"Non, je ne veux pas d'un éléphant dans un boa","ipa":"/nɔ̃ ʒə nə vø pa dœ̃n elefɑ̃ dɑ̃z œ̃ boa/","zh":"不，我不要蟒蛇肚子里的大象","en":"No, I don't want an elephant inside a boa constrictor","note":"","sourceLineIndex":16},{"id":"le-petit-prince-2cd-04-017","lineIndex":17,"speaker":"Le Petit Prince","original":"Un boa, c'est très dangereux","ipa":"/œ̃ boa sɛ tʁɛ dɑ̃ʒʁø/","zh":"蟒蛇非常危险","en":"A boa constrictor is very dangerous","note":"","sourceLineIndex":17},{"id":"le-petit-prince-2cd-04-018","lineIndex":18,"speaker":"Le Petit Prince","original":"Et un éléphant, c'est très encombrant","ipa":"/e œ̃n elefɑ̃ sɛ tʁɛz ɑ̃kɔ̃bʁɑ̃/","zh":"大象又非常占地方","en":"And an elephant takes up far too much room","note":"","sourceLineIndex":18},{"id":"le-petit-prince-2cd-04-019","lineIndex":19,"speaker":"Le Petit Prince","original":"Chez moi, c'est tout petit","ipa":"/ʃe mwa sɛ tu pəti/","zh":"我住的地方很小","en":"Where I live, everything is very small","note":"","sourceLineIndex":19},{"id":"le-petit-prince-2cd-04-020","lineIndex":20,"speaker":"Le Petit Prince","original":"J'ai besoin d'un mouton","ipa":"/ʒe bəzwɛ̃ dœ̃ mutɔ̃/","zh":"我需要一只绵羊","en":"I need a sheep","note":"","sourceLineIndex":20},{"id":"le-petit-prince-2cd-04-021","lineIndex":21,"speaker":"Le Petit Prince","original":"Dessine-moi un mouton","ipa":"/dɛsinmwa œ̃ mutɔ̃/","zh":"给我画一只绵羊","en":"Draw me a sheep","note":"","sourceLineIndex":21},{"id":"le-petit-prince-2cd-04-022","lineIndex":22,"speaker":"Le Petit Prince","original":"Celui-là est déjà très malade","ipa":"/səlyila ɛ deʒa tʁɛ malad/","zh":"这一只已经病得很重了","en":"That one is already very ill","note":"","sourceLineIndex":22},{"id":"le-petit-prince-2cd-04-023","lineIndex":23,"speaker":"Le Petit Prince","original":"Fais-en un autre","ipa":"/fɛzɑ̃n œ̃n otʁ/","zh":"再画一只吧","en":"Draw another one","note":"","sourceLineIndex":23},{"id":"le-petit-prince-2cd-04-024","lineIndex":24,"speaker":"Le Petit Prince","original":"Ce n'est pas un mouton","ipa":"/sə nɛ paz œ̃ mutɔ̃/","zh":"这不是绵羊","en":"That's not a sheep","note":"","sourceLineIndex":24},{"id":"le-petit-prince-2cd-04-025","lineIndex":25,"speaker":"Le Petit Prince","original":"C'est un bélier. Il a des cornes","ipa":"/sɛt œ̃ belje il a de kɔʁn/","zh":"这是只公羊。它长着角","en":"It's a ram. It has horns","note":"","sourceLineIndex":25},{"id":"le-petit-prince-2cd-04-026","lineIndex":26,"speaker":"Le Petit Prince","original":"Oh! Celui-là est trop vieux","ipa":"/ɔ səlyila ɛ tʁo vjø/","zh":"哦！这一只太老了","en":"Oh! That one is too old","note":"","sourceLineIndex":26},{"id":"le-petit-prince-2cd-04-027","lineIndex":27,"speaker":"Le Petit Prince","original":"Je veux un mouton qui vive longtemps","ipa":"/ʒə vøz œ̃ mutɔ̃ ki viv lɔ̃tɑ̃/","zh":"我要一只能活很久的绵羊","en":"I want a sheep that will live a long time","note":"","sourceLineIndex":27},{"id":"le-petit-prince-2cd-04-028","lineIndex":28,"speaker":"L'Aviateur","original":"Ça, c'est la caisse","ipa":"/sa sɛ la kɛs/","zh":"这个是箱子","en":"This is the box","note":"","sourceLineIndex":28},{"id":"le-petit-prince-2cd-04-029","lineIndex":29,"speaker":"L'Aviateur","original":"Le mouton que tu veux est dedans","ipa":"/lə mutɔ̃ kə ty vøz ɛ dədɑ̃/","zh":"你想要的绵羊就在里面","en":"The sheep you want is inside","note":"","sourceLineIndex":29},{"id":"le-petit-prince-2cd-04-030","lineIndex":30,"speaker":"Le Petit Prince","original":"Ah! C'est tout à fait comme ça que je le voulais","ipa":"/a sɛ tut a fɛ kɔm sa kə ʒə lə vulɛ/","zh":"啊！这正是我想要的样子","en":"Ah! This is exactly how I wanted it","note":"","sourceLineIndex":30},{"id":"le-petit-prince-2cd-04-031","lineIndex":31,"speaker":"Le Petit Prince","original":"Mais crois-tu qu'il faille beaucoup d'herbe à ce mouton?","ipa":"/mɛ kʁwaty kil faj boku dɛʁb a sə mutɔ̃/","zh":"你觉得这只绵羊需要很多草吗？","en":"But do you think this sheep will need a lot of grass?","note":"","sourceLineIndex":31},{"id":"le-petit-prince-2cd-04-032","lineIndex":32,"speaker":"L'Aviateur","original":"Pourquoi?","ipa":"/puʁkwa/","zh":"为什么？","en":"Why?","note":"","sourceLineIndex":32},{"id":"le-petit-prince-2cd-04-033","lineIndex":33,"speaker":"Le Petit Prince","original":"Parce que chez moi, c'est tout petit","ipa":"/paʁskə ʃe mwa sɛ tu pəti/","zh":"因为我住的地方很小","en":"Because where I live, everything is very small","note":"","sourceLineIndex":33},{"id":"le-petit-prince-2cd-04-034","lineIndex":34,"speaker":"L'Aviateur","original":"Ça suffira sûrement","ipa":"/sa syfiʁa syʁmɑ̃/","zh":"这些草一定够了","en":"That will surely be enough","note":"","sourceLineIndex":34},{"id":"le-petit-prince-2cd-04-035","lineIndex":35,"speaker":"L'Aviateur","original":"Je t'ai donné un tout petit mouton","ipa":"/ʒə te dɔne œ̃ tu pəti mutɔ̃/","zh":"我给了你一只很小的绵羊","en":"I gave you a very small sheep","note":"","sourceLineIndex":35},{"id":"le-petit-prince-2cd-04-036","lineIndex":36,"speaker":"Le Petit Prince","original":"Pas si petit que ça","ipa":"/pa si pəti kə sa/","zh":"也没有那么小","en":"Not that small","note":"","sourceLineIndex":36},{"id":"le-petit-prince-2cd-04-037","lineIndex":37,"speaker":"Le Petit Prince","original":"Tiens! Il s'est endormi","ipa":"/tjɛ̃ il sɛt ɑ̃dɔʁmi/","zh":"瞧！它睡着了","en":"Look! It has fallen asleep","note":"","sourceLineIndex":37},{"id":"le-petit-prince-2cd-04-038","lineIndex":38,"speaker":"Le Petit Prince","original":"Qu'est-ce que c'est que cette chose-là?","ipa":"/kɛskə sɛ kə sɛt ʃɔzla/","zh":"那个东西是什么？","en":"What is that thing?","note":"","sourceLineIndex":38},{"id":"le-petit-prince-2cd-04-039","lineIndex":39,"speaker":"L'Aviateur","original":"Ça? Mais ce n'est pas une chose","ipa":"/sa mɛ sə nɛ paz yn ʃɔz/","zh":"那个？可它不是什么“东西”","en":"That? But it isn't a thing","note":"","sourceLineIndex":39},{"id":"le-petit-prince-2cd-04-040","lineIndex":40,"speaker":"L'Aviateur","original":"Ça vole. C'est un avion","ipa":"/sa vɔl sɛt œ̃n avjɔ̃/","zh":"它会飞。这是一架飞机","en":"It flies. It's an airplane","note":"","sourceLineIndex":40},{"id":"le-petit-prince-2cd-04-041","lineIndex":41,"speaker":"L'Aviateur","original":"C'est mon avion","ipa":"/sɛ mɔ̃n avjɔ̃/","zh":"这是我的飞机","en":"It's my airplane","note":"","sourceLineIndex":41},{"id":"le-petit-prince-2cd-04-042","lineIndex":42,"speaker":"Le Petit Prince","original":"Comment! Tu es tombé du ciel, toi aussi?","ipa":"/kɔmɑ̃ ty ɛ tɔ̃be dy sjɛl twa osi/","zh":"什么！你也是从天上掉下来的吗？","en":"What! Did you fall from the sky too?","note":"","sourceLineIndex":42},{"id":"le-petit-prince-2cd-04-043","lineIndex":43,"speaker":"L'Aviateur","original":"Mais d'où viens-tu, mon petit bonhomme?","ipa":"/mɛ du vjɛ̃ty mɔ̃ pəti bɔnɔm/","zh":"可是你从哪里来，小家伙？","en":"But where do you come from, little fellow?","note":"","sourceLineIndex":43},{"id":"le-petit-prince-2cd-04-044","lineIndex":44,"speaker":"Le Petit Prince","original":"Ce qui est bien, avec la caisse que tu m'as donnée","ipa":"/sə ki ɛ bjɛ̃ avɛk la kɛs kə ty ma dɔne/","zh":"你给我的这个箱子有个好处","en":"The good thing about the box you gave me","note":"","sourceLineIndex":44},{"id":"le-petit-prince-2cd-04-045","lineIndex":45,"speaker":"Le Petit Prince","original":"C'est que, la nuit, ça lui servira de maison","ipa":"/sɛ kə la nyi sa lyi sɛʁviʁa də mɛzɔ̃/","zh":"就是夜里可以给它当房子","en":"Is that at night it can serve as its house","note":"","sourceLineIndex":45},{"id":"le-petit-prince-2cd-04-046","lineIndex":46,"speaker":"L'Aviateur","original":"Et… et je te donnerai une corde pour l'attacher le jour","ipa":"/e e ʒə tə dɔnʁe yn kɔʁd puʁ lataʃe lə ʒuʁ/","zh":"我还会给你一根绳子，白天把它拴住","en":"And… and I'll give you a rope to tie it up during the day","note":"","sourceLineIndex":46},{"id":"le-petit-prince-2cd-04-047","lineIndex":47,"speaker":"L'Aviateur","original":"Et un piquet","ipa":"/e œ̃ pikɛ/","zh":"再给你一根木桩","en":"And a stake","note":"","sourceLineIndex":47},{"id":"le-petit-prince-2cd-04-048","lineIndex":48,"speaker":"Le Petit Prince","original":"Mais où veux-tu qu'il aille?","ipa":"/mɛz u vøty kil aj/","zh":"可你觉得它能跑到哪里去？","en":"But where do you think it could go?","note":"","sourceLineIndex":48},{"id":"le-petit-prince-2cd-04-049","lineIndex":49,"speaker":"Le Petit Prince","original":"N'importe où. Droit devant lui…","ipa":"/nɛ̃pɔʁt u dʁwa dəvɑ̃ lyi/","zh":"随便哪里。一直往前走……","en":"Anywhere. Straight ahead…","note":"","sourceLineIndex":49}],"sourceOrder":4,"displayOrder":4},{"order":5,"id":"05-droit-devant-soi","title":"Droit Devant Soi","titleZh":"一往无前","lines":[{"id":"le-petit-prince-2cd-05-001","lineIndex":1,"speaker":"Le Petit Prince","original":"Toi aussi, tu viens du ciel?","ipa":"/twa osi ty vjɛ̃ dy sjɛl/","zh":"你也来自天上吗？","en":"Did you come from the sky too?","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-05-002","lineIndex":2,"speaker":"L'Aviateur","original":"Tu viens d'une autre planète?","ipa":"/ty vjɛ̃ dyn otʁ planɛt/","zh":"你来自另一个星球吗？","en":"Do you come from another planet?","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-05-003","lineIndex":3,"speaker":"Le Petit Prince","original":"C'est vrai qu'avec ces drôles d'ailes","ipa":"/sɛ vʁɛ kavɛk se dʁoːl dɛl/","zh":"有这样一对古怪的翅膀","en":"With such funny wings","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-05-004","lineIndex":4,"speaker":"Le Petit Prince","original":"On ne va pas bien loin","ipa":"/ɔ̃ nə va pa bjɛ̃ lwɛ̃/","zh":"的确飞不了多远","en":"You really can't go very far","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-05-005","lineIndex":5,"speaker":"Le Petit Prince","original":"Droit devant soi, on ne peut pas","ipa":"/dʁwa dəvɑ̃ swa ɔ̃ nə pø pa/","zh":"一直朝前走，也不可能","en":"Going straight ahead, you cannot","note":"","sourceLineIndex":5},{"id":"le-petit-prince-2cd-05-006","lineIndex":6,"speaker":"Le Petit Prince","original":"Aller tellement, tellement loin","ipa":"/ale tɛlmɑ̃ tɛlmɑ̃ lwɛ̃/","zh":"走得那么、那么远","en":"Go so very, very far","note":"","sourceLineIndex":6},{"id":"le-petit-prince-2cd-05-007","lineIndex":7,"speaker":"L'Aviateur","original":"Devant moi, je ne sais même pas aller jusqu'à toi","ipa":"/dəvɑ̃ mwa ʒə nə sɛ mɛm paz ale ʒyska twa/","zh":"你就在我前方，我竟连怎样走到你那里都不知道","en":"Though you are right in front of me, I don't even know how to reach you","note":"","sourceLineIndex":7},{"id":"le-petit-prince-2cd-05-008","lineIndex":8,"speaker":"Le Petit Prince","original":"Quelle drôle d'idée d'attacher","ipa":"/kɛl dʁoːl dide dataʃe/","zh":"把我的绵羊","en":"What a funny idea, tying","note":"","sourceLineIndex":8},{"id":"le-petit-prince-2cd-05-009","lineIndex":9,"speaker":"Le Petit Prince","original":"Mon mouton à ton piquet","ipa":"/mɔ̃ mutɔ̃ a tɔ̃ pikɛ/","zh":"拴在你的木桩上","en":"My sheep to your stake","note":"","sourceLineIndex":9},{"id":"le-petit-prince-2cd-05-010","lineIndex":10,"speaker":"L'Aviateur","original":"Mais si tu ne l'attaches pas","ipa":"/mɛ si ty nə lataʃ pa/","zh":"可你要是不拴住它","en":"But if you don't tie it up","note":"","sourceLineIndex":10},{"id":"le-petit-prince-2cd-05-011","lineIndex":11,"speaker":"L'Aviateur","original":"Il ira n'importe où","ipa":"/il iʁa nɛ̃pɔʁt u/","zh":"它会随便跑到什么地方","en":"It will go anywhere","note":"","sourceLineIndex":11},{"id":"le-petit-prince-2cd-05-012","lineIndex":12,"speaker":"Le Petit Prince","original":"Droit devant soi, on ne peut pas","ipa":"/dʁwa dəvɑ̃ swa ɔ̃ nə pø pa/","zh":"一直朝前走，也不可能","en":"Going straight ahead, you cannot","note":"","sourceLineIndex":12},{"id":"le-petit-prince-2cd-05-013","lineIndex":13,"speaker":"Le Petit Prince","original":"Aller tellement, tellement loin","ipa":"/ale tɛlmɑ̃ tɛlmɑ̃ lwɛ̃/","zh":"走得那么、那么远","en":"Go so very, very far","note":"","sourceLineIndex":13},{"id":"le-petit-prince-2cd-05-014","lineIndex":14,"speaker":"L'Aviateur","original":"Devant moi, je ne sais même pas aller jusqu'à toi","ipa":"/dəvɑ̃ mwa ʒə nə sɛ mɛm paz ale ʒyska twa/","zh":"你就在我前方，我竟连怎样走到你那里都不知道","en":"Though you are right in front of me, I don't even know how to reach you","note":"","sourceLineIndex":14},{"id":"le-petit-prince-2cd-05-015","lineIndex":15,"speaker":"Le Petit Prince","original":"Mais où crois-tu qu'il ira?","ipa":"/mɛz u kʁwaty kil iʁa/","zh":"可你觉得它会去哪里？","en":"But where do you think it will go?","note":"","sourceLineIndex":15},{"id":"le-petit-prince-2cd-05-016","lineIndex":16,"speaker":"L'Aviateur","original":"N'importe où, droit devant lui","ipa":"/nɛ̃pɔʁt u dʁwa dəvɑ̃ lyi/","zh":"随便哪里，一直朝前走","en":"Anywhere, straight ahead","note":"","sourceLineIndex":16},{"id":"le-petit-prince-2cd-05-017","lineIndex":17,"speaker":"Le Petit Prince","original":"Jamais il ne se perdra","ipa":"/ʒamɛz il nə sə pɛʁdʁa/","zh":"它永远不会迷路","en":"It will never lose its way","note":"","sourceLineIndex":17},{"id":"le-petit-prince-2cd-05-018","lineIndex":18,"speaker":"Le Petit Prince","original":"C'est si petit chez moi","ipa":"/sɛ si pəti ʃe mwa/","zh":"我的家那么小","en":"My home is so small","note":"","sourceLineIndex":18},{"id":"le-petit-prince-2cd-05-019","lineIndex":19,"speaker":"Le Petit Prince","original":"Droit devant soi, on ne peut pas","ipa":"/dʁwa dəvɑ̃ swa ɔ̃ nə pø pa/","zh":"一直朝前走，也不可能","en":"Going straight ahead, you cannot","note":"","sourceLineIndex":19},{"id":"le-petit-prince-2cd-05-020","lineIndex":20,"speaker":"Le Petit Prince","original":"Aller tellement, tellement loin","ipa":"/ale tɛlmɑ̃ tɛlmɑ̃ lwɛ̃/","zh":"走得那么、那么远","en":"Go so very, very far","note":"","sourceLineIndex":20},{"id":"le-petit-prince-2cd-05-021","lineIndex":21,"speaker":"L'Aviateur","original":"Devant moi, je ne sais même pas","ipa":"/dəvɑ̃ mwa ʒə nə sɛ mɛm pa/","zh":"你就在我前方，我甚至","en":"Though you are right in front of me, I cannot even","note":"","sourceLineIndex":21},{"id":"le-petit-prince-2cd-05-022","lineIndex":22,"speaker":"L'Aviateur","original":"Reconnaître la voie jusqu'à toi","ipa":"/ʁəkɔnɛtʁ la vwa ʒyska twa/","zh":"认出通往你那里的路","en":"Recognize the way that leads to you","note":"","sourceLineIndex":22},{"id":"le-petit-prince-2cd-05-023","lineIndex":23,"speaker":"Le Petit Prince","original":"Droit devant soi","ipa":"/dʁwa dəvɑ̃ swa/","zh":"一直朝前走","en":"Straight ahead","note":"","sourceLineIndex":23},{"id":"le-petit-prince-2cd-05-024","lineIndex":24,"speaker":"Le Petit Prince","original":"Ce chemin ne nous apprend rien","ipa":"/sə ʃəmɛ̃ nə nuz apʁɑ̃ ʁjɛ̃/","zh":"这条路什么也教不会我们","en":"This path teaches us nothing","note":"","sourceLineIndex":24},{"id":"le-petit-prince-2cd-05-025","lineIndex":25,"speaker":"Le Petit Prince","original":"On doit s'égarer pour mieux se trouver","ipa":"/ɔ̃ dwa seɡaʁe puʁ mjø sə tʁuve/","zh":"人得先迷失，才能更好地找到自己","en":"We must lose our way to find ourselves more truly","note":"","sourceLineIndex":25}],"sourceOrder":5,"displayOrder":5},{"order":6,"id":"06-les-grandes-personnes","title":"Les Grandes Personnes","titleZh":"伟大的人","lines":[{"id":"le-petit-prince-2cd-06-001","lineIndex":1,"speaker":"","original":"J'ai trouvé un ami!","ipa":"/ʒe tʁuve œ̃n ami/","zh":"我找到了一个朋友！","en":"I've found a friend!","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-06-002","lineIndex":2,"speaker":"","original":"Il vient d'une autre planète","ipa":"/il vjɛ̃ dyn otʁ planɛt/","zh":"他来自另一个星球","en":"He comes from another planet","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-06-003","lineIndex":3,"speaker":"","original":"Quel âge a-t-il? Combien a-t-il de frères? Combien pèse-t-il? Combien gagne son père?","ipa":"/kɛl aːʒ atil kɔ̃bjɛ̃ atil də fʁɛʁ kɔ̃bjɛ̃ pɛztil kɔ̃bjɛ̃ ɡaɲ sɔ̃ pɛʁ/","zh":"他多大？有几个兄弟？体重多少？他父亲挣多少钱？","en":"How old is he? How many brothers does he have? How much does he weigh? How much does his father earn?","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-06-004","lineIndex":4,"speaker":"","original":"Mais pourquoi ne me demandez-vous pas","ipa":"/mɛ puʁkwa nə mə dəmɑ̃devu pa/","zh":"可你们为什么不问我","en":"But why don't you ask me","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-06-005","lineIndex":5,"speaker":"","original":"Quel est le son de sa voix?","ipa":"/kɛl ɛ lə sɔ̃ də sa vwa/","zh":"他的声音是什么样的？","en":"What does his voice sound like?","note":"","sourceLineIndex":5},{"id":"le-petit-prince-2cd-06-006","lineIndex":6,"speaker":"","original":"Quels sont ses jeux préférés?","ipa":"/kɛl sɔ̃ se ʒø pʁefeʁe/","zh":"他最喜欢什么游戏？","en":"What are his favorite games?","note":"","sourceLineIndex":6},{"id":"le-petit-prince-2cd-06-007","lineIndex":7,"speaker":"","original":"S'il collectionne les papillons?","ipa":"/sil kɔlɛktjɔn le papijɔ̃/","zh":"他是否收集蝴蝶？","en":"Whether he collects butterflies?","note":"","sourceLineIndex":7},{"id":"le-petit-prince-2cd-06-008","lineIndex":8,"speaker":"","original":"Qu'est-ce que ça veut dire?","ipa":"/kɛskə sa vø diʁ/","zh":"这是什么意思？","en":"What does that mean?","note":"","sourceLineIndex":8},{"id":"le-petit-prince-2cd-06-009","lineIndex":9,"speaker":"","original":"Où habite-t-il?","ipa":"/u abittil/","zh":"他住在哪里？","en":"Where does he live?","note":"","sourceLineIndex":9},{"id":"le-petit-prince-2cd-06-010","lineIndex":10,"speaker":"","original":"Une petite planète avec deux volcans en activité","ipa":"/yn pətit planɛt avɛk dø vɔlkɑ̃z ɑ̃n aktivite/","zh":"一个小小的星球，上面有两座活火山","en":"A small planet with two active volcanoes","note":"","sourceLineIndex":10},{"id":"le-petit-prince-2cd-06-011","lineIndex":11,"speaker":"","original":"Qu'il faut ramoner soigneusement","ipa":"/kil fo ʁamone swanjøzmɑ̃/","zh":"必须仔细地清扫它们","en":"Which must be swept out carefully","note":"","sourceLineIndex":11},{"id":"le-petit-prince-2cd-06-012","lineIndex":12,"speaker":"","original":"Parce que c'est commode pour réchauffer le petit déjeuner le matin","ipa":"/paʁskə sɛ kɔmɔd puʁ ʁeʃofe lə pəti deʒøne lə matɛ̃/","zh":"因为早晨用它们热早餐很方便","en":"Because they are handy for heating breakfast in the morning","note":"","sourceLineIndex":12},{"id":"le-petit-prince-2cd-06-013","lineIndex":13,"speaker":"","original":"Et un volcan éteint qu'il faut ramoner aussi","ipa":"/e œ̃ vɔlkɑ̃ etɛ̃ kil fo ʁamone osi/","zh":"还有一座死火山，也必须清扫","en":"And an extinct volcano that must be swept out too","note":"","sourceLineIndex":13},{"id":"le-petit-prince-2cd-06-014","lineIndex":14,"speaker":"","original":"On ne sait jamais","ipa":"/ɔ̃ nə sɛ ʒamɛ/","zh":"谁也说不准","en":"You never know","note":"","sourceLineIndex":14},{"id":"le-petit-prince-2cd-06-015","lineIndex":15,"speaker":"","original":"On ne sait jamais","ipa":"/ɔ̃ nə sɛ ʒamɛ/","zh":"谁也说不准","en":"You never know","note":"","sourceLineIndex":15},{"id":"le-petit-prince-2cd-06-016","lineIndex":16,"speaker":"","original":"On ne sait jamais","ipa":"/ɔ̃ nə sɛ ʒamɛ/","zh":"谁也说不准","en":"You never know","note":"","sourceLineIndex":16},{"id":"le-petit-prince-2cd-06-017","lineIndex":17,"speaker":"","original":"C'est pour éviter les éruptions volcaniques","ipa":"/sɛ puʁ evite lez eʁypsjɔ̃ vɔlkanik/","zh":"这样是为了避免火山喷发","en":"It is to prevent volcanic eruptions","note":"","sourceLineIndex":17},{"id":"le-petit-prince-2cd-06-018","lineIndex":18,"speaker":"","original":"Qui sont quelque chose comme les feux de cheminée","ipa":"/ki sɔ̃ kɛlkə ʃɔz kɔm le fø də ʃəmine/","zh":"火山喷发有点像烟囱失火","en":"Which are rather like chimney fires","note":"","sourceLineIndex":18},{"id":"le-petit-prince-2cd-06-019","lineIndex":19,"speaker":"","original":"Qu'est-ce que tu es encore allé inventer?","ipa":"/kɛskə ty ɛz ɑ̃kɔʁ ale ɛ̃vɑ̃te/","zh":"你又编出了什么东西？","en":"What have you gone and made up now?","note":"","sourceLineIndex":19},{"id":"le-petit-prince-2cd-06-020","lineIndex":20,"speaker":"","original":"Sur Terre, les grandes personnes sont trop petites pour ramoner leurs volcans","ipa":"/syʁ tɛʁ le ɡʁɑ̃d pɛʁsɔn sɔ̃ tʁo pətit puʁ ʁamone lœʁ vɔlkɑ̃/","zh":"在地球上，大人们太渺小，没法清扫他们的火山","en":"On Earth, grown-ups are too small to sweep out their volcanoes","note":"","sourceLineIndex":20},{"id":"le-petit-prince-2cd-06-021","lineIndex":21,"speaker":"","original":"C'est pourquoi ils leur causent des tas d'ennuis","ipa":"/sɛ puʁkwa il lœʁ koz de ta dɑ̃nyi/","zh":"所以火山给他们惹出一大堆麻烦","en":"That is why the volcanoes cause them all sorts of trouble","note":"","sourceLineIndex":21},{"id":"le-petit-prince-2cd-06-022","lineIndex":22,"speaker":"","original":"Aujourd'hui, troisième jour dans le désert","ipa":"/oʒuʁdyi tʁwazjɛm ʒuʁ dɑ̃ lə dezɛʁ/","zh":"今天，我在沙漠里的第三天","en":"Today, my third day in the desert","note":"","sourceLineIndex":22},{"id":"le-petit-prince-2cd-06-023","lineIndex":23,"speaker":"","original":"La preuve que le Petit Prince a existé","ipa":"/la pʁøv kə lə pəti pʁɛ̃s a ɛɡziste/","zh":"小王子确实存在过的证据","en":"The proof that the Little Prince existed","note":"","sourceLineIndex":23},{"id":"le-petit-prince-2cd-06-024","lineIndex":24,"speaker":"","original":"C'est qu'il était ravissant, qu'il riait et qu'il voulait un mouton","ipa":"/sɛ kil etɛ ʁavisɑ̃ kil ʁiɛt e kil vulɛt œ̃ mutɔ̃/","zh":"就是他那么可爱，会笑，还想要一只绵羊","en":"Is that he was delightful, that he laughed, and that he wanted a sheep","note":"","sourceLineIndex":24},{"id":"le-petit-prince-2cd-06-025","lineIndex":25,"speaker":"","original":"Quand on veut un mouton, c'est la preuve qu'on existe","ipa":"/kɑ̃t ɔ̃ vøt œ̃ mutɔ̃ sɛ la pʁøv kɔ̃n ɛɡzist/","zh":"想要一只绵羊，就证明一个人确实存在","en":"When someone wants a sheep, it proves that they exist","note":"","sourceLineIndex":25},{"id":"le-petit-prince-2cd-06-026","lineIndex":26,"speaker":"","original":"Et la planète d'où il venait est l'astéroïde B612","ipa":"/e la planɛt du il vənɛt ɛ lasteʁɔid be sisɑ̃ duz/","zh":"而他来自的星球就是 B612 号小行星","en":"And the planet he came from is asteroid B612","note":"","sourceLineIndex":26},{"id":"le-petit-prince-2cd-06-027","lineIndex":27,"speaker":"","original":"Mais... C'est... C'est...","ipa":"/mɛ sɛ sɛ/","zh":"可是……这……这……","en":"But... It's... It's...","note":"","sourceLineIndex":27},{"id":"le-petit-prince-2cd-06-028","lineIndex":28,"speaker":"","original":"Chut... Les enfants doivent être indulgents envers les grandes personnes","ipa":"/ʃy lez ɑ̃fɑ̃ dwavt ɛtʁ ɛ̃dylʒz ɑ̃vɛʁ le ɡʁɑ̃d pɛʁsɔn/","zh":"嘘……孩子们应该宽容大人","en":"Shh... Children must be forgiving toward grown-ups","note":"","sourceLineIndex":28}],"sourceOrder":6,"displayOrder":6},{"order":7,"id":"07-les-grandes-personnes-sont-comme-ca","title":"Les Grandes Personnes Sont Comme ÇA","titleZh":"成年人即如此","lines":[{"id":"le-petit-prince-2cd-07-001","lineIndex":1,"speaker":"","original":"J'ai de sérieuses raisons de croire","ipa":"/ʒe də seʁjøz ʁɛzɔ̃ də kʁwaʁ/","zh":"我有充分的理由相信","en":"I have serious reasons to believe","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-07-002","lineIndex":2,"speaker":"","original":"Que la planète du Petit Prince est","ipa":"/kə la planɛt dy pəti pʁɛ̃s ɛ/","zh":"小王子的星球就是","en":"That the Little Prince's planet is","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-07-003","lineIndex":3,"speaker":"","original":"L'astéroïde B612","ipa":"/lasteʁɔid be sisɑ̃ duz/","zh":"B612 号小行星","en":"Asteroid B612","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-07-004","lineIndex":4,"speaker":"","original":"Cet astre n'a été aperçu","ipa":"/sɛt astʁ na ete apɛʁsy/","zh":"这颗天体只被观测到","en":"This celestial body was sighted","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-07-005","lineIndex":5,"speaker":"","original":"Qu'une seule fois, en 1909","ipa":"/kyn sœl fwa ɑ̃ mil nœfsɑ̃ nœf/","zh":"仅仅一次，那是在 1909 年","en":"Only once, in 1909","note":"","sourceLineIndex":5},{"id":"le-petit-prince-2cd-07-006","lineIndex":6,"speaker":"","original":"Par un astronome turc","ipa":"/paʁ œ̃n astʁonom tyʁk/","zh":"观测者是一位土耳其天文学家","en":"By a Turkish astronomer","note":"","sourceLineIndex":6},{"id":"le-petit-prince-2cd-07-007","lineIndex":7,"speaker":"","original":"Il avait alors démontré sa découverte à un congrès","ipa":"/il avɛt alɔʁ demɔ̃tʁe sa dekuvɛʁt a œ̃ kɔ̃ɡʁɛ/","zh":"当时他曾在一次大会上展示自己的发现","en":"He had presented his discovery at a conference","note":"","sourceLineIndex":7},{"id":"le-petit-prince-2cd-07-008","lineIndex":8,"speaker":"","original":"Mais personne ne l'avait jamais cru","ipa":"/mɛ pɛʁsɔn nə lavɛ ʒamɛ kʁy/","zh":"可是从来没有人相信他","en":"But no one had ever believed him","note":"","sourceLineIndex":8},{"id":"le-petit-prince-2cd-07-009","lineIndex":9,"speaker":"","original":"À cause de son costume","ipa":"/a koz də sɔ̃ kɔstym/","zh":"就因为他的服装","en":"Because of his clothes","note":"","sourceLineIndex":9},{"id":"le-petit-prince-2cd-07-010","lineIndex":10,"speaker":"","original":"Les grandes personnes sont comme ça","ipa":"/le ɡʁɑ̃d pɛʁsɔn sɔ̃ kɔm sa/","zh":"大人们就是这样","en":"Grown-ups are like that","note":"","sourceLineIndex":10},{"id":"le-petit-prince-2cd-07-011","lineIndex":11,"speaker":"","original":"Elles ne savent pas","ipa":"/ɛl nə sav pa/","zh":"他们就是不明白","en":"They just don't understand","note":"","sourceLineIndex":11},{"id":"le-petit-prince-2cd-07-012","lineIndex":12,"speaker":"","original":"Un dictateur turc imposa","ipa":"/œ̃ diktatœʁ tyʁk ɛ̃poza/","zh":"一位土耳其独裁者强令","en":"A Turkish dictator ordered","note":"","sourceLineIndex":12},{"id":"le-petit-prince-2cd-07-013","lineIndex":13,"speaker":"","original":"À son peuple, en 1920, de","ipa":"/a sɔ̃ pøpl ɑ̃ mil nœfsɑ̃ vɛ̃ də/","zh":"他的人民在 1920 年","en":"His people, in 1920, to","note":"","sourceLineIndex":13},{"id":"le-petit-prince-2cd-07-014","lineIndex":14,"speaker":"","original":"S'habiller à l'européenne","ipa":"/sabije a løʁopeɛn/","zh":"改穿欧洲式服装","en":"Dress in European clothes","note":"","sourceLineIndex":14},{"id":"le-petit-prince-2cd-07-015","lineIndex":15,"speaker":"","original":"Alors l'astronome put refaire","ipa":"/alɔʁ lastʁonom py ʁəfɛʁ/","zh":"于是那位天文学家得以","en":"Then the astronomer was able to give","note":"","sourceLineIndex":15},{"id":"le-petit-prince-2cd-07-016","lineIndex":16,"speaker":"","original":"Sa démonstration magistrale dans","ipa":"/sa demɔ̃stʁasjɔ̃ maʒistʁal dɑ̃/","zh":"身穿一套","en":"His masterful demonstration again, in","note":"","sourceLineIndex":16},{"id":"le-petit-prince-2cd-07-017","lineIndex":17,"speaker":"","original":"Un habit très élégant","ipa":"/œ̃n abi tʁɛz eleɡɑ̃/","zh":"非常优雅的服装，再次作出精彩论证","en":"A very elegant suit","note":"","sourceLineIndex":17},{"id":"le-petit-prince-2cd-07-018","lineIndex":18,"speaker":"","original":"Et cette fois-ci, évidemment","ipa":"/e sɛt fwasi evidamɑ̃/","zh":"而这一次，当然","en":"And this time, of course","note":"","sourceLineIndex":18},{"id":"le-petit-prince-2cd-07-019","lineIndex":19,"speaker":"","original":"Tout le monde fut de son avis","ipa":"/tulmɔ̃d fy də sɔ̃ avi/","zh":"所有人都赞同他","en":"Everyone agreed with him","note":"","sourceLineIndex":19},{"id":"le-petit-prince-2cd-07-020","lineIndex":20,"speaker":"","original":"Rien n'avait pourtant changé chez lui","ipa":"/ʁiɛ̃ navɛ puʁtɑ̃ ʃɑ̃ʒe ʃe lyi/","zh":"然而他本人什么也没有改变","en":"Yet nothing about him had changed","note":"","sourceLineIndex":20},{"id":"le-petit-prince-2cd-07-021","lineIndex":21,"speaker":"","original":"Excepté son costume","ipa":"/ɛksɛpte sɔ̃ kɔstym/","zh":"除了他的服装","en":"Except for his clothes","note":"","sourceLineIndex":21},{"id":"le-petit-prince-2cd-07-022","lineIndex":22,"speaker":"","original":"Les grandes personnes sont comme ça","ipa":"/le ɡʁɑ̃d pɛʁsɔn sɔ̃ kɔm sa/","zh":"大人们就是这样","en":"Grown-ups are like that","note":"","sourceLineIndex":22},{"id":"le-petit-prince-2cd-07-023","lineIndex":23,"speaker":"","original":"Elles ne veulent croire que ce qu'elles voient","ipa":"/ɛl nə vœl kʁwaʁ kə sə kɛl vwa/","zh":"他们只愿意相信亲眼看见的东西","en":"They only want to believe what they can see","note":"","sourceLineIndex":23},{"id":"le-petit-prince-2cd-07-024","lineIndex":24,"speaker":"","original":"Elles sont comme ça","ipa":"/ɛl sɔ̃ kɔm sa/","zh":"他们就是这样","en":"That's how they are","note":"","sourceLineIndex":24},{"id":"le-petit-prince-2cd-07-025","lineIndex":25,"speaker":"","original":"Elles sont comme ça","ipa":"/ɛl sɔ̃ kɔm sa/","zh":"他们就是这样","en":"That's how they are","note":"","sourceLineIndex":25}],"sourceOrder":7,"displayOrder":7},{"order":8,"id":"08-lever-de-soleil-le-drame-des-baobas","title":"Lever De Soleil / Le Drame Des Baobas","titleZh":"日出/猴面包树的戏剧","lines":[{"id":"le-petit-prince-2cd-08-001","lineIndex":1,"speaker":"","original":"C'est bien vrai que les moutons mangent les arbustes?","ipa":"/sɛ bjɛ̃ vʁɛ kə le mutɔ̃ mɑ̃ʒ lez aʁbyst/","zh":"绵羊确实吃灌木吗？","en":"Is it really true that sheep eat shrubs?","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-08-002","lineIndex":2,"speaker":"","original":"Oui. C'est vrai.","ipa":"/wi sɛ vʁɛ/","zh":"对，是真的。","en":"Yes. It's true.","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-08-003","lineIndex":3,"speaker":"","original":"Par conséquent, ils mangent aussi les baobabs?","ipa":"/paʁ kɔ̃sekɑ̃ il mɑ̃ʒt osi le baobab/","zh":"那么，它们也吃猴面包树吗？","en":"Then do they eat baobabs too?","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-08-004","lineIndex":4,"speaker":"","original":"Oh, tu sais, les baobabs ne sont pas des arbustes","ipa":"/ɔ ty sɛ le baobab nə sɔ̃ pa dez aʁbyst/","zh":"噢，你知道，猴面包树可不是灌木","en":"Oh, you know, baobabs are not shrubs","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-08-005","lineIndex":5,"speaker":"","original":"Mais des arbres grands comme des églises","ipa":"/mɛ dez aʁbʁ ɡʁɑ̃ kɔm dez eɡliz/","zh":"而是像教堂那么高大的树","en":"But trees as large as churches","note":"","sourceLineIndex":5},{"id":"le-petit-prince-2cd-08-006","lineIndex":6,"speaker":"","original":"Et même si tu emportais avec toi tout un troupeau d'éléphants","ipa":"/e mɛm si ty ɑ̃pɔʁtɛ avɛk twa tut œ̃ tʁupo delefɑ̃/","zh":"即使你带上一整群大象","en":"And even if you took a whole herd of elephants with you","note":"","sourceLineIndex":6},{"id":"le-petit-prince-2cd-08-007","lineIndex":7,"speaker":"","original":"Ce troupeau ne viendrait pas à bout d'un seul baobab","ipa":"/sə tʁupo nə vjɛ̃dʁɛ paz a bu dœ̃ sœl baobab/","zh":"那群大象也对付不了一棵猴面包树","en":"That herd would not be able to finish off even one baobab","note":"","sourceLineIndex":7},{"id":"le-petit-prince-2cd-08-008","lineIndex":8,"speaker":"","original":"Les baobabs, avant de grandir, commencent par être petits, non?","ipa":"/le baobab avɑ̃ də ɡʁɑ̃diʁ kɔmɑ̃s paʁ ɛtʁ pəti nɔ̃/","zh":"猴面包树在长大以前，先是小小的，对吗？","en":"Before baobabs grow large, they start out small, don't they?","note":"","sourceLineIndex":8},{"id":"le-petit-prince-2cd-08-009","lineIndex":9,"speaker":"","original":"Ah","ipa":"/a/","zh":"啊。","en":"Ah.","note":"","sourceLineIndex":9},{"id":"le-petit-prince-2cd-08-010","lineIndex":10,"speaker":"","original":"Donc, les moutons mangeront les petits baobabs","ipa":"/dɔ̃k le mutɔ̃ mɑ̃ʒʁɔ̃ le pəti baobab/","zh":"那绵羊会吃掉小猴面包树","en":"So sheep will eat the young baobabs","note":"","sourceLineIndex":10},{"id":"le-petit-prince-2cd-08-011","lineIndex":11,"speaker":"","original":"Mais pourquoi veux-tu que les moutons mangent les petits baobabs?","ipa":"/mɛ puʁkwa vøty kə le mutɔ̃ mɑ̃ʒ le pəti baobab/","zh":"可你为什么要让绵羊吃小猴面包树？","en":"But why do you want sheep to eat the young baobabs?","note":"","sourceLineIndex":11},{"id":"le-petit-prince-2cd-08-012","lineIndex":12,"speaker":"","original":"Ben! Voyons!","ipa":"/bɛn vwajɔ̃/","zh":"哎呀！当然啦！","en":"Well, of course!","note":"","sourceLineIndex":12},{"id":"le-petit-prince-2cd-08-013","lineIndex":13,"speaker":"","original":"Parce que si on laisse pousser les petits baobabs sur ma petite planète","ipa":"/paʁskə si ɔ̃ lɛs puse le pəti baobab syʁ ma pətit planɛt/","zh":"因为要是任由小猴面包树在我的小星球上生长","en":"Because if we let the young baobabs grow on my little planet","note":"","sourceLineIndex":13},{"id":"le-petit-prince-2cd-08-014","lineIndex":14,"speaker":"","original":"ils seront trop nombreux et ils la feront éclater","ipa":"/il səʁɔ̃ tʁo nɔ̃bʁøz e il la fəʁɔ̃t eklate/","zh":"它们就会多得把星球撑裂","en":"They will become too numerous and make it burst","note":"","sourceLineIndex":14},{"id":"le-petit-prince-2cd-08-015","lineIndex":15,"speaker":"","original":"C'est terrible, le drame des baobabs","ipa":"/sɛ tɛʁibl lə dʁam de baobab/","zh":"猴面包树的灾难太可怕了","en":"The baobab disaster is terrible","note":"","sourceLineIndex":15},{"id":"le-petit-prince-2cd-08-016","lineIndex":16,"speaker":"","original":"Fais un dessin pour prévenir les enfants de ta planète","ipa":"/fɛz œ̃ dɛsɛ̃ puʁ pʁevniʁ lez ɑ̃fɑ̃ də ta planɛt/","zh":"画一幅画，提醒你星球上的孩子们提高警惕","en":"Make a drawing to warn the children on your planet","note":"","sourceLineIndex":16}],"sourceOrder":8,"displayOrder":8},{"order":9,"id":"09-les-baobabs","title":"Les Baobabs","titleZh":"猴面包树","lines":[{"id":"le-petit-prince-2cd-09-001","lineIndex":1,"speaker":"Le Petit Prince","original":"On ne sait jamais les dangers qui nous guettent","ipa":"/ɔ̃ nə sɛ ʒamɛ le dɑ̃ʒe ki nu ɡɛt/","zh":"我们永远不知道会有什么危险在等着我们","en":"You never know what dangers may be lying in wait for us","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-09-002","lineIndex":2,"speaker":"Le Petit Prince","original":"Là sous nos pieds par-dessus nos têtes","ipa":"/la su no pje paʁdəsy no tɛt/","zh":"就在我们脚下、头顶上","en":"There, beneath our feet and above our heads","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-09-003","lineIndex":3,"speaker":"L'Aviateur","original":"Ces petites graines qui nous sont invisibles","ipa":"/se pətit ɡʁɛn ki nu sɔ̃t ɛ̃vizibl/","zh":"这些我们看不见的小种子","en":"These little seeds that are invisible to us","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-09-004","lineIndex":4,"speaker":"L'Aviateur","original":"Quelques brindilles qui deviennent terribles","ipa":"/kɛlkə bʁɛ̃dij ki dəvjɛn tɛʁibl/","zh":"几根会变得可怕的小枝条","en":"A few little shoots that become terrible","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-09-005","lineIndex":5,"speaker":"Le Petit Prince","original":"Elles sommeillent dans le secret de la terre","ipa":"/ɛl sɔmɛj dɑ̃ lə səkʁɛ də la tɛʁ/","zh":"它们沉睡在大地隐秘的深处","en":"They lie dormant in the secret depths of the earth","note":"","sourceLineIndex":5},{"id":"le-petit-prince-2cd-09-006","lineIndex":6,"speaker":"Le Petit Prince","original":"Jusqu'au jour où elles s'ouvrent à la lumière","ipa":"/ʒysko ʒuʁ u ɛl suvʁt a la lymjɛʁ/","zh":"直到有一天破土向着光亮张开","en":"Until the day they open themselves to the light","note":"","sourceLineIndex":6},{"id":"le-petit-prince-2cd-09-007","lineIndex":7,"speaker":"L'Aviateur","original":"Il faut faire vite avant que ne s'installent","ipa":"/il fo fɛʁ vit avɑ̃ kə nə sɛ̃stal/","zh":"必须趁它们扎根之前赶快行动","en":"We must act quickly before they take root","note":"","sourceLineIndex":7},{"id":"le-petit-prince-2cd-09-008","lineIndex":8,"speaker":"L'Aviateur","original":"Sur nos planètes les racines du mal","ipa":"/syʁ no planɛt le ʁasin dy mal/","zh":"趁恶的根须在我们的星球上扎根之前","en":"The roots of evil on our planets","note":"","sourceLineIndex":8},{"id":"le-petit-prince-2cd-09-009","lineIndex":9,"speaker":"L'Aviateur","original":"On ne voit jamais les dangers qui reviennent","ipa":"/ɔ̃ nə vwa ʒamɛ le dɑ̃ʒe ki ʁəvjɛn/","zh":"人们从来看不见再度逼近的危险","en":"We never see the dangers that come back","note":"","sourceLineIndex":9},{"id":"le-petit-prince-2cd-09-010","lineIndex":10,"speaker":"L'Aviateur","original":"La mauvaise herbe pour la mauvaise graine","ipa":"/la movɛz ɛʁb puʁ la movɛz ɡʁɛn/","zh":"坏种子长成的恶草","en":"The bad weed from the bad seed","note":"","sourceLineIndex":10},{"id":"le-petit-prince-2cd-09-011","lineIndex":11,"speaker":"Le Petit Prince","original":"Comme on doit faire le matin sa toilette","ipa":"/kɔm ɔ̃ dwa fɛʁ lə matɛ̃ sa twalɛt/","zh":"正如每天早晨都得洗漱","en":"Just as one must wash and groom oneself in the morning","note":"","sourceLineIndex":11},{"id":"le-petit-prince-2cd-09-012","lineIndex":12,"speaker":"Le Petit Prince","original":"On doit prendre soin de sa planète","ipa":"/ɔ̃ dwa pʁɑ̃dʁ swɛ̃ də sa planɛt/","zh":"我们也必须照料好自己的星球","en":"We must take care of our planet","note":"","sourceLineIndex":12},{"id":"le-petit-prince-2cd-09-013","lineIndex":13,"speaker":"Le Petit Prince","original":"Il ne faut pas la laisser s'encombrer","ipa":"/il nə fo pa la lɛse sɑ̃kɔ̃bʁe/","zh":"不能任由它变得杂乱、长满东西","en":"We must not let it become overgrown","note":"","sourceLineIndex":13},{"id":"le-petit-prince-2cd-09-014","lineIndex":14,"speaker":"Le Petit Prince","original":"Sinon elle va finir par éclater","ipa":"/sinɔ̃ ɛl va finiʁ paʁ eklate/","zh":"否则它终会爆裂","en":"Otherwise it will end up bursting","note":"","sourceLineIndex":14},{"id":"le-petit-prince-2cd-09-015","lineIndex":15,"speaker":"L'Aviateur","original":"Enfants je n'aime pas vous faire la morale","ipa":"/ɑ̃fɑ̃ ʒə nɛm pa vu fɛʁ la moʁal/","zh":"孩子们，我不喜欢对你们说教","en":"Children, I don't like lecturing you","note":"","sourceLineIndex":15},{"id":"le-petit-prince-2cd-09-016","lineIndex":16,"speaker":"L'Aviateur","original":"Mais avec ces arbres l'erreur est fatale","ipa":"/mɛ avɛk sez aʁbʁ lɛʁœʁ ɛ fatal/","zh":"但面对这些树，一次失误便会致命","en":"But with these trees, a mistake is fatal","note":"","sourceLineIndex":16},{"id":"le-petit-prince-2cd-09-017","lineIndex":17,"speaker":"Ensemble","original":"Faites attention aux baobabs","ipa":"/fɛtz atɑ̃sjɔ̃ o baobab/","zh":"当心猴面包树","en":"Watch out for the baobabs","note":"","sourceLineIndex":17},{"id":"le-petit-prince-2cd-09-018","lineIndex":18,"speaker":"Ensemble","original":"Ils envahissent la planète","ipa":"/ilz ɑ̃vais la planɛt/","zh":"它们侵占整颗星球","en":"They invade the planet","note":"","sourceLineIndex":18},{"id":"le-petit-prince-2cd-09-019","lineIndex":19,"speaker":"Ensemble","original":"Ils l'étouffent, ils la déchiquettent","ipa":"/il letuf il la deʃikɛt/","zh":"它们令星球窒息，把它撕得粉碎","en":"They suffocate it; they tear it to pieces","note":"","sourceLineIndex":19},{"id":"le-petit-prince-2cd-09-020","lineIndex":20,"speaker":"Ensemble","original":"Il faut les surveiller","ipa":"/il fo le syʁvɛje/","zh":"必须时刻留意它们","en":"We must keep an eye on them","note":"","sourceLineIndex":20},{"id":"le-petit-prince-2cd-09-021","lineIndex":21,"speaker":"Ensemble","original":"Il faut les arracher","ipa":"/il fo lez aʁaʃe/","zh":"必须把它们连根拔掉","en":"We must pull them out","note":"","sourceLineIndex":21},{"id":"le-petit-prince-2cd-09-022","lineIndex":22,"speaker":"Ensemble","original":"Il faut s'en débarrasser","ipa":"/il fo sɑ̃ debaʁase/","zh":"必须摆脱它们","en":"We must get rid of them","note":"","sourceLineIndex":22},{"id":"le-petit-prince-2cd-09-023","lineIndex":23,"speaker":"Ensemble","original":"Faites attention aux baobabs","ipa":"/fɛtz atɑ̃sjɔ̃ o baobab/","zh":"当心猴面包树","en":"Watch out for the baobabs","note":"","sourceLineIndex":23},{"id":"le-petit-prince-2cd-09-024","lineIndex":24,"speaker":"Ensemble","original":"Il ne faut surtout pas remettre","ipa":"/il nə fo syʁtu pa ʁəmɛtʁ/","zh":"尤其绝不能拖延","en":"Above all, we must not put it off","note":"","sourceLineIndex":24},{"id":"le-petit-prince-2cd-09-025","lineIndex":25,"speaker":"Ensemble","original":"Ce travail à plus tard car plus tard c'est trop tard","ipa":"/sə tʁavaj a ply taʁ kaʁ ply taʁ sɛ tʁo taʁ/","zh":"把这件事留到以后，因为以后就是太迟","en":"This task until later, because later is too late","note":"","sourceLineIndex":25},{"id":"le-petit-prince-2cd-09-026","lineIndex":26,"speaker":"Ensemble","original":"Faites attention aux baobabs","ipa":"/fɛtz atɑ̃sjɔ̃ o baobab/","zh":"当心猴面包树","en":"Watch out for the baobabs","note":"","sourceLineIndex":26},{"id":"le-petit-prince-2cd-09-027","lineIndex":27,"speaker":"Ensemble","original":"Il faut leur couper la tête","ipa":"/il fo lœʁ kupe la tɛt/","zh":"必须砍掉它们的头","en":"We must cut their heads off","note":"","sourceLineIndex":27},{"id":"le-petit-prince-2cd-09-028","lineIndex":28,"speaker":"Ensemble","original":"Faites attention aux baobabs","ipa":"/fɛtz atɑ̃sjɔ̃ o baobab/","zh":"当心猴面包树","en":"Watch out for the baobabs","note":"","sourceLineIndex":28},{"id":"le-petit-prince-2cd-09-029","lineIndex":29,"speaker":"Ensemble","original":"Ils envahissent la planète","ipa":"/ilz ɑ̃vais la planɛt/","zh":"它们侵占整颗星球","en":"They invade the planet","note":"","sourceLineIndex":29},{"id":"le-petit-prince-2cd-09-030","lineIndex":30,"speaker":"Ensemble","original":"Ils l'étouffent, ils la déchiquettent","ipa":"/il letuf il la deʃikɛt/","zh":"它们令星球窒息，把它撕得粉碎","en":"They suffocate it; they tear it to pieces","note":"","sourceLineIndex":30},{"id":"le-petit-prince-2cd-09-031","lineIndex":31,"speaker":"Ensemble","original":"Il faut les repérer","ipa":"/il fo le ʁəpeʁe/","zh":"必须辨认出它们","en":"We must spot them","note":"","sourceLineIndex":31},{"id":"le-petit-prince-2cd-09-032","lineIndex":32,"speaker":"Ensemble","original":"Il faut les supprimer","ipa":"/il fo le sypʁime/","zh":"必须除掉它们","en":"We must eliminate them","note":"","sourceLineIndex":32},{"id":"le-petit-prince-2cd-09-033","lineIndex":33,"speaker":"Ensemble","original":"Il faut les éradiquer","ipa":"/il fo lez eʁadike/","zh":"必须根除它们","en":"We must eradicate them","note":"","sourceLineIndex":33},{"id":"le-petit-prince-2cd-09-034","lineIndex":34,"speaker":"Ensemble","original":"Faites attention aux baobabs","ipa":"/fɛtz atɑ̃sjɔ̃ o baobab/","zh":"当心猴面包树","en":"Watch out for the baobabs","note":"","sourceLineIndex":34},{"id":"le-petit-prince-2cd-09-035","lineIndex":35,"speaker":"Ensemble","original":"Il ne faut surtout pas remettre","ipa":"/il nə fo syʁtu pa ʁəmɛtʁ/","zh":"尤其绝不能拖延","en":"Above all, we must not put it off","note":"","sourceLineIndex":35},{"id":"le-petit-prince-2cd-09-036","lineIndex":36,"speaker":"Ensemble","original":"Ce travail à plus tard car plus tard c'est trop tard","ipa":"/sə tʁavaj a ply taʁ kaʁ ply taʁ sɛ tʁo taʁ/","zh":"把这件事留到以后，因为以后就是太迟","en":"This task until later, because later is too late","note":"","sourceLineIndex":36},{"id":"le-petit-prince-2cd-09-037","lineIndex":37,"speaker":"Ensemble","original":"Faites attention aux baobabs","ipa":"/fɛtz atɑ̃sjɔ̃ o baobab/","zh":"当心猴面包树","en":"Watch out for the baobabs","note":"","sourceLineIndex":37},{"id":"le-petit-prince-2cd-09-038","lineIndex":38,"speaker":"Ensemble","original":"Il faut faire place nette","ipa":"/il fo fɛʁ plas nɛt/","zh":"必须彻底清出一片空地","en":"We must clear the ground completely","note":"","sourceLineIndex":38},{"id":"le-petit-prince-2cd-09-039","lineIndex":39,"speaker":"Les Grandes Personnes","original":"Faites attention aux baobabs","ipa":"/fɛtz atɑ̃sjɔ̃ o baobab/","zh":"当心猴面包树","en":"Watch out for the baobabs","note":"","sourceLineIndex":39},{"id":"le-petit-prince-2cd-09-040","lineIndex":40,"speaker":"Les Grandes Personnes","original":"Ils envahissent la planète","ipa":"/ilz ɑ̃vais la planɛt/","zh":"它们侵占整颗星球","en":"They invade the planet","note":"","sourceLineIndex":40},{"id":"le-petit-prince-2cd-09-041","lineIndex":41,"speaker":"Les Grandes Personnes","original":"Faites attention aux baobabs","ipa":"/fɛtz atɑ̃sjɔ̃ o baobab/","zh":"当心猴面包树","en":"Watch out for the baobabs","note":"","sourceLineIndex":41},{"id":"le-petit-prince-2cd-09-042","lineIndex":42,"speaker":"Les Grandes Personnes","original":"Faites attention aux baobabs","ipa":"/fɛtz atɑ̃sjɔ̃ o baobab/","zh":"当心猴面包树","en":"Watch out for the baobabs","note":"","sourceLineIndex":42},{"id":"le-petit-prince-2cd-09-043","lineIndex":43,"speaker":"Les Grandes Personnes","original":"Ils envahissent la planète","ipa":"/ilz ɑ̃vais la planɛt/","zh":"它们侵占整颗星球","en":"They invade the planet","note":"","sourceLineIndex":43},{"id":"le-petit-prince-2cd-09-044","lineIndex":44,"speaker":"Ensemble","original":"Faites attention aux baobabs","ipa":"/fɛtz atɑ̃sjɔ̃ o baobab/","zh":"当心猴面包树","en":"Watch out for the baobabs","note":"","sourceLineIndex":44},{"id":"le-petit-prince-2cd-09-045","lineIndex":45,"speaker":"Ensemble","original":"Ils envahissent la planète","ipa":"/ilz ɑ̃vais la planɛt/","zh":"它们侵占整颗星球","en":"They invade the planet","note":"","sourceLineIndex":45},{"id":"le-petit-prince-2cd-09-046","lineIndex":46,"speaker":"Ensemble","original":"Ils l'étouffent, ils la déchiquettent","ipa":"/il letuf il la deʃikɛt/","zh":"它们令星球窒息，把它撕得粉碎","en":"They suffocate it; they tear it to pieces","note":"","sourceLineIndex":46},{"id":"le-petit-prince-2cd-09-047","lineIndex":47,"speaker":"Ensemble","original":"Il faut les démolir","ipa":"/il fo le demoliʁ/","zh":"必须摧毁它们","en":"We must demolish them","note":"","sourceLineIndex":47},{"id":"le-petit-prince-2cd-09-048","lineIndex":48,"speaker":"Ensemble","original":"Les détruire les occire il faut les anéantir","ipa":"/le detʁyiʁ lez ɔksiʁ il fo lez aneɑ̃tiʁ/","zh":"必须毁掉它们、杀死它们、把它们彻底消灭","en":"Destroy them, kill them; we must annihilate them","note":"","sourceLineIndex":48},{"id":"le-petit-prince-2cd-09-049","lineIndex":49,"speaker":"Ensemble","original":"Faites attention aux baobabs","ipa":"/fɛtz atɑ̃sjɔ̃ o baobab/","zh":"当心猴面包树","en":"Watch out for the baobabs","note":"","sourceLineIndex":49},{"id":"le-petit-prince-2cd-09-050","lineIndex":50,"speaker":"Ensemble","original":"Il ne faut surtout pas remettre","ipa":"/il nə fo syʁtu pa ʁəmɛtʁ/","zh":"尤其绝不能拖延","en":"Above all, we must not put it off","note":"","sourceLineIndex":50},{"id":"le-petit-prince-2cd-09-051","lineIndex":51,"speaker":"Ensemble","original":"Ce travail à plus tard car plus tard c'est trop tard","ipa":"/sə tʁavaj a ply taʁ kaʁ ply taʁ sɛ tʁo taʁ/","zh":"把这件事留到以后，因为以后就是太迟","en":"This task until later, because later is too late","note":"","sourceLineIndex":51},{"id":"le-petit-prince-2cd-09-052","lineIndex":52,"speaker":"Ensemble","original":"Faites attention aux baobabs","ipa":"/fɛtz atɑ̃sjɔ̃ o baobab/","zh":"当心猴面包树","en":"Watch out for the baobabs","note":"","sourceLineIndex":52},{"id":"le-petit-prince-2cd-09-053","lineIndex":53,"speaker":"Ensemble","original":"Il faut que ça s'arrête","ipa":"/il fo kə sa saʁɛt/","zh":"必须让这一切停下来","en":"This has to stop","note":"","sourceLineIndex":53},{"id":"le-petit-prince-2cd-09-054","lineIndex":54,"speaker":"Ensemble","original":"Faites attention aux baobabs","ipa":"/fɛtz atɑ̃sjɔ̃ o baobab/","zh":"当心猴面包树","en":"Watch out for the baobabs","note":"","sourceLineIndex":54},{"id":"le-petit-prince-2cd-09-055","lineIndex":55,"speaker":"Ensemble","original":"Ils envahissent la planète","ipa":"/ilz ɑ̃vais la planɛt/","zh":"它们侵占整颗星球","en":"They invade the planet","note":"","sourceLineIndex":55},{"id":"le-petit-prince-2cd-09-056","lineIndex":56,"speaker":"Ensemble","original":"Faites attention aux baobabs","ipa":"/fɛtz atɑ̃sjɔ̃ o baobab/","zh":"当心猴面包树","en":"Watch out for the baobabs","note":"","sourceLineIndex":56},{"id":"le-petit-prince-2cd-09-057","lineIndex":57,"speaker":"Ensemble","original":"Il ne faut surtout pas remettre","ipa":"/il nə fo syʁtu pa ʁəmɛtʁ/","zh":"尤其绝不能拖延","en":"Above all, we must not put it off","note":"","sourceLineIndex":57},{"id":"le-petit-prince-2cd-09-058","lineIndex":58,"speaker":"Ensemble","original":"Ce travail à plus tard car plus tard c'est trop tard","ipa":"/sə tʁavaj a ply taʁ kaʁ ply taʁ sɛ tʁo taʁ/","zh":"把这件事留到以后，因为以后就是太迟","en":"This task until later, because later is too late","note":"","sourceLineIndex":58},{"id":"le-petit-prince-2cd-09-059","lineIndex":59,"speaker":"Ensemble","original":"Faites attention aux baobabs","ipa":"/fɛtz atɑ̃sjɔ̃ o baobab/","zh":"当心猴面包树","en":"Watch out for the baobabs","note":"","sourceLineIndex":59},{"id":"le-petit-prince-2cd-09-060","lineIndex":60,"speaker":"Ensemble","original":"Il faut que ça s'arrête","ipa":"/il fo kə sa saʁɛt/","zh":"必须让这一切停下来","en":"This has to stop","note":"","sourceLineIndex":60}],"sourceOrder":9,"displayOrder":9},{"order":10,"id":"10-coucher-de-soleil-4e-jour-dans-le-desert-la-fleur","title":"Coucher De Soleil / 4È Jour Dans Le Désert / La Fleur","titleZh":"日落/在沙漠的第四天/花","lines":[{"id":"le-petit-prince-2cd-10-001","lineIndex":1,"speaker":"L'Aviateur","original":"Tu as raison, faut pas laisser pousser les petits baobabs","ipa":"/ty a ʁɛzɔ̃ fo pa lɛse puse le pəti baobab/","zh":"你说得对，不能任由小猴面包树长大","en":"You're right: we must not let the young baobabs grow","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-10-002","lineIndex":2,"speaker":"L'Aviateur","original":"Dans certaines circonstances, sur certaines planètes","ipa":"/dɑ̃ sɛʁtɛn siʁkɔ̃stɑ̃s syʁ sɛʁtɛn planɛt/","zh":"在某些情形、某些星球上","en":"In certain circumstances, on certain planets","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-10-003","lineIndex":3,"speaker":"L'Aviateur","original":"c'est un très grave danger","ipa":"/sɛt œ̃ tʁɛ ɡʁav dɑ̃ʒe/","zh":"这会造成极其严重的危险","en":"It is a very serious danger","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-10-004","lineIndex":4,"speaker":"L'Aviateur","original":"Tu as l'air mélancolique","ipa":"/ty a lɛʁ melɑ̃kolik/","zh":"你看上去有些忧郁","en":"You look melancholy","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-10-005","lineIndex":5,"speaker":"Le Petit Prince","original":"J'aime bien les couchers de soleil","ipa":"/ʒɛm bjɛ̃ le kuʃe də solɛj/","zh":"我很喜欢日落","en":"I really like sunsets","note":"","sourceLineIndex":5},{"id":"le-petit-prince-2cd-10-006","lineIndex":6,"speaker":"Le Petit Prince","original":"Allons voir un coucher de soleil","ipa":"/alɔ̃ vwaʁ œ̃ kuʃe də solɛj/","zh":"我们去看一次日落吧","en":"Let's go and watch a sunset","note":"","sourceLineIndex":6},{"id":"le-petit-prince-2cd-10-007","lineIndex":7,"speaker":"L'Aviateur","original":"Mais il faut attendre","ipa":"/mɛz il fot atɑ̃dʁ/","zh":"可得等一等","en":"But we have to wait","note":"","sourceLineIndex":7},{"id":"le-petit-prince-2cd-10-008","lineIndex":8,"speaker":"Le Petit Prince","original":"Attendre quoi?","ipa":"/atɑ̃dʁ kwa/","zh":"等什么？","en":"Wait for what?","note":"","sourceLineIndex":8},{"id":"le-petit-prince-2cd-10-009","lineIndex":9,"speaker":"L'Aviateur","original":"Attendre que le soleil se couche","ipa":"/atɑ̃dʁ kə lə solɛj sə kuʃ/","zh":"等太阳落下去","en":"Wait for the sun to set","note":"","sourceLineIndex":9},{"id":"le-petit-prince-2cd-10-010","lineIndex":10,"speaker":"Le Petit Prince","original":"Chez moi, c'est si petit qu'il me suffit de tirer ma chaise de quelques pas","ipa":"/ʃe mwa sɛ si pəti kil mə syfi də tiʁe ma ʃɛz də kɛlkə pa/","zh":"我那里小得很，只要把椅子拖动几步就行","en":"Where I live, it is so small that I only have to move my chair a few steps","note":"","sourceLineIndex":10},{"id":"le-petit-prince-2cd-10-011","lineIndex":11,"speaker":"Le Petit Prince","original":"Et je regardais le crépuscule chaque fois que je le désirais","ipa":"/e ʒə ʁəɡaʁdɛ lə kʁepyskyl ʃak fwa kə ʒə lə deziʁɛ/","zh":"每当想看时，我就能看黄昏","en":"And I could watch the twilight whenever I wished","note":"","sourceLineIndex":11},{"id":"le-petit-prince-2cd-10-012","lineIndex":12,"speaker":"Le Petit Prince","original":"Un jour, j'ai vu le soleil se coucher 44 fois","ipa":"/œ̃ ʒuʁ ʒe vy lə solɛj sə kuʃe kaʁɑ̃tkatʁ fwa/","zh":"有一天，我看了四十四次日落","en":"One day I watched the sun set forty-four times","note":"","sourceLineIndex":12},{"id":"le-petit-prince-2cd-10-013","lineIndex":13,"speaker":"Le Petit Prince","original":"Quand on est tellement triste, on aime les couchers de soleil","ipa":"/kɑ̃t ɔ̃n ɛ tɛlmɑ̃ tʁist ɔ̃n ɛm le kuʃe də solɛj/","zh":"当人非常难过时，就会喜欢看日落","en":"When one is very sad, one loves sunsets","note":"","sourceLineIndex":13},{"id":"le-petit-prince-2cd-10-014","lineIndex":14,"speaker":"L'Aviateur","original":"Ce jour-là, tu étais donc tellement triste?","ipa":"/sə ʒuʁla ty etɛ dɔ̃k tɛlmɑ̃ tʁist/","zh":"那么那一天，你非常难过吗？","en":"So were you very sad that day?","note":"","sourceLineIndex":14},{"id":"le-petit-prince-2cd-10-015","lineIndex":15,"speaker":"L'Aviateur","original":"Aujourd'hui, quatrième jour dans le désert","ipa":"/oʒuʁdyi katʁiɛm ʒuʁ dɑ̃ lə dezɛʁ/","zh":"今天，来到沙漠的第四天","en":"Today, the fourth day in the desert","note":"","sourceLineIndex":15},{"id":"le-petit-prince-2cd-10-016","lineIndex":16,"speaker":"Le Petit Prince","original":"Un mouton, s'il mange les arbustes","ipa":"/œ̃ mutɔ̃ sil mɑ̃ʒ lez aʁbyst/","zh":"一只绵羊，要是吃灌木","en":"If a sheep eats shrubs","note":"","sourceLineIndex":16},{"id":"le-petit-prince-2cd-10-017","lineIndex":17,"speaker":"Le Petit Prince","original":"il mange aussi les fleurs?","ipa":"/il mɑ̃ʒ osi le flœʁ/","zh":"它也吃花吗？","en":"Does it eat flowers too?","note":"","sourceLineIndex":17},{"id":"le-petit-prince-2cd-10-018","lineIndex":18,"speaker":"L'Aviateur","original":"Un mouton mange tout ce qu'il rencontre","ipa":"/œ̃ mutɔ̃ mɑ̃ʒ tu sə kil ʁɑ̃kɔ̃tʁ/","zh":"绵羊遇见什么就吃什么","en":"A sheep eats everything it comes across","note":"","sourceLineIndex":18},{"id":"le-petit-prince-2cd-10-019","lineIndex":19,"speaker":"Le Petit Prince","original":"Même les fleurs qui ont des épines?","ipa":"/mɛm le flœʁ ki ɔ̃ dez epin/","zh":"连有刺的花也吃吗？","en":"Even flowers that have thorns?","note":"","sourceLineIndex":19},{"id":"le-petit-prince-2cd-10-020","lineIndex":20,"speaker":"L'Aviateur","original":"Même les fleurs qui ont des épines.","ipa":"/mɛm le flœʁ ki ɔ̃ dez epin/","zh":"对，连有刺的花也吃。","en":"Even flowers that have thorns.","note":"","sourceLineIndex":20},{"id":"le-petit-prince-2cd-10-021","lineIndex":21,"speaker":"Le Petit Prince","original":"Alors les épines, à quoi servent-elles?","ipa":"/alɔʁ lez epin a kwa sɛʁvtɛl/","zh":"那刺又有什么用呢？","en":"Then what are thorns for?","note":"","sourceLineIndex":21},{"id":"le-petit-prince-2cd-10-022","lineIndex":22,"speaker":"Le Petit Prince","original":"Les épines, à quoi servent-elles?","ipa":"/lez epin a kwa sɛʁvtɛl/","zh":"刺究竟有什么用呢？","en":"What are thorns for?","note":"","sourceLineIndex":22},{"id":"le-petit-prince-2cd-10-023","lineIndex":23,"speaker":"L'Aviateur","original":"Elles ne servent à rien","ipa":"/ɛl nə sɛʁvt a ʁjɛ̃/","zh":"它们一点用也没有","en":"They are of no use","note":"","sourceLineIndex":23},{"id":"le-petit-prince-2cd-10-024","lineIndex":24,"speaker":"L'Aviateur","original":"C'est de la pure méchanceté de ma part des fleurs","ipa":"/sɛ də la pyʁ meʃɑ̃ste də ma paʁ de flœʁ/","zh":"那只是花儿出于纯粹的坏心眼","en":"It is sheer spite on the part of flowers","note":"","sourceLineIndex":24},{"id":"le-petit-prince-2cd-10-025","lineIndex":25,"speaker":"Le Petit Prince","original":"Je ne te crois pas","ipa":"/ʒə nə tə kʁwa pa/","zh":"我不相信你","en":"I don't believe you","note":"","sourceLineIndex":25},{"id":"le-petit-prince-2cd-10-026","lineIndex":26,"speaker":"Le Petit Prince","original":"Les fleurs sont faibles","ipa":"/le flœʁ sɔ̃ fɛbl/","zh":"花儿很柔弱","en":"Flowers are weak","note":"","sourceLineIndex":26},{"id":"le-petit-prince-2cd-10-027","lineIndex":27,"speaker":"Le Petit Prince","original":"Elles sont naïves","ipa":"/ɛl sɔ̃ naiv/","zh":"它们很天真","en":"They are naïve","note":"","sourceLineIndex":27},{"id":"le-petit-prince-2cd-10-028","lineIndex":28,"speaker":"Le Petit Prince","original":"Elles se rassurent comme elles peuvent","ipa":"/ɛl sə ʁasyʁ kɔm ɛl pøv/","zh":"它们只能尽力给自己壮胆","en":"They reassure themselves as best they can","note":"","sourceLineIndex":28},{"id":"le-petit-prince-2cd-10-029","lineIndex":29,"speaker":"Le Petit Prince","original":"Elles se croient terribles avec leurs épines","ipa":"/ɛl sə kʁwa tɛʁibl avɛk lœʁz epin/","zh":"它们带着刺，就以为自己很厉害","en":"They think themselves formidable with their thorns","note":"","sourceLineIndex":29},{"id":"le-petit-prince-2cd-10-030","lineIndex":30,"speaker":"Le Petit Prince","original":"Alors, tu crois, toi, que les fleurs...","ipa":"/alɔʁ ty kʁwa twa kə le flœʁ/","zh":"那么你是认为，花儿……","en":"So you think that flowers...","note":"","sourceLineIndex":30},{"id":"le-petit-prince-2cd-10-031","lineIndex":31,"speaker":"L'Aviateur","original":"Non, je ne crois rien","ipa":"/nɔ̃ ʒə nə kʁwa ʁjɛ̃/","zh":"不，我什么也不认为","en":"No, I don't believe anything","note":"","sourceLineIndex":31},{"id":"le-petit-prince-2cd-10-032","lineIndex":32,"speaker":"L'Aviateur","original":"Je t'ai répondu n'importe quoi","ipa":"/ʒə te ʁepɔ̃dy nɛ̃pɔʁt kwa/","zh":"我刚才只是随口乱答","en":"I gave you any old answer","note":"","sourceLineIndex":32},{"id":"le-petit-prince-2cd-10-033","lineIndex":33,"speaker":"L'Aviateur","original":"Je m'occupe, moi, de choses sérieuses","ipa":"/ʒə mɔkyp mwa də ʃoz seʁjøz/","zh":"我呢，正忙着正经事","en":"I am busy with serious matters","note":"","sourceLineIndex":33},{"id":"le-petit-prince-2cd-10-034","lineIndex":34,"speaker":"Le Petit Prince","original":"De choses sérieuses!?","ipa":"/də ʃoz seʁjøz/","zh":"正经事！？","en":"Serious matters!?","note":"","sourceLineIndex":34},{"id":"le-petit-prince-2cd-10-035","lineIndex":35,"speaker":"Le Petit Prince","original":"Tu parles comme les grandes personnes!","ipa":"/ty paʁl kɔm le ɡʁɑ̃d pɛʁsɔn/","zh":"你说话就像那些大人！","en":"You talk like a grown-up!","note":"","sourceLineIndex":35},{"id":"le-petit-prince-2cd-10-036","lineIndex":36,"speaker":"Le Petit Prince","original":"Je connais une planète où il y a monsieur","ipa":"/ʒə kɔnɛz yn planɛt u il i a məsjø/","zh":"我知道有一颗星球，上面住着一位先生","en":"I know a planet where there is a gentleman","note":"","sourceLineIndex":36},{"id":"le-petit-prince-2cd-10-037","lineIndex":37,"speaker":"Le Petit Prince","original":"qui n'a jamais rien fait d'autre que des additions","ipa":"/ki na ʒamɛ ʁjɛ̃ fɛ dotʁ kə dez adisjɔ̃/","zh":"他从来只会做加法，别的什么也没做过","en":"who has never done anything except add up figures","note":"","sourceLineIndex":37},{"id":"le-petit-prince-2cd-10-038","lineIndex":38,"speaker":"Le Petit Prince","original":"Il n'a jamais respiré une fleur","ipa":"/il na ʒamɛ ʁɛspiʁe yn flœʁ/","zh":"他从未闻过一朵花","en":"He has never smelled a flower","note":"","sourceLineIndex":38},{"id":"le-petit-prince-2cd-10-039","lineIndex":39,"speaker":"Le Petit Prince","original":"jamais regardé une étoile","ipa":"/ʒamɛ ʁəɡaʁde yn etwal/","zh":"从未看过一颗星星","en":"Never looked at a star","note":"","sourceLineIndex":39},{"id":"le-petit-prince-2cd-10-040","lineIndex":40,"speaker":"Le Petit Prince","original":"et toute la journée il répète, comme toi","ipa":"/e tut la ʒuʁne il ʁepɛt kɔm twa/","zh":"而且他整天都像你一样重复说","en":"And all day long he repeats, just like you","note":"","sourceLineIndex":40},{"id":"le-petit-prince-2cd-10-041","lineIndex":41,"speaker":"Le Petit Prince","original":"Je suis un homme sérieux. Je suis un homme sérieux","ipa":"/ʒə syiz œ̃n ɔm seʁjø ʒə syiz œ̃n ɔm seʁjø/","zh":"我是个正经人，我是个正经人","en":"I am a serious man. I am a serious man","note":"","sourceLineIndex":41},{"id":"le-petit-prince-2cd-10-042","lineIndex":42,"speaker":"Le Petit Prince","original":"et ça le fait gonfler d'orgueil","ipa":"/e sa lə fɛ ɡɔ̃fle dɔʁɡœj/","zh":"这让他得意得膨胀起来","en":"And that makes him swell with pride","note":"","sourceLineIndex":42},{"id":"le-petit-prince-2cd-10-043","lineIndex":43,"speaker":"Le Petit Prince","original":"mais ça n'est pas un homme, c'est un champignon","ipa":"/mɛ sa nɛ paz œ̃n ɔm sɛt œ̃ ʃɑ̃pinjɔ̃/","zh":"可那不是一个人，那是一朵蘑菇","en":"But he is not a man; he is a mushroom","note":"","sourceLineIndex":43},{"id":"le-petit-prince-2cd-10-044","lineIndex":44,"speaker":"L'Aviateur","original":"Un quoi?","ipa":"/œ̃ kwa/","zh":"一个什么？","en":"A what?","note":"","sourceLineIndex":44},{"id":"le-petit-prince-2cd-10-045","lineIndex":45,"speaker":"Le Petit Prince","original":"Un champignon!","ipa":"/œ̃ ʃɑ̃pinjɔ̃/","zh":"一朵蘑菇！","en":"A mushroom!","note":"","sourceLineIndex":45},{"id":"le-petit-prince-2cd-10-046","lineIndex":46,"speaker":"Le Petit Prince","original":"Il y a des millions d'années que les fleurs fabriquent des épines","ipa":"/il i a de miljɔ̃ dane kə le flœʁ fabʁik dez epin/","zh":"花儿长出刺，已经有几百万年了","en":"Flowers have been making thorns for millions of years","note":"","sourceLineIndex":46},{"id":"le-petit-prince-2cd-10-047","lineIndex":47,"speaker":"Le Petit Prince","original":"Il y a des millions d'années que les moutons mangent quand même les fleurs","ipa":"/il i a de miljɔ̃ dane kə le mutɔ̃ mɑ̃ʒ kɑ̃ mɛm le flœʁ/","zh":"可绵羊吃花，也已经有几百万年了","en":"And sheep have nevertheless been eating flowers for millions of years","note":"","sourceLineIndex":47},{"id":"le-petit-prince-2cd-10-048","lineIndex":48,"speaker":"Le Petit Prince","original":"Et c'est pas important, ça, la guerre des moutons et des fleurs?","ipa":"/e sɛ paz ɛ̃pɔʁtɑ̃ sa la ɡɛʁ de mutɔ̃z e de flœʁ/","zh":"而绵羊和花儿之间的战争，这还不重要吗？","en":"And is the war between sheep and flowers not important?","note":"","sourceLineIndex":48},{"id":"le-petit-prince-2cd-10-049","lineIndex":49,"speaker":"Le Petit Prince","original":"Si quelqu'un aime une fleur qui n'existe qu'à un seul exemplaire dans les millions et les millions d'étoiles","ipa":"/si kɛlkœ̃ ɛm yn flœʁ ki nɛɡzist ka œ̃ sœl ɛɡzɑ̃plɛʁ dɑ̃ le miljɔ̃z e le miljɔ̃ detwal/","zh":"如果一个人爱上一朵花，而亿万星辰中只有这一朵","en":"If someone loves a flower that exists in only one copy among millions and millions of stars","note":"","sourceLineIndex":49},{"id":"le-petit-prince-2cd-10-050","lineIndex":50,"speaker":"Le Petit Prince","original":"ça suffit pour qu'il soit heureux quand il les regarde","ipa":"/sa syfi puʁ kil swa øʁø kɑ̃t il le ʁəɡaʁd/","zh":"那么当他仰望群星时，这就足以让他幸福","en":"That is enough to make him happy when he looks at the stars","note":"","sourceLineIndex":50},{"id":"le-petit-prince-2cd-10-051","lineIndex":51,"speaker":"Le Petit Prince","original":"Il se dit: Ma fleur est là quelque part","ipa":"/il sə di ma flœʁ ɛ la kɛlkə paʁ/","zh":"他会想：我的花就在某个地方","en":"He tells himself: My flower is there somewhere","note":"","sourceLineIndex":51},{"id":"le-petit-prince-2cd-10-052","lineIndex":52,"speaker":"Le Petit Prince","original":"Mais si le mouton mange la fleur","ipa":"/mɛ si lə mutɔ̃ mɑ̃ʒ la flœʁ/","zh":"但如果绵羊吃掉了那朵花","en":"But if the sheep eats the flower","note":"","sourceLineIndex":52},{"id":"le-petit-prince-2cd-10-053","lineIndex":53,"speaker":"Le Petit Prince","original":"c'est pour lui comme si brusquement toutes les étoiles s'éteignaient","ipa":"/sɛ puʁ lyi kɔm si bʁyskəmɑ̃ tut lez etwal setɛnjɛ/","zh":"对他来说，就仿佛所有星星突然熄灭","en":"For him, it is as if all the stars suddenly went out","note":"","sourceLineIndex":53},{"id":"le-petit-prince-2cd-10-054","lineIndex":54,"speaker":"Le Petit Prince","original":"Et c'est pas important, ça?","ipa":"/e sɛ paz ɛ̃pɔʁtɑ̃ sa/","zh":"而这还不重要吗？","en":"And is that not important?","note":"","sourceLineIndex":54},{"id":"le-petit-prince-2cd-10-055","lineIndex":55,"speaker":"L'Aviateur","original":"La fleur que tu aimes n'est pas en danger","ipa":"/la flœʁ kə ty ɛm nɛ paz ɑ̃ dɑ̃ʒe/","zh":"你爱的那朵花不会有危险","en":"The flower you love is not in danger","note":"","sourceLineIndex":55},{"id":"le-petit-prince-2cd-10-056","lineIndex":56,"speaker":"L'Aviateur","original":"Je lui dessinerais une muselière à ton mouton","ipa":"/ʒə lyi dɛsinʁɛz yn myzljɛʁ a tɔ̃ mutɔ̃/","zh":"我会给你的绵羊画一个口套","en":"I will draw a muzzle for your sheep","note":"","sourceLineIndex":56},{"id":"le-petit-prince-2cd-10-057","lineIndex":57,"speaker":"L'Aviateur","original":"Je te donnerai une armure pour ta fleur","ipa":"/ʒə tə dɔnʁe yn aʁmyʁ puʁ ta flœʁ/","zh":"我会给你的花一副盔甲","en":"I will give you armour for your flower","note":"","sourceLineIndex":57},{"id":"le-petit-prince-2cd-10-058","lineIndex":58,"speaker":"L'Aviateur","original":"Attends. Regarde! Regarde… Regarde","ipa":"/atɑ̃ ʁəɡaʁd ʁəɡaʁd ʁəɡaʁd/","zh":"等等。看！看……看","en":"Wait. Look! Look... Look","note":"","sourceLineIndex":58},{"id":"le-petit-prince-2cd-10-059","lineIndex":59,"speaker":"Le Petit Prince","original":"Des fleurs, il y en a toujours eu sur ma planète","ipa":"/de flœʁ il i ɑ̃n a tuʒuʁz y syʁ ma planɛt/","zh":"我的星球上一直都有花","en":"There have always been flowers on my planet","note":"","sourceLineIndex":59},{"id":"le-petit-prince-2cd-10-060","lineIndex":60,"speaker":"Le Petit Prince","original":"des fleurs très simples, armées d'un rang de pétales","ipa":"/de flœʁ tʁɛ sɛ̃pl aʁme dœ̃ ʁɑ̃ də petal/","zh":"都是很朴素、只有一圈花瓣的花","en":"Very simple flowers, with a single ring of petals","note":"","sourceLineIndex":60},{"id":"le-petit-prince-2cd-10-061","lineIndex":61,"speaker":"Le Petit Prince","original":"qui ne tiennent pas de place et ne dérangent personne","ipa":"/ki nə tjɛn pa də plas e nə deʁɑ̃ʒ pɛʁsɔn/","zh":"它们不占地方，也不打扰任何人","en":"They take up no space and bother no one","note":"","sourceLineIndex":61},{"id":"le-petit-prince-2cd-10-062","lineIndex":62,"speaker":"Le Petit Prince","original":"Mais un jour est arrivée ma fleur","ipa":"/mɛz œ̃ ʒuʁ ɛt aʁive ma flœʁ/","zh":"可有一天，我的花来了","en":"But one day my flower arrived","note":"","sourceLineIndex":62},{"id":"le-petit-prince-2cd-10-063","lineIndex":63,"speaker":"Le Petit Prince","original":"une graine apportée on ne sait d'où","ipa":"/yn ɡʁɛn apɔʁte ɔ̃ nə sɛ du/","zh":"一粒不知从何而来的种子","en":"A seed brought from who knows where","note":"","sourceLineIndex":63},{"id":"le-petit-prince-2cd-10-064","lineIndex":64,"speaker":"Le Petit Prince","original":"J'avais peur au début que ce soit un nouveau genre de baobab","ipa":"/ʒavɛ pœʁ o deby kə sə swa œ̃ nuvo ʒɑ̃ʁ də baobab/","zh":"起初我害怕那会是一种新的猴面包树","en":"At first I was afraid it might be a new kind of baobab","note":"","sourceLineIndex":64},{"id":"le-petit-prince-2cd-10-065","lineIndex":65,"speaker":"Le Petit Prince","original":"Mais l'arbuste a vite cessé de croître et a formé une fleur","ipa":"/mɛ laʁbyst a vit sɛse də kʁwatʁ e a fɔʁme yn flœʁ/","zh":"但那株小灌木很快停止生长，开始孕育一朵花","en":"But the little shrub soon stopped growing and began to form a flower","note":"","sourceLineIndex":65},{"id":"le-petit-prince-2cd-10-066","lineIndex":66,"speaker":"Le Petit Prince","original":"un bouton énorme","ipa":"/œ̃ butɔ̃ enɔʁm/","zh":"一个巨大的花苞","en":"An enormous bud","note":"","sourceLineIndex":66}],"sourceOrder":10,"displayOrder":10},{"order":11,"id":"11-pres-d-elle","title":"PrÈS D'elle","titleZh":"在她身边","lines":[{"id":"le-petit-prince-2cd-11-001","lineIndex":1,"speaker":"","original":"Bien à l'abri de sa chambre verte","ipa":"/bjɛ̃n a labʁi də sa ʃɑ̃bʁ vɛʁt/","zh":"安然藏在她绿色的小房间里","en":"Safe inside her green chamber","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-11-002","lineIndex":2,"speaker":"","original":"Elle n'en finit pas dans cette cachette","ipa":"/ɛl nɑ̃ fini pa dɑ̃ sɛt kaʃɛt/","zh":"她在这个藏身处里迟迟不肯出来","en":"She takes forever in that hiding place","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-11-003","lineIndex":3,"speaker":"","original":"De choisir avec soin ses couleurs","ipa":"/də ʃwaziʁ avɛk swɛ̃ se kulœʁ/","zh":"仔细挑选自己的色彩","en":"Choosing her colours with care","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-11-004","lineIndex":4,"speaker":"","original":"De s'habiller lentement le coeur","ipa":"/də sabije lɑ̃tmɑ̃ lə kœʁ/","zh":"慢慢装点自己的花心","en":"Slowly dressing her heart","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-11-005","lineIndex":5,"speaker":"","original":"Ses pétales ajustés un à un","ipa":"/se petalz aʒystez œ̃n a œ̃/","zh":"一片一片调整好她的花瓣","en":"Her petals adjusted one by one","note":"","sourceLineIndex":5},{"id":"le-petit-prince-2cd-11-006","lineIndex":6,"speaker":"","original":"Pour lui faire un corset de satin","ipa":"/puʁ lyi fɛʁ œ̃ kɔʁsɛ də satɛ̃/","zh":"为她做成一件缎面胸衣","en":"To make her a satin corset","note":"","sourceLineIndex":6},{"id":"le-petit-prince-2cd-11-007","lineIndex":7,"speaker":"","original":"Près d'elle","ipa":"/pʁɛ dɛl/","zh":"在她身边","en":"Near her","note":"","sourceLineIndex":7},{"id":"le-petit-prince-2cd-11-008","lineIndex":8,"speaker":"","original":"Je sens un miracle qui s'apprête","ipa":"/ʒə sɑ̃z œ̃ miʁakl ki sapʁɛt/","zh":"我感觉一个奇迹正在酝酿","en":"I feel a miracle preparing itself","note":"","sourceLineIndex":8},{"id":"le-petit-prince-2cd-11-009","lineIndex":9,"speaker":"","original":"Un soleil","ipa":"/œ̃ solɛj/","zh":"一轮太阳","en":"A sun","note":"","sourceLineIndex":9},{"id":"le-petit-prince-2cd-11-010","lineIndex":10,"speaker":"","original":"Qui vient pour éclairer ma planète","ipa":"/ki vjɛ̃ puʁ eklɛʁe ma planɛt/","zh":"正要来照亮我的星球","en":"Coming to light up my planet","note":"","sourceLineIndex":10},{"id":"le-petit-prince-2cd-11-011","lineIndex":11,"speaker":"","original":"Je n'ai connu que des fleurs fragiles","ipa":"/ʒə ne kɔny kə de flœʁ fʁaʒil/","zh":"我只认识那些娇弱的花","en":"I have known only fragile flowers","note":"","sourceLineIndex":11},{"id":"le-petit-prince-2cd-11-012","lineIndex":12,"speaker":"","original":"Jusqu'à ce qu'apparaisse cette brindille","ipa":"/ʒyska sə kapaʁɛs sɛt bʁɛ̃dij/","zh":"直到这株小芽出现","en":"Until this little shoot appeared","note":"","sourceLineIndex":12},{"id":"le-petit-prince-2cd-11-013","lineIndex":13,"speaker":"","original":"Des fleurs qui ne tenaient pas de place","ipa":"/de flœʁ ki nə tənɛ pa də plas/","zh":"那些不占地方的花","en":"Flowers that took up no space","note":"","sourceLineIndex":13},{"id":"le-petit-prince-2cd-11-014","lineIndex":14,"speaker":"","original":"Et qui passaient sans laisser de trace","ipa":"/e ki pasɛ sɑ̃ lɛse də tʁas/","zh":"匆匆来去，不留一点痕迹","en":"And passed without leaving a trace","note":"","sourceLineIndex":14},{"id":"le-petit-prince-2cd-11-015","lineIndex":15,"speaker":"","original":"Avec ses manières si émouvantes","ipa":"/avɛk se manjɛʁ si emuvɑ̃t/","zh":"她的姿态如此动人","en":"With her so moving ways","note":"","sourceLineIndex":15},{"id":"le-petit-prince-2cd-11-016","lineIndex":16,"speaker":"","original":"Celle-ci a l'air tellement différente","ipa":"/sɛl si a lɛʁ tɛlmɑ̃ difeʁɑ̃t/","zh":"这一朵看起来如此不同","en":"This one seems so different","note":"","sourceLineIndex":16},{"id":"le-petit-prince-2cd-11-017","lineIndex":17,"speaker":"","original":"Près d'elle","ipa":"/pʁɛ dɛl/","zh":"在她身边","en":"Near her","note":"","sourceLineIndex":17},{"id":"le-petit-prince-2cd-11-018","lineIndex":18,"speaker":"","original":"Je sens un miracle qui s'apprête","ipa":"/ʒə sɑ̃z œ̃ miʁakl ki sapʁɛt/","zh":"我感觉一个奇迹正在酝酿","en":"I feel a miracle preparing itself","note":"","sourceLineIndex":18},{"id":"le-petit-prince-2cd-11-019","lineIndex":19,"speaker":"","original":"Un soleil","ipa":"/œ̃ solɛj/","zh":"一轮太阳","en":"A sun","note":"","sourceLineIndex":19},{"id":"le-petit-prince-2cd-11-020","lineIndex":20,"speaker":"","original":"Qui vient pour réchauffer ma planète","ipa":"/ki vjɛ̃ puʁ ʁeʃofe ma planɛt/","zh":"正要来温暖我的星球","en":"Coming to warm my planet","note":"","sourceLineIndex":20},{"id":"le-petit-prince-2cd-11-021","lineIndex":21,"speaker":"","original":"Petite graine perdue dans l'univers","ipa":"/pətit ɡʁɛn pɛʁdy dɑ̃ lynivɛʁ/","zh":"迷失在宇宙中的小种子","en":"A little seed lost in the universe","note":"","sourceLineIndex":21},{"id":"le-petit-prince-2cd-11-022","lineIndex":22,"speaker":"","original":"Qui a trouvé sa place sur ma terre","ipa":"/ki a tʁuve sa plas syʁ ma tɛʁ/","zh":"在我的土地上找到了自己的位置","en":"That found its place on my earth","note":"","sourceLineIndex":22},{"id":"le-petit-prince-2cd-11-023","lineIndex":23,"speaker":"","original":"Elle se prépare avec tant d'amour","ipa":"/ɛl sə pʁepaʁ avɛk tɑ̃ damuʁ/","zh":"她满怀爱意地准备着","en":"She prepares herself with so much love","note":"","sourceLineIndex":23},{"id":"le-petit-prince-2cd-11-024","lineIndex":24,"speaker":"","original":"À naître en étant belle comme le jour","ipa":"/a nɛtʁ ɑ̃n etɑ̃ bɛl kɔm lə ʒuʁ/","zh":"准备诞生，像白昼一样美丽","en":"To be born as beautiful as day","note":"","sourceLineIndex":24},{"id":"le-petit-prince-2cd-11-025","lineIndex":25,"speaker":"","original":"Près d'elle","ipa":"/pʁɛ dɛl/","zh":"在她身边","en":"Near her","note":"","sourceLineIndex":25},{"id":"le-petit-prince-2cd-11-026","lineIndex":26,"speaker":"","original":"Je sens un miracle qui s'apprête","ipa":"/ʒə sɑ̃z œ̃ miʁakl ki sapʁɛt/","zh":"我感觉一个奇迹正在酝酿","en":"I feel a miracle preparing itself","note":"","sourceLineIndex":26},{"id":"le-petit-prince-2cd-11-027","lineIndex":27,"speaker":"","original":"Un soleil","ipa":"/œ̃ solɛj/","zh":"一轮太阳","en":"A sun","note":"","sourceLineIndex":27},{"id":"le-petit-prince-2cd-11-028","lineIndex":28,"speaker":"","original":"Qui vient pour éclairer ma planète","ipa":"/ki vjɛ̃ puʁ eklɛʁe ma planɛt/","zh":"正要来照亮我的星球","en":"Coming to light up my planet","note":"","sourceLineIndex":28},{"id":"le-petit-prince-2cd-11-029","lineIndex":29,"speaker":"","original":"Près d'elle","ipa":"/pʁɛ dɛl/","zh":"在她身边","en":"Near her","note":"","sourceLineIndex":29}],"sourceOrder":11,"displayOrder":11},{"order":12,"id":"12-la-rose","title":"La Rose","titleZh":"玫瑰","lines":[{"id":"le-petit-prince-2cd-12-001","lineIndex":1,"speaker":"Le Petit Prince","original":"Vous êtes belle.","ipa":"/vuz ɛt bɛl/","zh":"您真美。","en":"You are beautiful.","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-12-002","lineIndex":2,"speaker":"La Rose","original":"N'est-ce pas?","ipa":"/nɛs pa/","zh":"不是吗？","en":"Am I not?","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-12-003","lineIndex":3,"speaker":"Le Petit Prince","original":"Vous êtes belle, mais bien compliquée.","ipa":"/vuz ɛt bɛl mɛ bjɛ̃ kɔ̃plike/","zh":"您很美，不过真够复杂的。","en":"You are beautiful, but very complicated.","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-12-004","lineIndex":4,"speaker":"La Rose","original":"Ah! Je me réveille à peine.","ipa":"/a ʒə mə ʁevɛj a pɛn/","zh":"啊！我才刚醒呢。","en":"Ah! I have only just woken up.","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-12-005","lineIndex":5,"speaker":"La Rose","original":"Ah! Je vous demande pardon.","ipa":"/a ʒə vu dəmɑ̃d paʁdɔ̃/","zh":"啊！请您原谅。","en":"Ah! I beg your pardon.","note":"","sourceLineIndex":5},{"id":"le-petit-prince-2cd-12-006","lineIndex":6,"speaker":"La Rose","original":"Ah! Je suis toute décoiffée.","ipa":"/a ʒə syi tut dekwafe/","zh":"啊！我的头发全乱了。","en":"Ah! My hair is all mussed.","note":"","sourceLineIndex":6},{"id":"le-petit-prince-2cd-12-007","lineIndex":7,"speaker":"La Rose","original":"Mais je suis née en même temps que le soleil.","ipa":"/mɛ ʒə syi ne ɑ̃ mɛm tɑ̃ kə lə solɛj/","zh":"可我是和太阳同时诞生的。","en":"But I was born at the same time as the sun.","note":"","sourceLineIndex":7},{"id":"le-petit-prince-2cd-12-008","lineIndex":8,"speaker":"Le Petit Prince","original":"Elle est belle, mais un peu menteuse.","ipa":"/ɛl ɛ bɛl mɛz œ̃ pø mɑ̃tøz/","zh":"她很美，可有点爱说谎。","en":"She is beautiful, but a bit of a liar.","note":"","sourceLineIndex":8},{"id":"le-petit-prince-2cd-12-009","lineIndex":9,"speaker":"La Rose","original":"Ah! Sans trop vous déranger","ipa":"/a sɑ̃ tʁo vu deʁɑ̃ʒe/","zh":"啊！要是不太麻烦您","en":"Ah! Without troubling you too much","note":"","sourceLineIndex":9},{"id":"le-petit-prince-2cd-12-010","lineIndex":10,"speaker":"La Rose","original":"Ah! Pourriez-vous m'apporter","ipa":"/a puʁjevu mapɔʁte/","zh":"啊！您能不能给我拿来","en":"Ah! Could you bring me","note":"","sourceLineIndex":10},{"id":"le-petit-prince-2cd-12-011","lineIndex":11,"speaker":"La Rose","original":"Juste un petit déjeuner?","ipa":"/ʒyst œ̃ pəti deʒøne/","zh":"一点早餐？","en":"Just a little breakfast?","note":"","sourceLineIndex":11},{"id":"le-petit-prince-2cd-12-012","lineIndex":12,"speaker":"La Rose","original":"Je prendrais bien quelques gouttes de rosée.","ipa":"/ʒə pʁɑ̃dʁɛ bjɛ̃ kɛlkə ɡut də ʁoze/","zh":"我很想要几滴露水。","en":"I would quite like a few drops of dew.","note":"","sourceLineIndex":12},{"id":"le-petit-prince-2cd-12-013","lineIndex":13,"speaker":"Le Petit Prince","original":"Elle est belle, mais un peu capricieuse.","ipa":"/ɛl ɛ bɛl mɛz œ̃ pø kapʁisjøz/","zh":"她很美，可有点任性。","en":"She is beautiful, but a little capricious.","note":"","sourceLineIndex":13},{"id":"le-petit-prince-2cd-12-014","lineIndex":14,"speaker":"La Rose","original":"Ah! Avec mes quatre épines","ipa":"/a avɛk me katʁ epin/","zh":"啊！有我这四根刺","en":"Ah! With my four thorns","note":"","sourceLineIndex":14},{"id":"le-petit-prince-2cd-12-015","lineIndex":15,"speaker":"La Rose","original":"Ah! Je ne me laisse pas prendre","ipa":"/a ʒə nə mə lɛs pa pʁɑ̃dʁ/","zh":"啊！我可不会让人捉住","en":"Ah! I will not let myself be caught","note":"","sourceLineIndex":15},{"id":"le-petit-prince-2cd-12-016","lineIndex":16,"speaker":"La Rose","original":"Moi je n'ai pas peur des tigres","ipa":"/mwa ʒə ne pa pœʁ de tiɡʁ/","zh":"我可不怕老虎","en":"I am not afraid of tigers","note":"","sourceLineIndex":16},{"id":"le-petit-prince-2cd-12-017","lineIndex":17,"speaker":"La Rose","original":"Ils peuvent toujours venir, je sais me défendre.","ipa":"/il pøv tuʒuʁ vəniʁ ʒə sɛ mə defɑ̃dʁ/","zh":"它们尽管来，我知道怎么保护自己。","en":"They can come if they like; I know how to defend myself.","note":"","sourceLineIndex":17},{"id":"le-petit-prince-2cd-12-018","lineIndex":18,"speaker":"Le Petit Prince","original":"Elle est belle, mais un peu prétentieuse.","ipa":"/ɛl ɛ bɛl mɛz œ̃ pø pʁetɑ̃sjøz/","zh":"她很美，可有点自命不凡。","en":"She is beautiful, but a little pretentious.","note":"","sourceLineIndex":18},{"id":"le-petit-prince-2cd-12-019","lineIndex":19,"speaker":"La Rose","original":"Ah! J'ai toujours un peu froid.","ipa":"/a ʒe tuʒuʁz œ̃ pø fʁwa/","zh":"啊！我总觉得有点冷。","en":"Ah! I am always a little cold.","note":"","sourceLineIndex":19},{"id":"le-petit-prince-2cd-12-020","lineIndex":20,"speaker":"La Rose","original":"Ah! Je hais les courants d'air.","ipa":"/a ʒə ɛ le kuʁɑ̃ dɛʁ/","zh":"啊！我讨厌穿堂风。","en":"Ah! I hate drafts.","note":"","sourceLineIndex":20},{"id":"le-petit-prince-2cd-12-021","lineIndex":21,"speaker":"La Rose","original":"J'aime tant qu'on prenne soin de moi.","ipa":"/ʒɛm tɑ̃ kɔ̃ pʁɛn swɛ̃ də mwa/","zh":"我最喜欢有人照料我。","en":"I so love being taken care of.","note":"","sourceLineIndex":21},{"id":"le-petit-prince-2cd-12-022","lineIndex":22,"speaker":"La Rose","original":"Vous n'auriez pas par hasard un paravent?","ipa":"/vu noʁje pa paʁ azaʁ œ̃ paʁav/","zh":"您碰巧有一扇屏风吗？","en":"You would not happen to have a screen, would you?","note":"","sourceLineIndex":22},{"id":"le-petit-prince-2cd-12-023","lineIndex":23,"speaker":"Le Petit Prince","original":"Non.","ipa":"/nɔ̃/","zh":"没有。","en":"No.","note":"","sourceLineIndex":23},{"id":"le-petit-prince-2cd-12-024","lineIndex":24,"speaker":"Le Petit Prince","original":"Il n'y a pas de tigre sur ma planète, et les tigres, ça ne mange pas d'herbes.","ipa":"/il ni a pa də tiɡʁ syʁ ma planɛt e le tiɡʁ sa nə mɑ̃ʒ pa dɛʁb/","zh":"我的星球上没有老虎；再说，老虎不吃草。","en":"There are no tigers on my planet, and tigers do not eat grass.","note":"","sourceLineIndex":24},{"id":"le-petit-prince-2cd-12-025","lineIndex":25,"speaker":"La Rose","original":"Je ne suis pas une herbe.","ipa":"/ʒə nə syi paz yn ɛʁb/","zh":"我可不是草。","en":"I am not a blade of grass.","note":"","sourceLineIndex":25},{"id":"le-petit-prince-2cd-12-026","lineIndex":26,"speaker":"La Rose","original":"De toute façon, le soir vous me mettrez sous globe.","ipa":"/də tut fasɔ̃ lə swaʁ vu mə mɛtʁe su ɡlɔb/","zh":"不管怎样，晚上您得把我罩在玻璃罩里。","en":"In any case, in the evening you will put me under a glass globe.","note":"","sourceLineIndex":26},{"id":"le-petit-prince-2cd-12-027","lineIndex":27,"speaker":"Le Petit Prince","original":"Euh?","ipa":"/œ/","zh":"呃？","en":"Uh?","note":"","sourceLineIndex":27},{"id":"le-petit-prince-2cd-12-028","lineIndex":28,"speaker":"La Rose","original":"Il fait très froid chez vous.","ipa":"/il fɛ tʁɛ fʁwa ʃe vu/","zh":"您这里实在太冷了。","en":"It is very cold where you live.","note":"","sourceLineIndex":28},{"id":"le-petit-prince-2cd-12-029","lineIndex":29,"speaker":"La Rose","original":"C'est mal installé. Là d'où je viens...","ipa":"/sɛ mal ɛ̃stale la du ʒə vjɛ̃/","zh":"这儿安置得不好。我原来来的地方……","en":"It is poorly arranged here. Where I come from...","note":"","sourceLineIndex":29},{"id":"le-petit-prince-2cd-12-030","lineIndex":30,"speaker":"Le Petit Prince","original":"Chut","ipa":"/ʃy/","zh":"嘘。","en":"Hush.","note":"","sourceLineIndex":30},{"id":"le-petit-prince-2cd-12-031","lineIndex":31,"speaker":"La Rose","original":"Oh, pardon!","ipa":"/ɔ paʁdɔ̃/","zh":"噢，抱歉！","en":"Oh, pardon!","note":"","sourceLineIndex":31},{"id":"le-petit-prince-2cd-12-032","lineIndex":32,"speaker":"La Rose","original":"Ah, des oies sauvages!","ipa":"/a dez wa sovaʒ/","zh":"啊，野雁！","en":"Ah, wild geese!","note":"","sourceLineIndex":32},{"id":"le-petit-prince-2cd-12-033","lineIndex":33,"speaker":"La Rose","original":"Si, si!","ipa":"/si si/","zh":"对，对！","en":"Yes, yes!","note":"","sourceLineIndex":33},{"id":"le-petit-prince-2cd-12-034","lineIndex":34,"speaker":"Le Petit Prince","original":"Ah, je ne veux plus l'écouter","ipa":"/a ʒə nə vø ply lekute/","zh":"啊，我不想再听她说下去了","en":"Ah, I do not want to listen to her any more","note":"","sourceLineIndex":34},{"id":"le-petit-prince-2cd-12-035","lineIndex":35,"speaker":"Le Petit Prince","original":"Ah, il vaut mieux se sauver","ipa":"/a il vo mjø sə sove/","zh":"啊，还是赶紧离开为好","en":"Ah, it is better to make one's escape","note":"","sourceLineIndex":35},{"id":"le-petit-prince-2cd-12-036","lineIndex":36,"speaker":"Le Petit Prince","original":"Je prendrai le premier vol","ipa":"/ʒə pʁɑ̃dʁe lə pʁəmje vɔl/","zh":"我会搭上第一班","en":"I will take the first flight","note":"","sourceLineIndex":36},{"id":"le-petit-prince-2cd-12-037","lineIndex":37,"speaker":"Le Petit Prince","original":"D'oiseaux sauvages qui voudront m'emporter.","ipa":"/dwazo sovaʒ ki vudʁɔ̃ mɑ̃pɔʁte/","zh":"愿意带我离开的野雁。","en":"Of wild birds willing to carry me away.","note":"","sourceLineIndex":37},{"id":"le-petit-prince-2cd-12-038","lineIndex":38,"speaker":"Le Petit Prince","original":"Bon et bien voilà, je pars.","ipa":"/bɔ̃n e bjɛ̃ vwala ʒə paʁ/","zh":"好吧，就这样，我要走了。","en":"All right then, there it is: I am leaving.","note":"","sourceLineIndex":38},{"id":"le-petit-prince-2cd-12-039","lineIndex":39,"speaker":"Le Petit Prince","original":"J'ai fait tout ce que je pouvais.","ipa":"/ʒe fɛ tu sə kə ʒə puvɛ/","zh":"我已经尽了全力。","en":"I have done all I could.","note":"","sourceLineIndex":39},{"id":"le-petit-prince-2cd-12-040","lineIndex":40,"speaker":"Le Petit Prince","original":"Les volcans sont ramonés","ipa":"/le vɔlkɑ̃ sɔ̃ ʁamone/","zh":"火山都已清理干净。","en":"The volcanoes have been swept out.","note":"","sourceLineIndex":40},{"id":"le-petit-prince-2cd-12-041","lineIndex":41,"speaker":"Le Petit Prince","original":"Est-ce que tu veux ton globe pour la nuit?","ipa":"/ɛs kə ty vø tɔ̃ ɡlɔb puʁ la nyi/","zh":"你夜里要你的玻璃罩吗？","en":"Do you want your glass globe for the night?","note":"","sourceLineIndex":41}],"sourceOrder":12,"displayOrder":12},{"order":13,"id":"13-adieu-et-tache-d-etre-heureux","title":"Adieu (Et TÂChe D'ÊTre Heureux)","titleZh":"后会无期","lines":[{"id":"le-petit-prince-2cd-13-001","lineIndex":1,"speaker":"","original":"Adieu","ipa":"/adjø/","zh":"再见","en":"Goodbye","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-13-002","lineIndex":2,"speaker":"","original":"Et tâche d'être heureux","ipa":"/e taːʃ dɛtʁ øʁø/","zh":"而且要努力幸福","en":"And try to be happy","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-13-003","lineIndex":3,"speaker":"","original":"J'ai perdu du temps","ipa":"/ʒe pɛʁdy dy tɑ̃/","zh":"我浪费了时间","en":"I wasted time","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-13-004","lineIndex":4,"speaker":"","original":"On est tellement bête à vouloir cacher tous nos sentiments","ipa":"/ɔ̃n ɛ tɛlmɑ̃ bɛt a vulwaʁ kaʃe tu no sɑ̃timɑ̃/","zh":"想把所有感情藏起来，我们真是太傻了","en":"We are so foolish to want to hide all our feelings","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-13-005","lineIndex":5,"speaker":"","original":"Voilà que tu pars","ipa":"/vwala kə ty paʁ/","zh":"如今你就要走了","en":"Now you are leaving","note":"","sourceLineIndex":5},{"id":"le-petit-prince-2cd-13-006","lineIndex":6,"speaker":"","original":"Je te demande pardon","ipa":"/ʒə tə dəmɑ̃d paʁdɔ̃/","zh":"我请求你原谅","en":"I ask your forgiveness","note":"","sourceLineIndex":6},{"id":"le-petit-prince-2cd-13-007","lineIndex":7,"speaker":"","original":"J'aurais dû te dire","ipa":"/ʒoʁɛ dyː tə diʁ/","zh":"我本该告诉你","en":"I should have told you","note":"","sourceLineIndex":7},{"id":"le-petit-prince-2cd-13-008","lineIndex":8,"speaker":"","original":"Depuis si longtemps que je t'aimais tant","ipa":"/dəpyi si lɔ̃tɑ̃ kə ʒə tɛmɛ tɑ̃/","zh":"我已经爱你那么久、那么深","en":"For so long I have loved you so much","note":"","sourceLineIndex":8},{"id":"le-petit-prince-2cd-13-009","lineIndex":9,"speaker":"","original":"Va, maintenant va t'en","ipa":"/va mɛ̃tnɑ̃ va tɑ̃/","zh":"走吧，现在就走吧","en":"Go, now go away","note":"","sourceLineIndex":9},{"id":"le-petit-prince-2cd-13-010","lineIndex":10,"speaker":"","original":"J'apprendrai sans toi à aimer le vent l'air frais de la nuit","ipa":"/ʒapʁɑ̃dʁe sɑ̃ twa a ɛme lə vɑ̃ lɛʁ fʁɛ də la nyi/","zh":"没有你，我会学着去爱风和夜里的清凉空气","en":"Without you, I will learn to love the wind and the cool night air","note":"","sourceLineIndex":10},{"id":"le-petit-prince-2cd-13-011","lineIndex":11,"speaker":"","original":"J'apprendrai sans toi avec les chenilles et les papillons à tromper l'ennui","ipa":"/ʒapʁɑ̃dʁe sɑ̃ twa avɛk le ʃənijz e le papijɔ̃z a tʁɔ̃pe lɑ̃nyi/","zh":"没有你，我会和毛毛虫、蝴蝶一起学着排遣无聊","en":"Without you, I will learn to stave off boredom with caterpillars and butterflies","note":"","sourceLineIndex":11},{"id":"le-petit-prince-2cd-13-012","lineIndex":12,"speaker":"","original":"Ne traîne pas, adieu","ipa":"/nə tʁɛn pa adjø/","zh":"别再拖延了，再见","en":"Do not linger; goodbye","note":"","sourceLineIndex":12},{"id":"le-petit-prince-2cd-13-013","lineIndex":13,"speaker":"","original":"Et tâche d'être heureux","ipa":"/e taːʃ dɛtʁ øʁø/","zh":"而且要努力幸福","en":"And try to be happy","note":"","sourceLineIndex":13}],"sourceOrder":13,"displayOrder":13},{"order":14,"id":"14-le-roi","title":"Le Roi","titleZh":"国王","lines":[{"id":"le-petit-prince-2cd-14-001","lineIndex":1,"speaker":"Le Roi","original":"Ah, voilà un sujet.","ipa":"/a vwala œ̃ syʒɛ/","zh":"啊，来了一位臣民。","en":"Ah, here is a subject.","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-14-002","lineIndex":2,"speaker":"Le Petit Prince","original":"Mais vous ne me connaissez pas!","ipa":"/mɛ vu nə mə kɔnɛse pa/","zh":"可您并不认识我！","en":"But you do not know me!","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-14-003","lineIndex":3,"speaker":"Le Roi","original":"Mais tous les hommes sont mes sujets.","ipa":"/mɛ tu lez ɔm sɔ̃ me syʒɛ/","zh":"可所有人都是我的臣民。","en":"But all men are my subjects.","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-14-004","lineIndex":4,"speaker":"Le Petit Prince","original":"Ah bon.","ipa":"/a bɔ̃/","zh":"噢，是吗。","en":"Oh, really.","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-14-005","lineIndex":5,"speaker":"Le Roi","original":"On ne baille pas.","ipa":"/ɔ̃ nə baj pa/","zh":"不许打哈欠。","en":"One does not yawn.","note":"","sourceLineIndex":5},{"id":"le-petit-prince-2cd-14-006","lineIndex":6,"speaker":"Le Petit Prince","original":"Mais je suis fatigué…","ipa":"/mɛ ʒə syi fatiɡe/","zh":"可我累了……","en":"But I am tired...","note":"","sourceLineIndex":6},{"id":"le-petit-prince-2cd-14-007","lineIndex":7,"speaker":"Le Roi","original":"Mais on ne parle pas. Et on ne s'assied pas.","ipa":"/mɛz ɔ̃ nə paʁl pa e ɔ̃ nə ɛsasɪd pa/","zh":"不许说话，也不许坐下。","en":"But one does not speak. And one does not sit down.","note":"","sourceLineIndex":7},{"id":"le-petit-prince-2cd-14-008","lineIndex":8,"speaker":"Le Petit Prince","original":"Mais je suis fatigué, votre Majesté","ipa":"/mɛ ʒə syi fatiɡe votʁ maʒɛste/","zh":"可我累了，陛下。","en":"But I am tired, Your Majesty.","note":"","sourceLineIndex":8},{"id":"le-petit-prince-2cd-14-009","lineIndex":9,"speaker":"Le Petit Prince","original":"et je m'ennuie déjà.","ipa":"/e ʒə mɑ̃nyi deʒa/","zh":"而且我已经觉得无聊了。","en":"And I am already bored.","note":"","sourceLineIndex":9},{"id":"le-petit-prince-2cd-14-010","lineIndex":10,"speaker":"Le Petit Prince","original":"Et je crois bien que je vais repartir.","ipa":"/e ʒə kʁwa bjɛ̃ kə ʒə vɛ ʁəpaʁtiʁ/","zh":"我想我还是要走了。","en":"And I think I am going to leave again.","note":"","sourceLineIndex":10},{"id":"le-petit-prince-2cd-14-011","lineIndex":11,"speaker":"Le Roi","original":"Non, attends","ipa":"/nɔ̃ atɑ̃/","zh":"不，等等。","en":"No, wait.","note":"","sourceLineIndex":11}],"sourceOrder":14,"displayOrder":14},{"order":15,"id":"15-je-t-ordonne","title":"Je T'ordonne","titleZh":"我命令你","lines":[{"id":"le-petit-prince-2cd-15-001","lineIndex":1,"speaker":"","original":"Je t'ordonne de bâiller","ipa":"/ʒə tɔʁdɔn də baje/","zh":"我命令你打哈欠","en":"I order you to yawn","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-15-002","lineIndex":2,"speaker":"","original":"Je t'ordonne de parler","ipa":"/ʒə tɔʁdɔn də paʁle/","zh":"我命令你说话","en":"I order you to speak","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-15-003","lineIndex":3,"speaker":"","original":"Je t'ordonne de t'asseoir","ipa":"/ʒə tɔʁdɔn də taswaʁ/","zh":"我命令你坐下","en":"I order you to sit down","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-15-004","lineIndex":4,"speaker":"","original":"Et de m'interroger","ipa":"/e də mɛ̃tɛʁoʒe/","zh":"还命令你向我提问","en":"And to question me","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-15-005","lineIndex":5,"speaker":"","original":"Je t'ordonne d'arrêter!","ipa":"/ʒə tɔʁdɔn daʁɛte/","zh":"我命令你停下！","en":"I order you to stop!","note":"","sourceLineIndex":5},{"id":"le-petit-prince-2cd-15-006","lineIndex":6,"speaker":"","original":"Moi je règne sur tout","ipa":"/mwa ʒə ʁɛɲ syʁ tu/","zh":"我统治一切","en":"I reign over everything","note":"","sourceLineIndex":6},{"id":"le-petit-prince-2cd-15-007","lineIndex":7,"speaker":"","original":"Ce qui tourne autour de nous","ipa":"/sə ki tuʁn otuʁ də nu/","zh":"统治围绕我们转动的一切","en":"Everything that turns around us","note":"","sourceLineIndex":7},{"id":"le-petit-prince-2cd-15-008","lineIndex":8,"speaker":"","original":"Monarque universel","ipa":"/monaʁk ynivɛʁsɛl/","zh":"我是宇宙君主","en":"Universal monarch","note":"","sourceLineIndex":8},{"id":"le-petit-prince-2cd-15-009","lineIndex":9,"speaker":"","original":"Des étoiles et du ciel","ipa":"/dez etwalz e dy sjɛl/","zh":"统治群星与天空","en":"Of the stars and the sky","note":"","sourceLineIndex":9},{"id":"le-petit-prince-2cd-15-010","lineIndex":10,"speaker":"","original":"Et je ne tolère pas","ipa":"/e ʒə nə tolɛʁ pa/","zh":"我绝不容忍","en":"And I do not tolerate","note":"","sourceLineIndex":10},{"id":"le-petit-prince-2cd-15-011","lineIndex":11,"speaker":"","original":"La désobéissance","ipa":"/la dezobeisɑ̃s/","zh":"不服从","en":"Disobedience","note":"","sourceLineIndex":11},{"id":"le-petit-prince-2cd-15-012","lineIndex":12,"speaker":"","original":"Mes ordres sont raisonnables","ipa":"/mez ɔʁdʁ sɔ̃ ʁɛzɔnabl/","zh":"我的命令都合乎理性","en":"My orders are reasonable","note":"","sourceLineIndex":12},{"id":"le-petit-prince-2cd-15-013","lineIndex":13,"speaker":"","original":"On peut me faire confiance","ipa":"/ɔ̃ pø mə fɛʁ kɔ̃fjɑ̃s/","zh":"可以信任我","en":"You can trust me","note":"","sourceLineIndex":13},{"id":"le-petit-prince-2cd-15-014","lineIndex":14,"speaker":"","original":"Par contre si j'ordonnais","ipa":"/paʁ kɔ̃tʁ si ʒɔʁdɔnɛ/","zh":"不过，如果我命令","en":"On the other hand, if I ordered","note":"","sourceLineIndex":14},{"id":"le-petit-prince-2cd-15-015","lineIndex":15,"speaker":"","original":"A quelconque général","ipa":"/a kɛlkɔ̃k ʒeneʁal/","zh":"某一位将军","en":"Some general","note":"","sourceLineIndex":15},{"id":"le-petit-prince-2cd-15-016","lineIndex":16,"speaker":"","original":"De voler de fleur en fleur","ipa":"/də vole də flœʁ ɑ̃ flœʁ/","zh":"从一朵花飞到另一朵花","en":"To fly from flower to flower","note":"","sourceLineIndex":16},{"id":"le-petit-prince-2cd-15-017","lineIndex":17,"speaker":"","original":"Ou si j'exigeais de mon peuple","ipa":"/u si ʒɛɡziʒɛ də mɔ̃ pøpl/","zh":"或者如果我要求我的人民","en":"Or if I demanded of my people","note":"","sourceLineIndex":17},{"id":"le-petit-prince-2cd-15-018","lineIndex":18,"speaker":"","original":"Qu'ils se jettent à la mer","ipa":"/kil sə ʒɛtt a la mɛʁ/","zh":"投海而去","en":"That they throw themselves into the sea","note":"","sourceLineIndex":18},{"id":"le-petit-prince-2cd-15-019","lineIndex":19,"speaker":"","original":"S'ils n'obéissaient pas","ipa":"/sil nobeisɛ pa/","zh":"要是他们不服从","en":"If they did not obey","note":"","sourceLineIndex":19},{"id":"le-petit-prince-2cd-15-020","lineIndex":20,"speaker":"","original":"Et s'ils se révoltaient","ipa":"/e sil sə ʁevɔltɛ/","zh":"并且反抗","en":"And if they rebelled","note":"","sourceLineIndex":20},{"id":"le-petit-prince-2cd-15-021","lineIndex":21,"speaker":"","original":"Ils seraient dans leur droit","ipa":"/il səʁɛ dɑ̃ lœʁ dʁwa/","zh":"他们就有理","en":"They would be within their rights","note":"","sourceLineIndex":21},{"id":"le-petit-prince-2cd-15-022","lineIndex":22,"speaker":"","original":"Alors celui qui aurait tort","ipa":"/alɔʁ səlyi ki oʁɛ tɔʁ/","zh":"那么犯错的人","en":"Then the one who would be wrong","note":"","sourceLineIndex":22},{"id":"le-petit-prince-2cd-15-023","lineIndex":23,"speaker":"","original":"Bien sûr ce serait moi","ipa":"/bjɛ̃ syːʁ sə səʁɛ mwa/","zh":"当然会是我","en":"Would of course be me","note":"","sourceLineIndex":23},{"id":"le-petit-prince-2cd-15-024","lineIndex":24,"speaker":"","original":"L'autorité repose d'abord sur la raison","ipa":"/lotoʁite ʁəpɔz dabɔʁ syʁ la ʁɛzɔ̃/","zh":"权威首先建立在理性之上","en":"Authority rests first on reason","note":"","sourceLineIndex":24},{"id":"le-petit-prince-2cd-15-025","lineIndex":25,"speaker":"","original":"Il faut exiger de chacun ce que chacun peut donner","ipa":"/il fot ɛɡziʒe də ʃakœ̃ sə kə ʃakœ̃ pø dɔne/","zh":"必须向每个人只要求他做得到的事","en":"One must demand from each person what each person can give","note":"","sourceLineIndex":25}],"sourceOrder":15,"displayOrder":15},{"order":16,"id":"16-un-monarque-absolu","title":"Un Monarque Absolu","titleZh":"专制君主","lines":[{"id":"le-petit-prince-2cd-16-001","lineIndex":1,"speaker":"Le Petit Prince","original":"Et sur quoi régnez-vous?","ipa":"/e syʁ kwa ʁenjevu/","zh":"那您统治什么呢？","en":"And what do you reign over?","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-16-002","lineIndex":2,"speaker":"Le Roi","original":"Sur tout. Je suis un monarque absolu et universel.","ipa":"/syʁ tu ʒə syiz œ̃ monaʁk absoly e ynivɛʁsɛl/","zh":"统治一切。我是绝对而普世的君主。","en":"Over everything. I am an absolute and universal monarch.","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-16-003","lineIndex":3,"speaker":"Le Petit Prince","original":"Même les étoiles vous obéissent?","ipa":"/mɛm lez etwal vuz obeis/","zh":"连星星也服从您吗？","en":"Even the stars obey you?","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-16-004","lineIndex":4,"speaker":"Le Roi","original":"Bien sûr. Je ne tolère pas l'indiscipline.","ipa":"/bjɛ̃ syːʁ ʒə nə tolɛʁ pa lɛ̃disiplin/","zh":"当然。我不容忍不守纪律。","en":"Of course. I do not tolerate indiscipline.","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-16-005","lineIndex":5,"speaker":"Le Petit Prince","original":"Dans ce cas, faites-moi plaisir.","ipa":"/dɑ̃ sə ka fɛtmwa plɛziʁ/","zh":"既然这样，请满足我一个心愿。","en":"In that case, grant me a favour.","note":"","sourceLineIndex":5},{"id":"le-petit-prince-2cd-16-006","lineIndex":6,"speaker":"Le Petit Prince","original":"Ordonnez au soleil de se coucher.","ipa":"/ɔʁdɔnez o solɛj də sə kuʃe/","zh":"命令太阳落下去。","en":"Order the sun to set.","note":"","sourceLineIndex":6},{"id":"le-petit-prince-2cd-16-007","lineIndex":7,"speaker":"Le Roi","original":"Je l'y obligerai.","ipa":"/ʒə li ɔbliʒʁe/","zh":"我会命令它这么做。","en":"I will make it do so.","note":"","sourceLineIndex":7},{"id":"le-petit-prince-2cd-16-008","lineIndex":8,"speaker":"Le Roi","original":"Mais j'attendrai dans la science de mon gouvernement que les conditions soient favorables.","ipa":"/mɛ ʒatɑ̃dʁe dɑ̃ la sjɑ̃s də mɔ̃ ɡuvɛʁnəmɑ̃ kə le kɔ̃disjɔ̃ swa favoʁabl/","zh":"但依据我的治国之道，我会等到条件合适时再下令。","en":"But according to the science of my government, I will wait until conditions are favourable.","note":"","sourceLineIndex":8},{"id":"le-petit-prince-2cd-16-009","lineIndex":9,"speaker":"Le Petit Prince","original":"Et quand cela sera-t-il?","ipa":"/e kɑ̃ səla səʁatil/","zh":"那会是什么时候？","en":"And when will that be?","note":"","sourceLineIndex":9},{"id":"le-petit-prince-2cd-16-010","lineIndex":10,"speaker":"Le Roi","original":"Ce soir. Vers... sept heures quarante.","ipa":"/sə swaʁ vɛʁ sɛt œʁ kaʁɑ̃t/","zh":"今晚。大约……七点四十。","en":"This evening. Around... seven forty.","note":"","sourceLineIndex":10},{"id":"le-petit-prince-2cd-16-011","lineIndex":11,"speaker":"Le Roi","original":"Tu verras comme je suis bien obéi.","ipa":"/ty vɛʁa kɔm ʒə syi bjɛ̃n obei/","zh":"你会看见大家多么服从我。","en":"You will see how well I am obeyed.","note":"","sourceLineIndex":11},{"id":"le-petit-prince-2cd-16-012","lineIndex":12,"speaker":"Le Petit Prince","original":"J'ai compris. Je vais repartir.","ipa":"/ʒe kɔ̃pʁi ʒə vɛ ʁəpaʁtiʁ/","zh":"我明白了。我会继续上路。","en":"I understand. I am going to leave again.","note":"","sourceLineIndex":12},{"id":"le-petit-prince-2cd-16-013","lineIndex":13,"speaker":"Le Roi","original":"Non, ne pars pas, je te fais ministre de la justice.","ipa":"/nɔ̃ nə paʁ pa ʒə tə fɛ ministʁ də la ʒystis/","zh":"不，别走，我任命你为司法大臣。","en":"No, do not leave; I will make you minister of justice.","note":"","sourceLineIndex":13},{"id":"le-petit-prince-2cd-16-014","lineIndex":14,"speaker":"Le Petit Prince","original":"Il n'y a personne sur votre planète!","ipa":"/il ni a pɛʁsɔn syʁ votʁ planɛt/","zh":"您的星球上根本没有人！","en":"There is no one on your planet!","note":"","sourceLineIndex":14},{"id":"le-petit-prince-2cd-16-015","lineIndex":15,"speaker":"Le Roi","original":"Ah, mais tu te jugeras donc toi-même.","ipa":"/a mɛ ty tə ʒyʒʁa dɔ̃k twamɛm/","zh":"啊，那你就审判自己吧。","en":"Ah, then you will judge yourself.","note":"","sourceLineIndex":15},{"id":"le-petit-prince-2cd-16-016","lineIndex":16,"speaker":"Le Roi","original":"Il est bien plus difficile de se juger soi-même que de juger autrui.","ipa":"/il ɛ bjɛ̃ ply difisil də sə ʒyʒe swamɛm kə də ʒyʒe otʁyi/","zh":"审判自己比审判别人难得多。","en":"It is far more difficult to judge oneself than to judge others.","note":"","sourceLineIndex":16},{"id":"le-petit-prince-2cd-16-017","lineIndex":17,"speaker":"Le Petit Prince","original":"Je puis me juger moi-même n'importe où","ipa":"/ʒə pyi mə ʒyʒe mwamɛm nɛ̃pɔʁt u/","zh":"我在哪儿都可以审判自己","en":"I can judge myself anywhere","note":"","sourceLineIndex":17},{"id":"le-petit-prince-2cd-16-018","lineIndex":18,"speaker":"Le Petit Prince","original":"je n'ai pas besoin d'habiter ici. Adieu.","ipa":"/ʒə ne pa bəzwɛ̃ dabite isi adjø/","zh":"我不必住在这里。再见。","en":"I do not need to live here. Goodbye.","note":"","sourceLineIndex":18},{"id":"le-petit-prince-2cd-16-019","lineIndex":19,"speaker":"Le Roi","original":"Non, attends.","ipa":"/nɔ̃ atɑ̃/","zh":"不，等等。","en":"No, wait.","note":"","sourceLineIndex":19},{"id":"le-petit-prince-2cd-16-020","lineIndex":20,"speaker":"Le Roi","original":"Je crois qu'il y a quelque part un vieux rat que j'entends courir la nuit.","ipa":"/ʒə kʁwa kil i a kɛlkə paʁ œ̃ vjø ʁa kə ʒɑ̃tɑ̃ kuʁiʁ la nyi/","zh":"我想某个地方有一只老鼠，我夜里能听见它跑动。","en":"I think there is an old rat somewhere that I hear running at night.","note":"","sourceLineIndex":20},{"id":"le-petit-prince-2cd-16-021","lineIndex":21,"speaker":"Le Roi","original":"Tu le condamneras à mort de temps en temps","ipa":"/ty lə kɔ̃danʁaz a mɔʁ də tɑ̃zɑ̃tɑ̃/","zh":"你可以时不时判它死刑","en":"From time to time, you will sentence it to death","note":"","sourceLineIndex":21},{"id":"le-petit-prince-2cd-16-022","lineIndex":22,"speaker":"Le Roi","original":"mais tu le gracieras chaque fois pour l'économiser","ipa":"/mɛ ty lə ɡʁasiʁa ʃak fwa puʁ lekonomize/","zh":"可每次都要赦免它，好让它活下去","en":"But you will pardon it each time, to spare it","note":"","sourceLineIndex":22},{"id":"le-petit-prince-2cd-16-023","lineIndex":23,"speaker":"Le Roi","original":"il n'y en a qu'un.","ipa":"/il ni ɑ̃n a kœ̃/","zh":"因为只有这一只。","en":"There is only one.","note":"","sourceLineIndex":23},{"id":"le-petit-prince-2cd-16-024","lineIndex":24,"speaker":"Le Petit Prince","original":"Je n'aime pas condamner à mort","ipa":"/ʒə nɛm pa kɔ̃dane a mɔʁ/","zh":"我不喜欢判人死刑","en":"I do not like sentencing anyone to death","note":"","sourceLineIndex":24},{"id":"le-petit-prince-2cd-16-025","lineIndex":25,"speaker":"Le Petit Prince","original":"et je crois bien que je m'en vais.","ipa":"/e ʒə kʁwa bjɛ̃ kə ʒə mɑ̃ vɛ/","zh":"我想我还是要走了。","en":"And I think I am leaving.","note":"","sourceLineIndex":25},{"id":"le-petit-prince-2cd-16-026","lineIndex":26,"speaker":"Le Roi","original":"Non.","ipa":"/nɔ̃/","zh":"不。","en":"No.","note":"","sourceLineIndex":26},{"id":"le-petit-prince-2cd-16-027","lineIndex":27,"speaker":"Le Petit Prince","original":"Ordonnez-moi, par exemple, de partir avant une minute.","ipa":"/ɔʁdɔnemwa paʁ ɛɡzɑ̃pl də paʁtiʁ avɑ̃ yn minyt/","zh":"比如，请命令我在一分钟内离开。","en":"For example, order me to leave within a minute.","note":"","sourceLineIndex":27},{"id":"le-petit-prince-2cd-16-028","lineIndex":28,"speaker":"Le Roi","original":"Non.","ipa":"/nɔ̃/","zh":"不。","en":"No.","note":"","sourceLineIndex":28},{"id":"le-petit-prince-2cd-16-029","lineIndex":29,"speaker":"Le Roi","original":"Je te fais mon ambassadeur, va.","ipa":"/ʒə tə fɛ mɔ̃n ɑ̃basadœʁ va/","zh":"我封你做我的大使，去吧。","en":"I make you my ambassador; go.","note":"","sourceLineIndex":29},{"id":"le-petit-prince-2cd-16-030","lineIndex":30,"speaker":"Le Petit Prince","original":"Les grandes personnes sont bien étranges.","ipa":"/le ɡʁɑ̃d pɛʁsɔn sɔ̃ bjɛ̃n etʁɑ̃ʒ/","zh":"大人们真是奇怪。","en":"Grown-ups are very strange.","note":"","sourceLineIndex":30}],"sourceOrder":16,"displayOrder":16},{"order":17,"id":"17-le-vaniteux","title":"Le Vaniteux","titleZh":"虚荣","lines":[{"id":"le-petit-prince-2cd-17-001","lineIndex":1,"speaker":"Le Vaniteux","original":"Ah, voilà la visite d'un admirateur.","ipa":"/a vwala la vizit dœ̃n admiʁatœʁ/","zh":"啊，来了一位崇拜者。","en":"Ah, here comes a visit from an admirer.","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-17-002","lineIndex":2,"speaker":"Le Petit Prince","original":"Ça, c'est un vaniteux.","ipa":"/sa sɛt œ̃ vanitø/","zh":"这人真虚荣。","en":"That is a vain man.","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-17-003","lineIndex":3,"speaker":"Le Petit Prince","original":"Vous avez un drôle de chapeau.","ipa":"/vuz avez œ̃ dʁoːl də ʃapo/","zh":"您的帽子真奇怪。","en":"You have a funny hat.","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-17-004","lineIndex":4,"speaker":"Le Vaniteux","original":"Mais c'est pour saluer, quand on m'acclame","ipa":"/mɛ sɛ puʁ salye kɑ̃t ɔ̃ maklam/","zh":"那是为了在别人向我欢呼时致意。","en":"But it is for greeting people when they cheer me.","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-17-005","lineIndex":5,"speaker":"Le Vaniteux","original":"Frappe dans tes mains.","ipa":"/fʁap dɑ̃ te mɛ̃/","zh":"拍拍手。","en":"Clap your hands.","note":"","sourceLineIndex":5}],"sourceOrder":17,"displayOrder":17},{"order":18,"id":"18-moi-je","title":"Moi, Je","titleZh":"我","lines":[{"id":"le-petit-prince-2cd-18-001","lineIndex":1,"speaker":"","original":"J'aime qu'on me jette des fleurs","ipa":"/ʒɛm kɔ̃ mə ʒɛt de flœʁ/","zh":"我喜欢别人向我献花。","en":"I love it when people throw flowers at me.","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-18-002","lineIndex":2,"speaker":"","original":"J'aime la lumière des projecteurs","ipa":"/ʒɛm la lymjɛʁ de pʁoʒɛktœʁ/","zh":"我喜欢聚光灯的光。","en":"I love the light of spotlights.","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-18-003","lineIndex":3,"speaker":"","original":"J'aime les flatteurs j'aime les honneurs","ipa":"/ʒɛm le flatœʁ ʒɛm lez ɔnœʁ/","zh":"我喜欢奉承者，也喜欢荣誉。","en":"I love flatterers; I love honours.","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-18-004","lineIndex":4,"speaker":"","original":"J'aime même les menteurs","ipa":"/ʒɛm mɛm le mɑ̃tœʁ/","zh":"我甚至喜欢骗子。","en":"I even love liars.","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-18-005","lineIndex":5,"speaker":"","original":"Quand ils savent me dire","ipa":"/kɑ̃t il sav mə diʁ/","zh":"只要他们懂得对我说","en":"When they know how to tell me","note":"","sourceLineIndex":5},{"id":"le-petit-prince-2cd-18-006","lineIndex":6,"speaker":"","original":"Ce que je veux entendre","ipa":"/sə kə ʒə vøz ɑ̃tɑ̃dʁ/","zh":"我想听的话。","en":"What I want to hear.","note":"","sourceLineIndex":6},{"id":"le-petit-prince-2cd-18-007","lineIndex":7,"speaker":"","original":"À quoi je peux prétendre","ipa":"/a kwa ʒə pø pʁetɑ̃dʁ/","zh":"我有资格奢望什么。","en":"What I can lay claim to.","note":"","sourceLineIndex":7},{"id":"le-petit-prince-2cd-18-008","lineIndex":8,"speaker":"","original":"J'aime les compliments","ipa":"/ʒɛm le kɔ̃plimɑ̃/","zh":"我喜欢恭维。","en":"I love compliments.","note":"","sourceLineIndex":8},{"id":"le-petit-prince-2cd-18-009","lineIndex":9,"speaker":"","original":"La chaleur des applaudissements","ipa":"/la ʃalœʁ dez aplodismɑ̃/","zh":"喜欢掌声的热度。","en":"The warmth of applause.","note":"","sourceLineIndex":9},{"id":"le-petit-prince-2cd-18-010","lineIndex":10,"speaker":"","original":"J'aime la gloire et tous ses égards","ipa":"/ʒɛm la ɡlwaʁ e tu sez eɡaʁ/","zh":"我喜欢荣耀和随之而来的敬意。","en":"I love glory and all the regard that comes with it.","note":"","sourceLineIndex":10},{"id":"le-petit-prince-2cd-18-011","lineIndex":11,"speaker":"","original":"J'aime tous ces boniments","ipa":"/ʒɛm tu se bonimɑ̃/","zh":"我喜欢这一切花言巧语。","en":"I love all that sweet talk.","note":"","sourceLineIndex":11},{"id":"le-petit-prince-2cd-18-012","lineIndex":12,"speaker":"","original":"Si je dois me sentir","ipa":"/si ʒə dwa mə sɑ̃tiʁ/","zh":"只要能让我觉得自己","en":"If it lets me feel","note":"","sourceLineIndex":12},{"id":"le-petit-prince-2cd-18-013","lineIndex":13,"speaker":"","original":"Ne serait-ce qu'un instant","ipa":"/nə səʁɛs kœ̃n ɛ̃stɑ̃/","zh":"哪怕只是一瞬间","en":"If only for a moment","note":"","sourceLineIndex":13},{"id":"le-petit-prince-2cd-18-014","lineIndex":14,"speaker":"","original":"Le plus intéressant","ipa":"/lə plyz ɛ̃teʁɛsɑ̃/","zh":"是最引人注目的。","en":"The most interesting.","note":"","sourceLineIndex":14},{"id":"le-petit-prince-2cd-18-015","lineIndex":15,"speaker":"","original":"Moi je suis le plus beau","ipa":"/mwa ʒə syi lə ply bo/","zh":"我最美。","en":"I am the most beautiful.","note":"","sourceLineIndex":15},{"id":"le-petit-prince-2cd-18-016","lineIndex":16,"speaker":"","original":"Moi je suis le plus riche","ipa":"/mwa ʒə syi lə ply ʁiʃ/","zh":"我最富有。","en":"I am the richest.","note":"","sourceLineIndex":16},{"id":"le-petit-prince-2cd-18-017","lineIndex":17,"speaker":"","original":"Moi je suis le plus drôle","ipa":"/mwa ʒə syi lə ply dʁoːl/","zh":"我最有趣。","en":"I am the funniest.","note":"","sourceLineIndex":17},{"id":"le-petit-prince-2cd-18-018","lineIndex":18,"speaker":"","original":"Moi je suis moi je suis moi","ipa":"/mwa ʒə syi mwa ʒə syi mwa/","zh":"我就是我，我就是我。","en":"I am me, I am me.","note":"","sourceLineIndex":18},{"id":"le-petit-prince-2cd-18-019","lineIndex":19,"speaker":"","original":"Moi je suis le meilleur de toute la planète","ipa":"/mwa ʒə syi lə mɛjœʁ də tut la planɛt/","zh":"我是整颗星球上最棒的人。","en":"I am the best on the whole planet.","note":"","sourceLineIndex":19},{"id":"le-petit-prince-2cd-18-020","lineIndex":20,"speaker":"","original":"Mais je suis toujours seul pour le reconnaître","ipa":"/mɛ ʒə syi tuʒuʁ sœl puʁ lə ʁəkɔnɛtʁ/","zh":"可总是只有我自己承认这一点。","en":"But I am always alone in acknowledging it.","note":"","sourceLineIndex":20},{"id":"le-petit-prince-2cd-18-021","lineIndex":21,"speaker":"","original":"J'aime tellement qu'on m'aime","ipa":"/ʒɛm tɛlmɑ̃ kɔ̃ mɛm/","zh":"我如此喜欢被爱。","en":"I love being loved so much.","note":"","sourceLineIndex":21},{"id":"le-petit-prince-2cd-18-022","lineIndex":22,"speaker":"","original":"Alors frappe des mains","ipa":"/alɔʁ fʁap de mɛ̃/","zh":"那就拍拍手。","en":"So clap your hands.","note":"","sourceLineIndex":22},{"id":"le-petit-prince-2cd-18-023","lineIndex":23,"speaker":"","original":"Admire-moi quand même","ipa":"/admiʁmwa kɑ̃ mɛm/","zh":"无论如何都崇拜我吧。","en":"Admire me anyway.","note":"","sourceLineIndex":23},{"id":"le-petit-prince-2cd-18-024","lineIndex":24,"speaker":"","original":"Tu me feras plaisir","ipa":"/ty mə fəʁa plɛziʁ/","zh":"你会让我高兴。","en":"You will please me.","note":"","sourceLineIndex":24},{"id":"le-petit-prince-2cd-18-025","lineIndex":25,"speaker":"","original":"J'aime tellement qu'on m'aime","ipa":"/ʒɛm tɛlmɑ̃ kɔ̃ mɛm/","zh":"我如此喜欢被爱。","en":"I love being loved so much.","note":"","sourceLineIndex":25}],"sourceOrder":18,"displayOrder":18},{"order":19,"id":"19-le-buveur","title":"Le Buveur","titleZh":"喝酒的人","lines":[{"id":"le-petit-prince-2cd-19-001","lineIndex":1,"speaker":"Le Petit Prince","original":"Je t'admire...","ipa":"/ʒə tadmiʁ/","zh":"我崇拜你……","en":"I admire you...","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-19-002","lineIndex":2,"speaker":"Le Vaniteux","original":"Oh oui...","ipa":"/ɔ wi/","zh":"噢，是啊……","en":"Oh yes...","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-19-003","lineIndex":3,"speaker":"Le Petit Prince","original":"Mais en quoi cela peut-il bien t'intéresser?","ipa":"/mɛz ɑ̃ kwa səla pøtil bjɛ̃ tɛ̃teʁɛse/","zh":"可这到底有什么能让你感兴趣呢？","en":"But how can that possibly interest you?","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-19-004","lineIndex":4,"speaker":"Le Petit Prince","original":"Les grandes personnes sont décidément bien bizarres.","ipa":"/le ɡʁɑ̃d pɛʁsɔn sɔ̃ desidemɑ̃ bjɛ̃ bizaʁ/","zh":"大人们真是奇怪得很。","en":"Grown-ups are decidedly very strange.","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-19-005","lineIndex":5,"speaker":"Le Petit Prince","original":"Que fais-tu là? Comme c'est triste!","ipa":"/kə fɛty la kɔm sɛ tʁist/","zh":"你在那儿做什么？真令人难过！","en":"What are you doing there? How sad!","note":"","sourceLineIndex":5}],"sourceOrder":19,"displayOrder":19},{"order":20,"id":"20-je-bois-pour-oublier","title":"Je Bois Pour Oublier","titleZh":"借酒释怀","lines":[{"id":"le-petit-prince-2cd-20-001","lineIndex":1,"speaker":"Le Buveur","original":"Plus rien ne me paraît très net","ipa":"/ply ʁjɛ̃ nə mə paʁɛ tʁɛ nɛt/","zh":"我觉得再没有什么清楚的了。","en":"Nothing seems very clear to me any more.","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-20-002","lineIndex":2,"speaker":"Le Buveur","original":"Vous êtes sur ma drôle de planète","ipa":"/vuz ɛt syʁ ma dʁoːl də planɛt/","zh":"您来到了我这颗古怪的星球。","en":"You are on my strange planet.","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-20-003","lineIndex":3,"speaker":"Le Buveur","original":"Tout est tordu tout est flou","ipa":"/tut ɛ tɔʁdy tut ɛ flu/","zh":"一切都扭曲，一切都模糊。","en":"Everything is twisted; everything is blurry.","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-20-004","lineIndex":4,"speaker":"Le Buveur","original":"Je suis tout sens dessus dessous","ipa":"/ʒə syi tu sɑ̃s dəsy dəsu/","zh":"我整个人都颠三倒四。","en":"I am completely upside down.","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-20-005","lineIndex":5,"speaker":"Le Buveur","original":"Je collectionne pour la peine","ipa":"/ʒə kɔlɛktjɔn puʁ la pɛn/","zh":"我为了排遣愁苦收集","en":"To ease the pain, I collect","note":"","sourceLineIndex":5},{"id":"le-petit-prince-2cd-20-006","lineIndex":6,"speaker":"Le Buveur","original":"Les bouteilles vides les bouteilles pleines","ipa":"/le butɛj vid le butɛj plɛn/","zh":"空酒瓶和满酒瓶。","en":"Empty bottles and full bottles.","note":"","sourceLineIndex":6},{"id":"le-petit-prince-2cd-20-007","lineIndex":7,"speaker":"Le Buveur","original":"Toi qui t'en viens vers moi","ipa":"/twa ki tɑ̃ vjɛ̃ vɛʁ mwa/","zh":"你正向我走来","en":"You who are coming toward me","note":"","sourceLineIndex":7},{"id":"le-petit-prince-2cd-20-008","lineIndex":8,"speaker":"Le Buveur","original":"Tu te demandes ce que je fais là","ipa":"/ty tə dəmɑ̃d sə kə ʒə fɛ la/","zh":"你在想我在这里做什么。","en":"You wonder what I am doing here.","note":"","sourceLineIndex":8},{"id":"le-petit-prince-2cd-20-009","lineIndex":9,"speaker":"Le Buveur","original":"Je bois pour oublier","ipa":"/ʒə bwa puʁ ublie/","zh":"我喝酒是为了忘记。","en":"I drink to forget.","note":"","sourceLineIndex":9},{"id":"le-petit-prince-2cd-20-010","lineIndex":10,"speaker":"Le Petit Prince","original":"Mais tu bois pour oublier quoi?","ipa":"/mɛ ty bwa puʁ ublie kwa/","zh":"可你喝酒是为了忘记什么？","en":"But what do you drink to forget?","note":"","sourceLineIndex":10},{"id":"le-petit-prince-2cd-20-011","lineIndex":11,"speaker":"Le Buveur","original":"Oublier que j'ai honte","ipa":"/ublie kə ʒe ɔ̃t/","zh":"忘掉我感到羞耻。","en":"To forget that I am ashamed.","note":"","sourceLineIndex":11},{"id":"le-petit-prince-2cd-20-012","lineIndex":12,"speaker":"Le Petit Prince","original":"Que tu as honte de quoi?","ipa":"/kə ty a ɔ̃t də kwa/","zh":"你为哪件事羞耻？","en":"Ashamed of what?","note":"","sourceLineIndex":12},{"id":"le-petit-prince-2cd-20-013","lineIndex":13,"speaker":"Le Buveur","original":"Que j'ai honte de boire","ipa":"/kə ʒe ɔ̃t də bwaʁ/","zh":"我为自己喝酒而羞耻。","en":"That I am ashamed of drinking.","note":"","sourceLineIndex":13},{"id":"le-petit-prince-2cd-20-014","lineIndex":14,"speaker":"Le Petit Prince","original":"Alors tu te ressers un verre","ipa":"/alɔʁ ty tə ʁəsez œ̃ vɛʁ/","zh":"可你却又给自己倒了一杯。","en":"And then you pour yourself another drink.","note":"","sourceLineIndex":14},{"id":"le-petit-prince-2cd-20-015","lineIndex":15,"speaker":"Le Buveur","original":"Je bois pour oublier","ipa":"/ʒə bwa puʁ ublie/","zh":"我喝酒是为了忘记。","en":"I drink to forget.","note":"","sourceLineIndex":15},{"id":"le-petit-prince-2cd-20-016","lineIndex":16,"speaker":"Le Buveur","original":"Pour oublier que je bois","ipa":"/puʁ ublie kə ʒə bwa/","zh":"为了忘掉我在喝酒。","en":"To forget that I drink.","note":"","sourceLineIndex":16},{"id":"le-petit-prince-2cd-20-017","lineIndex":17,"speaker":"Le Petit Prince","original":"Les grandes personnes sont décidément très, très bizarres.","ipa":"/le ɡʁɑ̃d pɛʁsɔn sɔ̃ desidemɑ̃ tʁɛ tʁɛ bizaʁ/","zh":"大人们真是、真是奇怪。","en":"Grown-ups are decidedly very, very strange.","note":"","sourceLineIndex":17}],"sourceOrder":20,"displayOrder":20},{"order":21,"id":"21-je-suis-un-homme-serieux","title":"Je Suis Un Homme SÉRieux","titleZh":"我是个正经人","lines":[{"id":"le-petit-prince-2cd-21-001","lineIndex":1,"speaker":"Le Petit Prince","original":"Bonjour!","ipa":"/bɔ̃ʒuʁ/","zh":"您好！","en":"Hello!","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-21-002","lineIndex":2,"speaker":"Le Petit Prince","original":"Votre cigarette est éteinte.","ipa":"/votʁ siɡaʁɛt ɛt etɛ̃t/","zh":"您的香烟已经熄灭了。","en":"Your cigarette has gone out.","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-21-003","lineIndex":3,"speaker":"Le Petit Prince","original":"Bonjour!","ipa":"/bɔ̃ʒuʁ/","zh":"您好！","en":"Hello!","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-21-004","lineIndex":4,"speaker":"Le Businessman","original":"Trois et deux font cinq","ipa":"/tʁwaz e dø fɔ̃ sɛ̃k/","zh":"三加二等于五","en":"Three and two make five","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-21-005","lineIndex":5,"speaker":"Le Businessman","original":"Et cinq plus sept font douze","ipa":"/e sɛ̃k ply sɛt fɔ̃ duz/","zh":"五加七等于十二","en":"And five plus seven make twelve","note":"","sourceLineIndex":5},{"id":"le-petit-prince-2cd-21-006","lineIndex":6,"speaker":"Le Businessman","original":"Et douze plus trois égalent bien quinze.","ipa":"/e duz ply tʁwaz eɡal bjɛ̃ kɛ̃z/","zh":"十二加三等于十五","en":"And twelve plus three equal fifteen.","note":"","sourceLineIndex":6},{"id":"le-petit-prince-2cd-21-007","lineIndex":7,"speaker":"Le Businessman","original":"Bonjour.","ipa":"/bɔ̃ʒuʁ/","zh":"你好","en":"Hello.","note":"","sourceLineIndex":7},{"id":"le-petit-prince-2cd-21-008","lineIndex":8,"speaker":"Le Businessman","original":"Vingt-deux et six vingt-huit","ipa":"/vɛ̃tdøz e si vɛ̃tyit/","zh":"二十二加六等于二十八","en":"Twenty-two plus six make twenty-eight.","note":"","sourceLineIndex":8},{"id":"le-petit-prince-2cd-21-009","lineIndex":9,"speaker":"Le Businessman","original":"Pas le temps de la rallumer","ipa":"/pa lə tɑ̃ də la ʁalyme/","zh":"我没时间重新点燃它。","en":"No time to relight it.","note":"","sourceLineIndex":9},{"id":"le-petit-prince-2cd-21-010","lineIndex":10,"speaker":"Le Businessman","original":"Vingt-six et cinq font trente et un","ipa":"/vɛ̃tsiz e sɛ̃k fɔ̃ tʁɑ̃t e œ̃/","zh":"二十六加五等于三十一","en":"Twenty-six plus five make thirty-one.","note":"","sourceLineIndex":10},{"id":"le-petit-prince-2cd-21-011","lineIndex":11,"speaker":"Le Businessman","original":"Ça me fait donc cinq cent un millions six cent vingt-deux mille sept cent trente et un","ipa":"/sa mə fɛ dɔ̃k sɛ̃ sɑ̃ œ̃ miljɔ̃ si sɑ̃ vɛ̃tdø mil sɛt sɑ̃ tʁɑ̃t e œ̃/","zh":"一共是五亿零一百六十二万二千七百三十一","en":"That makes five hundred and one million, six hundred and twenty-two thousand, seven hundred and thirty-one.","note":"","sourceLineIndex":11},{"id":"le-petit-prince-2cd-21-012","lineIndex":12,"speaker":"Le Petit Prince","original":"Cinq cent un millions de quoi?","ipa":"/sɛ̃ sɑ̃ œ̃ miljɔ̃ də kwa/","zh":"五亿个什么？","en":"Five hundred and one million of what?","note":"","sourceLineIndex":12},{"id":"le-petit-prince-2cd-21-013","lineIndex":13,"speaker":"Le Businessman","original":"Tiens, tu es toujours là","ipa":"/tjɛ̃ ty ɛ tuʒuʁ la/","zh":"噢，你还在这儿。","en":"Oh, you're still here.","note":"","sourceLineIndex":13},{"id":"le-petit-prince-2cd-21-014","lineIndex":14,"speaker":"Le Businessman","original":"Cinq cent un millions de...","ipa":"/sɛ̃ sɑ̃ œ̃ miljɔ̃ də/","zh":"五亿零一百万……","en":"Five hundred and one million...","note":"","sourceLineIndex":14},{"id":"le-petit-prince-2cd-21-015","lineIndex":15,"speaker":"Le Businessman","original":"Je ne sais même plus","ipa":"/ʒə nə sɛ mɛm ply/","zh":"我都不记得了。","en":"I don't even remember any more.","note":"","sourceLineIndex":15},{"id":"le-petit-prince-2cd-21-016","lineIndex":16,"speaker":"Le Petit Prince","original":"Cinq cent un millions de quoi?","ipa":"/sɛ̃ sɑ̃ œ̃ miljɔ̃ də kwa/","zh":"五亿零一百万个什么？","en":"Five hundred and one million of what?","note":"","sourceLineIndex":16},{"id":"le-petit-prince-2cd-21-017","lineIndex":17,"speaker":"Le Businessman","original":"J'ai tellement de travail","ipa":"/ʒe tɛlmɑ̃ də tʁavaj/","zh":"我有那么多工作。","en":"I have so much work to do.","note":"","sourceLineIndex":17},{"id":"le-petit-prince-2cd-21-018","lineIndex":18,"speaker":"Le Businessman","original":"Je ne peux pas m'amuser avec toutes ces balivernes","ipa":"/ʒə nə pø pa mamyze avɛk tut se balivɛʁn/","zh":"我没工夫拿这些废话消遣。","en":"I cannot waste time on all this nonsense.","note":"","sourceLineIndex":18},{"id":"le-petit-prince-2cd-21-019","lineIndex":19,"speaker":"Le Petit Prince","original":"Des millions de quoi?","ipa":"/de miljɔ̃ də kwa/","zh":"几百万个什么？","en":"Millions of what?","note":"","sourceLineIndex":19},{"id":"le-petit-prince-2cd-21-020","lineIndex":20,"speaker":"Le Businessman","original":"Tu ne dois pas me déranger","ipa":"/ty nə dwa pa mə deʁɑ̃ʒe/","zh":"你不该打扰我。","en":"You must not disturb me.","note":"","sourceLineIndex":20},{"id":"le-petit-prince-2cd-21-021","lineIndex":21,"speaker":"Le Businessman","original":"Deux et cinq font sept","ipa":"/døz e sɛ̃k fɔ̃ sɛt/","zh":"二加五等于七","en":"Two and five make seven","note":"","sourceLineIndex":21},{"id":"le-petit-prince-2cd-21-022","lineIndex":22,"speaker":"Le Businessman","original":"Je suis un homme sérieux","ipa":"/ʒə syiz œ̃n ɔm seʁjø/","zh":"我是个正经人。","en":"I am a serious man.","note":"","sourceLineIndex":22},{"id":"le-petit-prince-2cd-21-023","lineIndex":23,"speaker":"Le Petit Prince","original":"Cinq cent un millions de quoi?","ipa":"/sɛ̃ sɑ̃ œ̃ miljɔ̃ də kwa/","zh":"五亿零一百万个什么？","en":"Five hundred and one million of what?","note":"","sourceLineIndex":23},{"id":"le-petit-prince-2cd-21-024","lineIndex":24,"speaker":"Le Businessman","original":"Des millions d'étoiles","ipa":"/de miljɔ̃ detwal/","zh":"几百万颗星星。","en":"Millions of stars.","note":"","sourceLineIndex":24},{"id":"le-petit-prince-2cd-21-025","lineIndex":25,"speaker":"Le Businessman","original":"Auxquelles rêvent les paresseux","ipa":"/okɛl ʁɛv le paʁɛsø/","zh":"懒人拿来做梦的星星","en":"The ones lazy people dream about","note":"","sourceLineIndex":25},{"id":"le-petit-prince-2cd-21-026","lineIndex":26,"speaker":"Le Businessman","original":"Que je change en calcul mental","ipa":"/kə ʒə ʃɑ̃ʒ ɑ̃ kalkyl mɑ̃tal/","zh":"我把它们化作心算。","en":"Which I turn into mental arithmetic.","note":"","sourceLineIndex":26},{"id":"le-petit-prince-2cd-21-027","lineIndex":27,"speaker":"Le Businessman","original":"Moi qui suis un homme sérieux j'ai besoin","ipa":"/mwa ki syiz œ̃n ɔm seʁjø ʒe bəzwɛ̃/","zh":"我是个正经人，我需要","en":"I, a serious man, need","note":"","sourceLineIndex":27},{"id":"le-petit-prince-2cd-21-028","lineIndex":28,"speaker":"Le Businessman","original":"J'ai besoin de posséder pour me rassurer","ipa":"/ʒe bəzwɛ̃ də pɔsede puʁ mə ʁasyʁe/","zh":"我得拥有它们，才能安心。","en":"I need to own things to reassure myself.","note":"","sourceLineIndex":28},{"id":"le-petit-prince-2cd-21-029","lineIndex":29,"speaker":"Le Businessman","original":"J'ai besoin de me sentir riche pour exister","ipa":"/ʒe bəzwɛ̃ də mə sɑ̃tiʁ ʁiʃ puʁ ɛɡziste/","zh":"我得觉得自己富有，才觉得自己存在。","en":"I need to feel rich in order to exist.","note":"","sourceLineIndex":29},{"id":"le-petit-prince-2cd-21-030","lineIndex":30,"speaker":"Le Businessman","original":"Des millions d'étoiles","ipa":"/de miljɔ̃ detwal/","zh":"几百万颗星星。","en":"Millions of stars.","note":"","sourceLineIndex":30},{"id":"le-petit-prince-2cd-21-031","lineIndex":31,"speaker":"Le Businessman","original":"Que je ne sais que compter","ipa":"/kə ʒə nə sɛ kə kɔ̃te/","zh":"而我只会数它们。","en":"That I only know how to count.","note":"","sourceLineIndex":31},{"id":"le-petit-prince-2cd-21-032","lineIndex":32,"speaker":"Le Businessman","original":"Moi qui n'ai jamais rêvé","ipa":"/mwa ki ne ʒamɛ ʁɛve/","zh":"我从不做梦。","en":"I who have never dreamed.","note":"","sourceLineIndex":32},{"id":"le-petit-prince-2cd-21-033","lineIndex":33,"speaker":"Le Businessman","original":"Trois et deux font cinq","ipa":"/tʁwaz e dø fɔ̃ sɛ̃k/","zh":"三加二等于五","en":"Three and two make five","note":"","sourceLineIndex":33},{"id":"le-petit-prince-2cd-21-034","lineIndex":34,"speaker":"Le Businessman","original":"Et cinq plus sept font douze","ipa":"/e sɛ̃k ply sɛt fɔ̃ duz/","zh":"五加七等于十二","en":"And five plus seven make twelve","note":"","sourceLineIndex":34},{"id":"le-petit-prince-2cd-21-035","lineIndex":35,"speaker":"Le Businessman","original":"Et douze plus trois égalent bien quinze","ipa":"/e duz ply tʁwaz eɡal bjɛ̃ kɛ̃z/","zh":"十二加三等于十五","en":"And twelve plus three equal fifteen","note":"","sourceLineIndex":35},{"id":"le-petit-prince-2cd-21-036","lineIndex":36,"speaker":"Le Businessman","original":"Quinze et sept vingt-deux","ipa":"/kɛ̃z e sɛt vɛ̃tdø/","zh":"十五加七等于二十二","en":"Fifteen plus seven make twenty-two","note":"","sourceLineIndex":36},{"id":"le-petit-prince-2cd-21-037","lineIndex":37,"speaker":"Le Businessman","original":"Vingt-deux et six vingt-huit","ipa":"/vɛ̃tdøz e si vɛ̃tyit/","zh":"二十二加六等于二十八","en":"Twenty-two plus six make twenty-eight","note":"","sourceLineIndex":37},{"id":"le-petit-prince-2cd-21-038","lineIndex":38,"speaker":"Le Businessman","original":"Vingt-six et cinq font trente et un","ipa":"/vɛ̃tsiz e sɛ̃k fɔ̃ tʁɑ̃t e œ̃/","zh":"二十六加五等于三十一","en":"Twenty-six plus five make thirty-one","note":"","sourceLineIndex":38},{"id":"le-petit-prince-2cd-21-039","lineIndex":39,"speaker":"Le Businessman","original":"Ça me fait donc cinq cent un millions six cent vingt-deux mille sept cent trente et un...","ipa":"/sa mə fɛ dɔ̃k sɛ̃ sɑ̃ œ̃ miljɔ̃ si sɑ̃ vɛ̃tdø mil sɛt sɑ̃ tʁɑ̃t e œ̃/","zh":"一共是五亿零一百六十二万二千七百三十一。","en":"That makes five hundred and one million, six hundred and twenty-two thousand, seven hundred and thirty-one...","note":"","sourceLineIndex":39}],"sourceOrder":21,"displayOrder":21},{"order":22,"id":"22-le-businessman","title":"Le Businessman","titleZh":"商人","lines":[{"id":"le-petit-prince-2cd-22-001","lineIndex":1,"speaker":"Le Petit Prince","original":"D'étoiles, je sais.","ipa":"/detwal ʒə sɛ/","zh":"星星，我知道。","en":"Stars, I know.","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-22-002","lineIndex":2,"speaker":"Le Petit Prince","original":"J'ai déjà vu un roi qui possédait une étoile.","ipa":"/ʒe deʒa vy œ̃ ʁwa ki pɔsedɛt yn etwal/","zh":"我见过一位国王，他拥有一颗星。","en":"I once saw a king who owned a star.","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-22-003","lineIndex":3,"speaker":"Le Businessman","original":"Mais les rois ne possèdent pas","ipa":"/mɛ le ʁwa nə pɔsɛd pa/","zh":"但国王并不拥有东西","en":"But kings do not own things;","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-22-004","lineIndex":4,"speaker":"Le Businessman","original":"ils règnent sur, c'est très différent.","ipa":"/il ʁɛnj syʁ sɛ tʁɛ difeʁɑ̃/","zh":"他们只是统治，这大不相同。","en":"they rule over them; that is very different.","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-22-005","lineIndex":5,"speaker":"Le Petit Prince","original":"Et comment peut-on posséder une étoile?","ipa":"/e kɔmɑ̃ pøtɔ̃ pɔsede yn etwal/","zh":"那怎样才能拥有一颗星？","en":"And how can one own a star?","note":"","sourceLineIndex":5},{"id":"le-petit-prince-2cd-22-006","lineIndex":6,"speaker":"Le Businessman","original":"Je possède les étoiles parce que personne avant moi n'a pensé à les posséder.","ipa":"/ʒə pɔsɛd lez etwal paʁskə pɛʁsɔn avɑ̃ mwa na pɑ̃se a le pɔsede/","zh":"我拥有星星，因为在我之前没人想过拥有它们。","en":"I own the stars because no one before me thought of owning them.","note":"","sourceLineIndex":6},{"id":"le-petit-prince-2cd-22-007","lineIndex":7,"speaker":"Le Petit Prince","original":"Ça, c'est vrai","ipa":"/sa sɛ vʁɛ/","zh":"这倒是真的","en":"That is true","note":"","sourceLineIndex":7},{"id":"le-petit-prince-2cd-22-008","lineIndex":8,"speaker":"Le Petit Prince","original":"mais tu ne peux pas cueillir une étoile comme je peux cueillir une fleur et l'emporter.","ipa":"/mɛ ty nə pø pa kœjiʁ yn etwal kɔm ʒə pø kœjiʁ yn flœʁ e lɑ̃pɔʁte/","zh":"但你不能像我摘下一朵花并带走它那样，摘下一颗星。","en":"but you cannot pick a star as I can pick a flower and take it away.","note":"","sourceLineIndex":8},{"id":"le-petit-prince-2cd-22-009","lineIndex":9,"speaker":"Le Businessman","original":"Non, mais je peux les placer en banque.","ipa":"/nɔ̃ mɛ ʒə pø le plase ɑ̃ bɑ̃k/","zh":"不，不过我可以把它们存进银行。","en":"No, but I can put them in the bank.","note":"","sourceLineIndex":9},{"id":"le-petit-prince-2cd-22-010","lineIndex":10,"speaker":"Le Businessman","original":"J'écris sur un petit papier le nombre de mes étoiles","ipa":"/ʒekʁi syʁ œ̃ pəti papje lə nɔ̃bʁ də mez etwal/","zh":"我把星星的数目写在一张小纸条上","en":"I write the number of my stars on a little piece of paper","note":"","sourceLineIndex":10},{"id":"le-petit-prince-2cd-22-011","lineIndex":11,"speaker":"Le Businessman","original":"et je l'enferme à clé dans un tiroir.","ipa":"/e ʒə lɑ̃fɛʁm a kle dɑ̃z œ̃ tiʁwaʁ/","zh":"再把纸条锁进抽屉。","en":"and lock it in a drawer.","note":"","sourceLineIndex":11},{"id":"le-petit-prince-2cd-22-012","lineIndex":12,"speaker":"Le Petit Prince","original":"C'est assez poétique, mais ce n'est vraiment pas très sérieux.","ipa":"/sɛt ase pɔetik mɛ sə nɛ vʁɛmɑ̃ pa tʁɛ seʁjø/","zh":"这倒挺有诗意，但实在不算严肃。","en":"It is rather poetic, but not really very serious.","note":"","sourceLineIndex":12},{"id":"le-petit-prince-2cd-22-013","lineIndex":13,"speaker":"Le Petit Prince","original":"Moi je ramone mes volcans et j'arrose ma fleur","ipa":"/mwa ʒə ʁamɔn me vɔlkɑ̃z e ʒaʁɔz ma flœʁ/","zh":"我清扫火山，也浇灌我的花","en":"I sweep out my volcanoes and water my flower","note":"","sourceLineIndex":13},{"id":"le-petit-prince-2cd-22-014","lineIndex":14,"speaker":"Le Petit Prince","original":"aussi c'est utile à mes volcans et c'est utile à ma fleur que je les possède.","ipa":"/osi sɛt ytil a me vɔlkɑ̃z e sɛt ytil a ma flœʁ kə ʒə le pɔsɛd/","zh":"我拥有火山和花，对它们都有好处。","en":"and it is useful to my volcanoes and my flower that I own them.","note":"","sourceLineIndex":14},{"id":"le-petit-prince-2cd-22-015","lineIndex":15,"speaker":"Le Petit Prince","original":"Mais toi tu n'es pas utile aux étoiles.","ipa":"/mɛ twa ty nɛ paz ytil oz etwal/","zh":"但你对星星毫无用处。","en":"But you are of no use to the stars.","note":"","sourceLineIndex":15},{"id":"le-petit-prince-2cd-22-016","lineIndex":16,"speaker":"Le Petit Prince","original":"Je voudrais aller voir ailleurs.","ipa":"/ʒə vudʁɛz ale vwaʁ ajœʁ/","zh":"我想去别处看看。","en":"I would like to go and see elsewhere.","note":"","sourceLineIndex":16},{"id":"le-petit-prince-2cd-22-017","lineIndex":17,"speaker":"Le Petit Prince","original":"Voilà une jolie planète.","ipa":"/vwala yn ʒoli planɛt/","zh":"那儿有一颗漂亮的星球。","en":"There is a pretty planet.","note":"","sourceLineIndex":17},{"id":"le-petit-prince-2cd-22-018","lineIndex":18,"speaker":"Le Businessman","original":"C'est une planète minuscule, et absurde.","ipa":"/sɛt yn planɛt minyskyl e absyʁd/","zh":"那是一颗小得可怜又荒谬的星球。","en":"It is a tiny, absurd planet.","note":"","sourceLineIndex":18},{"id":"le-petit-prince-2cd-22-019-a","lineIndex":19,"speaker":"Le Businessman","original":"À quoi peut bien servir, dans le ciel","ipa":"/a kwa pø bjɛ̃ sɛʁviʁ dɑ̃ lə sjɛl/","zh":"天上那颗没有房屋和居民的星球","en":"What use could a street lamp and a lamplighter have on a planet in the sky with no houses or inhabitants?","note":"","sourceLineIndex":19},{"id":"le-petit-prince-2cd-22-019-b","lineIndex":20,"speaker":"Le Businessman","original":"sur une planète sans maison ni population, un réverbère et un allumeur de réverbère?","ipa":"/syʁ yn planɛt sɑ̃ mɛzɔ̃ ni popylasjɔ̃ œ̃ ʁevɛʁbɛʁ e œ̃n alymœʁ də ʁevɛʁbɛʁ/","zh":"要一盏路灯和点灯人究竟有什么用？","en":"What use could a street lamp and a lamplighter have on a planet in the sky with no houses or inhabitants?","note":"","sourceLineIndex":19},{"id":"le-petit-prince-2cd-22-020","lineIndex":21,"speaker":"Le Petit Prince","original":"Peut-être bien que cet homme est absurde.","ipa":"/pøtɛtʁ bjɛ̃ kə sɛt ɔm ɛt absyʁd/","zh":"也许那个人确实有些荒谬。","en":"Perhaps that man is absurd.","note":"","sourceLineIndex":20},{"id":"le-petit-prince-2cd-22-021-a","lineIndex":22,"speaker":"Le Petit Prince","original":"Moins cependant que vous tous, parce que","ipa":"/mwɛ̃ səpɑ̃dɑ̃ kə vu tus paʁskə/","zh":"不过他总比你们都不那么荒谬：","en":"Yet he is less absurd than all of you","note":"","sourceLineIndex":21},{"id":"le-petit-prince-2cd-22-021-b","lineIndex":23,"speaker":"Le Petit Prince","original":"quand il allume son réverbère","ipa":"/kɑ̃t il alym sɔ̃ ʁevɛʁbɛʁ/","zh":"他点亮路灯","en":"because when he lights his lamp","note":"","sourceLineIndex":21},{"id":"le-petit-prince-2cd-22-021-c","lineIndex":24,"speaker":"Le Petit Prince","original":"c'est comme s'il faisait naître une étoile de plus ou une fleur.","ipa":"/sɛ kɔm sil fəzɛ nɛtʁ yn etwal də ply u yn flœʁ/","zh":"就像多诞生了一颗星或一朵花。","en":"it is as if he brings another star or flower into being.","note":"","sourceLineIndex":21},{"id":"le-petit-prince-2cd-22-022","lineIndex":25,"speaker":"Le Petit Prince","original":"Quand il éteint son réverbère, ça endort l'étoile ou la fleur.","ipa":"/kɑ̃t il etɛ̃ sɔ̃ ʁevɛʁbɛʁ sa ɑ̃dɔʁ letwal u la flœʁ/","zh":"他熄灭路灯，就让星星或花儿睡去。","en":"When he puts out his lamp, it sends the star or flower to sleep.","note":"","sourceLineIndex":22},{"id":"le-petit-prince-2cd-22-023","lineIndex":26,"speaker":"Le Petit Prince","original":"C'est une occupation très jolie et véritablement utile","ipa":"/sɛt yn ɔkypasjɔ̃ tʁɛ ʒoli e veʁitabləmɑ̃ ytil/","zh":"这是一份很美、也确实有用的工作","en":"It is a very lovely and genuinely useful occupation","note":"","sourceLineIndex":23},{"id":"le-petit-prince-2cd-22-024","lineIndex":27,"speaker":"Le Petit Prince","original":"puisque c'est joli. Adieu.","ipa":"/pyiskə sɛ ʒoli adjø/","zh":"因为它很美。再见。","en":"because it is lovely. Goodbye.","note":"","sourceLineIndex":24},{"id":"le-petit-prince-2cd-22-025","lineIndex":28,"speaker":"Le Petit Prince","original":"Les grandes personnes sont décidément tout à fait extraordinaires.","ipa":"/le ɡʁɑ̃d pɛʁsɔn sɔ̃ desidemɑ̃ tut a fɛt ɛkstʁaɔʁdinɛʁ/","zh":"大人们真是无比古怪。","en":"Grown-ups really are quite extraordinary.","note":"","sourceLineIndex":25},{"id":"le-petit-prince-2cd-22-026","lineIndex":29,"speaker":"Le Petit Prince","original":"Pourquoi éteins-tu ton réverbère?","ipa":"/puʁkwa etɛ̃ty tɔ̃ ʁevɛʁbɛʁ/","zh":"你为什么熄灭路灯？","en":"Why do you put out your street lamp?","note":"","sourceLineIndex":26},{"id":"le-petit-prince-2cd-22-027","lineIndex":30,"speaker":"Le Petit Prince","original":"Tu viens à peine de l'allumer.","ipa":"/ty vjɛ̃z a pɛn də lalyme/","zh":"你才刚把它点亮。","en":"You have only just lit it.","note":"","sourceLineIndex":27}],"sourceOrder":22,"displayOrder":22},{"order":23,"id":"23-l-allumeur-de-reverberes","title":"L'allumeur De RÉVerbÈRes","titleZh":"点灯人","lines":[{"id":"le-petit-prince-2cd-23-001","lineIndex":1,"speaker":"","original":"J'éteins mon réverbère","ipa":"/ʒetɛ̃ mɔ̃ ʁevɛʁbɛʁ/","zh":"我熄灭路灯。","en":"I put out my street lamp.","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-23-002","lineIndex":2,"speaker":"","original":"Je l'allume aussitôt","ipa":"/ʒə lalym ositoː/","zh":"我又立刻点亮它。","en":"I light it again at once.","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-23-003","lineIndex":3,"speaker":"","original":"C'est la consigne","ipa":"/sɛ la kɔ̃siɲ/","zh":"这是规程。","en":"Those are the instructions.","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-23-004","lineIndex":4,"speaker":"","original":"Bonjour bonsoir","ipa":"/bɔ̃ʒuʁ bɔ̃swaʁ/","zh":"早安，晚安。","en":"Good morning, good evening.","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-23-005","lineIndex":5,"speaker":"","original":"J'allume mon réverbère","ipa":"/ʒalym mɔ̃ ʁevɛʁbɛʁ/","zh":"我点亮路灯。","en":"I light my street lamp.","note":"","sourceLineIndex":5},{"id":"le-petit-prince-2cd-23-006","lineIndex":6,"speaker":"","original":"Je l'éteins à nouveau","ipa":"/ʒə letɛ̃z a nuvo/","zh":"我又把它熄灭。","en":"I put it out again.","note":"","sourceLineIndex":6},{"id":"le-petit-prince-2cd-23-007","lineIndex":7,"speaker":"","original":"C'est la consigne","ipa":"/sɛ la kɔ̃siɲ/","zh":"这是规程。","en":"Those are the instructions.","note":"","sourceLineIndex":7},{"id":"le-petit-prince-2cd-23-008","lineIndex":8,"speaker":"","original":"Bonjour bonsoir","ipa":"/bɔ̃ʒuʁ bɔ̃swaʁ/","zh":"早安，晚安。","en":"Good morning, good evening.","note":"","sourceLineIndex":8},{"id":"le-petit-prince-2cd-23-009","lineIndex":9,"speaker":"","original":"Mon métier est terrible","ipa":"/mɔ̃ metje ɛ tɛʁibl/","zh":"我的工作太折磨人了。","en":"My job is dreadful.","note":"","sourceLineIndex":9},{"id":"le-petit-prince-2cd-23-010","lineIndex":10,"speaker":"","original":"Je ne dois pas réfléchir","ipa":"/ʒə nə dwa pa ʁefleʃiʁ/","zh":"我不该思考。","en":"I must not think.","note":"","sourceLineIndex":10},{"id":"le-petit-prince-2cd-23-011","lineIndex":11,"speaker":"","original":"Je ne suis plus jamais libre","ipa":"/ʒə nə syi ply ʒamɛ libʁ/","zh":"我再也没有自由。","en":"I am never free any more.","note":"","sourceLineIndex":11},{"id":"le-petit-prince-2cd-23-012","lineIndex":12,"speaker":"","original":"J'obéis sans rien dire","ipa":"/ʒobei sɑ̃ ʁjɛ̃ diʁ/","zh":"我一言不发地服从。","en":"I obey without saying a word.","note":"","sourceLineIndex":12},{"id":"le-petit-prince-2cd-23-013","lineIndex":13,"speaker":"","original":"La consigne c'est la consigne","ipa":"/la kɔ̃siɲ sɛ la kɔ̃siɲ/","zh":"规程就是规程。","en":"Instructions are instructions.","note":"","sourceLineIndex":13},{"id":"le-petit-prince-2cd-23-014","lineIndex":14,"speaker":"","original":"Bonjour bonsoir","ipa":"/bɔ̃ʒuʁ bɔ̃swaʁ/","zh":"早安，晚安。","en":"Good morning, good evening.","note":"","sourceLineIndex":14},{"id":"le-petit-prince-2cd-23-015","lineIndex":15,"speaker":"","original":"Bonjour bonsoir","ipa":"/bɔ̃ʒuʁ bɔ̃swaʁ/","zh":"早安，晚安。","en":"Good morning, good evening.","note":"","sourceLineIndex":15},{"id":"le-petit-prince-2cd-23-016","lineIndex":16,"speaker":"","original":"Je regrette autrefois Quand je n'avais encore Qu'à éteindre le matin Et allumer le soir","ipa":"/ʒə ʁəɡʁɛt otʁəfwa kɑ̃ ʒə navɛz ɑ̃kɔʁ ka etɛ̃dʁ lə matɛ̃ e alyme lə swaʁ/","zh":"我怀念从前那时我还只需早晨熄灯晚上点灯。","en":"I miss the old days when I only still had to put it out in the morning and light it in the evening.","note":"","sourceLineIndex":16},{"id":"le-petit-prince-2cd-23-020","lineIndex":17,"speaker":"","original":"Année après année La planète a tourné Chaque jour un peu plus vite Sans que change la consigne","ipa":"/ane apʁɛz ane la planɛt a tuʁne ʃak ʒuʁ œ̃ pø ply vit sɑ̃ kə ʃɑ̃ʒ la kɔ̃siɲ/","zh":"年复一年星球不停转动每天都快一点可规程却没有改变。","en":"Year after year the planet has turned a little faster every day without the instructions changing.","note":"","sourceLineIndex":20},{"id":"le-petit-prince-2cd-23-024","lineIndex":18,"speaker":"","original":"Bonjour bonsoir","ipa":"/bɔ̃ʒuʁ bɔ̃swaʁ/","zh":"早安，晚安。","en":"Good morning, good evening.","note":"","sourceLineIndex":24},{"id":"le-petit-prince-2cd-23-025","lineIndex":19,"speaker":"","original":"Et maintenant elle fait","ipa":"/e mɛ̃tnɑ̃ ɛl fɛ/","zh":"如今它在","en":"And now it makes","note":"","sourceLineIndex":25},{"id":"le-petit-prince-2cd-23-026","lineIndex":20,"speaker":"","original":"En soixante secondes","ipa":"/ɑ̃ swasɑ̃t səɡɔ̃d/","zh":"六十秒内","en":"in sixty seconds","note":"","sourceLineIndex":26},{"id":"le-petit-prince-2cd-23-027","lineIndex":21,"speaker":"","original":"Sur elle un tour entier Et je n'ai en ce monde Plus un instant de paix","ipa":"/syʁ ɛl œ̃ tuʁ ɑ̃tje e ʒə ne ɑ̃ sə mɔ̃d plyz œ̃n ɛ̃stɑ̃ də pɛ/","zh":"自转一整圈而在这世上我再没有片刻安宁。","en":"one complete turn on itself and in this world I have no more moment of peace.","note":"","sourceLineIndex":27},{"id":"le-petit-prince-2cd-23-030","lineIndex":22,"speaker":"","original":"Bonjour bonsoir","ipa":"/bɔ̃ʒuʁ bɔ̃swaʁ/","zh":"早安，晚安。","en":"Good morning, good evening.","note":"","sourceLineIndex":30},{"id":"le-petit-prince-2cd-23-031","lineIndex":23,"speaker":"","original":"J'éteins mon réverbère","ipa":"/ʒetɛ̃ mɔ̃ ʁevɛʁbɛʁ/","zh":"我熄灭路灯。","en":"I put out my street lamp.","note":"","sourceLineIndex":31},{"id":"le-petit-prince-2cd-23-032","lineIndex":24,"speaker":"","original":"Je l'allume aussitôt","ipa":"/ʒə lalym ositoː/","zh":"我又立刻点亮它。","en":"I light it again at once.","note":"","sourceLineIndex":32},{"id":"le-petit-prince-2cd-23-033","lineIndex":25,"speaker":"","original":"C'est la consigne","ipa":"/sɛ la kɔ̃siɲ/","zh":"这是规程。","en":"Those are the instructions.","note":"","sourceLineIndex":33},{"id":"le-petit-prince-2cd-23-034","lineIndex":26,"speaker":"","original":"Bonjour bonsoir","ipa":"/bɔ̃ʒuʁ bɔ̃swaʁ/","zh":"早安，晚安。","en":"Good morning, good evening.","note":"","sourceLineIndex":34},{"id":"le-petit-prince-2cd-23-035","lineIndex":27,"speaker":"","original":"J'allume mon réverbère","ipa":"/ʒalym mɔ̃ ʁevɛʁbɛʁ/","zh":"我点亮路灯。","en":"I light my street lamp.","note":"","sourceLineIndex":35},{"id":"le-petit-prince-2cd-23-036","lineIndex":28,"speaker":"","original":"Je l'éteins à nouveau","ipa":"/ʒə letɛ̃z a nuvo/","zh":"我又把它熄灭。","en":"I put it out again.","note":"","sourceLineIndex":36},{"id":"le-petit-prince-2cd-23-037","lineIndex":29,"speaker":"","original":"C'est la consigne","ipa":"/sɛ la kɔ̃siɲ/","zh":"这是规程。","en":"Those are the instructions.","note":"","sourceLineIndex":37},{"id":"le-petit-prince-2cd-23-038","lineIndex":30,"speaker":"","original":"Bonjour bonsoir","ipa":"/bɔ̃ʒuʁ bɔ̃swaʁ/","zh":"早安，晚安。","en":"Good morning, good evening.","note":"","sourceLineIndex":38},{"id":"le-petit-prince-2cd-23-039","lineIndex":31,"speaker":"Le Petit Prince","original":"Au moins lui ne s'occupe pas que de lui-même","ipa":"/o mwɛ̃ lyi nə sɔkyp pa kə də lyimɛm/","zh":"至少他不只顾自己。","en":"At least he does not concern himself only with himself.","note":"","sourceLineIndex":39},{"id":"le-petit-prince-2cd-23-040","lineIndex":32,"speaker":"Le Petit Prince","original":"S'il y avait eu de la place pour deux","ipa":"/sil i avɛt y də la plas puʁ dø/","zh":"要是他的星球容得下两个人","en":"If there had been room for two","note":"","sourceLineIndex":40},{"id":"le-petit-prince-2cd-23-041","lineIndex":33,"speaker":"Le Petit Prince","original":"j'aurais aimé en faire mon ami.","ipa":"/ʒoʁɛz ɛme ɑ̃ fɛʁ mɔ̃n ami/","zh":"我本愿意和他交朋友。","en":"I would have liked to make him my friend.","note":"","sourceLineIndex":41},{"id":"le-petit-prince-2cd-23-042","lineIndex":34,"speaker":"Le Petit Prince","original":"Et puis soixante couchers de soleil par heure","ipa":"/e pyi swasɑ̃t kuʃe də solɛj paʁ œʁ/","zh":"再说，一小时六十次日落","en":"And besides, sixty sunsets an hour","note":"","sourceLineIndex":42},{"id":"le-petit-prince-2cd-23-043","lineIndex":35,"speaker":"Le Petit Prince","original":"ça fait... mille quatre cent quarante couchers de soleil par jour!","ipa":"/sa fɛ mil katʁ sɑ̃ kaʁɑ̃t kuʃe də solɛj paʁ ʒuʁ/","zh":"那就是每天一千四百四十次日落！","en":"that makes... one thousand four hundred and forty sunsets a day!","note":"","sourceLineIndex":43},{"id":"le-petit-prince-2cd-23-044","lineIndex":36,"speaker":"Le Petit Prince","original":"J'y retourne.","ipa":"/ʒi ʁətuʁn/","zh":"我还是回去吧。","en":"I am going back.","note":"","sourceLineIndex":44}],"sourceOrder":23,"displayOrder":23},{"order":24,"id":"24-le-geographe","title":"Le GÉOgraphe","titleZh":"地理学家","lines":[{"id":"le-petit-prince-2cd-24-001","lineIndex":1,"speaker":"Le Petit Prince","original":"Ah, voilà une grande planète.","ipa":"/a vwala yn ɡʁɑ̃d planɛt/","zh":"啊，这是一颗大星球。","en":"Ah, this is a big planet.","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-24-002","lineIndex":2,"speaker":"Le Géographe","original":"Tiens, voilà un explorateur.","ipa":"/tjɛ̃ vwala œ̃n ɛksploʁatœʁ/","zh":"瞧，来了一位探险家。","en":"Look, here is an explorer.","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-24-003","lineIndex":3,"speaker":"Le Petit Prince","original":"Quel est ce gros livre?","ipa":"/kɛl ɛ sə ɡʁo livʁ/","zh":"这本大书是什么？","en":"What is this big book?","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-24-004","lineIndex":4,"speaker":"Le Petit Prince","original":"Que faites-vous ici?","ipa":"/kə fɛtvuz isi/","zh":"您在这里做什么？","en":"What are you doing here?","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-24-005","lineIndex":5,"speaker":"Le Géographe","original":"Je suis géographe","ipa":"/ʒə syi ʒeɔɡʁaf/","zh":"我是地理学家","en":"I am a geographer","note":"","sourceLineIndex":5},{"id":"le-petit-prince-2cd-24-006","lineIndex":6,"speaker":"Le Géographe","original":"et je prends en note les souvenirs des explorateurs.","ipa":"/e ʒə pʁɑ̃z ɑ̃ nɔt le suvniʁ dez ɛksploʁatœʁ/","zh":"记录探险家带来的见闻。","en":"and I record the accounts of explorers.","note":"","sourceLineIndex":6},{"id":"le-petit-prince-2cd-24-007","lineIndex":7,"speaker":"Le Petit Prince","original":"Elle est bien belle votre planète.","ipa":"/ɛl ɛ bjɛ̃ bɛl votʁ planɛt/","zh":"您的星球真美。","en":"Your planet is very beautiful.","note":"","sourceLineIndex":7},{"id":"le-petit-prince-2cd-24-008","lineIndex":8,"speaker":"Le Petit Prince","original":"Est-ce qu'il y a des océans?","ipa":"/ɛs kil i a dez oseɑ̃/","zh":"有海洋吗？","en":"Are there oceans?","note":"","sourceLineIndex":8},{"id":"le-petit-prince-2cd-24-009","lineIndex":9,"speaker":"Le Géographe","original":"Je ne puis pas le savoir.","ipa":"/ʒə nə pyi pa lə savwaʁ/","zh":"我不能知道。","en":"I cannot know.","note":"","sourceLineIndex":9},{"id":"le-petit-prince-2cd-24-010","lineIndex":10,"speaker":"Le Petit Prince","original":"Et des montagnes, des villes, des fleuves, des déserts?","ipa":"/e de mɔ̃tanj de vil de fløv de dezɛʁ/","zh":"那山脉、城市、河流和沙漠呢？","en":"And mountains, cities, rivers and deserts?","note":"","sourceLineIndex":10},{"id":"le-petit-prince-2cd-24-011","lineIndex":11,"speaker":"Le Géographe","original":"Je ne puis pas le savoir.","ipa":"/ʒə nə pyi pa lə savwaʁ/","zh":"我不能知道。","en":"I cannot know.","note":"","sourceLineIndex":11},{"id":"le-petit-prince-2cd-24-012","lineIndex":12,"speaker":"Le Petit Prince","original":"Mais vous êtes géographe?","ipa":"/mɛ vuz ɛt ʒeɔɡʁaf/","zh":"可您是地理学家呀？","en":"But you are a geographer?","note":"","sourceLineIndex":12},{"id":"le-petit-prince-2cd-24-013","lineIndex":13,"speaker":"Le Géographe","original":"C'est exact, mais je ne suis pas explorateur","ipa":"/sɛt ɛɡzakt mɛ ʒə nə syi paz ɛksploʁatœʁ/","zh":"没错，但我不是探险家。","en":"That is correct, but I am not an explorer.","note":"","sourceLineIndex":13},{"id":"le-petit-prince-2cd-24-014","lineIndex":14,"speaker":"Le Géographe","original":"Le géographe est trop important pour flâner.","ipa":"/lə ʒeɔɡʁaf ɛ tʁop ɛ̃pɔʁtɑ̃ puʁ flane/","zh":"地理学家太重要，不能四处闲逛。","en":"A geographer is too important to go wandering about.","note":"","sourceLineIndex":14},{"id":"le-petit-prince-2cd-24-015","lineIndex":15,"speaker":"Le Géographe","original":"Il ne quitte pas son bureau.","ipa":"/il nə kit pa sɔ̃ byʁo/","zh":"他不能离开办公室。","en":"He does not leave his office.","note":"","sourceLineIndex":15},{"id":"le-petit-prince-2cd-24-016","lineIndex":16,"speaker":"Le Géographe","original":"Mais il y reçoit les explorateurs.","ipa":"/mɛz il i ʁəswa lez ɛksploʁatœʁ/","zh":"但他会在那里接待探险家。","en":"But he receives explorers there.","note":"","sourceLineIndex":16},{"id":"le-petit-prince-2cd-24-017","lineIndex":17,"speaker":"Le Géographe","original":"Et si les souvenirs de l'un d'eux lui paraissent intéressants","ipa":"/e si le suvniʁ də lœ̃ dø lyi paʁɛst ɛ̃teʁɛsɑ̃/","zh":"如果其中一人的见闻引起他的兴趣","en":"And if one explorer's account seems interesting to him","note":"","sourceLineIndex":17},{"id":"le-petit-prince-2cd-24-018","lineIndex":18,"speaker":"Le Géographe","original":"alors le géographe fait faire une enquête sur la moralité de l'explorateur.","ipa":"/alɔʁ lə ʒeɔɡʁaf fɛ fɛʁ yn ɑ̃kɛt syʁ la moʁalite də lɛksploʁatœʁ/","zh":"地理学家就会调查这位探险家的品行。","en":"then the geographer has the explorer's character investigated.","note":"","sourceLineIndex":18},{"id":"le-petit-prince-2cd-24-019","lineIndex":19,"speaker":"Le Petit Prince","original":"Pourquoi ça?","ipa":"/puʁkwa sa/","zh":"为什么？","en":"Why is that?","note":"","sourceLineIndex":19},{"id":"le-petit-prince-2cd-24-020","lineIndex":20,"speaker":"Le Géographe","original":"Si l'explorateur mentait, tu imagines la catastrophe.","ipa":"/si lɛksploʁatœʁ mɑ̃tɛ ty imaʒin la katastʁɔf/","zh":"若探险家说谎，你能想象那会造成怎样的灾难。","en":"If an explorer lied, imagine the catastrophe.","note":"","sourceLineIndex":20},{"id":"le-petit-prince-2cd-24-021","lineIndex":21,"speaker":"Le Géographe","original":"Et si c'est un ivrogne, il voit double, il noterait deux montagnes, deux!","ipa":"/e si sɛt œ̃n ivʁɔɲ il vwa dubl il notʁɛ dø mɔ̃tanj dø/","zh":"若他是酒鬼，看东西重影，就会记下两座山，两座！","en":"And if he is a drunkard, he sees double: he would record two mountains, two!","note":"","sourceLineIndex":21},{"id":"le-petit-prince-2cd-24-022","lineIndex":22,"speaker":"Le Géographe","original":"Là où il n'y en a qu'une.","ipa":"/la u il ni ɑ̃n a kyn/","zh":"而那里其实只有一座。","en":"Where there is only one.","note":"","sourceLineIndex":22},{"id":"le-petit-prince-2cd-24-023","lineIndex":23,"speaker":"Le Petit Prince","original":"Ah, ah, ah.","ipa":"/a a a/","zh":"哈哈哈。","en":"Ah, ah, ah.","note":"","sourceLineIndex":23},{"id":"le-petit-prince-2cd-24-024","lineIndex":24,"speaker":"Le Géographe","original":"Et toi, tu viens de loin?","ipa":"/e twa ty vjɛ̃ də lwɛ̃/","zh":"你呢，你从很远的地方来？","en":"And you, do you come from far away?","note":"","sourceLineIndex":24},{"id":"le-petit-prince-2cd-24-025","lineIndex":25,"speaker":"Le Géographe","original":"Je vais noter ton récit, au crayon d'abord","ipa":"/ʒə vɛ note tɔ̃ ʁesi o kʁɛjɔ̃ dabɔʁ/","zh":"我会先用铅笔记下你的叙述","en":"I shall note down your account, first in pencil","note":"","sourceLineIndex":25},{"id":"le-petit-prince-2cd-24-026","lineIndex":26,"speaker":"Le Géographe","original":"à l'encre quand tu auras fourni les preuves.","ipa":"/a lɑ̃kʁ kɑ̃ ty oʁa fuʁni le pʁøv/","zh":"等你提供证据后再用墨水写。","en":"then in ink once you have supplied the proof.","note":"","sourceLineIndex":26},{"id":"le-petit-prince-2cd-24-027","lineIndex":27,"speaker":"Le Petit Prince","original":"Quelles preuves?","ipa":"/kɛl pʁøv/","zh":"什么证据？","en":"What proof?","note":"","sourceLineIndex":27},{"id":"le-petit-prince-2cd-24-028","lineIndex":28,"speaker":"Le Géographe","original":"C'est très simple.","ipa":"/sɛ tʁɛ sɛ̃pl/","zh":"很简单。","en":"It is very simple.","note":"","sourceLineIndex":28},{"id":"le-petit-prince-2cd-24-029","lineIndex":29,"speaker":"Le Géographe","original":"S'il s'agit, par exemple, de la découverte d'une grosse montagne","ipa":"/sil saʒi paʁ ɛɡzɑ̃pl də la dekuvɛʁt dyn ɡʁos mɔ̃taɲ/","zh":"比如发现了一座大山","en":"If it is, for example, the discovery of a large mountain","note":"","sourceLineIndex":29},{"id":"le-petit-prince-2cd-24-030","lineIndex":30,"speaker":"Le Géographe","original":"on exige de l'explorateur qu'il en rapporte de grosses pierres. Alors?","ipa":"/ɔ̃n ɛɡziʒ də lɛksploʁatœʁ kil ɑ̃ ʁapɔʁt də ɡʁos pjɛʁ alɔʁ/","zh":"就要求探险家带回大石头。怎么样？","en":"one requires the explorer to bring back large stones. Well?","note":"","sourceLineIndex":30},{"id":"le-petit-prince-2cd-24-031","lineIndex":31,"speaker":"Le Petit Prince","original":"Chez moi, c'est tout petit","ipa":"/ʃe mwa sɛ tu pəti/","zh":"我那儿什么都很小","en":"Where I live, everything is very small","note":"","sourceLineIndex":31},{"id":"le-petit-prince-2cd-24-032","lineIndex":32,"speaker":"Le Petit Prince","original":"deux volcans en activité, un volcan éteint...","ipa":"/dø vɔlkɑ̃z ɑ̃n aktivite œ̃ vɔlkɑ̃ etɛ̃/","zh":"有两座活火山和一座死火山……","en":"two active volcanoes and one extinct volcano...","note":"","sourceLineIndex":32},{"id":"le-petit-prince-2cd-24-033","lineIndex":33,"speaker":"Le Géographe","original":"Je prends note, on ne sait jamais.","ipa":"/ʒə pʁɑ̃ nɔt ɔ̃ nə sɛ ʒamɛ/","zh":"我记下来，谁知道呢。","en":"I shall note that down; one never knows.","note":"","sourceLineIndex":33},{"id":"le-petit-prince-2cd-24-034","lineIndex":34,"speaker":"Le Petit Prince","original":"J'ai aussi une fleur.","ipa":"/ʒe osi yn flœʁ/","zh":"我还有一朵花。","en":"I have a flower too.","note":"","sourceLineIndex":34},{"id":"le-petit-prince-2cd-24-035","lineIndex":35,"speaker":"Le Géographe","original":"Nous ne notons pas les fleurs, elles sont éphémères.","ipa":"/nu nə notɔ̃ pa le flœʁ ɛl sɔ̃t efemɛʁ/","zh":"我们不记录花，因为它们是短暂易逝的。","en":"We do not record flowers; they are ephemeral.","note":"","sourceLineIndex":35},{"id":"le-petit-prince-2cd-24-036","lineIndex":36,"speaker":"Le Géographe","original":"Nous n'écrivons que les choses éternelles, qui ne se démodent pas.","ipa":"/nu nekʁivɔ̃ kə le ʃozz etɛʁnɛl ki nə sə demod pa/","zh":"我们只记录永恒、不随时间过时的事物。","en":"We write down only eternal things, which do not go out of date.","note":"","sourceLineIndex":36},{"id":"le-petit-prince-2cd-24-037","lineIndex":37,"speaker":"Le Petit Prince","original":"Qu'est-ce que ça signifie, \"éphémère\"?","ipa":"/kɛskə sa siɲifi efemɛʁ/","zh":"“短暂易逝”是什么意思？","en":"What does “ephemeral” mean?","note":"","sourceLineIndex":37},{"id":"le-petit-prince-2cd-24-038","lineIndex":38,"speaker":"Le Géographe","original":"Ça signifie... \"qui est menacé de disparition prochaine\".","ipa":"/sa siɲifi ki ɛ mənase də dispaʁisjɔ̃ pʁoʃɛn/","zh":"意思是“面临很快消失的危险”。","en":"It means... “threatened with imminent disappearance.”","note":"","sourceLineIndex":38},{"id":"le-petit-prince-2cd-24-039","lineIndex":39,"speaker":"Le Petit Prince","original":"Ma fleur est éphémère, et elle n'a que quatre épines pour se défendre contre le monde!","ipa":"/ma flœʁ ɛt efemɛʁ e ɛl na kə katʁ epin puʁ sə defɑ̃dʁ kɔ̃tʁ lə mɔ̃d/","zh":"我的花是短暂易逝的，而她只有四根刺来抵御世界！","en":"My flower is ephemeral, and she has only four thorns to defend herself against the world!","note":"","sourceLineIndex":39},{"id":"le-petit-prince-2cd-24-040","lineIndex":40,"speaker":"Le Petit Prince","original":"Et je l'ai laissée toute seule chez moi!","ipa":"/e ʒə le lɛse tut sœl ʃe mwa/","zh":"可我把她一个人留在家里了！","en":"And I left her all alone at home!","note":"","sourceLineIndex":40}],"sourceOrder":24,"displayOrder":24},{"order":25,"id":"25-je-prends-note","title":"Je Prends Note","titleZh":"做笔记","lines":[{"id":"le-petit-prince-2cd-25-001","lineIndex":1,"speaker":"","original":"Je dois connaître les déserts","ipa":"/ʒə dwa kɔnɛtʁ le dezɛʁ/","zh":"我必须了解沙漠","en":"I must know the deserts","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-25-002","lineIndex":2,"speaker":"","original":"Les sources qui jaillissent de la terre","ipa":"/le suʁs ki ʒajis də la tɛʁ/","zh":"从大地涌出的泉水","en":"The springs that gush from the earth","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-25-003","lineIndex":3,"speaker":"","original":"Les océans les rivières","ipa":"/lez oseɑ̃ le ʁivjɛʁ/","zh":"海洋与河流","en":"The oceans and rivers","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-25-004","lineIndex":4,"speaker":"","original":"Et les îles plantées sous la mer","ipa":"/e lez il plɑ̃te su la mɛʁ/","zh":"以及扎根海中的岛屿","en":"And islands rooted in the sea","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-25-005","lineIndex":5,"speaker":"","original":"Et je rêve de volcans qui grondent","ipa":"/e ʒə ʁɛv də vɔlkɑ̃ ki ɡʁɔ̃d/","zh":"我还梦想着轰鸣的火山","en":"And I dream of rumbling volcanoes","note":"","sourceLineIndex":5},{"id":"le-petit-prince-2cd-25-006","lineIndex":6,"speaker":"","original":"Dans des flots incandescents","ipa":"/dɑ̃ de floz ɛ̃kɑ̃dɛsɑ̃/","zh":"涌动着炽热的熔岩","en":"amid incandescent flows","note":"","sourceLineIndex":6},{"id":"le-petit-prince-2cd-25-007","lineIndex":7,"speaker":"","original":"De ces voiliers amarrés aux ondes","ipa":"/də se vwaljez amaʁez oz ɔ̃d/","zh":"还有仿佛系泊在波涛上的帆船","en":"of sailing ships moored to the waves","note":"","sourceLineIndex":7},{"id":"le-petit-prince-2cd-25-008","lineIndex":8,"speaker":"","original":"Dans les Quarantièmes Rugissants","ipa":"/dɑ̃ le kaʁɑ̃sjɛm ʁyʒisɑ̃/","zh":"航行在咆哮西风带","en":"in the Roaring Forties","note":"","sourceLineIndex":8},{"id":"le-petit-prince-2cd-25-009","lineIndex":9,"speaker":"","original":"Je prends note","ipa":"/ʒə pʁɑ̃ nɔt/","zh":"我做记录","en":"I take note","note":"","sourceLineIndex":9},{"id":"le-petit-prince-2cd-25-010","lineIndex":10,"speaker":"","original":"Enfermées au fond d'un cahier","ipa":"/ɑ̃fɛʁmez o fɔ̃ dœ̃ kaje/","zh":"被锁在一本笔记簿深处","en":"Shut away in the depths of a notebook","note":"","sourceLineIndex":10},{"id":"le-petit-prince-2cd-25-011","lineIndex":11,"speaker":"","original":"S'étalent mes seules lignes d'horizon","ipa":"/setal me sœl linj doʁizɔ̃/","zh":"那里铺展着我仅有的地平线","en":"my only horizons stretch out there","note":"","sourceLineIndex":11},{"id":"le-petit-prince-2cd-25-012","lineIndex":12,"speaker":"","original":"Ce bureau est ma dernière prison","ipa":"/sə byʁo ɛ ma dɛʁnjɛʁ pʁizɔ̃/","zh":"这间办公室是我最后的牢笼","en":"This office is my final prison","note":"","sourceLineIndex":12},{"id":"le-petit-prince-2cd-25-013","lineIndex":13,"speaker":"","original":"Je prends note","ipa":"/ʒə pʁɑ̃ nɔt/","zh":"我做记录","en":"I take note","note":"","sourceLineIndex":13},{"id":"le-petit-prince-2cd-25-014","lineIndex":14,"speaker":"","original":"Je ne vis rien je ne vois rien","ipa":"/ʒə nə vi ʁjɛ̃ ʒə nə vwa ʁjɛ̃/","zh":"我什么也没经历，什么也没看见","en":"I experience nothing; I see nothing","note":"","sourceLineIndex":14},{"id":"le-petit-prince-2cd-25-015","lineIndex":15,"speaker":"","original":"Je vis tout par procuration","ipa":"/ʒə vi tu paʁ pʁokyʁasjɔ̃/","zh":"我只能借别人的经历活着","en":"I live everything second-hand","note":"","sourceLineIndex":15},{"id":"le-petit-prince-2cd-25-016","lineIndex":16,"speaker":"","original":"En voyageur immobile","ipa":"/ɑ̃ vwajaʒœʁ imobil/","zh":"像一个静止不动的旅行者","en":"as a motionless traveller","note":"","sourceLineIndex":16},{"id":"le-petit-prince-2cd-25-017","lineIndex":17,"speaker":"","original":"À travers vos explorations","ipa":"/a tʁavɛʁ voz ɛksploʁasjɔ̃/","zh":"透过你们的探险","en":"through your explorations","note":"","sourceLineIndex":17},{"id":"le-petit-prince-2cd-25-018","lineIndex":18,"speaker":"","original":"Je prends note","ipa":"/ʒə pʁɑ̃ nɔt/","zh":"我做记录","en":"I take note","note":"","sourceLineIndex":18},{"id":"le-petit-prince-2cd-25-019","lineIndex":19,"speaker":"","original":"Je n'écris que des choses éternelles","ipa":"/ʒə nekʁi kə de ʃozz etɛʁnɛl/","zh":"我只记录永恒的事物","en":"I write down only eternal things","note":"","sourceLineIndex":19},{"id":"le-petit-prince-2cd-25-020","lineIndex":20,"speaker":"","original":"Je prends note","ipa":"/ʒə pʁɑ̃ nɔt/","zh":"我做记录","en":"I take note","note":"","sourceLineIndex":20},{"id":"le-petit-prince-2cd-25-021","lineIndex":21,"speaker":"","original":"Je n'ai que faire de ces choses précaires","ipa":"/ʒə ne kə fɛʁ də se ʃoz pʁekɛʁ/","zh":"我不需要这些短暂无常的事物","en":"I have no use for such fleeting things","note":"","sourceLineIndex":21},{"id":"le-petit-prince-2cd-25-022","lineIndex":22,"speaker":"","original":"Qui encombrent la terre et le ciel","ipa":"/ki ɑ̃kɔ̃bʁ la tɛʁ e lə sjɛl/","zh":"它们充塞大地与天空","en":"that clutter the earth and sky","note":"","sourceLineIndex":22},{"id":"le-petit-prince-2cd-25-023","lineIndex":23,"speaker":"","original":"Les poèmes et les dictionnaires","ipa":"/le pɔɛmz e le diksjɔnɛʁ/","zh":"诗歌与词典","en":"Poems and dictionaries","note":"","sourceLineIndex":23},{"id":"le-petit-prince-2cd-25-024","lineIndex":24,"speaker":"","original":"Je prends note","ipa":"/ʒə pʁɑ̃ nɔt/","zh":"我做记录","en":"I take note","note":"","sourceLineIndex":24},{"id":"le-petit-prince-2cd-25-025","lineIndex":25,"speaker":"","original":"Mais je ne sais rien de ma planète","ipa":"/mɛ ʒə nə sɛ ʁjɛ̃ də ma planɛt/","zh":"但我对自己的星球一无所知","en":"But I know nothing about my own planet","note":"","sourceLineIndex":25},{"id":"le-petit-prince-2cd-25-026","lineIndex":26,"speaker":"","original":"Je ne connais même pas un cours d'eau","ipa":"/ʒə nə kɔnɛ mɛm paz œ̃ kuʁ do/","zh":"我甚至不认识一条河流","en":"I do not even know a single watercourse","note":"","sourceLineIndex":26},{"id":"le-petit-prince-2cd-25-027","lineIndex":27,"speaker":"","original":"Je sais juste où mes frontières s'arrêtent","ipa":"/ʒə sɛ ʒyst u me fʁɔ̃tjɛʁ saʁɛt/","zh":"我只知道自己的边界止于何处","en":"I only know where my borders end","note":"","sourceLineIndex":27},{"id":"le-petit-prince-2cd-25-028","lineIndex":28,"speaker":"","original":"Coincé à l'arrière d'un bureau","ipa":"/kwɛ̃se a laʁjɛʁ dœ̃ byʁo/","zh":"困在一张书桌后面","en":"Stuck behind a desk","note":"","sourceLineIndex":28},{"id":"le-petit-prince-2cd-25-029","lineIndex":29,"speaker":"","original":"Je prends note","ipa":"/ʒə pʁɑ̃ nɔt/","zh":"我做记录","en":"I take note","note":"","sourceLineIndex":29}],"sourceOrder":25,"displayOrder":25},{"order":26,"id":"26-la-planete-terre","title":"La PlanÈTe Terre","titleZh":"地球","lines":[{"id":"le-petit-prince-2cd-26-001","lineIndex":1,"speaker":"Le Petit Prince","original":"J'aurais dû ne pas l'écouter.","ipa":"/ʒoʁɛ dyː nə pa lekute/","zh":"我本不该听她说了什么。","en":"I should not have listened to her.","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-26-002","lineIndex":2,"speaker":"Le Petit Prince","original":"Il ne faut jamais écouter les fleurs.","ipa":"/il nə fo ʒamɛz ekute le flœʁ/","zh":"永远不该听花说了什么。","en":"One should never listen to flowers.","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-26-003","lineIndex":3,"speaker":"Le Petit Prince","original":"Il faut les regarder et les respirer.","ipa":"/il fo le ʁəɡaʁde e le ʁɛspiʁe/","zh":"应该看着花、闻她们的香气。","en":"One should look at them and breathe in their fragrance.","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-26-004","lineIndex":4,"speaker":"Le Petit Prince","original":"La mienne embaumait ma planète","ipa":"/la mjɛn ɑ̃bomɛ ma planɛt/","zh":"我的花让整颗星球芳香四溢","en":"Mine perfumed my planet","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-26-005","lineIndex":5,"speaker":"Le Petit Prince","original":"mais je ne savais pas m'en réjouir.","ipa":"/mɛ ʒə nə savɛ pa mɑ̃ ʁeʒwiʁ/","zh":"可我不懂得为此欢喜。","en":"but I did not know how to delight in it.","note":"","sourceLineIndex":5},{"id":"le-petit-prince-2cd-26-006","lineIndex":6,"speaker":"Le Petit Prince","original":"Cette histoire de griffes, qui m'avait tellement agacé, aurait dû m'attendrir.","ipa":"/sɛt istwaʁ də ɡʁif ki mavɛ tɛlmɑ̃ aɡase oʁɛ dyː matɑ̃dʁiʁ/","zh":"那个关于爪子的说法曾让我十分恼火，其实本该令我心软。","en":"That business about claws, which had annoyed me so much, should have moved me.","note":"","sourceLineIndex":6},{"id":"le-petit-prince-2cd-26-007","lineIndex":7,"speaker":"Le Petit Prince","original":"Je n'ai rien su comprendre.","ipa":"/ʒə ne ʁjɛ̃ sy kɔ̃pʁɑ̃dʁ/","zh":"我什么也不懂。","en":"I understood nothing.","note":"","sourceLineIndex":7},{"id":"le-petit-prince-2cd-26-008","lineIndex":8,"speaker":"Le Petit Prince","original":"J'aurais dû la juger sur les actes et non sur les mots.","ipa":"/ʒoʁɛ dyː la ʒyʒe syʁ lez aktz e nɔ̃ syʁ le mo/","zh":"我本该凭她的行动，而非言语来判断她。","en":"I should have judged her by her actions, not her words.","note":"","sourceLineIndex":8},{"id":"le-petit-prince-2cd-26-009","lineIndex":9,"speaker":"Le Petit Prince","original":"Elle m'embaumait et m'éclairait.","ipa":"/ɛl mɑ̃bomɛt e meklɛʁɛ/","zh":"她用芬芳包围我，也照亮我。","en":"She filled me with fragrance and light.","note":"","sourceLineIndex":9},{"id":"le-petit-prince-2cd-26-010","lineIndex":10,"speaker":"Le Petit Prince","original":"Je n'aurais jamais dû m'enfuir.","ipa":"/ʒə noʁɛ ʒamɛ dyː mɑ̃fyiʁ/","zh":"我根本不该逃走。","en":"I should never have run away.","note":"","sourceLineIndex":10},{"id":"le-petit-prince-2cd-26-011","lineIndex":11,"speaker":"Le Petit Prince","original":"J'aurais dû deviner sa tendresse derrière ses pauvres ruses.","ipa":"/ʒoʁɛ dyː dəvine sa tɑ̃dʁɛs dɛʁjɛʁ se povʁ ʁyz/","zh":"我本该看出她拙劣伎俩背后的温柔。","en":"I should have sensed her tenderness behind her poor little tricks.","note":"","sourceLineIndex":11},{"id":"le-petit-prince-2cd-26-012","lineIndex":12,"speaker":"Le Petit Prince","original":"Les fleurs sont si contradictoires.","ipa":"/le flœʁ sɔ̃ si kɔ̃tʁadiktwaʁ/","zh":"花儿总是如此矛盾。","en":"Flowers are so contradictory.","note":"","sourceLineIndex":12},{"id":"le-petit-prince-2cd-26-013","lineIndex":13,"speaker":"Le Petit Prince","original":"J'étais trop jeune pour savoir l'aimer.","ipa":"/ʒetɛ tʁo ʒøn puʁ savwaʁ lɛme/","zh":"那时我太年轻，还不懂得如何爱她。","en":"I was too young to know how to love her.","note":"","sourceLineIndex":13},{"id":"le-petit-prince-2cd-26-014","lineIndex":14,"speaker":"Le Géographe","original":"Tout cela, nous n'en prenons pas note.","ipa":"/tu səla nu nɑ̃ pʁənɔ̃ pa nɔt/","zh":"这一切，我们都不作记录。","en":"We do not record any of that.","note":"","sourceLineIndex":14},{"id":"le-petit-prince-2cd-26-015","lineIndex":15,"speaker":"Le Petit Prince","original":"Que me conseillez-vous d'aller visiter?","ipa":"/kə mə kɔ̃sɛjevu dale vizite/","zh":"您建议我去哪里看看？","en":"Where do you advise me to visit?","note":"","sourceLineIndex":15},{"id":"le-petit-prince-2cd-26-016","lineIndex":16,"speaker":"Le Géographe","original":"La planète Terre. Elle a bonne réputation.","ipa":"/la planɛt tɛʁ ɛl a bɔn ʁepytasjɔ̃/","zh":"地球。它名声很好。","en":"Planet Earth. It has a good reputation.","note":"","sourceLineIndex":16}],"sourceOrder":26,"displayOrder":26},{"order":27,"id":"27-la-terre","title":"La Terre","titleZh":"地球","lines":[{"id":"le-petit-prince-2cd-27-001","lineIndex":1,"speaker":"","original":"La septième planète sera donc la Terre","ipa":"/la sɛtjɛm planɛt səʁa dɔ̃k la tɛʁ/","zh":"第七颗星球就是地球","en":"The seventh planet will therefore be Earth","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-27-002","lineIndex":2,"speaker":"","original":"La Terre n'est pas une planète quelconque","ipa":"/la tɛʁ nɛ paz yn planɛt kɛlkɔ̃k/","zh":"地球不是一颗普通的星球","en":"Earth is not just any planet","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-27-003","lineIndex":3,"speaker":"","original":"On y compte cent onze rois (En n'oubliant pas bien sûr les rois nègres)","ipa":"/ɔ̃n i kɔ̃t sɑ̃ ɔ̃z ʁwa ɑ̃ nubliɑ̃ pa bjɛ̃ syːʁ le ʁwa nɛɡʁ/","zh":"这里有一百一十一个国王（当然也包括黑人国王）","en":"There are one hundred and eleven kings (not forgetting, of course, the Black kings)","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-27-004","lineIndex":4,"speaker":"","original":"Sept mille géographes neuf cent mille businessmen","ipa":"/sɛt mil ʒeɔɡʁaf nœf sɑ̃ mil bɪznəsmɛn/","zh":"七千个地理学家，九十万生意人","en":"Seven thousand geographers, nine hundred thousand businessmen","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-27-005","lineIndex":5,"speaker":"","original":"Sept millions et demi d'ivrognes, Trois cent onze millions de vaniteux","ipa":"/sɛt miljɔ̃z e dəmi divʁonj tʁwa sɑ̃ ɔ̃z miljɔ̃ də vanitø/","zh":"七百五十万酒鬼，三亿一千一百万爱慕虚荣的人","en":"Seven and a half million drunkards, Three hundred and eleven million vain people","note":"","sourceLineIndex":5},{"id":"le-petit-prince-2cd-27-006","lineIndex":6,"speaker":"","original":"C'est-à-dire environ deux milliards de grandes personnes","ipa":"/sɛtadiʁ ɑ̃viʁɔ̃ dø miljaʁ də ɡʁɑ̃d pɛʁsɔn/","zh":"也就是说，有二十亿左右的大人","en":"That is to say around two billion grown-ups","note":"","sourceLineIndex":6},{"id":"le-petit-prince-2cd-27-007","lineIndex":7,"speaker":"","original":"La Terre","ipa":"/la tɛʁ/","zh":"地球","en":"The Earth","note":"","sourceLineIndex":7},{"id":"le-petit-prince-2cd-27-008","lineIndex":8,"speaker":"","original":"Dans cet univers Et ses particules élémentaires","ipa":"/dɑ̃ sɛt ynivɛʁz e se paʁtikylz elemɑ̃tɛʁ/","zh":"在这宇宙及其基本粒子之间","en":"In this universe and among its elementary particles","note":"","sourceLineIndex":8},{"id":"le-petit-prince-2cd-27-009","lineIndex":9,"speaker":"","original":"Ce mystère Au milieu des airs","ipa":"/sə mistɛʁ o miljø dez ɛʁ/","zh":"这个悬在空中的谜","en":"this mystery suspended in the air","note":"","sourceLineIndex":9},{"id":"le-petit-prince-2cd-27-010","lineIndex":10,"speaker":"","original":"Ces mers ces déserts","ipa":"/se mɛʁ se dezɛʁ/","zh":"这些大海，这些沙漠","en":"These seas these deserts","note":"","sourceLineIndex":10},{"id":"le-petit-prince-2cd-27-011","lineIndex":11,"speaker":"","original":"Une légère goutte de boue Perdue dans l'éther","ipa":"/yn leʒɛʁ ɡut də bu pɛʁdy dɑ̃ ɛleɪðə/","zh":"以太中迷失的一小滴泥","en":"A tiny drop of mud lost in the ether","note":"","sourceLineIndex":11},{"id":"le-petit-prince-2cd-27-012","lineIndex":12,"speaker":"","original":"Où tous les hommes se tiennent debout","ipa":"/u tu lez ɔm sə tjɛn dəbu/","zh":"这里所有的人都直立行走","en":"Where all men stand upright","note":"","sourceLineIndex":12},{"id":"le-petit-prince-2cd-27-013","lineIndex":13,"speaker":"","original":"Accrochés au clair De leur étoile","ipa":"/akʁoʃez o klɛʁ də lœʁ etwal/","zh":"攀附在自己星球的光亮上","en":"Clinging to the light of their star","note":"","sourceLineIndex":13},{"id":"le-petit-prince-2cd-27-014","lineIndex":14,"speaker":"","original":"Solitaire","ipa":"/solitɛʁ/","zh":"孤独","en":"Solitary","note":"","sourceLineIndex":14},{"id":"le-petit-prince-2cd-27-015","lineIndex":15,"speaker":"","original":"Planète en colère","ipa":"/planɛt ɑ̃ kolɛʁ/","zh":"愤怒的星球","en":"Angry planet","note":"","sourceLineIndex":15},{"id":"le-petit-prince-2cd-27-016","lineIndex":16,"speaker":"","original":"Du système solaire Révolutionnaire","ipa":"/dy sistɛm solɛʁ ʁevolysjɔnɛʁ/","zh":"太阳系里叛逆的星球","en":"revolutionary within the solar system","note":"","sourceLineIndex":16},{"id":"le-petit-prince-2cd-27-017","lineIndex":17,"speaker":"","original":"C'est la Terre","ipa":"/sɛ la tɛʁ/","zh":"这就是地球","en":"It's the Earth","note":"","sourceLineIndex":17},{"id":"le-petit-prince-2cd-27-018","lineIndex":18,"speaker":"","original":"Ses années lumière","ipa":"/sez ane lymjɛʁ/","zh":"它的光年","en":"Its light-years","note":"","sourceLineIndex":18},{"id":"le-petit-prince-2cd-27-019","lineIndex":19,"speaker":"","original":"Et ses allumeurs de réverbères","ipa":"/e sez alymœʁ də ʁevɛʁbɛʁ/","zh":"以及它的点灯人","en":"And its lamplighters","note":"","sourceLineIndex":19},{"id":"le-petit-prince-2cd-27-020","lineIndex":20,"speaker":"","original":"Pour vous donner une idée des dimensions de la Terre","ipa":"/puʁ vu dɔne yn ide de dimɑ̃sjɔ̃ də la tɛʁ/","zh":"为了让你对地球的大小有个概念","en":"To give you an idea of the dimensions of the Earth","note":"","sourceLineIndex":20},{"id":"le-petit-prince-2cd-27-021","lineIndex":21,"speaker":"","original":"je vous dirai qu'avant l'invention de l'électricité","ipa":"/ʒə vu diʁe kavɑ̃ lɛ̃vɑ̃sjɔ̃ də lelɛktʁisite/","zh":"我可以告诉你，在电力发明以前","en":"I shall tell you that before electricity was invented","note":"","sourceLineIndex":21},{"id":"le-petit-prince-2cd-27-022","lineIndex":22,"speaker":"","original":"on y devait entretenir","ipa":"/ɔ̃n i dəvɛt ɑ̃tʁətniʁ/","zh":"地球上需要维持","en":"it was necessary to maintain","note":"","sourceLineIndex":22},{"id":"le-petit-prince-2cd-27-023","lineIndex":23,"speaker":"","original":"sur l'ensemble des six continents","ipa":"/syʁ lɑ̃sɑ̃bl de si kɔ̃tinɑ̃/","zh":"遍布六大洲的","en":"across all six continents","note":"","sourceLineIndex":23},{"id":"le-petit-prince-2cd-27-024","lineIndex":24,"speaker":"","original":"une véritable armée de quatre cent soixante deux mille cinq cent onze allumeurs de réverbères.","ipa":"/yn veʁitabl aʁme də katʁ sɑ̃ swasɑ̃t dø mil sɛ̃ sɑ̃ ɔ̃z alymœʁ də ʁevɛʁbɛʁ/","zh":"一支由四十六万两千五百一十一名点灯人组成的真正大军。","en":"a veritable army of four hundred and sixty-two thousand five hundred and eleven lamplighters.","note":"","sourceLineIndex":24},{"id":"le-petit-prince-2cd-27-025","lineIndex":25,"speaker":"","original":"Vu d'un peu loin ça faisait un effet splendide.","ipa":"/vy dœ̃ pø lwɛ̃ sa fəzɛt œ̃n efɛ splɑ̃did/","zh":"远远望去，这些灯真是光彩夺目","en":"Seen from a little distance it had a splendid effect.","note":"","sourceLineIndex":25},{"id":"le-petit-prince-2cd-27-026","lineIndex":26,"speaker":"","original":"La Terre","ipa":"/la tɛʁ/","zh":"地球","en":"The Earth","note":"","sourceLineIndex":26},{"id":"le-petit-prince-2cd-27-027","lineIndex":27,"speaker":"","original":"Une légère goutte de boue Perdue dans l'éther","ipa":"/yn leʒɛʁ ɡut də bu pɛʁdy dɑ̃ ɛleɪðə/","zh":"以太中迷失的一小滴泥","en":"A tiny drop of mud lost in the ether","note":"","sourceLineIndex":27},{"id":"le-petit-prince-2cd-27-028","lineIndex":28,"speaker":"","original":"Où tous les hommes se tiennent debout","ipa":"/u tu lez ɔm sə tjɛn dəbu/","zh":"所有的人都直立行走","en":"Where all men stand upright","note":"","sourceLineIndex":28},{"id":"le-petit-prince-2cd-27-029","lineIndex":29,"speaker":"","original":"Le temps d'un éclair","ipa":"/lə tɑ̃ dœ̃n eklɛʁ/","zh":"闪电般的一瞬","en":"The time of a flash","note":"","sourceLineIndex":29},{"id":"le-petit-prince-2cd-27-030","lineIndex":30,"speaker":"","original":"La Terre","ipa":"/la tɛʁ/","zh":"地球","en":"The Earth","note":"","sourceLineIndex":30},{"id":"le-petit-prince-2cd-27-031","lineIndex":31,"speaker":"","original":"Dans cet univers","ipa":"/dɑ̃ sɛt ynivɛʁ/","zh":"在这个宇宙中","en":"In this universe","note":"","sourceLineIndex":31},{"id":"le-petit-prince-2cd-27-032","lineIndex":32,"speaker":"","original":"Ridicule et fière","ipa":"/ʁidikyl e fjɛʁ/","zh":"可笑而骄傲","en":"Ridiculous and proud","note":"","sourceLineIndex":32},{"id":"le-petit-prince-2cd-27-033","lineIndex":33,"speaker":"","original":"Particulière","ipa":"/paʁtikyljɛʁ/","zh":"与众不同","en":"Particular","note":"","sourceLineIndex":33},{"id":"le-petit-prince-2cd-27-034","lineIndex":34,"speaker":"","original":"Volontaire","ipa":"/volɔ̃tɛʁ/","zh":"意志坚定","en":"Wilful","note":"","sourceLineIndex":34},{"id":"le-petit-prince-2cd-27-035","lineIndex":35,"speaker":"","original":"À ne pas se taire","ipa":"/a nə pa sə tɛʁ/","zh":"决不沉默","en":"Refusing to be silent","note":"","sourceLineIndex":35},{"id":"le-petit-prince-2cd-27-036","lineIndex":36,"speaker":"","original":"Cette mère nourricière Qui nous enterre","ipa":"/sɛt mɛʁ nuʁisjɛʁ ki nuz ɑ̃tɛʁ/","zh":"这位养育并最终埋葬我们的母亲","en":"This nurturing mother who buries us","note":"","sourceLineIndex":36},{"id":"le-petit-prince-2cd-27-037","lineIndex":37,"speaker":"","original":"C'est la Terre","ipa":"/sɛ la tɛʁ/","zh":"这就是地球","en":"It's the Earth","note":"","sourceLineIndex":37},{"id":"le-petit-prince-2cd-27-038","lineIndex":38,"speaker":"","original":"La Terre","ipa":"/la tɛʁ/","zh":"地球","en":"The Earth","note":"","sourceLineIndex":38}],"sourceOrder":27,"displayOrder":27},{"order":28,"id":"28-ephemeres","title":"Ephémères","titleZh":"蜉蝣","lines":[{"id":"le-petit-prince-2cd-28-001","lineIndex":1,"speaker":"","original":"On veut croire à des choses éternelles","ipa":"/ɔ̃ vø kʁwaʁ a de ʃozz etɛʁnɛl/","zh":"我们愿意相信那些永恒之物","en":"We want to believe in eternal things","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-28-002","lineIndex":2,"speaker":"","original":"Pour oublier toutes ces choses précaires","ipa":"/puʁ ublie tut se ʃoz pʁekɛʁ/","zh":"好忘却所有短暂无常的事物","en":"To forget all these fleeting things","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-28-003","lineIndex":3,"speaker":"","original":"Qui encombrent la Terre et le ciel","ipa":"/ki ɑ̃kɔ̃bʁ la tɛʁ e lə sjɛl/","zh":"易逝之物在大地和天空之间","en":"Which clutter the Earth and the sky","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-28-004","lineIndex":4,"speaker":"","original":"Les poèmes et les dictionnaires","ipa":"/le pɔɛmz e le diksjɔnɛʁ/","zh":"诗歌与词典","en":"Poems and dictionaries","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-28-005","lineIndex":5,"speaker":"","original":"Car nous sommes","ipa":"/kaʁ nu sɔm/","zh":"因为我们","en":"Because we are","note":"","sourceLineIndex":5},{"id":"le-petit-prince-2cd-28-006","lineIndex":6,"speaker":"","original":"Éphémères","ipa":"/efemɛʁ/","zh":"命如蜉蝣，转瞬即逝","en":"Ephemeral","note":"","sourceLineIndex":6},{"id":"le-petit-prince-2cd-28-007","lineIndex":7,"speaker":"","original":"Menacés par une fin prochaine","ipa":"/mənase paʁ yn fɛ̃ pʁoʃɛn/","zh":"面临着即将到来的终结","en":"Threatened by an approaching end","note":"","sourceLineIndex":7},{"id":"le-petit-prince-2cd-28-008","lineIndex":8,"speaker":"","original":"Les explosions en chaîne","ipa":"/lez ɛksplozjɔ̃z ɑ̃ ʃɛn/","zh":"接连发生的爆炸","en":"Chain reactions","note":"","sourceLineIndex":8},{"id":"le-petit-prince-2cd-28-009","lineIndex":9,"speaker":"","original":"Les amours et les gloires, passagères","ipa":"/lez amuʁz e le ɡlwaʁ pasaʒɛʁ/","zh":"转瞬即逝的爱情与荣耀","en":"Fleeting loves and glories","note":"","sourceLineIndex":9},{"id":"le-petit-prince-2cd-28-010","lineIndex":10,"speaker":"","original":"Éphémères","ipa":"/efemɛʁ/","zh":"命如蜉蝣，转瞬即逝","en":"Ephemeral","note":"","sourceLineIndex":10},{"id":"le-petit-prince-2cd-28-011","lineIndex":11,"speaker":"","original":"Avoir la sagesse nécessaire","ipa":"/avwaʁ la saʒɛs nesɛsɛʁ/","zh":"有必要的智慧","en":"Have the necessary wisdom","note":"","sourceLineIndex":11},{"id":"le-petit-prince-2cd-28-012","lineIndex":12,"speaker":"","original":"De prendre un peu tout à la légère","ipa":"/də pʁɑ̃dʁ œ̃ pø tut a la leʒɛʁ/","zh":"把一切看轻","en":"To take everything lightly","note":"","sourceLineIndex":12},{"id":"le-petit-prince-2cd-28-013","lineIndex":13,"speaker":"","original":"Et savoir se détacher de la Terre","ipa":"/e savwaʁ sə detaʃe də la tɛʁ/","zh":"也知道如何摆脱地球的束缚","en":"And know how to detach yourself from the Earth","note":"","sourceLineIndex":13},{"id":"le-petit-prince-2cd-28-014","lineIndex":14,"speaker":"","original":"Éphémères","ipa":"/efemɛʁ/","zh":"命如蜉蝣，转瞬即逝","en":"Ephemeral","note":"","sourceLineIndex":14},{"id":"le-petit-prince-2cd-28-015","lineIndex":15,"speaker":"","original":"Épris de folie temporaire","ipa":"/epʁi də foli tɑ̃poʁɛʁ/","zh":"迷恋着短暂的疯狂","en":"Infatuated with temporary madness","note":"","sourceLineIndex":15},{"id":"le-petit-prince-2cd-28-016","lineIndex":16,"speaker":"","original":"Qui nous laisse espérer le ciel","ipa":"/ki nu lɛs ɛspeʁe lə sjɛl/","zh":"它让我们对天空怀抱希望","en":"which lets us hope for heaven","note":"","sourceLineIndex":16},{"id":"le-petit-prince-2cd-28-017","lineIndex":17,"speaker":"","original":"Et nous attache à des pierres","ipa":"/e nuz ataʃ a de pjɛʁ/","zh":"又把我们系在石头上","en":"and binds us to stones","note":"","sourceLineIndex":17},{"id":"le-petit-prince-2cd-28-018","lineIndex":18,"speaker":"","original":"Éphémères","ipa":"/efemɛʁ/","zh":"命如蜉蝣，转瞬即逝","en":"Ephemeral","note":"","sourceLineIndex":18},{"id":"le-petit-prince-2cd-28-019","lineIndex":19,"speaker":"","original":"Qui, en prières","ipa":"/ki ɑ̃ pʁiɛʁ/","zh":"我们在祈祷中","en":"Who, in prayer","note":"","sourceLineIndex":19},{"id":"le-petit-prince-2cd-28-020","lineIndex":20,"speaker":"","original":"Trouvent un sens à leurs destins","ipa":"/tʁuvt œ̃ sɑ̃s a lœʁ dɛstɛ̃/","zh":"为自己的命运找到意义","en":"find meaning in their destinies","note":"","sourceLineIndex":20},{"id":"le-petit-prince-2cd-28-021","lineIndex":21,"speaker":"","original":"Si incertains","ipa":"/si ɛ̃sɛʁtɛ̃/","zh":"那如此不确定的命运","en":"so uncertain","note":"","sourceLineIndex":21},{"id":"le-petit-prince-2cd-28-022","lineIndex":22,"speaker":"","original":"On veut croire à des choses éternelles","ipa":"/ɔ̃ vø kʁwaʁ a de ʃozz etɛʁnɛl/","zh":"我们愿意相信永恒之物","en":"We want to believe in eternal things","note":"","sourceLineIndex":22},{"id":"le-petit-prince-2cd-28-023","lineIndex":23,"speaker":"","original":"Pour oublier toutes ces choses précaires","ipa":"/puʁ ublie tut se ʃoz pʁekɛʁ/","zh":"好忘却所有短暂无常的事物","en":"To forget all these fleeting things","note":"","sourceLineIndex":23},{"id":"le-petit-prince-2cd-28-024","lineIndex":24,"speaker":"","original":"Qui ne font que nous ramener","ipa":"/ki nə fɔ̃ kə nu ʁamne/","zh":"易逝之物只会将我们","en":"Who only bring us back","note":"","sourceLineIndex":24},{"id":"le-petit-prince-2cd-28-025","lineIndex":25,"speaker":"","original":"Vers notre simple condition de mortel","ipa":"/vɛʁ notʁ sɛ̃pl kɔ̃disjɔ̃ də mɔʁtɛl/","zh":"带至唯一的必死之境","en":"Towards our simple mortal condition","note":"","sourceLineIndex":25},{"id":"le-petit-prince-2cd-28-026","lineIndex":26,"speaker":"","original":"Éphémères","ipa":"/efemɛʁ/","zh":"命如蜉蝣，转瞬即逝","en":"Ephemeral","note":"","sourceLineIndex":26},{"id":"le-petit-prince-2cd-28-027","lineIndex":27,"speaker":"","original":"Pris au piège sous l'effet de serre","ipa":"/pʁi o pjɛʒ su lefɛ də sɛʁ/","zh":"陷入温室效应的困境","en":"Trapped under the greenhouse effect","note":"","sourceLineIndex":27},{"id":"le-petit-prince-2cd-28-028","lineIndex":28,"speaker":"","original":"Comme ces fragiles insectes","ipa":"/kɔm se fʁaʒilz ɛ̃sɛkt/","zh":"就像那些脆弱的昆虫","en":"Like these fragile insects","note":"","sourceLineIndex":28},{"id":"le-petit-prince-2cd-28-029","lineIndex":29,"speaker":"","original":"Qui naissent pour s'éteindre","ipa":"/ki nɛs puʁ setɛ̃dʁ/","zh":"生来便注定熄灭","en":"born only to fade away","note":"","sourceLineIndex":29},{"id":"le-petit-prince-2cd-28-030","lineIndex":30,"speaker":"","original":"En pleine lumière","ipa":"/ɑ̃ plɛn lymjɛʁ/","zh":"在明亮的光中","en":"in full light","note":"","sourceLineIndex":30},{"id":"le-petit-prince-2cd-28-031","lineIndex":31,"speaker":"","original":"Éphémères","ipa":"/efemɛʁ/","zh":"命如蜉蝣，转瞬即逝","en":"Ephemeral","note":"","sourceLineIndex":31},{"id":"le-petit-prince-2cd-28-032","lineIndex":32,"speaker":"","original":"Avoir la sagesse nécessaire","ipa":"/avwaʁ la saʒɛs nesɛsɛʁ/","zh":"有必要的智慧","en":"Have the necessary wisdom","note":"","sourceLineIndex":32},{"id":"le-petit-prince-2cd-28-033","lineIndex":33,"speaker":"","original":"De prendre un peu tout à la légère","ipa":"/də pʁɑ̃dʁ œ̃ pø tut a la leʒɛʁ/","zh":"把一切看轻","en":"To take everything lightly","note":"","sourceLineIndex":33},{"id":"le-petit-prince-2cd-28-034","lineIndex":34,"speaker":"","original":"Et savoir se détacher de la terre","ipa":"/e savwaʁ sə detaʃe də la tɛʁ/","zh":"也知道如何摆脱地球的束缚","en":"And knowing how to detach themselves from the earth","note":"","sourceLineIndex":34},{"id":"le-petit-prince-2cd-28-035","lineIndex":35,"speaker":"","original":"Éphémères","ipa":"/efemɛʁ/","zh":"命如蜉蝣，转瞬即逝","en":"Ephemeral","note":"","sourceLineIndex":35},{"id":"le-petit-prince-2cd-28-036","lineIndex":36,"speaker":"","original":"Épris de folie temporaire","ipa":"/epʁi də foli tɑ̃poʁɛʁ/","zh":"迷恋着短暂的疯狂","en":"Infatuated with temporary madness","note":"","sourceLineIndex":36},{"id":"le-petit-prince-2cd-28-037","lineIndex":37,"speaker":"","original":"Qui nous laisse espérer le ciel","ipa":"/ki nu lɛs ɛspeʁe lə sjɛl/","zh":"它让我们对天空怀抱希望","en":"which lets us hope for heaven","note":"","sourceLineIndex":37},{"id":"le-petit-prince-2cd-28-038","lineIndex":38,"speaker":"","original":"Et nous attache à des pierres","ipa":"/e nuz ataʃ a de pjɛʁ/","zh":"又把我们系在石头上","en":"and binds us to stones","note":"","sourceLineIndex":38},{"id":"le-petit-prince-2cd-28-039","lineIndex":39,"speaker":"","original":"Éphémères","ipa":"/efemɛʁ/","zh":"命如蜉蝣，转瞬即逝","en":"Ephemeral","note":"","sourceLineIndex":39},{"id":"le-petit-prince-2cd-28-040","lineIndex":40,"speaker":"","original":"Pour enfin n'être dans ces déserts","ipa":"/puʁ ɑ̃fɛ̃ nɛtʁ dɑ̃ se dezɛʁ/","zh":"直到最终在这些沙漠中","en":"until at last, in these deserts, we are","note":"","sourceLineIndex":40},{"id":"le-petit-prince-2cd-28-041","lineIndex":41,"speaker":"","original":"Plus qu'un grain de poussière","ipa":"/ply kœ̃ ɡʁɛ̃ də pusjɛʁ/","zh":"不过一粒尘埃","en":"nothing more than a grain of dust","note":"","sourceLineIndex":41}],"sourceOrder":28,"displayOrder":28},{"order":29,"id":"29-sur-la-terre","title":"Sur La Terre","titleZh":"世上","lines":[{"id":"le-petit-prince-2cd-29-001","lineIndex":1,"speaker":"Le Petit Prince","original":"Bonne nuit.","ipa":"/bɔn nyi/","zh":"晚安","en":"Good night.","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-29-002","lineIndex":2,"speaker":"Le Serpent","original":"Bonne nuit.","ipa":"/bɔn nyi/","zh":"晚安","en":"Good night.","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-29-003","lineIndex":3,"speaker":"Le Petit Prince","original":"Sur quelle planète suis-je tombé?","ipa":"/syʁ kɛl planɛt syiʒ tɔ̃be/","zh":"这儿是什么星球？","en":"What planet have I fallen on?","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-29-004","lineIndex":4,"speaker":"Le Serpent","original":"Sur la Terre, en Afrique.","ipa":"/syʁ la tɛʁ ɑ̃n afʁik/","zh":"在地球，非洲。","en":"On Earth, in Africa.","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-29-005","lineIndex":5,"speaker":"Le Petit Prince","original":"Où sont les hommes?","ipa":"/u sɔ̃ lez ɔm/","zh":"人在哪儿呢？","en":"Where are the men?","note":"","sourceLineIndex":5},{"id":"le-petit-prince-2cd-29-006","lineIndex":6,"speaker":"Le Serpent","original":"Ici c'est le désert, il n'y a personne dans les déserts.","ipa":"/isi sɛ lə dezɛʁ il ni a pɛʁsɔn dɑ̃ le dezɛʁ/","zh":"这儿是沙漠 沙漠里是没有人烟的","en":"This is the desert, there is no one in the deserts.","note":"","sourceLineIndex":6},{"id":"le-petit-prince-2cd-29-007","lineIndex":7,"speaker":"Le Serpent","original":"La Terre est grande.","ipa":"/la tɛʁ ɛ ɡʁɑ̃d/","zh":"地球很大","en":"The Earth is big.","note":"","sourceLineIndex":7},{"id":"le-petit-prince-2cd-29-008","lineIndex":8,"speaker":"Le Petit Prince","original":"Je sais, deux milliards d'habitants","ipa":"/ʒə sɛ dø miljaʁ dabitɑ̃/","zh":"我晓得 地球上有二十亿人口","en":"I know, two billion inhabitants","note":"","sourceLineIndex":8},{"id":"le-petit-prince-2cd-29-009","lineIndex":9,"speaker":"Le Petit Prince","original":"avec une armée de 472 511 allumeurs de réverbères sur six continents","ipa":"/avɛk yn aʁme də katʁsɑ̃ swasɑ̃tduz mil sɛ̃ksɑ̃ ɔ̃z alymœʁ də ʁevɛʁbɛʁ syʁ si kɔ̃tinɑ̃/","zh":"六大洲上有着472511个点灯人组成的大军","en":"with an army of 472, 511 lamplighters on six continents","note":"","sourceLineIndex":9},{"id":"le-petit-prince-2cd-29-010","lineIndex":10,"speaker":"Le Petit Prince","original":"ça faisait un effet splendide vu d'en haut, comme un ballet d'opéra.","ipa":"/sa fəzɛt œ̃n efɛ splɑ̃did vy dɑ̃ o kɔm œ̃ balɛ dopeʁa/","zh":"从高处看蔚为壮观，宛如歌剧中的芭蕾。","en":"seen from above, it made a splendid sight, like a ballet at the opera.","note":"","sourceLineIndex":10},{"id":"le-petit-prince-2cd-29-011","lineIndex":11,"speaker":"Le Petit Prince","original":"D'abord les allumeurs de réverbères de Nouvelle-Zélande, d'Australie, et...","ipa":"/dabɔʁ lez alymœʁ də ʁevɛʁbɛʁ də nuvɛlzelɑ̃d dostʁali e/","zh":"首先上场的是新西兰、澳大利亚的点灯人 接着......","en":"First the lamplighters from New Zealand, Australia, and...","note":"","sourceLineIndex":11},{"id":"le-petit-prince-2cd-29-012","lineIndex":12,"speaker":"Le Serpent","original":"Attention","ipa":"/atɑ̃sjɔ̃/","zh":"当心。","en":"Careful.","note":"","sourceLineIndex":12},{"id":"le-petit-prince-2cd-29-013","lineIndex":13,"speaker":"Le Serpent","original":"Quand on veut faire de l'esprit, il arrive qu'on invente un peu.","ipa":"/kɑ̃t ɔ̃ vø fɛʁ də lɛspʁi il aʁiv kɔ̃n ɛ̃vɑ̃t œ̃ pø/","zh":"好出风头 喜欢卖弄聪明的人 多少会讲几句大话 吹点牛皮","en":"When we want to be witty, we sometimes invent a little.","note":"","sourceLineIndex":13},{"id":"le-petit-prince-2cd-29-014","lineIndex":14,"speaker":"Le Serpent","original":"Tu vas donner une fausse idée de la planète à ceux qui ne la connaissent pas.","ipa":"/ty va dɔne yn fos ide də la planɛt a sø ki nə la kɔnɛs pa/","zh":"你会让不了解这颗星球的人产生错误印象。","en":"You will give those who do not know the planet a false idea of it.","note":"","sourceLineIndex":14},{"id":"le-petit-prince-2cd-29-015","lineIndex":15,"speaker":"Le Serpent","original":"Les hommes occupent très peu de place sur la Terre.","ipa":"/lez ɔmz ɔkyp tʁɛ pø də plas syʁ la tɛʁ/","zh":"人在地球上占的位置微乎其微","en":"Men occupy very little space on Earth.","note":"","sourceLineIndex":15},{"id":"le-petit-prince-2cd-29-016","lineIndex":16,"speaker":"Le Serpent","original":"Si tous les habitants se tenaient debout et un peu serrés","ipa":"/si tu lez abitɑ̃ sə tənɛ dəbu e œ̃ pø sɛʁe/","zh":"如果所有居民都站着、挤得紧些","en":"If all the inhabitants stood upright and crowded a little close together","note":"","sourceLineIndex":16},{"id":"le-petit-prince-2cd-29-017","lineIndex":17,"speaker":"Le Serpent","original":"on pourrait entasser l'humanité entière sur le moindre petit ilôt du Pacifique.","ipa":"/ɔ̃ puʁɛt ɑ̃tase lymanite ɑ̃tjɛʁ syʁ lə mwɛ̃dʁ pətit iloː dy pasifik/","zh":"整个人类都能挤在太平洋上一座最小的小岛上。","en":"all humanity could be crowded onto one tiny islet in the Pacific.","note":"","sourceLineIndex":17},{"id":"le-petit-prince-2cd-29-018","lineIndex":18,"speaker":"Le Petit Prince","original":"Les grandes personnes ne te croiront jamais.","ipa":"/le ɡʁɑ̃d pɛʁsɔn nə tə kʁwaʁɔ̃ ʒamɛ/","zh":"大人们不会相信你的话的","en":"Grown-ups will never believe you.","note":"","sourceLineIndex":18},{"id":"le-petit-prince-2cd-29-019","lineIndex":19,"speaker":"Le Serpent","original":"Elles se voient importantes comme des baobabs.","ipa":"/ɛl sə vwat ɛ̃pɔʁtɑ̃t kɔm de baobab/","zh":"他们把自己看得像猴面包树一样了不起。","en":"They imagine themselves as important as baobabs.","note":"","sourceLineIndex":19},{"id":"le-petit-prince-2cd-29-020","lineIndex":20,"speaker":"Le Petit Prince","original":"Je me demande si les étoiles sont éclairées afin que chacun puisse un jour retrouver la sienne.","ipa":"/ʒə mə dəmɑ̃d si lez etwal sɔ̃t eklɛʁe afɛ̃ kə ʃakœ̃ pyis œ̃ ʒuʁ ʁətʁuve la sjɛn/","zh":"我在想 星星发亮是不是为了让每个人有一天能找到自己的星星","en":"I wonder if the stars are lit so that everyone can one day find their own.","note":"","sourceLineIndex":20},{"id":"le-petit-prince-2cd-29-021","lineIndex":21,"speaker":"Le Petit Prince","original":"Regarde ma planète","ipa":"/ʁəɡaʁd ma planɛt/","zh":"你看我的星球","en":"Look at my planet","note":"","sourceLineIndex":21},{"id":"le-petit-prince-2cd-29-022","lineIndex":22,"speaker":"Le Petit Prince","original":"elle est juste au-dessus de nous.","ipa":"/ɛl ɛ ʒyst odəsy də nu/","zh":"它就在我们正上方。","en":"it's right above us.","note":"","sourceLineIndex":22},{"id":"le-petit-prince-2cd-29-023","lineIndex":23,"speaker":"Le Petit Prince","original":"Comme elle est loin...","ipa":"/kɔm ɛl ɛ lwɛ̃/","zh":"它多么遥远啊……","en":"How far away it is...","note":"","sourceLineIndex":23},{"id":"le-petit-prince-2cd-29-024","lineIndex":24,"speaker":"Le Serpent","original":"Elle est belle.","ipa":"/ɛl ɛ bɛl/","zh":"它真美","en":"She is beautiful.","note":"","sourceLineIndex":24},{"id":"le-petit-prince-2cd-29-025","lineIndex":25,"speaker":"Le Serpent","original":"Mais que viens-tu faire ici?","ipa":"/mɛ kə vjɛ̃ty fɛʁ isi/","zh":"但是你来这儿干什么？","en":"But what are you doing here?","note":"","sourceLineIndex":25},{"id":"le-petit-prince-2cd-29-026","lineIndex":26,"speaker":"Le Petit Prince","original":"J'ai des difficultés avec une fleur...","ipa":"/ʒe de difikylte avɛk yn flœʁ/","zh":"我和一朵花之间遇到了些难处……","en":"I am having trouble with a flower...","note":"","sourceLineIndex":26},{"id":"le-petit-prince-2cd-29-027","lineIndex":27,"speaker":"Le Serpent","original":"Une fleur?","ipa":"/yn flœʁ/","zh":"一朵花？","en":"A flower?","note":"","sourceLineIndex":27},{"id":"le-petit-prince-2cd-29-028","lineIndex":28,"speaker":"Le Petit Prince","original":"Non, ça c'est une fleur à trois pétales","ipa":"/nɔ̃ sa sɛt yn flœʁ a tʁwa petal/","zh":"只是一朵三瓣花","en":"No, that's a flower with three petals","note":"","sourceLineIndex":28},{"id":"le-petit-prince-2cd-29-029","lineIndex":29,"speaker":"Le Petit Prince","original":"une fleur de rien du tout.","ipa":"/yn flœʁ də ʁjɛ̃ dy tu/","zh":"一朵毫不起眼的花。","en":"a flower of no consequence.","note":"","sourceLineIndex":29},{"id":"le-petit-prince-2cd-29-030","lineIndex":30,"speaker":"Le Petit Prince","original":"La mienne est éphémère.","ipa":"/la mjɛn ɛt efemɛʁ/","zh":"我的花生命是很短暂的","en":"Mine is fleeting.","note":"","sourceLineIndex":30},{"id":"le-petit-prince-2cd-29-031","lineIndex":31,"speaker":"Le Serpent","original":"Ah...","ipa":"/a/","zh":"哦......","en":"Ah...","note":"","sourceLineIndex":31}],"sourceOrder":29,"displayOrder":29},{"order":31,"id":"31-ou-sont-les-hommes-les-cactus","title":"Ou Sont Les Hommes? / Les Cactus","titleZh":"男人在哪里?/仙人掌","lines":[{"id":"le-petit-prince-2cd-31-001","lineIndex":1,"speaker":"Le Petit Prince","original":"Où sont les hommes?","ipa":"/u sɔ̃ lez ɔm/","zh":"人在哪儿呢？","en":"Where are the men?","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-31-002","lineIndex":2,"speaker":"Le Petit Prince","original":"On est un peu seul dans le désert.","ipa":"/ɔ̃n ɛt œ̃ pø sœl dɑ̃ lə dezɛʁ/","zh":"待在沙漠里有点孤独","en":"We are a bit alone in the desert.","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-31-003","lineIndex":3,"speaker":"Le Serpent","original":"On est seul aussi chez les hommes.","ipa":"/ɔ̃n ɛ sœl osi ʃe lez ɔm/","zh":"跟人在一起照样会孤独","en":"We are alone among men too.","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-31-004","lineIndex":4,"speaker":"Le Petit Prince","original":"Tu es une drôle de bête.","ipa":"/ty ɛz yn dʁoːl də bɛt/","zh":"你是个奇特的动物","en":"You are a strange creature.","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-31-005","lineIndex":5,"speaker":"Le Petit Prince","original":"Tu n'as même pas de pattes.","ipa":"/ty na mɛm pa də pat/","zh":"你连爪子都没有","en":"You don't even have legs.","note":"","sourceLineIndex":5},{"id":"le-petit-prince-2cd-31-006","lineIndex":6,"speaker":"Le Petit Prince","original":"Tu ne peux même pas voyager.","ipa":"/ty nə pø mɛm pa vwajaʒe/","zh":"你甚至无法旅行。","en":"You can't even travel.","note":"","sourceLineIndex":6},{"id":"le-petit-prince-2cd-31-007","lineIndex":7,"speaker":"Le Serpent","original":"Oh, je puis t'emporter plus loin qu'un navire.","ipa":"/ɔ ʒə pyi tɑ̃pɔʁte ply lwɛ̃ kœ̃ naviʁ/","zh":"哦，我能带你去比船更远的地方。","en":"Oh, I can take you farther than a ship can.","note":"","sourceLineIndex":7},{"id":"le-petit-prince-2cd-31-008","lineIndex":8,"speaker":"Le Serpent","original":"Celui que je touche, je le rends à la terre dont il est sorti.","ipa":"/səlyi kə ʒə tuʃ ʒə lə ʁɑ̃z a la tɛʁ dɔ̃t il ɛ sɔʁti/","zh":"我碰到谁，就能让他归于他所来自的土地。","en":"Whoever I touch, I return to the earth from which he came.","note":"","sourceLineIndex":8},{"id":"le-petit-prince-2cd-31-009","lineIndex":9,"speaker":"Le Serpent","original":"Mais tu es pur, tu viens d'une étoile","ipa":"/mɛ ty ɛ pyʁ ty vjɛ̃ dyn etwal/","zh":"但你是纯洁的 你来自一颗星","en":"But you are pure, you come from a star","note":"","sourceLineIndex":9},{"id":"le-petit-prince-2cd-31-010","lineIndex":10,"speaker":"Le Serpent","original":"mais tu me fais pitié, toi si faible, sur cette terre de granit.","ipa":"/mɛ ty mə fɛ pitje twa si fɛbl syʁ sɛt tɛʁ də ɡʁanit/","zh":"可我很同情你；在这花岗岩构成的地球上，你是那么弱小。","en":"but I pity you, so weak on this granite earth.","note":"","sourceLineIndex":10},{"id":"le-petit-prince-2cd-31-011","lineIndex":11,"speaker":"Le Serpent","original":"Je puis t'aider un jour, si tu regrettes trop ta planète.","ipa":"/ʒə pyi tɛde œ̃ ʒuʁ si ty ʁəɡʁɛt tʁo ta planɛt/","zh":"如果你有朝一日思念你的星球了 我可以帮助你","en":"I can help you one day, if you miss your planet too much.","note":"","sourceLineIndex":11},{"id":"le-petit-prince-2cd-31-012","lineIndex":12,"speaker":"Le Serpent","original":"Je puis...","ipa":"/ʒə pyi/","zh":"我可以......","en":"I can...","note":"","sourceLineIndex":12},{"id":"le-petit-prince-2cd-31-013","lineIndex":13,"speaker":"Le Petit Prince","original":"Oh, j'ai très bien compris.","ipa":"/ɔ ʒe tʁɛ bjɛ̃ kɔ̃pʁi/","zh":"哦，我完全明白了。","en":"Oh, I understand perfectly.","note":"","sourceLineIndex":13},{"id":"le-petit-prince-2cd-31-014","lineIndex":14,"speaker":"Le Petit Prince","original":"Mais pourquoi parles-tu toujours par énigmes?","ipa":"/mɛ puʁkwa paʁlty tuʒuʁ paʁ eniɡm/","zh":"但你的话为什么句句都像谜似的？","en":"But why do you always speak in riddles?","note":"","sourceLineIndex":14},{"id":"le-petit-prince-2cd-31-015","lineIndex":15,"speaker":"Le Serpent","original":"Je les résous toutes.","ipa":"/ʒə le ʁezu tut/","zh":"我能解一切谜","en":"I solve them all.","note":"","sourceLineIndex":15},{"id":"le-petit-prince-2cd-31-016","lineIndex":16,"speaker":"Le Petit Prince","original":"Bonjour.","ipa":"/bɔ̃ʒuʁ/","zh":"你好","en":"Hello.","note":"","sourceLineIndex":16},{"id":"le-petit-prince-2cd-31-017","lineIndex":17,"speaker":"Les Cactus","original":"Bonjour.","ipa":"/bɔ̃ʒuʁ/","zh":"你好","en":"Hello.","note":"","sourceLineIndex":17},{"id":"le-petit-prince-2cd-31-018","lineIndex":18,"speaker":"Le Petit Prince","original":"Où sont les hommes?","ipa":"/u sɔ̃ lez ɔm/","zh":"人在哪儿呢？","en":"Where are the men?","note":"","sourceLineIndex":18},{"id":"le-petit-prince-2cd-31-019","lineIndex":19,"speaker":"Les Cactus","original":"Oh, les hommes!","ipa":"/ɔ lez ɔm/","zh":"哦，人类！","en":"Oh, men!","note":"","sourceLineIndex":19},{"id":"le-petit-prince-2cd-31-020","lineIndex":20,"speaker":"Les Cactus","original":"Il en existe je crois six ou sept.","ipa":"/il ɑ̃n ɛɡzist ʒə kʁwa sis u sɛt/","zh":"我想，大概有六七个人吧。","en":"I believe there are six or seven of them.","note":"","sourceLineIndex":20},{"id":"le-petit-prince-2cd-31-021","lineIndex":21,"speaker":"Les Cactus","original":"Je les ai aperçus il y a des années.","ipa":"/ʒə lez e apɛʁsy il i a dez ane/","zh":"好几年前我见过他们","en":"I saw them years ago.","note":"","sourceLineIndex":21},{"id":"le-petit-prince-2cd-31-022","lineIndex":22,"speaker":"Les Cactus","original":"Mais on ne sait jamais où les trouver.","ipa":"/mɛz ɔ̃ nə sɛ ʒamɛz u le tʁuve/","zh":"但永远不知道到哪儿能找到他们。","en":"But one never knows where to find them.","note":"","sourceLineIndex":22},{"id":"le-petit-prince-2cd-31-023","lineIndex":23,"speaker":"Les Cactus","original":"Le vent les promène, ils manquent de racines.","ipa":"/lə vɑ̃ le pʁomɛn il mɑ̃k də ʁasin/","zh":"风把他们吹来吹去；他们没有根。","en":"The wind blows them about; they have no roots.","note":"","sourceLineIndex":23},{"id":"le-petit-prince-2cd-31-024","lineIndex":24,"speaker":"Les Cactus","original":"Ça les gêne beaucoup.","ipa":"/sa le ʒɛn boku/","zh":"这让他们很不方便。","en":"This inconveniences them a great deal.","note":"","sourceLineIndex":24},{"id":"le-petit-prince-2cd-31-025","lineIndex":25,"speaker":"Le Petit Prince","original":"Adieu.","ipa":"/adjø/","zh":"别了","en":"Goodbye.","note":"","sourceLineIndex":25},{"id":"le-petit-prince-2cd-31-026","lineIndex":26,"speaker":"Les Cactus","original":"Adieu.","ipa":"/adjø/","zh":"别了","en":"Goodbye.","note":"","sourceLineIndex":26}],"sourceOrder":31,"displayOrder":30},{"order":32,"id":"32-la-montagne","title":"La Montagne","titleZh":"高山","lines":[{"id":"le-petit-prince-2cd-32-001","lineIndex":1,"speaker":"Le Petit Prince","original":"Je vais faire l'ascension de cette haute montagne.","ipa":"/ʒə vɛ fɛʁ lasɑ̃sjɔ̃ də sɛt ot mɔ̃taɲ/","zh":"我要登上这座高山","en":"I'm going to climb this high mountain.","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-32-002","lineIndex":2,"speaker":"Le Petit Prince","original":"Tu sais... aïe!","ipa":"/ty sɛ aj/","zh":"你知道......哎唷！","en":"You know... ouch!","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-32-003","lineIndex":3,"speaker":"Les Cactus","original":"Oh pardon!","ipa":"/ɔ paʁdɔ̃/","zh":"啊 抱歉！","en":"Oh sorry!","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-32-004","lineIndex":4,"speaker":"Le Petit Prince","original":"Je n'ai jamais eu de montagne comme ça.","ipa":"/ʒə ne ʒamɛz y də mɔ̃taɲ kɔm sa/","zh":"我从来没有过这样的山。","en":"I've never had a mountain like this.","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-32-005","lineIndex":5,"speaker":"Le Petit Prince","original":"J'ai trois volcans qui m'arrivent à peine aux genoux.","ipa":"/ʒe tʁwa vɔlkɑ̃ ki maʁivt a pɛn o ʒənu/","zh":"我只有三座火山 才到我的膝盖","en":"I have three volcanoes that barely reach my knees.","note":"","sourceLineIndex":5},{"id":"le-petit-prince-2cd-32-006","lineIndex":6,"speaker":"Les Cactus","original":"Aux genoux?","ipa":"/o ʒənu/","zh":"才到膝盖？","en":"Knees?","note":"","sourceLineIndex":6},{"id":"le-petit-prince-2cd-32-007","lineIndex":7,"speaker":"Le Petit Prince","original":"Au sommet, j'apercevrai d'un coup toute la planète et tous les hommes.","ipa":"/o sɔmɛ ʒapɛʁsəvʁe dœ̃ ku tut la planɛt e tu lez ɔm/","zh":"在山顶 我就能一眼看见整个星球和所有的人了","en":"At the top, I will see the whole planet and all the people at once.","note":"","sourceLineIndex":7},{"id":"le-petit-prince-2cd-32-008","lineIndex":8,"speaker":"Les Cactus","original":"Oui...","ipa":"/wi/","zh":"是......","en":"Yes...","note":"","sourceLineIndex":8},{"id":"le-petit-prince-2cd-32-009","lineIndex":9,"speaker":"Le Petit Prince","original":"Bonjour.","ipa":"/bɔ̃ʒuʁ/","zh":"您好","en":"Hello.","note":"","sourceLineIndex":9},{"id":"le-petit-prince-2cd-32-010","lineIndex":10,"speaker":"L'Écho","original":"Bonjour... Bonjour... Bonjour...","ipa":"/bɔ̃ʒuʁ bɔ̃ʒuʁ bɔ̃ʒuʁ/","zh":"您好......您好......您好......","en":"Hello... Hello... Hello...","note":"","sourceLineIndex":10},{"id":"le-petit-prince-2cd-32-011","lineIndex":11,"speaker":"Le Petit Prince","original":"Qui êtes-vous?","ipa":"/ki ɛtvu/","zh":"您是谁？","en":"Who are you?","note":"","sourceLineIndex":11},{"id":"le-petit-prince-2cd-32-012","lineIndex":12,"speaker":"L'Écho","original":"Qui êtes-vous... Qui êtes-vous...","ipa":"/ki ɛtvu ki ɛtvu/","zh":"您是谁......您是谁......","en":"Who are you... Who are you...","note":"","sourceLineIndex":12},{"id":"le-petit-prince-2cd-32-013","lineIndex":13,"speaker":"Le Petit Prince","original":"Soyez mes amis.","ipa":"/swaje mez ami/","zh":"做我的朋友吧","en":"Be my friends.","note":"","sourceLineIndex":13},{"id":"le-petit-prince-2cd-32-014","lineIndex":14,"speaker":"L'Écho","original":"Mes amis...","ipa":"/mez ami/","zh":"我的朋友......","en":"My friends...","note":"","sourceLineIndex":14},{"id":"le-petit-prince-2cd-32-015","lineIndex":15,"speaker":"Le Petit Prince","original":"Je suis seul.","ipa":"/ʒə syi sœl/","zh":"我很孤单","en":"I am alone.","note":"","sourceLineIndex":15},{"id":"le-petit-prince-2cd-32-016","lineIndex":16,"speaker":"L'Écho","original":"Je suis seul....","ipa":"/ʒə syi sœl/","zh":"我很孤单......","en":"I am alone....","note":"","sourceLineIndex":16},{"id":"le-petit-prince-2cd-32-017","lineIndex":17,"speaker":"Le Petit Prince","original":"Bonjour.","ipa":"/bɔ̃ʒuʁ/","zh":"您好","en":"Hello.","note":"","sourceLineIndex":17},{"id":"le-petit-prince-2cd-32-018","lineIndex":18,"speaker":"L'Écho","original":"Bonjour... Bonjour... Bonjour...","ipa":"/bɔ̃ʒuʁ bɔ̃ʒuʁ bɔ̃ʒuʁ/","zh":"您好......您好......您好......","en":"Hello... Hello... Hello...","note":"","sourceLineIndex":18},{"id":"le-petit-prince-2cd-32-019","lineIndex":19,"speaker":"Le Petit Prince","original":"Qui êtes-vous?","ipa":"/ki ɛtvu/","zh":"您是谁？","en":"Who are you?","note":"","sourceLineIndex":19},{"id":"le-petit-prince-2cd-32-020","lineIndex":20,"speaker":"L'Écho","original":"Qui êtes-vous... Qui êtes-vous...","ipa":"/ki ɛtvu ki ɛtvu/","zh":"您是谁......您是谁......","en":"Who are you... Who are you...","note":"","sourceLineIndex":20},{"id":"le-petit-prince-2cd-32-021","lineIndex":21,"speaker":"Le Petit Prince","original":"Soyez mes amis.","ipa":"/swaje mez ami/","zh":"做我的朋友吧","en":"Be my friends.","note":"","sourceLineIndex":21},{"id":"le-petit-prince-2cd-32-022","lineIndex":22,"speaker":"L'Écho","original":"Mes amis...","ipa":"/mez ami/","zh":"我的朋友......","en":"My friends...","note":"","sourceLineIndex":22},{"id":"le-petit-prince-2cd-32-023","lineIndex":23,"speaker":"Le Petit Prince","original":"Je suis seul.","ipa":"/ʒə syi sœl/","zh":"我很孤单","en":"I am alone.","note":"","sourceLineIndex":23},{"id":"le-petit-prince-2cd-32-024","lineIndex":24,"speaker":"L'Écho","original":"Je suis seul....","ipa":"/ʒə syi sœl/","zh":"我很孤单......","en":"I am alone....","note":"","sourceLineIndex":24},{"id":"le-petit-prince-2cd-32-025","lineIndex":25,"speaker":"Le Petit Prince","original":"Cette Terre est","ipa":"/sɛt tɛʁ ɛ/","zh":"这地球","en":"This Earth is","note":"","sourceLineIndex":25},{"id":"le-petit-prince-2cd-32-026","lineIndex":26,"speaker":"Le Petit Prince","original":"Une drôle de planète","ipa":"/yn dʁoːl də planɛt/","zh":"是个古怪的行星","en":"A strange planet","note":"","sourceLineIndex":26},{"id":"le-petit-prince-2cd-32-027","lineIndex":27,"speaker":"Le Petit Prince","original":"Elle est toute sèche","ipa":"/ɛl ɛ tut sɛʃ/","zh":"干干巴巴","en":"It is all dry","note":"","sourceLineIndex":27},{"id":"le-petit-prince-2cd-32-028","lineIndex":28,"speaker":"Le Petit Prince","original":"Toute pointue Toute salée","ipa":"/tut pwɛ̃ty tut sale/","zh":"处处尖峭，遍地咸涩","en":"All pointed, all salty","note":"","sourceLineIndex":28},{"id":"le-petit-prince-2cd-32-029","lineIndex":29,"speaker":"Le Petit Prince","original":"Et les hommes manquent d'imagination","ipa":"/e lez ɔm mɑ̃k dimaʒinasjɔ̃/","zh":"而人类缺乏想象力","en":"And men lack imagination","note":"","sourceLineIndex":29},{"id":"le-petit-prince-2cd-32-030","lineIndex":30,"speaker":"Le Petit Prince","original":"Ils répètent tout. Tout ce qu'on leur dit...","ipa":"/il ʁepɛt tu tu sə kɔ̃ lœʁ di/","zh":"他们重复一切，重复别人对他们说的一切……","en":"They repeat everything—everything one says to them...","note":"","sourceLineIndex":30},{"id":"le-petit-prince-2cd-32-031","lineIndex":31,"speaker":"Le Petit Prince","original":"Bonjour.","ipa":"/bɔ̃ʒuʁ/","zh":"您好","en":"Hello.","note":"","sourceLineIndex":31},{"id":"le-petit-prince-2cd-32-032","lineIndex":32,"speaker":"L'Écho","original":"Bonjour... Bonjour... Bonjour...","ipa":"/bɔ̃ʒuʁ bɔ̃ʒuʁ bɔ̃ʒuʁ/","zh":"您好......您好......您好......","en":"Hello... Hello... Hello...","note":"","sourceLineIndex":32},{"id":"le-petit-prince-2cd-32-033","lineIndex":33,"speaker":"Le Petit Prince","original":"Qui êtes-vous?","ipa":"/ki ɛtvu/","zh":"您是谁？","en":"Who are you?","note":"","sourceLineIndex":33},{"id":"le-petit-prince-2cd-32-034","lineIndex":34,"speaker":"L'Écho","original":"Qui êtes-vous... Qui êtes-vous...","ipa":"/ki ɛtvu ki ɛtvu/","zh":"您是谁......您是谁......","en":"Who are you... Who are you...","note":"","sourceLineIndex":34},{"id":"le-petit-prince-2cd-32-035","lineIndex":35,"speaker":"Le Petit Prince","original":"Soyez mes amis.","ipa":"/swaje mez ami/","zh":"做我的朋友吧","en":"Be my friends.","note":"","sourceLineIndex":35},{"id":"le-petit-prince-2cd-32-036","lineIndex":36,"speaker":"L'Écho","original":"Mes amis...","ipa":"/mez ami/","zh":"我的朋友......","en":"My friends...","note":"","sourceLineIndex":36},{"id":"le-petit-prince-2cd-32-037","lineIndex":37,"speaker":"Le Petit Prince","original":"Je suis seul.","ipa":"/ʒə syi sœl/","zh":"我很孤单","en":"I am alone.","note":"","sourceLineIndex":37},{"id":"le-petit-prince-2cd-32-038","lineIndex":38,"speaker":"L'Écho","original":"Je suis seul....","ipa":"/ʒə syi sœl/","zh":"我很孤单......","en":"I am alone....","note":"","sourceLineIndex":38},{"id":"le-petit-prince-2cd-32-039","lineIndex":39,"speaker":"Le Petit Prince","original":"Seul...","ipa":"/sœl/","zh":"孤单......","en":"Alone...","note":"","sourceLineIndex":39},{"id":"le-petit-prince-2cd-32-040","lineIndex":40,"speaker":"L'Écho","original":"Seul... Seul... Seul...","ipa":"/sœl sœl sœl/","zh":"孤单......孤单......孤单......","en":"Alone... Alone... Alone...","note":"","sourceLineIndex":40},{"id":"le-petit-prince-2cd-32-041","lineIndex":41,"speaker":"Le Petit Prince","original":"Chez moi j'avais une fleur","ipa":"/ʃe mwa ʒavɛz yn flœʁ/","zh":"在我的星球上，我有一朵花","en":"Back home, I had a flower","note":"","sourceLineIndex":41},{"id":"le-petit-prince-2cd-32-042","lineIndex":42,"speaker":"Le Petit Prince","original":"Elle parlait toujours la première","ipa":"/ɛl paʁlɛ tuʒuʁ la pʁəmjɛʁ/","zh":"她总是抢先讲话","en":"She always spoke first","note":"","sourceLineIndex":42}],"sourceOrder":32,"displayOrder":31},{"order":33,"id":"33-le-jardin-des-roses","title":"Le Jardin Des Roses","titleZh":"玫瑰花园","lines":[{"id":"le-petit-prince-2cd-33-001","lineIndex":1,"speaker":"Les Roses","original":"Ah! Je me réveille à peine","ipa":"/a ʒə mə ʁevɛj a pɛn/","zh":"啊，我才刚刚醒来","en":"Ah! I have only just woken up","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-33-002","lineIndex":2,"speaker":"Les Roses","original":"Ah! Je vous demande pardon","ipa":"/a ʒə vu dəmɑ̃d paʁdɔ̃/","zh":"啊 请您原谅","en":"Ah! I beg your pardon","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-33-003","lineIndex":3,"speaker":"Les Roses","original":"Ah! Je suis toute décoiffée","ipa":"/a ʒə syi tut dekwafe/","zh":"啊，我的头发全乱了","en":"Ah! My hair is all tousled","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-33-004","lineIndex":4,"speaker":"Les Roses","original":"Mais je suis née en même temps que le soleil","ipa":"/mɛ ʒə syi ne ɑ̃ mɛm tɑ̃ kə lə solɛj/","zh":"不过我和太阳同时诞生","en":"But I was born at the same time as the sun","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-33-005","lineIndex":5,"speaker":"Les Roses","original":"Ah! Sans trop vous déranger","ipa":"/a sɑ̃ tʁo vu deʁɑ̃ʒe/","zh":"啊 希望不会太打扰您","en":"Ah! Without disturbing you too much","note":"","sourceLineIndex":5},{"id":"le-petit-prince-2cd-33-006","lineIndex":6,"speaker":"Les Roses","original":"Ah! Pourriez-vous m'apporter","ipa":"/a puʁjevu mapɔʁte/","zh":"啊 可否请您给我","en":"Ah! Could you bring me","note":"","sourceLineIndex":6},{"id":"le-petit-prince-2cd-33-007","lineIndex":7,"speaker":"Les Roses","original":"Juste un petit déjeuner","ipa":"/ʒyst œ̃ pəti deʒøne/","zh":"带点早餐来？","en":"Just breakfast","note":"","sourceLineIndex":7},{"id":"le-petit-prince-2cd-33-008","lineIndex":8,"speaker":"Les Roses","original":"Je prendrais bien quelques gouttes de rosée","ipa":"/ʒə pʁɑ̃dʁɛ bjɛ̃ kɛlkə ɡut də ʁoze/","zh":"我只要几滴露水就好","en":"I would like a few drops of dew","note":"","sourceLineIndex":8},{"id":"le-petit-prince-2cd-33-009","lineIndex":9,"speaker":"Le Petit Prince","original":"Ma fleur me disait","ipa":"/ma flœʁ mə dizɛ/","zh":"我的花儿曾告诉我","en":"My flower told me","note":"","sourceLineIndex":9},{"id":"le-petit-prince-2cd-33-010","lineIndex":10,"speaker":"Le Petit Prince","original":"Que dans tout l'univers","ipa":"/kə dɑ̃ tu lynivɛʁ/","zh":"大千世界中","en":"That in the whole universe","note":"","sourceLineIndex":10},{"id":"le-petit-prince-2cd-33-011","lineIndex":11,"speaker":"Le Petit Prince","original":"Elle était seule en son genre","ipa":"/ɛl etɛ sœl ɑ̃ sɔ̃ ʒɑ̃ʁ/","zh":"她是唯一的玫瑰花","en":"She was the only one of her kind","note":"","sourceLineIndex":11},{"id":"le-petit-prince-2cd-33-012","lineIndex":12,"speaker":"Le Petit Prince","original":"Mais ce n'était pas vrai","ipa":"/mɛ sə netɛ pa vʁɛ/","zh":"可这并不是真的","en":"But this was not true","note":"","sourceLineIndex":12},{"id":"le-petit-prince-2cd-33-013","lineIndex":13,"speaker":"Le Petit Prince","original":"Comme elle il y en a des milliers","ipa":"/kɔm ɛl il i ɑ̃n a de milje/","zh":"像她这样的有成千上万朵","en":"There are thousands like her","note":"","sourceLineIndex":13},{"id":"le-petit-prince-2cd-33-014","lineIndex":14,"speaker":"Le Petit Prince","original":"Ah! Si ma fleur vous voyait","ipa":"/a si ma flœʁ vu vwajɛ/","zh":"啊，若是我的花儿看见了你们","en":"Ah! If my flower saw all of you","note":"","sourceLineIndex":14},{"id":"le-petit-prince-2cd-33-015","lineIndex":15,"speaker":"Le Petit Prince","original":"Elle se sentirait humiliée","ipa":"/ɛl sə sɑ̃tiʁɛt ymilje/","zh":"她定会觉得羞愧","en":"She would feel humiliated","note":"","sourceLineIndex":15},{"id":"le-petit-prince-2cd-33-016","lineIndex":16,"speaker":"Le Petit Prince","original":"Et pour être moins ridicule","ipa":"/e puʁ ɛtʁ mwɛ̃ ʁidikyl/","zh":"为了不显得那么可笑","en":"And to seem less ridiculous","note":"","sourceLineIndex":16},{"id":"le-petit-prince-2cd-33-017","lineIndex":17,"speaker":"Le Petit Prince","original":"Elle tousserait et ferait semblant de mourir","ipa":"/ɛl tusʁɛt e fəʁɛ sɑ̃blɑ̃ də muʁiʁ/","zh":"她又要装模作样地咳嗽 做出一副要死要活的样子","en":"She would cough and pretend to die","note":"","sourceLineIndex":17},{"id":"le-petit-prince-2cd-33-018","lineIndex":18,"speaker":"Le Petit Prince","original":"Moi je serais bien obligé","ipa":"/mwa ʒə səʁɛ bjɛ̃n ɔbliʒe/","zh":"我就不得不","en":"I would be obliged","note":"","sourceLineIndex":18},{"id":"le-petit-prince-2cd-33-019","lineIndex":19,"speaker":"Le Petit Prince","original":"De faire semblant de la soigner","ipa":"/də fɛʁ sɑ̃blɑ̃ də la swanje/","zh":"假装照料她","en":"to pretend to nurse her","note":"","sourceLineIndex":19},{"id":"le-petit-prince-2cd-33-020","lineIndex":20,"speaker":"Le Petit Prince","original":"Sinon pour m'humilier aussi","ipa":"/sinɔ̃ puʁ mymilje osi/","zh":"否则，为了也羞辱我","en":"otherwise, to humiliate me too","note":"","sourceLineIndex":20},{"id":"le-petit-prince-2cd-33-021","lineIndex":21,"speaker":"Le Petit Prince","original":"Elle pourrait bien se laisser vraiment mourir","ipa":"/ɛl puʁɛ bjɛ̃ sə lɛse vʁɛmɑ̃ muʁiʁ/","zh":"她很可能真的会任由自己死去","en":"she might really let herself die","note":"","sourceLineIndex":21},{"id":"le-petit-prince-2cd-33-022","lineIndex":22,"speaker":"Le Petit Prince","original":"Moi qui me croyais","ipa":"/mwa ki mə kʁwajɛ/","zh":"我原以为自己","en":"I, who thought myself","note":"","sourceLineIndex":22},{"id":"le-petit-prince-2cd-33-023","lineIndex":23,"speaker":"Le Petit Prince","original":"Si riche d'une fleur unique","ipa":"/si ʁiʃ dyn flœʁ ynik/","zh":"因拥有一朵独一无二的花而如此富有","en":"so rich in possessing a unique flower","note":"","sourceLineIndex":23},{"id":"le-petit-prince-2cd-33-024","lineIndex":24,"speaker":"Le Petit Prince","original":"Je n'ai qu'une rose ordinaire","ipa":"/ʒə ne kyn ʁɔz ɔʁdinɛʁ/","zh":"原来她只是一朵极平常的花","en":"I only have an ordinary rose","note":"","sourceLineIndex":24},{"id":"le-petit-prince-2cd-33-025","lineIndex":25,"speaker":"Le Petit Prince","original":"Entre elle et mes volcans","ipa":"/ɑ̃tʁ ɛl e me vɔlkɑ̃/","zh":"她和我的火山加在一起","en":"With her and my volcanoes","note":"","sourceLineIndex":25},{"id":"le-petit-prince-2cd-33-026","lineIndex":26,"speaker":"Le Petit Prince","original":"Je n'ai vraiment pas l'air d'un grand prince","ipa":"/ʒə ne vʁɛmɑ̃ pa lɛʁ dœ̃ ɡʁɑ̃ pʁɛ̃s/","zh":"不能使我成为一位伟大的王子","en":"I really don't look like a great prince","note":"","sourceLineIndex":26},{"id":"le-petit-prince-2cd-33-027","lineIndex":27,"speaker":"Les Roses","original":"Ah! Avec mes quatre épines","ipa":"/a avɛk me katʁ epin/","zh":"啊 我有四根刺","en":"Ah! With my four thorns","note":"","sourceLineIndex":27},{"id":"le-petit-prince-2cd-33-028","lineIndex":28,"speaker":"Les Roses","original":"Ah! Je ne me laisse pas prendre","ipa":"/a ʒə nə mə lɛs pa pʁɑ̃dʁ/","zh":"啊 我不会任由自己被采摘","en":"Ah! I don't let myself be caught","note":"","sourceLineIndex":28},{"id":"le-petit-prince-2cd-33-029","lineIndex":29,"speaker":"Les Roses","original":"Moi je n'ai pas peur des tigres","ipa":"/mwa ʒə ne pa pœʁ de tiɡʁ/","zh":"我可不怕老虎","en":"I'm not afraid of tigers","note":"","sourceLineIndex":29},{"id":"le-petit-prince-2cd-33-030","lineIndex":30,"speaker":"Les Roses","original":"Ils peuvent toujours venir je sais me défendre","ipa":"/il pøv tuʒuʁ vəniʁ ʒə sɛ mə defɑ̃dʁ/","zh":"它们尽管来吧，我知道如何自卫","en":"Let them come; I know how to defend myself","note":"","sourceLineIndex":30},{"id":"le-petit-prince-2cd-33-031","lineIndex":31,"speaker":"Les Roses","original":"Ah! J'ai toujours un peu froid","ipa":"/a ʒe tuʒuʁz œ̃ pø fʁwa/","zh":"啊 我总有点怕冷","en":"Ah! I'm always a little cold","note":"","sourceLineIndex":31},{"id":"le-petit-prince-2cd-33-032","lineIndex":32,"speaker":"Les Roses","original":"Ah! Je hais les courants d'air","ipa":"/a ʒə ɛ le kuʁɑ̃ dɛʁ/","zh":"啊 我讨厌风","en":"Ah! I hate drafts","note":"","sourceLineIndex":32},{"id":"le-petit-prince-2cd-33-033","lineIndex":33,"speaker":"Les Roses","original":"J'aime tant qu'on prenne soin de moi","ipa":"/ʒɛm tɑ̃ kɔ̃ pʁɛn swɛ̃ də mwa/","zh":"我多么喜欢有人照料我","en":"I so love being taken care of","note":"","sourceLineIndex":33},{"id":"le-petit-prince-2cd-33-034","lineIndex":34,"speaker":"Les Roses","original":"Vous n'auriez pas par hasard un paravent?","ipa":"/vu noʁje pa paʁ azaʁ œ̃ paʁav/","zh":"您是否碰巧有一扇屏风呢？","en":"You wouldn't happen to have a screen, would you?","note":"","sourceLineIndex":34}],"sourceOrder":33,"displayOrder":32},{"order":34,"id":"34-le-renard","title":"Le Renard","titleZh":"狐狸","lines":[{"id":"le-petit-prince-2cd-34-001","lineIndex":1,"speaker":"Le Petit Prince","original":"Je me croyais riche d'une fleur unique, et je n'ai qu'une rose ordinaire comme les autres.","ipa":"/ʒə mə kʁwajɛ ʁiʃ dyn flœʁ ynik e ʒə ne kyn ʁɔz ɔʁdinɛʁ kɔm lez otʁ/","zh":"我原以为自己拥有一朵独一无二的花而很富有，可我只有一朵和别的花一样普通的玫瑰。","en":"I thought I was rich with a unique flower, and I have only an ordinary rose like all the others.","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-34-002","lineIndex":2,"speaker":"Le Petit Prince","original":"Ça, et mes trois volcans qui m'arrivent à peine aux genoux","ipa":"/sa e me tʁwa vɔlkɑ̃ ki maʁivt a pɛn o ʒənu/","zh":"她 以及我那三座只有我膝盖高的火山","en":"That, and my three volcanoes which barely reach my knees","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-34-003","lineIndex":3,"speaker":"Le Petit Prince","original":"et dont l'un peut-être est éteint pour toujours","ipa":"/e dɔ̃ lœ̃ pøtɛtʁ ɛt etɛ̃ puʁ tuʒuʁ/","zh":"其中一座也许已经永远熄灭了","en":"one of which may be extinct forever","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-34-004","lineIndex":4,"speaker":"Le Petit Prince","original":"ça ne fait pas de moi un grand prince...","ipa":"/sa nə fɛ pa də mwa œ̃ ɡʁɑ̃ pʁɛ̃s/","zh":"它们不能使我成为一位伟大的王子......","en":"that does not make me a great prince...","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-34-005","lineIndex":5,"speaker":"Le Renard","original":"Bonjour!","ipa":"/bɔ̃ʒuʁ/","zh":"你好！","en":"Hello!","note":"","sourceLineIndex":5},{"id":"le-petit-prince-2cd-34-006","lineIndex":6,"speaker":"Le Petit Prince","original":"Bonjour! Qui es-tu?","ipa":"/bɔ̃ʒuʁ ki ɛty/","zh":"你好！你是谁？","en":"Hello! Who are you?","note":"","sourceLineIndex":6},{"id":"le-petit-prince-2cd-34-007","lineIndex":7,"speaker":"Le Petit Prince","original":"Tu es bien joli.","ipa":"/ty ɛ bjɛ̃ ʒoli/","zh":"你真漂亮","en":"You are very pretty.","note":"","sourceLineIndex":7},{"id":"le-petit-prince-2cd-34-008","lineIndex":8,"speaker":"Le Renard","original":"Je suis un renard.","ipa":"/ʒə syiz œ̃ ʁənaʁ/","zh":"我是狐狸","en":"I am a fox.","note":"","sourceLineIndex":8},{"id":"le-petit-prince-2cd-34-009","lineIndex":9,"speaker":"Le Petit Prince","original":"Viens jouer avec moi, je suis tellement triste.","ipa":"/vjɛ̃ ʒwe avɛk mwa ʒə syi tɛlmɑ̃ tʁist/","zh":"来跟我一起玩吧 我非常伤心","en":"Come play with me, I'm so sad.","note":"","sourceLineIndex":9},{"id":"le-petit-prince-2cd-34-010","lineIndex":10,"speaker":"Le Renard","original":"Je ne puis pas jouer avec toi","ipa":"/ʒə nə pyi pa ʒwe avɛk twa/","zh":"我不能跟你一起玩","en":"I can't play with you","note":"","sourceLineIndex":10},{"id":"le-petit-prince-2cd-34-011","lineIndex":11,"speaker":"Le Renard","original":"je ne suis pas apprivoisé.","ipa":"/ʒə nə syi paz apʁivwaze/","zh":"我还没有被驯服。","en":"I have not been tamed.","note":"","sourceLineIndex":11},{"id":"le-petit-prince-2cd-34-012","lineIndex":12,"speaker":"Le Petit Prince","original":"Pardon. Qu'est-ce que ça signifie, \"apprivoiser\"?","ipa":"/paʁdɔ̃ kɛskə sa siɲifi apʁivwaze/","zh":"对不起 什么叫做“驯养”？","en":"Sorry. What does “tame” mean?","note":"","sourceLineIndex":12},{"id":"le-petit-prince-2cd-34-013","lineIndex":13,"speaker":"Le Renard","original":"Tu n'es pas d'ici.","ipa":"/ty nɛ pa disi/","zh":"你不是本地人","en":"You're not from here.","note":"","sourceLineIndex":13},{"id":"le-petit-prince-2cd-34-014","lineIndex":14,"speaker":"Le Renard","original":"Que cherches-tu?","ipa":"/kə ʃɛʁʃty/","zh":"你在找什么？","en":"What are you looking for?","note":"","sourceLineIndex":14},{"id":"le-petit-prince-2cd-34-015","lineIndex":15,"speaker":"Le Petit Prince","original":"Je cherche les hommes.","ipa":"/ʒə ʃɛʁʃ lez ɔm/","zh":"我找人","en":"I'm looking for men.","note":"","sourceLineIndex":15},{"id":"le-petit-prince-2cd-34-016","lineIndex":16,"speaker":"Le Petit Prince","original":"Qu'est-ce que ça signifie, \"apprivoiser\"?","ipa":"/kɛskə sa siɲifi apʁivwaze/","zh":"什么叫做“驯养”？","en":"What does “tame” mean?","note":"","sourceLineIndex":16},{"id":"le-petit-prince-2cd-34-017","lineIndex":17,"speaker":"Le Renard","original":"Les hommes... Ils ont des fusils et ils chassent.","ipa":"/lez ɔm ilz ɔ̃ de fyziz e il ʃas/","zh":"人......他们有枪 还打猎","en":"Men... They have guns and they hunt.","note":"","sourceLineIndex":17},{"id":"le-petit-prince-2cd-34-018","lineIndex":18,"speaker":"Le Renard","original":"C'est bien gênant.","ipa":"/sɛ bjɛ̃ ʒɛnɑ̃/","zh":"这很麻烦。","en":"That is quite troublesome.","note":"","sourceLineIndex":18},{"id":"le-petit-prince-2cd-34-019","lineIndex":19,"speaker":"Le Renard","original":"Ils élèvent aussi des poules.","ipa":"/ilz elɛvt osi de pul/","zh":"可是人也养鸡","en":"They also raise chickens.","note":"","sourceLineIndex":19},{"id":"le-petit-prince-2cd-34-020","lineIndex":20,"speaker":"Le Renard","original":"C'est leur seul intérêt.","ipa":"/sɛ lœʁ sœl ɛ̃teʁɛ/","zh":"这是他们唯一的好处。","en":"That is their only redeeming feature.","note":"","sourceLineIndex":20},{"id":"le-petit-prince-2cd-34-021","lineIndex":21,"speaker":"Le Renard","original":"Tu cherches des poules?","ipa":"/ty ʃɛʁʃ de pul/","zh":"你也找鸡吗？","en":"Are you looking for chickens?","note":"","sourceLineIndex":21},{"id":"le-petit-prince-2cd-34-022","lineIndex":22,"speaker":"Le Petit Prince","original":"Non, je cherche des amis.","ipa":"/nɔ̃ ʒə ʃɛʁʃ dez ami/","zh":"不 我找朋友","en":"No, I'm looking for friends.","note":"","sourceLineIndex":22},{"id":"le-petit-prince-2cd-34-023","lineIndex":23,"speaker":"Le Petit Prince","original":"Qu'est-ce que ça signifie, \"apprivoiser\"?","ipa":"/kɛskə sa siɲifi apʁivwaze/","zh":"什么叫做“驯养”？","en":"What does “tame” mean?","note":"","sourceLineIndex":23},{"id":"le-petit-prince-2cd-34-024","lineIndex":24,"speaker":"Le Renard","original":"C'est une chose trop oubliée.","ipa":"/sɛt yn ʃɔz tʁop ublie/","zh":"这是一件被人遗忘干净的事了","en":"This is something too often forgotten.","note":"","sourceLineIndex":24},{"id":"le-petit-prince-2cd-34-025","lineIndex":25,"speaker":"Le Renard","original":"Cela signifie créer des liens.","ipa":"/səla siɲifi kʁee de ljɛ̃/","zh":"它的意思是“建立纽带”。","en":"It means establishing bonds.","note":"","sourceLineIndex":25},{"id":"le-petit-prince-2cd-34-026","lineIndex":26,"speaker":"Le Petit Prince","original":"Créer des liens?","ipa":"/kʁee de ljɛ̃/","zh":"建立纽带？","en":"Establishing bonds?","note":"","sourceLineIndex":26},{"id":"le-petit-prince-2cd-34-027","lineIndex":27,"speaker":"Le Renard","original":"Bien sûr.","ipa":"/bjɛ̃ syːʁ/","zh":"当然","en":"Of course.","note":"","sourceLineIndex":27},{"id":"le-petit-prince-2cd-34-028","lineIndex":28,"speaker":"Le Renard","original":"Tu n'es encore pour moi qu'un petit garçon tout semblable à cent mille petits garçons","ipa":"/ty nɛz ɑ̃kɔʁ puʁ mwa kœ̃ pəti ɡaʁsɔ̃ tu sɑ̃blabl a sɑ̃ mil pəti ɡaʁsɔ̃/","zh":"对我而言，你不过是个与十万个小男孩毫无区别的小男孩","en":"To me, you are still just a little boy like a hundred thousand other little boys","note":"","sourceLineIndex":28},{"id":"le-petit-prince-2cd-34-029","lineIndex":29,"speaker":"Le Renard","original":"et je n'ai pas besoin de toi.","ipa":"/e ʒə ne pa bəzwɛ̃ də twa/","zh":"而且我不需要你","en":"and I don't need you.","note":"","sourceLineIndex":29},{"id":"le-petit-prince-2cd-34-030","lineIndex":30,"speaker":"Le Renard","original":"Et tu n'as pas besoin de moi non plus","ipa":"/e ty na pa bəzwɛ̃ də mwa nɔ̃ ply/","zh":"你也不需要我","en":"And you don't need me either","note":"","sourceLineIndex":30},{"id":"le-petit-prince-2cd-34-031","lineIndex":31,"speaker":"Le Renard","original":"je ne suis pour toi qu'un renard semblable à cent mille renards.","ipa":"/ʒə nə syi puʁ twa kœ̃ ʁənaʁ sɑ̃blabl a sɑ̃ mil ʁənaʁ/","zh":"对你而言，我也只是一只与十万只狐狸毫无区别的狐狸。","en":"to you, I am only a fox like a hundred thousand other foxes.","note":"","sourceLineIndex":31},{"id":"le-petit-prince-2cd-34-032","lineIndex":32,"speaker":"Le Renard","original":"Mais si tu m'apprivoises, nous aurons besoin l'un de l'autre.","ipa":"/mɛ si ty mapʁivwaz nuz oʁɔ̃ bəzwɛ̃ lœ̃ də lotʁ/","zh":"但如果你驯养了我 我们就相互需要了","en":"But if you tame me, we will need each other.","note":"","sourceLineIndex":32},{"id":"le-petit-prince-2cd-34-033","lineIndex":33,"speaker":"Le Renard","original":"Tu seras pour moi unique au monde","ipa":"/ty səʁa puʁ mwa ynik o mɔ̃d/","zh":"你就是我在世界上唯一的人了","en":"You will be unique in the world for me","note":"","sourceLineIndex":33},{"id":"le-petit-prince-2cd-34-034","lineIndex":34,"speaker":"Le Renard","original":"je serai pour toi unique au monde.","ipa":"/ʒə səʁe puʁ twa ynik o mɔ̃d/","zh":"我也是你世上唯一的狐狸了","en":"I will be unique in the world for you.","note":"","sourceLineIndex":34},{"id":"le-petit-prince-2cd-34-035","lineIndex":35,"speaker":"Le Petit Prince","original":"Il y a une fleur, je crois qu'elle m'a apprivoisé.","ipa":"/il i a yn flœʁ ʒə kʁwa kɛl ma apʁivwaze/","zh":"有一朵花儿，我觉得她已经驯服了我。","en":"There is a flower; I think she has tamed me.","note":"","sourceLineIndex":35},{"id":"le-petit-prince-2cd-34-036","lineIndex":36,"speaker":"Le Renard","original":"C'est possible. On voit sur la Terre toutes sortes de choses.","ipa":"/sɛ pɔsibl ɔ̃ vwa syʁ la tɛʁ tut sɔʁt də ʃoz/","zh":"这很可能。地球上什么样的事都看得到。","en":"That is possible. One sees all sorts of things on Earth.","note":"","sourceLineIndex":36},{"id":"le-petit-prince-2cd-34-037","lineIndex":37,"speaker":"Le Petit Prince","original":"Oh, ce n'est pas sur la Terre.","ipa":"/ɔ sə nɛ pa syʁ la tɛʁ/","zh":"哦，她不在地球上。","en":"Oh, she is not on Earth.","note":"","sourceLineIndex":37},{"id":"le-petit-prince-2cd-34-038","lineIndex":38,"speaker":"Le Renard","original":"Sur une autre planète?","ipa":"/syʁ yn otʁ planɛt/","zh":"在另一个星球上？","en":"On another planet?","note":"","sourceLineIndex":38},{"id":"le-petit-prince-2cd-34-039","lineIndex":39,"speaker":"Le Petit Prince","original":"Oui.","ipa":"/wi/","zh":"是的","en":"Yes.","note":"","sourceLineIndex":39},{"id":"le-petit-prince-2cd-34-040","lineIndex":40,"speaker":"Le Renard","original":"Il y a des chasseurs sur cette planète-là?","ipa":"/il i a de ʃasœʁ syʁ sɛt planɛtla/","zh":"那颗星球上有猎人吗？","en":"Are there hunters on that planet?","note":"","sourceLineIndex":40},{"id":"le-petit-prince-2cd-34-041","lineIndex":41,"speaker":"Le Petit Prince","original":"Non.","ipa":"/nɔ̃/","zh":"没有","en":"No.","note":"","sourceLineIndex":41},{"id":"le-petit-prince-2cd-34-042","lineIndex":42,"speaker":"Le Renard","original":"Ça c'est intéressant! Et des poules?","ipa":"/sa sɛt ɛ̃teʁɛsɑ̃ e de pul/","zh":"那可有意思了！有鸡吗？","en":"That’s interesting! And chickens?","note":"","sourceLineIndex":42},{"id":"le-petit-prince-2cd-34-043","lineIndex":43,"speaker":"Le Petit Prince","original":"Non.","ipa":"/nɔ̃/","zh":"没有","en":"No.","note":"","sourceLineIndex":43},{"id":"le-petit-prince-2cd-34-044","lineIndex":44,"speaker":"Le Renard","original":"Rien n'est parfait.","ipa":"/ʁiɛ̃ nɛ paʁfɛ/","zh":"世上就没有十全十美的东西","en":"Nothing is perfect.","note":"","sourceLineIndex":44},{"id":"le-petit-prince-2cd-34-045","lineIndex":45,"speaker":"Le Renard","original":"S'il te plaît, apprivoise-moi.","ipa":"/sil tə plɛ apʁivwazmwa/","zh":"请你 驯养我吧","en":"Please tame me.","note":"","sourceLineIndex":45},{"id":"le-petit-prince-2cd-34-046","lineIndex":46,"speaker":"Le Petit Prince","original":"Je veux bien, mais je n'ai pas beaucoup de temps","ipa":"/ʒə vø bjɛ̃ mɛ ʒə ne pa boku də tɑ̃/","zh":"我很愿意，但是我没有多少时间","en":"I would be glad to, but I do not have much time","note":"","sourceLineIndex":46},{"id":"le-petit-prince-2cd-34-047","lineIndex":47,"speaker":"Le Petit Prince","original":"j'ai des amis à découvrir et beaucoup de choses à connaître.","ipa":"/ʒe dez ami a dekuvʁiʁ e boku də ʃozz a kɔnɛtʁ/","zh":"我还有朋友要去发现，还有许多事物要去了解。","en":"I have friends to discover and many things to understand.","note":"","sourceLineIndex":47},{"id":"le-petit-prince-2cd-34-048","lineIndex":48,"speaker":"Le Renard","original":"On ne connaît que les choses que l'on apprivoise.","ipa":"/ɔ̃ nə kɔnɛ kə le ʃoz kə lɔ̃n apʁivwaz/","zh":"人只能认识自己所驯养的","en":"We only know the things we tame.","note":"","sourceLineIndex":48}],"sourceOrder":34,"displayOrder":33},{"order":35,"id":"35-apprivoise-moi","title":"Apprivoise-Moi","titleZh":"驯养我吧","lines":[{"id":"le-petit-prince-2cd-35-001","lineIndex":1,"speaker":"Le Renard","original":"Si tu veux jouer avec moi","ipa":"/si ty vø ʒwe avɛk mwa/","zh":"如果你想和我玩","en":"If you want to play with me","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-35-002","lineIndex":2,"speaker":"Le Renard","original":"il va falloir m'apprivoiser","ipa":"/il va falwaʁ mapʁivwaze/","zh":"就得先驯养我","en":"you will have to tame me","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-35-003","lineIndex":3,"speaker":"Le Renard","original":"Et créer des liens pas à pas","ipa":"/e kʁee de ljɛ̃ paz a pa/","zh":"一步步建立纽带","en":"And establish bonds step by step","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-35-004","lineIndex":4,"speaker":"Le Renard","original":"Pour commencer à s'attacher","ipa":"/puʁ kɔmɑ̃se a sataʃe/","zh":"以使彼此之间产生依恋","en":"To start getting attached","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-35-005","lineIndex":5,"speaker":"Le Renard","original":"Sinon tu n'es encore pour moi","ipa":"/sinɔ̃ ty nɛz ɑ̃kɔʁ puʁ mwa/","zh":"否则你于我不过是","en":"Otherwise you are still for me","note":"","sourceLineIndex":5},{"id":"le-petit-prince-2cd-35-006","lineIndex":6,"speaker":"Le Renard","original":"Qu'un petit garçon comme les autres","ipa":"/kœ̃ pəti ɡaʁsɔ̃ kɔm lez otʁ/","zh":"和别人没有两样的小男孩","en":"Just a little boy like the others","note":"","sourceLineIndex":6},{"id":"le-petit-prince-2cd-35-007","lineIndex":7,"speaker":"Le Renard","original":"Pour toi qui ne me connais pas","ipa":"/puʁ twa ki nə mə kɔnɛ pa/","zh":"对不熟悉我的你而言","en":"For you who don't know me","note":"","sourceLineIndex":7},{"id":"le-petit-prince-2cd-35-008","lineIndex":8,"speaker":"Le Renard","original":"Je ne suis qu'un renard parmi d'autres","ipa":"/ʒə nə syi kœ̃ ʁənaʁ paʁmi dotʁ/","zh":"我不过是一只和别的狐狸一样的狐狸","en":"I'm just another fox","note":"","sourceLineIndex":8},{"id":"le-petit-prince-2cd-35-009","lineIndex":9,"speaker":"Le Renard","original":"Apprivoise-moi je t'en prie","ipa":"/apʁivwazmwa ʒə tɑ̃ pʁi/","zh":"请你驯养我吧","en":"Tame me, please","note":"","sourceLineIndex":9},{"id":"le-petit-prince-2cd-35-010","lineIndex":10,"speaker":"Le Renard","original":"Si tu as besoin d'un ami","ipa":"/si ty a bəzwɛ̃ dœ̃n ami/","zh":"如果你需要朋友","en":"If you need a friend","note":"","sourceLineIndex":10},{"id":"le-petit-prince-2cd-35-011","lineIndex":11,"speaker":"Le Renard","original":"Et jusqu'à ma dernière seconde","ipa":"/e ʒyska ma dɛʁnjɛʁ səɡɔ̃d/","zh":"那么直到最后一秒","en":"And until my last second","note":"","sourceLineIndex":11},{"id":"le-petit-prince-2cd-35-012","lineIndex":12,"speaker":"Le Renard","original":"Tu resteras unique au monde","ipa":"/ty ʁɛstʁaz ynik o mɔ̃d/","zh":"你都是我在这世上的唯一","en":"You will remain unique in the world","note":"","sourceLineIndex":12},{"id":"le-petit-prince-2cd-35-013","lineIndex":13,"speaker":"Le Renard","original":"Mais si tu sais m'apprivoiser","ipa":"/mɛ si ty sɛ mapʁivwaze/","zh":"但如果你懂得如何驯服我","en":"But if you know how to tame me","note":"","sourceLineIndex":13},{"id":"le-petit-prince-2cd-35-014","lineIndex":14,"speaker":"Le Renard","original":"Ma vie sera ensoleillée","ipa":"/ma vi səʁa ɑ̃solɛje/","zh":"我的生活就会充满阳光","en":"My life will be sunny","note":"","sourceLineIndex":14},{"id":"le-petit-prince-2cd-35-015","lineIndex":15,"speaker":"Le Renard","original":"Je connaîtrai ton bruit de pas","ipa":"/ʒə kɔnɛtʁe tɔ̃ bʁyi də pa/","zh":"我将辨认出你的脚步声","en":"I will recognize the sound of your footsteps","note":"","sourceLineIndex":15},{"id":"le-petit-prince-2cd-35-016","lineIndex":16,"speaker":"Le Renard","original":"Qui m'appellera hors du terrier","ipa":"/ki mapɛlʁa ɔʁ dy tɛʁje/","zh":"它会召唤我走出洞穴","en":"which will call me out of my burrow","note":"","sourceLineIndex":16},{"id":"le-petit-prince-2cd-35-017","lineIndex":17,"speaker":"Le Renard","original":"Et la blondeur des champs de blé","ipa":"/e la blɔ̃dœʁ de ʃɑ̃ də ble/","zh":"而麦田的金色","en":"And the golden color of the wheat fields","note":"","sourceLineIndex":17},{"id":"le-petit-prince-2cd-35-018","lineIndex":18,"speaker":"Le Renard","original":"Me fera souvenir de toi","ipa":"/mə fəʁa suvniʁ də twa/","zh":"会让我想起你","en":"will remind me of you","note":"","sourceLineIndex":18},{"id":"le-petit-prince-2cd-35-019","lineIndex":19,"speaker":"Le Renard","original":"Enfin j'aimerai le bruit du vent","ipa":"/ɑ̃fɛ̃ ʒɛmʁe lə bʁyi dy vɑ̃/","zh":"最终，我会爱上风声","en":"At last I will love the sound of the wind","note":"","sourceLineIndex":19},{"id":"le-petit-prince-2cd-35-020","lineIndex":20,"speaker":"Le Renard","original":"Qui viendra souffler dans ces champs","ipa":"/ki vjɛ̃dʁa sufle dɑ̃ se ʃɑ̃/","zh":"那吹过这些田野的风声","en":"that comes blowing through these fields","note":"","sourceLineIndex":20},{"id":"le-petit-prince-2cd-35-021","lineIndex":21,"speaker":"Le Renard","original":"Apprivoise-moi je t'en prie","ipa":"/apʁivwazmwa ʒə tɑ̃ pʁi/","zh":"请你驯养我吧","en":"Tame me, please","note":"","sourceLineIndex":21},{"id":"le-petit-prince-2cd-35-022","lineIndex":22,"speaker":"Le Renard","original":"Si tu as besoin d'un ami","ipa":"/si ty a bəzwɛ̃ dœ̃n ami/","zh":"如果你需要朋友","en":"If you need a friend","note":"","sourceLineIndex":22},{"id":"le-petit-prince-2cd-35-023","lineIndex":23,"speaker":"Le Renard","original":"Et jusqu'à ma dernière seconde","ipa":"/e ʒyska ma dɛʁnjɛʁ səɡɔ̃d/","zh":"那么直到最后一秒","en":"And until my last second","note":"","sourceLineIndex":23},{"id":"le-petit-prince-2cd-35-024","lineIndex":24,"speaker":"Le Renard","original":"Tu resteras unique au monde","ipa":"/ty ʁɛstʁaz ynik o mɔ̃d/","zh":"你都是我在这世上的唯一","en":"You will remain unique in the world","note":"","sourceLineIndex":24},{"id":"le-petit-prince-2cd-35-025","lineIndex":25,"speaker":"Le Renard","original":"On ne peut connaître vraiment","ipa":"/ɔ̃ nə pø kɔnɛtʁ vʁɛmɑ̃/","zh":"人只能深入了解","en":"We can only truly know","note":"","sourceLineIndex":25},{"id":"le-petit-prince-2cd-35-026","lineIndex":26,"speaker":"Le Renard","original":"Que les choses que l'on apprivoise","ipa":"/kə le ʃoz kə lɔ̃n apʁivwaz/","zh":"自己驯养的东西","en":"The things we tame","note":"","sourceLineIndex":26},{"id":"le-petit-prince-2cd-35-027","lineIndex":27,"speaker":"Le Renard","original":"Mais les hommes n'ont plus de temps","ipa":"/mɛ lez ɔm nɔ̃ ply də tɑ̃/","zh":"但是人们没时间","en":"But men no longer have time","note":"","sourceLineIndex":27},{"id":"le-petit-prince-2cd-35-028","lineIndex":28,"speaker":"Le Renard","original":"De s'attarder quand ils se croisent","ipa":"/də sataʁde kɑ̃t il sə kʁwaz/","zh":"停下来相互认识","en":"To linger when they cross paths","note":"","sourceLineIndex":28},{"id":"le-petit-prince-2cd-35-029","lineIndex":29,"speaker":"Le Renard","original":"Ils achètent des choses toutes faites","ipa":"/ilz aʃɛt de ʃoz tut fɛt/","zh":"他们购买现成的东西","en":"They buy ready-made things","note":"","sourceLineIndex":29},{"id":"le-petit-prince-2cd-35-030","lineIndex":30,"speaker":"Le Renard","original":"Mais il n'y a pas de marchands d'amis","ipa":"/mɛz il ni a pa də maʁʃɑ̃ dami/","zh":"可没有朋友商人","en":"But there are no merchants of friends","note":"","sourceLineIndex":30},{"id":"le-petit-prince-2cd-35-031","lineIndex":31,"speaker":"Le Renard","original":"Qui vendent de l'amitié toute prête","ipa":"/ki vɑ̃d də lamitje tut pʁɛt/","zh":"出售现成的友谊","en":"who sell ready-made friendship","note":"","sourceLineIndex":31},{"id":"le-petit-prince-2cd-35-032","lineIndex":32,"speaker":"Le Renard","original":"Alors les hommes n'ont plus d'amis","ipa":"/alɔʁ lez ɔm nɔ̃ ply dami/","zh":"于是人也就没朋友了","en":"So men no longer have friends","note":"","sourceLineIndex":32},{"id":"le-petit-prince-2cd-35-033","lineIndex":33,"speaker":"Le Renard","original":"Apprivoise-moi je t'en prie","ipa":"/apʁivwazmwa ʒə tɑ̃ pʁi/","zh":"请你驯养我吧","en":"Tame me, please","note":"","sourceLineIndex":33},{"id":"le-petit-prince-2cd-35-034","lineIndex":34,"speaker":"Le Renard","original":"Si tu as besoin d'un ami","ipa":"/si ty a bəzwɛ̃ dœ̃n ami/","zh":"如果你需要朋友","en":"If you need a friend","note":"","sourceLineIndex":34},{"id":"le-petit-prince-2cd-35-035","lineIndex":35,"speaker":"Le Renard","original":"Et jusqu'à ma dernière seconde","ipa":"/e ʒyska ma dɛʁnjɛʁ səɡɔ̃d/","zh":"那么直到最后一秒","en":"And until my last second","note":"","sourceLineIndex":35},{"id":"le-petit-prince-2cd-35-036","lineIndex":36,"speaker":"Le Renard","original":"Tu resteras unique au monde","ipa":"/ty ʁɛstʁaz ynik o mɔ̃d/","zh":"你都是我在这世上的唯一","en":"You will remain unique in the world","note":"","sourceLineIndex":36},{"id":"le-petit-prince-2cd-35-037","lineIndex":37,"speaker":"Le Renard","original":"Il nous faudra des rendez-vous","ipa":"/il nu fodʁa de ʁɑ̃devu/","zh":"我们需要定时约见","en":"We will need meetings","note":"","sourceLineIndex":37},{"id":"le-petit-prince-2cd-35-038","lineIndex":38,"speaker":"Le Renard","original":"Pour pouvoir s'habiller le coeur","ipa":"/puʁ puvwaʁ sabije lə kœʁ/","zh":"以便装扮自己的心","en":"To be able to dress the heart","note":"","sourceLineIndex":38},{"id":"le-petit-prince-2cd-35-039","lineIndex":39,"speaker":"Le Renard","original":"Et tous ces moments entre nous","ipa":"/e tu se momɑ̃z ɑ̃tʁ nu/","zh":"这样每次在一起的时候","en":"And all these moments between us","note":"","sourceLineIndex":39},{"id":"le-petit-prince-2cd-35-040","lineIndex":40,"speaker":"Le Renard","original":"M'apprendront le prix du bonheur","ipa":"/mapʁɑ̃dʁɔ̃ lə pʁi dy bɔnœʁ/","zh":"我就能体会到幸福的价值","en":"Will teach me the price of happiness","note":"","sourceLineIndex":40},{"id":"le-petit-prince-2cd-35-041","lineIndex":41,"speaker":"Le Petit Prince","original":"Que faut-il faire?","ipa":"/kə fotil fɛʁ/","zh":"我该做些什么呢？","en":"What should I do?","note":"","sourceLineIndex":41},{"id":"le-petit-prince-2cd-35-042","lineIndex":42,"speaker":"Le Renard","original":"Il faut être patient.","ipa":"/il fot ɛtʁ pasjɑ̃/","zh":"要有耐心。","en":"One must be patient.","note":"","sourceLineIndex":42},{"id":"le-petit-prince-2cd-35-043","lineIndex":43,"speaker":"Le Renard","original":"Tu t'assoiras d'abord un peu loin de moi","ipa":"/ty taswaʁa dabɔʁ œ̃ pø lwɛ̃ də mwa/","zh":"首先你要离我稍远点 坐着","en":"You will first sit a little far from me","note":"","sourceLineIndex":43},{"id":"le-petit-prince-2cd-35-044","lineIndex":44,"speaker":"Le Renard","original":"je te regarderai du coin de l'oeil...","ipa":"/ʒə tə ʁəɡaʁdəʁe dy kwɛ̃ də lœj/","zh":"我斜瞟着你","en":"I will look at you out of the corner of my eye...","note":"","sourceLineIndex":44},{"id":"le-petit-prince-2cd-35-045","lineIndex":45,"speaker":"Le Petit Prince","original":"Et...","ipa":"/e/","zh":"那......","en":"And...","note":"","sourceLineIndex":45},{"id":"le-petit-prince-2cd-35-046","lineIndex":46,"speaker":"Le Renard","original":"Et tu ne diras rien.","ipa":"/e ty nə diʁa ʁjɛ̃/","zh":"什么也别对我说","en":"And you will not say anything.","note":"","sourceLineIndex":46},{"id":"le-petit-prince-2cd-35-047","lineIndex":47,"speaker":"Le Petit Prince","original":"Oh...","ipa":"/ɔ/","zh":"哦......","en":"Oh...","note":"","sourceLineIndex":47},{"id":"le-petit-prince-2cd-35-048","lineIndex":48,"speaker":"Le Renard","original":"Le langage est source de malentendus.","ipa":"/lə lɑ̃ɡaʒ ɛ suʁs də malɑ̃tɑ̃dy/","zh":"语言是误会的源泉","en":"Language is a source of misunderstanding.","note":"","sourceLineIndex":48},{"id":"le-petit-prince-2cd-35-049","lineIndex":49,"speaker":"Le Renard","original":"Mais, chaque jour, tu pourras t'asseoir un peu plus près.","ipa":"/mɛ ʃak ʒuʁ ty puʁa taswaʁ œ̃ pø ply pʁɛ/","zh":"可是 每天你可以坐得稍近一点","en":"But, each day, you will be able to sit a little closer.","note":"","sourceLineIndex":49},{"id":"le-petit-prince-2cd-35-050","lineIndex":50,"speaker":"Le Petit Prince","original":"Il faut que je parte.","ipa":"/il fo kə ʒə paʁt/","zh":"我得走了","en":"I have to leave.","note":"","sourceLineIndex":50},{"id":"le-petit-prince-2cd-35-051","lineIndex":51,"speaker":"Le Renard","original":"Ah! Je pleurerai.","ipa":"/a ʒə pløʁʁe/","zh":"啊！我会哭的。","en":"Ah! I will cry.","note":"","sourceLineIndex":51},{"id":"le-petit-prince-2cd-35-052","lineIndex":52,"speaker":"Le Petit Prince","original":"C'est ta faute.","ipa":"/sɛ ta fot/","zh":"这就是你的不对了","en":"It's your fault.","note":"","sourceLineIndex":52},{"id":"le-petit-prince-2cd-35-053","lineIndex":53,"speaker":"Le Petit Prince","original":"Je ne te souhaitais pas de mal","ipa":"/ʒə nə tə suɛtɛ pa də mal/","zh":"我并不想伤害你","en":"I didn't wish you harm","note":"","sourceLineIndex":53},{"id":"le-petit-prince-2cd-35-054","lineIndex":54,"speaker":"Le Petit Prince","original":"mais tu as voulu que je t'apprivoise.","ipa":"/mɛ ty a vuly kə ʒə tapʁivwaz/","zh":"但你却要我驯养你","en":"but you wanted me to tame you.","note":"","sourceLineIndex":54},{"id":"le-petit-prince-2cd-35-055","lineIndex":55,"speaker":"Le Renard","original":"Bien sûr...","ipa":"/bjɛ̃ syːʁ/","zh":"不错......","en":"Of course...","note":"","sourceLineIndex":55},{"id":"le-petit-prince-2cd-35-056","lineIndex":56,"speaker":"Le Petit Prince","original":"Mais tu vas pleurer?","ipa":"/mɛ ty va pløʁe/","zh":"但你会哭吗？","en":"But are you going to cry?","note":"","sourceLineIndex":56},{"id":"le-petit-prince-2cd-35-057","lineIndex":57,"speaker":"Le Renard","original":"Bien sûr.","ipa":"/bjɛ̃ syːʁ/","zh":"不错","en":"Of course.","note":"","sourceLineIndex":57},{"id":"le-petit-prince-2cd-35-058","lineIndex":58,"speaker":"Le Petit Prince","original":"Alors tu n'y gagnes rien.","ipa":"/alɔʁ ty ni ɡanj ʁiɛ̃/","zh":"那你是一无所获了","en":"So you gain nothing.","note":"","sourceLineIndex":58},{"id":"le-petit-prince-2cd-35-059","lineIndex":59,"speaker":"Le Renard","original":"Ah, j'y gagne, à cause de la couleur du blé.","ipa":"/a ʒi ɡaɲ a koz də la kulœʁ dy ble/","zh":"啊，我有收获，因为有麦子的颜色。","en":"Ah, I gain from it, because of the color of the wheat.","note":"","sourceLineIndex":59},{"id":"le-petit-prince-2cd-35-060","lineIndex":60,"speaker":"Le Renard","original":"Va revoir les roses et tu comprendras que la tienne est unique au monde.","ipa":"/va ʁəvwaʁ le ʁozz e ty kɔ̃pʁɑ̃dʁa kə la tjɛn ɛt ynik o mɔ̃d/","zh":"你去探望玫瑰花们吧 你就会明白 你的玫瑰花是世界上独一无二的","en":"Go see the roses again and you will understand that yours is unique in the world.","note":"","sourceLineIndex":60}],"sourceOrder":35,"displayOrder":34},{"order":36,"id":"36-puisque-c-est-ma-rose","title":"Puisque C'est Ma Rose","titleZh":"因为她是我的玫瑰","lines":[{"id":"le-petit-prince-2cd-36-001","lineIndex":1,"speaker":"","original":"Vous ne ressemblez pas à ma rose","ipa":"/vu nə ʁəsɑ̃ble paz a ma ʁɔz/","zh":"你们不像我的玫瑰","en":"You don't look like my rose","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-36-002","lineIndex":2,"speaker":"","original":"Même si un passant ordinaire","ipa":"/mɛm si œ̃ pasɑ̃ ɔʁdinɛʁ/","zh":"即使一个普通的路人","en":"Even if an ordinary passerby","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-36-003","lineIndex":3,"speaker":"","original":"Pouvait prétendre le contraire","ipa":"/puvɛ pʁetɑ̃dʁ lə kɔ̃tʁɛʁ/","zh":"可能声称恰恰相反","en":"might claim otherwise","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-36-004","lineIndex":4,"speaker":"","original":"Vous n'êtes rien encore","ipa":"/vu nɛt ʁiɛ̃n ɑ̃kɔʁ/","zh":"可你们仍然什么都不是","en":"You are nothing yet","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-36-005","lineIndex":5,"speaker":"","original":"Personne ne vous a apprivoisée","ipa":"/pɛʁsɔn nə vuz a apʁivwaze/","zh":"没有人驯服过你们","en":"No one has tamed you","note":"","sourceLineIndex":5},{"id":"le-petit-prince-2cd-36-006","lineIndex":6,"speaker":"","original":"Vous n'avez apprivoisé personne","ipa":"/vu navez apʁivwaze pɛʁsɔn/","zh":"你们也没有驯服过任何人","en":"You have tamed no one","note":"","sourceLineIndex":6},{"id":"le-petit-prince-2cd-36-007","lineIndex":7,"speaker":"","original":"Tant que vous n'avez pas d'amis","ipa":"/tɑ̃ kə vu nave pa dami/","zh":"只要你们没有朋友","en":"As long as you don't have friends","note":"","sourceLineIndex":7},{"id":"le-petit-prince-2cd-36-008","lineIndex":8,"speaker":"","original":"Vous n'êtes pas unique au monde","ipa":"/vu nɛt paz ynik o mɔ̃d/","zh":"就不是这世上独一无二的","en":"You are not unique in the world","note":"","sourceLineIndex":8},{"id":"le-petit-prince-2cd-36-009","lineIndex":9,"speaker":"","original":"Vous êtes belle mais vous êtes vide","ipa":"/vuz ɛt bɛl mɛ vuz ɛt vid/","zh":"你们很美，但内里空空","en":"You are beautiful, but empty","note":"","sourceLineIndex":9},{"id":"le-petit-prince-2cd-36-010","lineIndex":10,"speaker":"","original":"On ne peut pas mourir pour vous","ipa":"/ɔ̃ nə pø pa muʁiʁ puʁ vu/","zh":"没有人会为了你们去死","en":"No one could die for you","note":"","sourceLineIndex":10},{"id":"le-petit-prince-2cd-36-011","lineIndex":11,"speaker":"","original":"Et à elle toute seule ma rose","ipa":"/e a ɛl tut sœl ma ʁɔz/","zh":"而我的玫瑰，单凭她一个","en":"And my rose, all by herself","note":"","sourceLineIndex":11},{"id":"le-petit-prince-2cd-36-012","lineIndex":12,"speaker":"","original":"Compte bien plus que tout","ipa":"/kɔ̃t bjɛ̃ ply kə tu/","zh":"就比你们全部更重要","en":"matters far more than all of you","note":"","sourceLineIndex":12},{"id":"le-petit-prince-2cd-36-013","lineIndex":13,"speaker":"","original":"Puisque c'est elle que j'ai arrosée","ipa":"/pyiskə sɛt ɛl kə ʒe aʁoze/","zh":"因为她是我亲手浇灌的","en":"because she is the one I watered","note":"","sourceLineIndex":13},{"id":"le-petit-prince-2cd-36-014","lineIndex":14,"speaker":"","original":"Puisque c'est elle que j'ai protégée","ipa":"/pyiskə sɛt ɛl kə ʒe pʁoteʒe/","zh":"因为她是我亲手保护的","en":"because she is the one I protected","note":"","sourceLineIndex":14}],"sourceOrder":36,"displayOrder":35},{"order":38,"id":"38-l-aiguilleur","title":"L'aiguilleur","titleZh":"扳道工","lines":[{"id":"le-petit-prince-2cd-38-001","lineIndex":1,"speaker":"L'Aiguilleur","original":"Je trie les voyageurs par paquets de mille","ipa":"/ʒə tʁi le vwajaʒœʁ paʁ pakɛ də mil/","zh":"我把旅客分组，每一千人为一批","en":"I sort the travelers into batches of a thousand","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-38-002","lineIndex":2,"speaker":"L'Aiguilleur","original":"J'expédie les trains qui les emportent","ipa":"/ʒɛkspedi le tʁɛ̃ ki lez ɑ̃pɔʁt/","zh":"载乘客的火车由我调度","en":"I dispatch the trains that carry them","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-38-003","lineIndex":3,"speaker":"L'Aiguilleur","original":"Tantôt vers la droite tantôt vers la gauche","ipa":"/tɑ̃toː vɛʁ la dʁwat tɑ̃toː vɛʁ la ɡoʃ/","zh":"它们有时开往右方 有时开往左方","en":"Sometimes to the right, sometimes to the left","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-38-004","lineIndex":4,"speaker":"Le Petit Prince","original":"Ils sont bien pressés que cherchent-ils?","ipa":"/il sɔ̃ bjɛ̃ pʁɛse kə ʃɛʁʃtil/","zh":"他们行色匆匆 他们寻找什么？","en":"They are in a hurry, what are they looking for?","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-38-005","lineIndex":5,"speaker":"L'Aiguilleur","original":"L'homme de la locomotive l'ignore lui-même","ipa":"/lɔm də la lokomotiv linjɔʁ lyimɛm/","zh":"就连火车司机自己也不知道","en":"The engine driver himself does not know","note":"","sourceLineIndex":5},{"id":"le-petit-prince-2cd-38-006","lineIndex":6,"speaker":"Le Petit Prince","original":"Ils reviennent déjà?","ipa":"/il ʁəvjɛn deʒa/","zh":"他们已经回来了？","en":"Are they coming back already?","note":"","sourceLineIndex":6},{"id":"le-petit-prince-2cd-38-007","lineIndex":7,"speaker":"L'Aiguilleur","original":"Ce ne sont pas les mêmes c'est un échange","ipa":"/sə nə sɔ̃ pa le mɛm sɛt œ̃n eʃɑ̃ʒ/","zh":"不是同一批，这是对开的列车","en":"They are not the same ones; it is an exchange","note":"","sourceLineIndex":7},{"id":"le-petit-prince-2cd-38-008","lineIndex":8,"speaker":"Le Petit Prince","original":"Ils n'étaient pas contents là où ils étaient?","ipa":"/il netɛ pa kɔ̃tɑ̃ la u ilz etɛ/","zh":"他们对他们的居住地不满意？","en":"They weren't happy where they were?","note":"","sourceLineIndex":8},{"id":"le-petit-prince-2cd-38-009","lineIndex":9,"speaker":"L'Aiguilleur","original":"On n'est jamais contents là où l'on est","ipa":"/ɔ̃ nɛ ʒamɛ kɔ̃tɑ̃ la u lɔ̃n ɛ/","zh":"人总是这山望着那山高的","en":"People are never satisfied where they are","note":"","sourceLineIndex":9},{"id":"le-petit-prince-2cd-38-010","lineIndex":10,"speaker":"Le Petit Prince","original":"Ils poursuivent les premiers voyageurs?","ipa":"/il puʁsyiv le pʁəmje vwajaʒœʁ/","zh":"他们在追赶第一批旅客吗？","en":"They are chasing the first travelers?","note":"","sourceLineIndex":10},{"id":"le-petit-prince-2cd-38-011","lineIndex":11,"speaker":"L'Aiguilleur","original":"Ils ne poursuivent rien du tout.","ipa":"/il nə puʁsyiv ʁiɛ̃ dy tu/","zh":"他们什么也不追。","en":"They are not pursuing anything at all.","note":"","sourceLineIndex":11},{"id":"le-petit-prince-2cd-38-012","lineIndex":12,"speaker":"L'Aiguilleur","original":"Ils dorment là-dedans, ou bien ils baillent.","ipa":"/il dɔʁm ladədɑ̃ u bjɛ̃n il baj/","zh":"他们在车厢里睡觉，或是打哈欠。","en":"They sleep in there, or else they yawn.","note":"","sourceLineIndex":12},{"id":"le-petit-prince-2cd-38-013","lineIndex":13,"speaker":"L'Aiguilleur","original":"Les enfants seuls écrasent leur nez contre les vitres.","ipa":"/lez ɑ̃fɑ̃ sœlz ekʁaz lœʁ ne kɔ̃tʁ le vitʁ/","zh":"只有孩子们才把鼻子紧贴在车窗上。","en":"Only the children press their noses against the windows.","note":"","sourceLineIndex":13},{"id":"le-petit-prince-2cd-38-014","lineIndex":14,"speaker":"Le Petit Prince","original":"Les enfants seuls savent ce qu'ils cherchent.","ipa":"/lez ɑ̃fɑ̃ sœl sav sə kil ʃɛʁʃ/","zh":"只有孩子才知道他们要寻觅什么","en":"Only children know what they are looking for.","note":"","sourceLineIndex":14},{"id":"le-petit-prince-2cd-38-015","lineIndex":15,"speaker":"Le Petit Prince","original":"Ils perdent du temps pour une poupée de chiffons, et elle devient très importante.","ipa":"/il pɛʁd dy tɑ̃ puʁ yn pupe də ʃifɔ̃ e ɛl dəvjɛ̃ tʁɛz ɛ̃pɔʁtɑ̃t/","zh":"他们在一个布娃娃身上花费时间，于是她变得非常重要。","en":"They spend time on a rag doll, and she becomes very important.","note":"","sourceLineIndex":15},{"id":"le-petit-prince-2cd-38-016","lineIndex":16,"speaker":"Le Petit Prince","original":"Et si on la leur enlève, ils pleurent.","ipa":"/e si ɔ̃ la løʁ ɑ̃lɛv il plœʁ/","zh":"如果有人把她拿走，他们就会哭。","en":"And if she is taken away from them, they cry.","note":"","sourceLineIndex":16},{"id":"le-petit-prince-2cd-38-017","lineIndex":17,"speaker":"L'Aiguilleur","original":"Ils ont de la chance.","ipa":"/ilz ɔ̃ də la ʃɑ̃s/","zh":"他们是有运气的人","en":"They're lucky.","note":"","sourceLineIndex":17}],"sourceOrder":38,"displayOrder":36},{"order":39,"id":"39-le-marchant-de-pilules-deuxieme-tempete-de-sable-la-ville","title":"Le Marchant De Pilules / DeuxiÈMe TempÊTe De Sable / La Ville","titleZh":"药丸商人 / 第二沙殿 / 城市","lines":[{"id":"le-petit-prince-2cd-39-001","lineIndex":1,"speaker":"Le Marchand de Pilules","original":"Demandez les pilules du Docteur Désir","ipa":"/dəmɑ̃de le pilyl dy dɔktœʁ deziʁ/","zh":"渴望医生牌药丸，快来买！","en":"Ask for Doctor Désir's pills","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-39-002","lineIndex":2,"speaker":"Le Marchand de Pilules","original":"demandez les pilules contre la soif!","ipa":"/dəmɑ̃de le pilyl kɔ̃tʁ la swaf/","zh":"止渴药丸，快来买！","en":"ask for the pills against thirst!","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-39-003","lineIndex":3,"speaker":"Le Petit Prince","original":"Bonjour!","ipa":"/bɔ̃ʒuʁ/","zh":"您好！","en":"Hello!","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-39-004","lineIndex":4,"speaker":"Le Marchand de Pilules","original":"Bonjour!","ipa":"/bɔ̃ʒuʁ/","zh":"你好！","en":"Hello!","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-39-005","lineIndex":5,"speaker":"Le Petit Prince","original":"Et vous, qui êtes-vous?","ipa":"/e vu ki ɛtvu/","zh":"您是做什么的呢？","en":"And you, who are you?","note":"","sourceLineIndex":5},{"id":"le-petit-prince-2cd-39-006","lineIndex":6,"speaker":"Le Marchand de Pilules","original":"Je suis un marchand de pilules perfectionnées qui apaisent la soif.","ipa":"/ʒə syiz œ̃ maʁʃɑ̃ də pilyl pɛʁfɛksjɔne ki apɛz la swaf/","zh":"我是贩卖解渴药丸的商人","en":"I am a dealer in advanced thirst-quenching pills.","note":"","sourceLineIndex":6},{"id":"le-petit-prince-2cd-39-007","lineIndex":7,"speaker":"Le Marchand de Pilules","original":"Demandez les pilules du Docteur Désir","ipa":"/dəmɑ̃de le pilyl dy dɔktœʁ deziʁ/","zh":"渴望医生牌药丸，快来买！","en":"Ask for Doctor Désir's pills","note":"","sourceLineIndex":7},{"id":"le-petit-prince-2cd-39-008","lineIndex":8,"speaker":"Le Marchand de Pilules","original":"demandez les pilules contre la soif!","ipa":"/dəmɑ̃de le pilyl kɔ̃tʁ la swaf/","zh":"止渴药丸，快来买！","en":"ask for the pills against thirst!","note":"","sourceLineIndex":8},{"id":"le-petit-prince-2cd-39-009","lineIndex":9,"speaker":"Le Marchand de Pilules","original":"Et on en avale une par semaine et l'on n'éprouve plus le besoin de boire.","ipa":"/e ɔ̃n ɑ̃n aval yn paʁ səmɛn e lɔ̃ nepʁuv ply lə bəzwɛ̃ də bwaʁ/","zh":"一星期吃一颗 就不再需要喝水了","en":"And we swallow one a week and we no longer feel the need to drink.","note":"","sourceLineIndex":9},{"id":"le-petit-prince-2cd-39-010","lineIndex":10,"speaker":"Le Petit Prince","original":"Pourquoi vends-tu ça?","ipa":"/puʁkwa vɑ̃ty sa/","zh":"为什么你卖这种药？","en":"Why are you selling this?","note":"","sourceLineIndex":10},{"id":"le-petit-prince-2cd-39-011","lineIndex":11,"speaker":"Le Marchand de Pilules","original":"Mais c'est une grosse économie de temps.","ipa":"/mɛ sɛt yn ɡʁos ekonomi də tɑ̃/","zh":"为了节省更多的时间啊","en":"But it's a big time saver.","note":"","sourceLineIndex":11},{"id":"le-petit-prince-2cd-39-012","lineIndex":12,"speaker":"Le Marchand de Pilules","original":"On épargne cinquante-trois minutes par semaine selon les experts.","ipa":"/ɔ̃n epaʁɲ sɛ̃kɑ̃ttʁwa minyt paʁ səmɛn səlɔ̃ lez ɛkspɛʁ/","zh":"每个星期能节省五十三分钟","en":"We save fifty-three minutes per week according to experts.","note":"","sourceLineIndex":12},{"id":"le-petit-prince-2cd-39-013","lineIndex":13,"speaker":"Le Petit Prince","original":"Et que fait-on de ces cinquante-trois minutes?","ipa":"/e kə fɛtɔ̃ də se sɛ̃kɑ̃ttʁwa minyt/","zh":"省出的这五十三分钟有什么用途？","en":"And what do we do with these fifty-three minutes?","note":"","sourceLineIndex":13},{"id":"le-petit-prince-2cd-39-014","lineIndex":14,"speaker":"Le Marchand de Pilules","original":"Eh bien, on en fait... ce que l'on veut.","ipa":"/ɛ bjɛ̃ ɔ̃n ɑ̃ fɛ sə kə lɔ̃ vø/","zh":"嗯……想拿它们做什么都行。","en":"Well, one does with them... whatever one likes.","note":"","sourceLineIndex":14},{"id":"le-petit-prince-2cd-39-015","lineIndex":15,"speaker":"Le Petit Prince","original":"Moi, si j'avais cinquante-trois minutes à dépenser","ipa":"/mwa si ʒavɛ sɛ̃kɑ̃ttʁwa minytz a depɑ̃se/","zh":"如果我有五十三分钟可以支配","en":"If I had fifty-three minutes to spend","note":"","sourceLineIndex":15},{"id":"le-petit-prince-2cd-39-016","lineIndex":16,"speaker":"Le Petit Prince","original":"je marcherais tout doucement vers une fontaine.","ipa":"/ʒə maʁʃʁɛ tu dusmɑ̃ vɛʁ yn fɔ̃tɛn/","zh":"我就缓缓朝一泓泉水走去","en":"I would walk slowly towards a fountain.","note":"","sourceLineIndex":16},{"id":"le-petit-prince-2cd-39-017","lineIndex":17,"speaker":"Le Marchand de Pilules","original":"Demandez les pilules du Docteur Désir...","ipa":"/dəmɑ̃de le pilyl dy dɔktœʁ deziʁ/","zh":"渴望医生牌药丸，快来买……","en":"Ask for Doctor Désir's pills...","note":"","sourceLineIndex":17},{"id":"le-petit-prince-2cd-39-018","lineIndex":18,"speaker":"Le Petit Prince","original":"Je retourne dans le désert","ipa":"/ʒə ʁətuʁn dɑ̃ lə dezɛʁ/","zh":"我要回沙漠去了","en":"I am going back to the desert","note":"","sourceLineIndex":18},{"id":"le-petit-prince-2cd-39-019","lineIndex":19,"speaker":"Le Marchand de Pilules","original":"Demandez les pilules contre la soif...","ipa":"/dəmɑ̃de le pilyl kɔ̃tʁ la swaf/","zh":"止渴药丸，快来买……","en":"Ask for the pills against thirst...","note":"","sourceLineIndex":19},{"id":"le-petit-prince-2cd-39-020","lineIndex":20,"speaker":"Le Petit Prince","original":"j'aime mieux le désert.","ipa":"/ʒɛm mjø lə dezɛʁ/","zh":"我更喜欢沙漠。","en":"I prefer the desert.","note":"","sourceLineIndex":20},{"id":"le-petit-prince-2cd-39-021","lineIndex":21,"speaker":"Le Marchand de Pilules","original":"Demandez les pilules contre la soif...","ipa":"/dəmɑ̃de le pilyl kɔ̃tʁ la swaf/","zh":"止渴药丸，快来买……","en":"Ask for the pills against thirst...","note":"","sourceLineIndex":21}],"sourceOrder":39,"displayOrder":37},{"order":40,"id":"40-lever-de-soleil-retour-dans-le-desert-8e-jour-coucher-de-soleil","title":"Lever De Soleil / Retour Dans Le DÉSert: 8È Jour Coucher De Soleil","titleZh":"日出／重返沙漠：第八天／日落","lines":[{"id":"le-petit-prince-2cd-40-001","lineIndex":1,"speaker":"Le Petit Prince","original":"Dessine-moi un mouton.","ipa":"/dɛsinmwa œ̃ mutɔ̃/","zh":"给我画一只绵羊吧","en":"Draw me a sheep.","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-40-002","lineIndex":2,"speaker":"L'Aviateur","original":"Mais qu'est-ce que tu fais là?","ipa":"/mɛ kɛskə ty fɛ la/","zh":"你在这儿干什么？","en":"But what are you doing here?","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-40-003","lineIndex":3,"speaker":"Le Petit Prince","original":"Dessine-moi un mouton. C'est pour ma fleur.","ipa":"/dɛsinmwa œ̃ mutɔ̃ sɛ puʁ ma flœʁ/","zh":"给我画一只绵羊吧。这是给我的花的。","en":"Draw me a sheep. It is for my flower.","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-40-004","lineIndex":4,"speaker":"Le Petit Prince","original":"Pour la protéger des baobabs.","ipa":"/puʁ la pʁoteʒe de baobab/","zh":"好保护她免受猴面包树的侵害。","en":"To protect her from the baobabs.","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-40-005","lineIndex":5,"speaker":"Le Petit Prince","original":"Mais il me faut aussi une muselière","ipa":"/mɛz il mə fot osi yn myzljɛʁ/","zh":"但我还需要一个嘴套","en":"But I also need a muzzle","note":"","sourceLineIndex":5},{"id":"le-petit-prince-2cd-40-006","lineIndex":6,"speaker":"Le Petit Prince","original":"pour protéger ma fleur du mouton.","ipa":"/puʁ pʁoteʒe ma flœʁ dy mutɔ̃/","zh":"防止绵羊吃了花儿","en":"to protect my flower from the sheep.","note":"","sourceLineIndex":6},{"id":"le-petit-prince-2cd-40-007","lineIndex":7,"speaker":"Le Petit Prince","original":"Tu penses, il mange aussi les épines.","ipa":"/ty pɑ̃s il mɑ̃ʒ osi lez epin/","zh":"你想想，它连刺也吃。","en":"Just think, it eats the thorns too.","note":"","sourceLineIndex":7},{"id":"le-petit-prince-2cd-40-008","lineIndex":8,"speaker":"Le Petit Prince","original":"Tu comprends, je suis responsable de ma rose.","ipa":"/ty kɔ̃pʁɑ̃ ʒə syi ʁɛspɔ̃sabl də ma ʁɔz/","zh":"你明白吗，我要对我的玫瑰负责。","en":"You understand, I am responsible for my rose.","note":"","sourceLineIndex":8},{"id":"le-petit-prince-2cd-40-009","lineIndex":9,"speaker":"L'Aviateur","original":"Huitième jour dans le désert.","ipa":"/yisjɛm ʒuʁ dɑ̃ lə dezɛʁ/","zh":"沙漠里的第八天","en":"Eighth day in the desert.","note":"","sourceLineIndex":9},{"id":"le-petit-prince-2cd-40-010","lineIndex":10,"speaker":"L'Aviateur","original":"Plus d'eau.","ipa":"/ply do/","zh":"没有水了。","en":"No more water.","note":"","sourceLineIndex":10},{"id":"le-petit-prince-2cd-40-011","lineIndex":11,"speaker":"L'Aviateur","original":"Aucune chance de trouver un puits dans cette immensité.","ipa":"/okyn ʃɑ̃s də tʁuve œ̃ pyi dɑ̃ sɛt imɑ̃site/","zh":"在这片无边无际之中，根本不可能找到一口井。","en":"No chance of finding a well in this vastness.","note":"","sourceLineIndex":11}],"sourceOrder":40,"displayOrder":38},{"order":41,"id":"41-la-quete","title":"La QuÊTe","titleZh":"追求","lines":[{"id":"le-petit-prince-2cd-41-001","lineIndex":1,"speaker":"L'Aviateur","original":"Tu penses à ta rose.","ipa":"/ty pɑ̃sz a ta ʁɔz/","zh":"你在想你的玫瑰吧","en":"You think about your rose.","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-41-002","lineIndex":2,"speaker":"L'Aviateur","original":"Elle rayonne en toi comme la flamme d'une lampe","ipa":"/ɛl ʁɛjɔn ɑ̃ twa kɔm la flam dyn lɑ̃p/","zh":"她在你心中发光，宛如一盏灯的火焰","en":"She shines within you like the flame of a lamp","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-41-003","lineIndex":3,"speaker":"L'Aviateur","original":"même quand tu dors.","ipa":"/mɛm kɑ̃ ty dɔʁ/","zh":"连你睡着的时候都一样","en":"even when you sleep.","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-41-004","lineIndex":4,"speaker":"Le Petit Prince","original":"Les étoiles sont belles à cause d'une fleur que l'on ne voit pas.","ipa":"/lez etwal sɔ̃ bɛlz a koz dyn flœʁ kə lɔ̃ nə vwa pa/","zh":"星星美丽，是因为里面有一朵看不见的花","en":"The stars are beautiful because of a flower that we cannot see.","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-41-005","lineIndex":5,"speaker":"Le Petit Prince","original":"J'aime le désert.","ipa":"/ʒɛm lə dezɛʁ/","zh":"我喜欢沙漠","en":"I love the desert.","note":"","sourceLineIndex":5},{"id":"le-petit-prince-2cd-41-006","lineIndex":6,"speaker":"L'Aviateur","original":"J'ai toujours aimé le désert.","ipa":"/ʒe tuʒuʁz ɛme lə dezɛʁ/","zh":"我素来喜爱沙漠","en":"I have always loved the desert.","note":"","sourceLineIndex":6},{"id":"le-petit-prince-2cd-41-007","lineIndex":7,"speaker":"L'Aviateur","original":"On ne voit rien, on n'entend rien","ipa":"/ɔ̃ nə vwa ʁjɛ̃ ɔ̃ nɑ̃tɑ̃ ʁjɛ̃/","zh":"我们无所见 无所闻","en":"We see nothing, we hear nothing","note":"","sourceLineIndex":7},{"id":"le-petit-prince-2cd-41-008","lineIndex":8,"speaker":"L'Aviateur","original":"et pourtant quelque chose rayonne dans le silence.","ipa":"/e puʁtɑ̃ kɛlkə ʃɔz ʁɛjɔn dɑ̃ lə silɑ̃s/","zh":"然而，有什么东西在寂静中发着光。","en":"and yet something shines in the silence.","note":"","sourceLineIndex":8},{"id":"le-petit-prince-2cd-41-009","lineIndex":9,"speaker":"Le Petit Prince","original":"Ce qui embellit le désert","ipa":"/sə ki ɑ̃bɛli lə dezɛʁ/","zh":"沙漠美丽","en":"What beautifies the desert","note":"","sourceLineIndex":9},{"id":"le-petit-prince-2cd-41-010","lineIndex":10,"speaker":"Le Petit Prince","original":"c'est qu'il cache un puits quelque part.","ipa":"/sɛ kil kaʃ œ̃ pyi kɛlkə paʁ/","zh":"是因为沙漠的某处隐藏着一口井","en":"is that it hides a well somewhere.","note":"","sourceLineIndex":10},{"id":"le-petit-prince-2cd-41-011","lineIndex":11,"speaker":"L'Aviateur","original":"Tu as donc soif, toi aussi?","ipa":"/ty a dɔ̃k swaf twa osi/","zh":"你也口渴了吗？","en":"So you're thirsty too?","note":"","sourceLineIndex":11},{"id":"le-petit-prince-2cd-41-012","lineIndex":12,"speaker":"Le Petit Prince","original":"L'eau peut être bonne pour le cœur.","ipa":"/lo pøt ɛtʁ bɔn puʁ lə kœʁ/","zh":"水对心也有好处","en":"Water can be good for the heart.","note":"","sourceLineIndex":12},{"id":"le-petit-prince-2cd-41-013","lineIndex":13,"speaker":"L'Aviateur","original":"Ce qui fait la beauté du désert ou des étoiles est invisible.","ipa":"/sə ki fɛ la bote dy dezɛʁ u dez etwalz ɛt ɛ̃vizibl/","zh":"无论沙漠还是星星，使它们美丽的东西都是看不见的。","en":"What makes the desert or the stars beautiful is invisible.","note":"","sourceLineIndex":13},{"id":"le-petit-prince-2cd-41-014","lineIndex":14,"speaker":"L'Aviateur","original":"Lorsque j'étais petit garçon","ipa":"/lɔʁskə ʒetɛ pəti ɡaʁsɔ̃/","zh":"在我小时候","en":"When I was a little boy","note":"","sourceLineIndex":14},{"id":"le-petit-prince-2cd-41-015","lineIndex":15,"speaker":"L'Aviateur","original":"j'habitais une maison ancienne et la légende racontait qu'un trésor y était enfoui.","ipa":"/ʒabitɛz yn mɛzɔ̃ ɑ̃sjɛn e la leʒɑ̃d ʁakɔ̃tɛ kœ̃ tʁezɔʁ i etɛt ɑ̃fwi/","zh":"我住在一幢古老的房子里，传说那里埋着一件宝藏。","en":"I lived in an old house, and legend had it that a treasure was buried there.","note":"","sourceLineIndex":15},{"id":"le-petit-prince-2cd-41-016","lineIndex":16,"speaker":"L'Aviateur","original":"Bien sûr, personne n'a jamais su le trouver, ni peut-être même ne l'a cherché.","ipa":"/bjɛ̃ syːʁ pɛʁsɔn na ʒamɛ sy lə tʁuve ni pøtɛtʁ mɛm nə la ʃɛʁʃe/","zh":"当然，从来没有人知道怎样找到它，也许甚至根本没有人寻找过它。","en":"Of course, no one ever knew how to find it, and perhaps no one even looked for it.","note":"","sourceLineIndex":16},{"id":"le-petit-prince-2cd-41-017","lineIndex":17,"speaker":"L'Aviateur","original":"Il était invisible.","ipa":"/il etɛt ɛ̃vizibl/","zh":"它是看不见的。","en":"It was invisible.","note":"","sourceLineIndex":17},{"id":"le-petit-prince-2cd-41-018","lineIndex":18,"speaker":"L'Aviateur","original":"Mais il enchantait toute la maison qui cachait un secret au fond de son cœur.","ipa":"/mɛz il ɑ̃ʃɑ̃tɛ tut la mɛzɔ̃ ki kaʃɛt œ̃ səkʁɛ o fɔ̃ də sɔ̃ kœʁ/","zh":"但它给整幢房子施了魔法；房子在内心深处藏着一个秘密。","en":"But it enchanted the whole house, which hid a secret deep in its heart.","note":"","sourceLineIndex":18},{"id":"le-petit-prince-2cd-41-019","lineIndex":19,"speaker":"L'Aviateur","original":"Ce que je vois là n'est qu'une écorce, le plus important est invisible.","ipa":"/sə kə ʒə vwa la nɛ kyn ekɔʁs lə plyz ɛ̃pɔʁtɑ̃ ɛt ɛ̃vizibl/","zh":"我眼前所见不过是一层外壳，最重要的东西是看不见的。","en":"What I see there is only a shell; what is most important is invisible.","note":"","sourceLineIndex":19}],"sourceOrder":41,"displayOrder":39},{"order":42,"id":"42-chercher-la-source","title":"Chercher La Source","titleZh":"寻觅水源","lines":[{"id":"le-petit-prince-2cd-42-001","lineIndex":1,"speaker":"Le Petit Prince","original":"Je suis content que tu sois d'accord avec mon renard.","ipa":"/ʒə syi kɔ̃tɑ̃ kə ty swa dakɔʁ avɛk mɔ̃ ʁənaʁ/","zh":"你同意狐狸的看法 我很欣慰","en":"I'm glad you agree with my fox.","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-42-002","lineIndex":2,"speaker":"Le Petit Prince","original":"C'est bien d'avoir un ami renard, même si l'on doit mourir de soif.","ipa":"/sɛ bjɛ̃ davwaʁ œ̃n ami ʁənaʁ mɛm si lɔ̃ dwa muʁiʁ də swaf/","zh":"有一位狐狸朋友真好，哪怕我们就要渴死。","en":"It is good to have a fox for a friend, even if one must die of thirst.","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-42-003","lineIndex":3,"speaker":"Le Petit Prince","original":"Alors cherchons le puits.","ipa":"/alɔʁ ʃɛʁʃɔ̃ lə pyi/","zh":"我们去找井吧","en":"Then let's look for the well.","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-42-004","lineIndex":4,"speaker":"L'Aviateur","original":"Au hasard, dans le désert?","ipa":"/o azaʁ dɑ̃ lə dezɛʁ/","zh":"就在这沙漠里瞎逛么？","en":"Randomly, in the desert?","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-42-005","lineIndex":5,"speaker":"L'Aviateur","original":"Que regardes-tu?","ipa":"/kə ʁəɡaʁdty/","zh":"你在看什么呢？","en":"What are you looking at?","note":"","sourceLineIndex":5},{"id":"le-petit-prince-2cd-42-006","lineIndex":6,"speaker":"Le Petit Prince","original":"Le reflet du puits dans les étoiles.","ipa":"/lə ʁəflɛ dy pyi dɑ̃ lez etwal/","zh":"井在众星辰上的倒影","en":"The reflection of the well in the stars.","note":"","sourceLineIndex":6},{"id":"le-petit-prince-2cd-42-007","lineIndex":7,"speaker":"L'Aviateur","original":"Tout doucement","ipa":"/tu dusmɑ̃/","zh":"轻轻地","en":"Gently","note":"","sourceLineIndex":7},{"id":"le-petit-prince-2cd-42-008","lineIndex":8,"speaker":"L'Aviateur","original":"L'emporter avec moi comme un trésor quand il s'endort","ipa":"/lɑ̃pɔʁte avɛk mwa kɔm œ̃ tʁezɔʁ kɑ̃t il sɑ̃dɔʁ/","zh":"在他睡着时，像带着珍宝一样把他带在身边","en":"carry him with me like a treasure when he falls asleep","note":"","sourceLineIndex":8},{"id":"le-petit-prince-2cd-42-009","lineIndex":9,"speaker":"L'Aviateur","original":"Sentir ce qui se cache derrière l'écorce derrière le corps","ipa":"/sɑ̃tiʁ sə ki sə kaʃ dɛʁjɛʁ lekɔʁs dɛʁjɛʁ lə kɔʁ/","zh":"感受藏在外壳之后、躯体之后的东西","en":"Sense what lies hidden behind the shell, behind the body","note":"","sourceLineIndex":9},{"id":"le-petit-prince-2cd-42-010","lineIndex":10,"speaker":"L'Aviateur","original":"Prendre la route marcher encore","ipa":"/pʁɑ̃dʁ la ʁut maʁʃe ɑ̃kɔʁ/","zh":"踏上旅途，继续前行","en":"Set out and keep walking","note":"","sourceLineIndex":10},{"id":"le-petit-prince-2cd-42-011","lineIndex":11,"speaker":"L'Aviateur","original":"Chercher la source","ipa":"/ʃɛʁʃe la suʁs/","zh":"寻觅水源","en":"Look for the source","note":"","sourceLineIndex":11},{"id":"le-petit-prince-2cd-42-012","lineIndex":12,"speaker":"L'Aviateur","original":"Trouver les puits","ipa":"/tʁuve le pyi/","zh":"找到水井","en":"Find the wells","note":"","sourceLineIndex":12},{"id":"le-petit-prince-2cd-42-013","lineIndex":13,"speaker":"L'Aviateur","original":"De l'eau de pluie","ipa":"/də lo də plyi/","zh":"天空之甘霖","en":"Rainwater","note":"","sourceLineIndex":13},{"id":"le-petit-prince-2cd-42-014","lineIndex":14,"speaker":"L'Aviateur","original":"Suivre une étoile","ipa":"/syivʁ yn etwal/","zh":"跟随一颗星","en":"Follow a star","note":"","sourceLineIndex":14},{"id":"le-petit-prince-2cd-42-015","lineIndex":15,"speaker":"L'Aviateur","original":"Retrouver sa voie des milliers de fois dans ces déserts","ipa":"/ʁətʁuve sa vwa de milje də fwa dɑ̃ se dezɛʁ/","zh":"在这些沙漠中千百次重新找到自己的方向","en":"Find one's way again thousands of times in these deserts","note":"","sourceLineIndex":15},{"id":"le-petit-prince-2cd-42-016","lineIndex":16,"speaker":"L'Aviateur","original":"Tenir la main qui connaît le chemin sur cette terre","ipa":"/təniʁ la mɛ̃ ki kɔnɛ lə ʃəmɛ̃ syʁ sɛt tɛʁ/","zh":"跟随了解此地之人的引领","en":"Hold the hand that knows the way on this earth","note":"","sourceLineIndex":16},{"id":"le-petit-prince-2cd-42-017","lineIndex":17,"speaker":"L'Aviateur","original":"Perdus éperdus on espère","ipa":"/pɛʁdy epɛʁdy ɔ̃n ɛspɛʁ/","zh":"迷失而慌乱，我们仍怀抱希望","en":"Lost and distraught, we still hope","note":"","sourceLineIndex":17},{"id":"le-petit-prince-2cd-42-018","lineIndex":18,"speaker":"L'Aviateur","original":"Chercher la source","ipa":"/ʃɛʁʃe la suʁs/","zh":"找寻水源","en":"Look for the source","note":"","sourceLineIndex":18},{"id":"le-petit-prince-2cd-42-019","lineIndex":19,"speaker":"L'Aviateur","original":"Trouver les puits","ipa":"/tʁuve le pyi/","zh":"找到水井","en":"Find the wells","note":"","sourceLineIndex":19},{"id":"le-petit-prince-2cd-42-020","lineIndex":20,"speaker":"L'Aviateur","original":"De l'eau de pluie","ipa":"/də lo də plyi/","zh":"天空之甘霖","en":"Rainwater","note":"","sourceLineIndex":20},{"id":"le-petit-prince-2cd-42-021","lineIndex":21,"speaker":"L'Aviateur","original":"En bout de course","ipa":"/ɑ̃ bu də kuʁs/","zh":"在旅程终点","en":"At the end of the journey","note":"","sourceLineIndex":21},{"id":"le-petit-prince-2cd-42-022","lineIndex":22,"speaker":"L'Aviateur","original":"Toucher le ciel","ipa":"/tuʃe lə sjɛl/","zh":"触及天空","en":"Touch the sky","note":"","sourceLineIndex":22},{"id":"le-petit-prince-2cd-42-023","lineIndex":23,"speaker":"L'Aviateur","original":"Voir l'essentiel","ipa":"/vwaʁ lesɑ̃sjɛl/","zh":"看见最重要的东西","en":"See what is essential","note":"","sourceLineIndex":23},{"id":"le-petit-prince-2cd-42-024","lineIndex":24,"speaker":"L'Aviateur","original":"Chercher la source","ipa":"/ʃɛʁʃe la suʁs/","zh":"找寻水源","en":"Look for the source","note":"","sourceLineIndex":24},{"id":"le-petit-prince-2cd-42-025","lineIndex":25,"speaker":"L'Aviateur","original":"Trouver les puits","ipa":"/tʁuve le pyi/","zh":"找到水井","en":"Find the wells","note":"","sourceLineIndex":25},{"id":"le-petit-prince-2cd-42-026","lineIndex":26,"speaker":"L'Aviateur","original":"De l'eau de pluie","ipa":"/də lo də plyi/","zh":"天空之甘霖","en":"Rainwater","note":"","sourceLineIndex":26},{"id":"le-petit-prince-2cd-42-027","lineIndex":27,"speaker":"L'Aviateur","original":"En bout de course","ipa":"/ɑ̃ bu də kuʁs/","zh":"在旅程终点","en":"At the end of the journey","note":"","sourceLineIndex":27},{"id":"le-petit-prince-2cd-42-028","lineIndex":28,"speaker":"L'Aviateur","original":"Toucher le ciel","ipa":"/tuʃe lə sjɛl/","zh":"触及天空","en":"Touch the sky","note":"","sourceLineIndex":28},{"id":"le-petit-prince-2cd-42-029","lineIndex":29,"speaker":"L'Aviateur","original":"Voir l'essentiel","ipa":"/vwaʁ lesɑ̃sjɛl/","zh":"看见最重要的东西","en":"See what is essential","note":"","sourceLineIndex":29},{"id":"le-petit-prince-2cd-42-030","lineIndex":30,"speaker":"L'Aviateur","original":"Et dans la Grande Ourse","ipa":"/e dɑ̃ la ɡʁɑ̃d uʁs/","zh":"在大熊座之中","en":"And in Ursa Major","note":"","sourceLineIndex":30},{"id":"le-petit-prince-2cd-42-031","lineIndex":31,"speaker":"L'Aviateur","original":"Ou l'infini","ipa":"/u lɛ̃fini/","zh":"或在无穷之中","en":"Or in infinity","note":"","sourceLineIndex":31},{"id":"le-petit-prince-2cd-42-032","lineIndex":32,"speaker":"L'Aviateur","original":"Chercher le sens d'une vie","ipa":"/ʃɛʁʃe lə sɑ̃s dyn vi/","zh":"探寻生命的意义","en":"Seek the meaning of a life","note":"","sourceLineIndex":32}],"sourceOrder":42,"displayOrder":40},{"order":43,"id":"43-le-puits","title":"Le Puits","titleZh":"井","lines":[{"id":"le-petit-prince-2cd-43-001","lineIndex":1,"speaker":"L'Aviateur","original":"C'est étrange.","ipa":"/sɛt etʁɑ̃ʒ/","zh":"这就奇了","en":"This is strange.","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-43-002","lineIndex":2,"speaker":"L'Aviateur","original":"Ce n'est pas un puits saharien.","ipa":"/sə nɛ paz œ̃ pyi saaʁjɛ̃/","zh":"这不是一口撒哈拉式的井。","en":"This is not a Saharan well.","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-43-003","lineIndex":3,"speaker":"L'Aviateur","original":"Tout est prêt, la poulie, la corde, le seau","ipa":"/tut ɛ pʁɛ la puli la kɔʁd lə so/","zh":"一切都齐备：辘轳、绳子、水桶","en":"Everything is ready: the pulley, the rope, the bucket","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-43-004","lineIndex":4,"speaker":"L'Aviateur","original":"comme un puits de village.","ipa":"/kɔm œ̃ pyi də vilaʒ/","zh":"跟村子里的井似的","en":"like a village well.","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-43-005","lineIndex":5,"speaker":"L'Aviateur","original":"Mais il n'y a aucun village.","ipa":"/mɛz il ni a okœ̃ vilaʒ/","zh":"可是这儿没有一个村子","en":"But there is no village.","note":"","sourceLineIndex":5},{"id":"le-petit-prince-2cd-43-006","lineIndex":6,"speaker":"Le Petit Prince","original":"Tu entends?","ipa":"/ty ɑ̃tɑ̃/","zh":"你听","en":"Do you hear?","note":"","sourceLineIndex":6},{"id":"le-petit-prince-2cd-43-007","lineIndex":7,"speaker":"Le Petit Prince","original":"Nous réveillons ce puits et il chante.","ipa":"/nu ʁevɛjɔ̃ sə pyiz e il ʃɑ̃t/","zh":"我们唤醒了这口井，它正在歌唱。","en":"We are waking this well, and it is singing.","note":"","sourceLineIndex":7},{"id":"le-petit-prince-2cd-43-008","lineIndex":8,"speaker":"Le Petit Prince","original":"J'ai soif de cette eau-là.","ipa":"/ʒe swaf də sɛt ola/","zh":"我渴望的就是这样的水","en":"I thirst for that water.","note":"","sourceLineIndex":8},{"id":"le-petit-prince-2cd-43-009","lineIndex":9,"speaker":"Le Petit Prince","original":"Donne-moi à boire.","ipa":"/dɔnmwa a bwaʁ/","zh":"让我喝上几口","en":"Give me a drink.","note":"","sourceLineIndex":9},{"id":"le-petit-prince-2cd-43-010","lineIndex":10,"speaker":"L'Aviateur","original":"C'est doux comme une fête.","ipa":"/sɛ du kɔm yn fɛt/","zh":"它甘甜得如同一场庆典。","en":"It is as sweet as a celebration.","note":"","sourceLineIndex":10},{"id":"le-petit-prince-2cd-43-011","lineIndex":11,"speaker":"Le Petit Prince","original":"C'est beaucoup plus que de l'eau.","ipa":"/sɛ boku ply kə də lo/","zh":"这远不止是水。","en":"It's much more than water.","note":"","sourceLineIndex":11},{"id":"le-petit-prince-2cd-43-012","lineIndex":12,"speaker":"L'Aviateur","original":"Elle est née de la marche sous les étoiles","ipa":"/ɛl ɛ ne də la maʁʃ su lez etwal/","zh":"它诞生于星光下的跋涉","en":"It was born of the walk beneath the stars","note":"","sourceLineIndex":12},{"id":"le-petit-prince-2cd-43-013","lineIndex":13,"speaker":"L'Aviateur","original":"du chant de la poulie, de l'effort de mes bras...","ipa":"/dy ʃɑ̃ də la puli də lefɔʁ də me bʁa/","zh":"诞生于辘轳的歌声和我双臂的努力……","en":"the song of the pulley, and the effort of my arms...","note":"","sourceLineIndex":13},{"id":"le-petit-prince-2cd-43-014","lineIndex":14,"speaker":"Le Petit Prince","original":"Elle est bonne pour le cœur, comme un cadeau.","ipa":"/ɛl ɛ bɔn puʁ lə kœʁ kɔm œ̃ kado/","zh":"它像礼物一样愉悦心灵","en":"It is good for the heart, like a gift.","note":"","sourceLineIndex":14},{"id":"le-petit-prince-2cd-43-015","lineIndex":15,"speaker":"L'Aviateur","original":"Lorsque j'étais petit garçon","ipa":"/lɔʁskə ʒetɛ pəti ɡaʁsɔ̃/","zh":"在我小时候","en":"When I was a little boy","note":"","sourceLineIndex":15},{"id":"le-petit-prince-2cd-43-016","lineIndex":16,"speaker":"L'Aviateur","original":"les lumières de l'arbre de Noël","ipa":"/le lymjɛʁ də laʁbʁ də nɔɛl/","zh":"圣诞树上挂的灯","en":"the lights of the Christmas tree","note":"","sourceLineIndex":16},{"id":"le-petit-prince-2cd-43-017","lineIndex":17,"speaker":"L'Aviateur","original":"la musique de la messe de minuit","ipa":"/la myzik də la mɛs də minyi/","zh":"子夜弥撒的音乐","en":"the music of midnight mass","note":"","sourceLineIndex":17},{"id":"le-petit-prince-2cd-43-018","lineIndex":18,"speaker":"L'Aviateur","original":"la douceur des sourires","ipa":"/la dusœʁ de suʁiʁ/","zh":"甜蜜的微笑","en":"the sweetness of the smiles","note":"","sourceLineIndex":18},{"id":"le-petit-prince-2cd-43-019","lineIndex":19,"speaker":"L'Aviateur","original":"faisaient tout le rayonnement du cadeau de Noël que je recevais.","ipa":"/fəzɛ tu lə ʁɛjɔnmɑ̃ dy kado də nɔɛl kə ʒə ʁəsəvɛ/","zh":"共同赋予我收到的圣诞礼物全部的光彩。","en":"were what gave the Christmas present I received all its radiance.","note":"","sourceLineIndex":19},{"id":"le-petit-prince-2cd-43-020","lineIndex":20,"speaker":"Le Petit Prince","original":"Les hommes de chez toi cultivent cinq mille roses dans un même jardin","ipa":"/lez ɔm də ʃe twa kyltiv sɛ̃ mil ʁoz dɑ̃z œ̃ mɛm ʒaʁdɛ̃/","zh":"你们那里的人在同一座花园里种了五千株玫瑰","en":"The people where you come from grow five thousand roses in a single garden","note":"","sourceLineIndex":20},{"id":"le-petit-prince-2cd-43-021","lineIndex":21,"speaker":"Le Petit Prince","original":"et ils n'y trouvent pas ce qu'ils cherchent.","ipa":"/e il ni tʁuv pa sə kil ʃɛʁʃ/","zh":"却没有从中找到他们所寻找的东西。","en":"and they do not find there what they are looking for.","note":"","sourceLineIndex":21},{"id":"le-petit-prince-2cd-43-022","lineIndex":22,"speaker":"L'Aviateur","original":"Ils ne le trouvent pas.","ipa":"/il nə lə tʁuv pa/","zh":"他们找不到。","en":"They do not find it.","note":"","sourceLineIndex":22},{"id":"le-petit-prince-2cd-43-023","lineIndex":23,"speaker":"Le Petit Prince","original":"Et cependant ce qu'ils cherchent pourrait être trouvé dans une seule rose ou un peu d'eau.","ipa":"/e səpɑ̃dɑ̃ sə kil ʃɛʁʃ puʁɛt ɛtʁ tʁuve dɑ̃z yn sœl ʁɔz u œ̃ pø do/","zh":"然而他们要找的 明明可以在一朵玫瑰或一点点水里找到","en":"And yet what they seek could be found in a single rose or a little water.","note":"","sourceLineIndex":23},{"id":"le-petit-prince-2cd-43-024","lineIndex":24,"speaker":"Le Petit Prince","original":"Mais les yeux sont aveugles.","ipa":"/mɛ lez jø sɔ̃t avøɡl/","zh":"然而肉眼是盲目的","en":"But the eyes are blind.","note":"","sourceLineIndex":24},{"id":"le-petit-prince-2cd-43-025","lineIndex":25,"speaker":"L'Aviateur","original":"Il faut chercher avec le cœur.","ipa":"/il fo ʃɛʁʃe avɛk lə kœʁ/","zh":"必须用心去寻找。","en":"One must search with the heart.","note":"","sourceLineIndex":25}],"sourceOrder":43,"displayOrder":41},{"order":44,"id":"44-le-mur","title":"Le Mur","titleZh":"墙上","lines":[{"id":"le-petit-prince-2cd-44-001","lineIndex":1,"speaker":"Le Petit Prince","original":"Tu ne t'en souviens donc pas?","ipa":"/ty nə tɑ̃ suvjɛ̃ dɔ̃k pa/","zh":"你不记得了吗？","en":"So you don't remember?","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-44-002","lineIndex":2,"speaker":"Le Petit Prince","original":"Si, si, c'est bien le jour, mais ce n'est pas tout à fait ici.","ipa":"/si si sɛ bjɛ̃ lə ʒuʁ mɛ sə nɛ pa tut a fɛt isi/","zh":"对，对，就是这一天，但不完全是在这里。","en":"Yes, yes, this is the right day, but not quite here.","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-44-003","lineIndex":3,"speaker":"Le Petit Prince","original":"Tu n'as qu'à m'attendre, j'y serai cette nuit.","ipa":"/ty na ka matɑ̃dʁ ʒi səʁe sɛt nyi/","zh":"你只管等我，今夜我会在那里。","en":"You need only wait for me; I will be there tonight.","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-44-004","lineIndex":4,"speaker":"Le Petit Prince","original":"Tu as du bon venin?","ipa":"/ty a dy bɔ̃ vənɛ̃/","zh":"你的毒液有效吗？","en":"Is your venom potent?","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-44-005","lineIndex":5,"speaker":"Le Petit Prince","original":"Tu es sûr de ne pas me faire souffrir trop longtemps?","ipa":"/ty ɛ syːʁ də nə pa mə fɛʁ sufʁiʁ tʁo lɔ̃tɑ̃/","zh":"你能肯定不让我经受很久的痛苦？","en":"Are you sure you won't make me suffer for too long?","note":"","sourceLineIndex":5},{"id":"le-petit-prince-2cd-44-006","lineIndex":6,"speaker":"L'Aviateur","original":"Quelle est cette histoire-là?","ipa":"/kɛl ɛ sɛt istwaʁla/","zh":"怎么回事？","en":"What is this story?","note":"","sourceLineIndex":6},{"id":"le-petit-prince-2cd-44-007","lineIndex":7,"speaker":"L'Aviateur","original":"Tu parles aux serpents maintenant?","ipa":"/ty paʁlz o sɛʁpɑ̃ mɛ̃tnɑ̃/","zh":"你和蛇说话了？","en":"Are you talking to snakes now?","note":"","sourceLineIndex":7},{"id":"le-petit-prince-2cd-44-008","lineIndex":8,"speaker":"Le Petit Prince","original":"Dessine-moi une muselière pour mon mouton.","ipa":"/dɛsinmwa yn myzljɛʁ puʁ mɔ̃ mutɔ̃/","zh":"给我的绵羊画一个嘴套吧。","en":"Draw me a muzzle for my sheep.","note":"","sourceLineIndex":8},{"id":"le-petit-prince-2cd-44-009","lineIndex":9,"speaker":"Le Petit Prince","original":"N'oublie pas, je suis responsable de ma fleur...","ipa":"/nubli pa ʒə syi ʁɛspɔ̃sabl də ma flœʁ/","zh":"别忘了 我要对我的花儿负责呀","en":"Don't forget, I am responsible for my flower...","note":"","sourceLineIndex":9},{"id":"le-petit-prince-2cd-44-010","lineIndex":10,"speaker":"L'Aviateur","original":"Je ne savais rien dessiner que des boas fermés et des boas ouverts.","ipa":"/ʒə nə savɛ ʁjɛ̃ dɛsine kə de boa fɛʁmez e de boaz uvɛʁ/","zh":"我并不会画画 只会画没打开肚子的蟒蛇和打开了肚子的蟒蛇","en":"I didn't know how to draw anything except closed boas and open boas.","note":"","sourceLineIndex":10},{"id":"le-petit-prince-2cd-44-011","lineIndex":11,"speaker":"Le Petit Prince","original":"Oh ça ira! Les enfants savent...","ipa":"/ɔ sa iʁa lez ɑ̃fɑ̃ sav/","zh":"哦，这样就行！孩子们看得懂……","en":"Oh, that will do! Children understand...","note":"","sourceLineIndex":11},{"id":"le-petit-prince-2cd-44-012","lineIndex":12,"speaker":"L'Aviateur","original":"Petit bonhomme, tu as des projets que j'ignore?","ipa":"/pəti bɔnɔm ty a de pʁoʒɛ kə ʒinjɔʁ/","zh":"小人儿 你已有了我不知道的计划吧","en":"Little man, do you have plans that I don't know about?","note":"","sourceLineIndex":12},{"id":"le-petit-prince-2cd-44-013","lineIndex":13,"speaker":"Le Petit Prince","original":"Tu sais, ma chute sur la Terre","ipa":"/ty sɛ ma ʃyt syʁ la tɛʁ/","zh":"你知道 我落到地球上","en":"You know, my fall to Earth","note":"","sourceLineIndex":13},{"id":"le-petit-prince-2cd-44-014","lineIndex":14,"speaker":"Le Petit Prince","original":"c'en sera demain l'anniversaire.","ipa":"/sɑ̃ səʁa dəmɛ̃ lanivɛʁsɛʁ/","zh":"明天已是一周年了","en":"tomorrow will be the anniversary.","note":"","sourceLineIndex":14},{"id":"le-petit-prince-2cd-44-015","lineIndex":15,"speaker":"Le Petit Prince","original":"J'étais tombé tout près d'ici.","ipa":"/ʒetɛ tɔ̃be tu pʁɛ disi/","zh":"当时我就落在附近","en":"I fell very close to here.","note":"","sourceLineIndex":15},{"id":"le-petit-prince-2cd-44-016","lineIndex":16,"speaker":"L'Aviateur","original":"Alors ce n'est pas par hasard que ce matin je t'ai rencontré, il y a huit jours.","ipa":"/alɔʁ sə nɛ pa paʁ azaʁ kə sə matɛ̃ ʒə te ʁɑ̃kɔ̃tʁe il i a yi ʒuʁ/","zh":"这么说 一星期之前 认识你的那天早上","en":"So it's not by chance that this morning I met you, eight days ago.","note":"","sourceLineIndex":16},{"id":"le-petit-prince-2cd-44-017","lineIndex":17,"speaker":"L'Aviateur","original":"Tu marchais seul, à mille milles de toute région habitée.","ipa":"/ty maʁʃɛ sœl a mil mil də tut ʁeʒjɔ̃ abite/","zh":"你不是偶然只身来到这远离人烟的沙漠的","en":"You walked alone, a thousand miles from any inhabited region.","note":"","sourceLineIndex":17},{"id":"le-petit-prince-2cd-44-018","lineIndex":18,"speaker":"L'Aviateur","original":"Tu retournais vers le point de chute.","ipa":"/ty ʁətuʁnɛ vɛʁ lə pwɛ̃ də ʃyt/","zh":"你当时正返回坠落的地点。","en":"You were heading back toward the place where you fell.","note":"","sourceLineIndex":18},{"id":"le-petit-prince-2cd-44-019","lineIndex":19,"speaker":"L'Aviateur","original":"À cause peut-être de l'anniversaire?","ipa":"/a koz pøtɛtʁ də lanivɛʁsɛʁ/","zh":"也许是因为这个周年？","en":"Perhaps because of the anniversary?","note":"","sourceLineIndex":19},{"id":"le-petit-prince-2cd-44-020","lineIndex":20,"speaker":"Le Petit Prince","original":"Cette nuit, ça fera un an.","ipa":"/sɛt nyi sa fəʁa œ̃n ɑ̃/","zh":"到今夜就整整一年了。","en":"Tonight it will be exactly one year.","note":"","sourceLineIndex":20},{"id":"le-petit-prince-2cd-44-021","lineIndex":21,"speaker":"Le Petit Prince","original":"Mon étoile se trouvera juste au-dessus de l'endroit","ipa":"/mɔ̃n etwal sə tʁuvʁa ʒyst odəsy də lɑ̃dʁwa/","zh":"我的星星正好在","en":"My star will be right above the place","note":"","sourceLineIndex":21},{"id":"le-petit-prince-2cd-44-022","lineIndex":22,"speaker":"Le Petit Prince","original":"où je suis tombé l'année dernière.","ipa":"/u ʒə syi tɔ̃be lane dɛʁnjɛʁ/","zh":"我去年降落处的正上方","en":"where I fell last year.","note":"","sourceLineIndex":22},{"id":"le-petit-prince-2cd-44-023","lineIndex":23,"speaker":"Le Petit Prince","original":"Le serpent m'a promis de... m'aider.","ipa":"/lə sɛʁpɑ̃ ma pʁomi də mɛde/","zh":"蛇答应过要……帮助我。","en":"The snake promised to... help me.","note":"","sourceLineIndex":23},{"id":"le-petit-prince-2cd-44-024","lineIndex":24,"speaker":"Le Petit Prince","original":"Tu sais, on aura toujours rendez-vous.","ipa":"/ty sɛ ɔ̃n oʁa tuʒuʁ ʁɑ̃devu/","zh":"你知道，我们永远都会有约。","en":"You know, we shall always have our rendezvous.","note":"","sourceLineIndex":24},{"id":"le-petit-prince-2cd-44-025","lineIndex":25,"speaker":"Le Petit Prince","original":"C'est comme pour la fleur.","ipa":"/sɛ kɔm puʁ la flœʁ/","zh":"花儿也是这样","en":"It's like the flower.","note":"","sourceLineIndex":25},{"id":"le-petit-prince-2cd-44-026","lineIndex":26,"speaker":"Le Petit Prince","original":"Si tu aimes une fleur qui se trouve dans une étoile","ipa":"/si ty ɛmz yn flœʁ ki sə tʁuv dɑ̃z yn etwal/","zh":"如果你爱上了一朵长在一颗星星里的花儿","en":"If you love a flower that is in a star","note":"","sourceLineIndex":26},{"id":"le-petit-prince-2cd-44-027","lineIndex":27,"speaker":"Le Petit Prince","original":"c'est doux la nuit de regarder le ciel.","ipa":"/sɛ du la nyi də ʁəɡaʁde lə sjɛl/","zh":"夜里看看星空就会觉得甜蜜","en":"it's sweet at night to look at the sky.","note":"","sourceLineIndex":27},{"id":"le-petit-prince-2cd-44-028","lineIndex":28,"speaker":"Le Petit Prince","original":"Toutes les étoiles sont fleuries.","ipa":"/tut lez etwal sɔ̃ fløʁi/","zh":"所有的星星都像开了花","en":"All the stars are in bloom.","note":"","sourceLineIndex":28},{"id":"le-petit-prince-2cd-44-029","lineIndex":29,"speaker":"L'Aviateur","original":"Bien sûr.","ipa":"/bjɛ̃ syːʁ/","zh":"不错...","en":"Of course.","note":"","sourceLineIndex":29},{"id":"le-petit-prince-2cd-44-030","lineIndex":30,"speaker":"Le Petit Prince","original":"C'est comme pour l'eau.","ipa":"/sɛ kɔm puʁ lo/","zh":"水也是这样","en":"It's like water.","note":"","sourceLineIndex":30},{"id":"le-petit-prince-2cd-44-031","lineIndex":31,"speaker":"Le Petit Prince","original":"Celle que tu m'as donnée à boire est comme une musique","ipa":"/sɛl kə ty ma dɔne a bwaʁ ɛ kɔm yn myzik/","zh":"你给我喝的那水宛如音乐","en":"The water you gave me to drink is like music","note":"","sourceLineIndex":31},{"id":"le-petit-prince-2cd-44-032","lineIndex":32,"speaker":"Le Petit Prince","original":"à cause du chant de la poulie et de la corde.","ipa":"/a koz dy ʃɑ̃ də la puli e də la kɔʁd/","zh":"因为有辘轳与绳索的歌声。","en":"because of the song of the pulley and the rope.","note":"","sourceLineIndex":32},{"id":"le-petit-prince-2cd-44-033","lineIndex":33,"speaker":"Le Petit Prince","original":"Tu te rappelles? Elle était bonne.","ipa":"/ty tə ʁapɛl ɛl etɛ bɔn/","zh":"你记得吗？它很甘甜。","en":"Do you remember? It was sweet.","note":"","sourceLineIndex":33},{"id":"le-petit-prince-2cd-44-034","lineIndex":34,"speaker":"L'Aviateur","original":"Bien sûr.","ipa":"/bjɛ̃ syːʁ/","zh":"没错...","en":"Of course.","note":"","sourceLineIndex":34},{"id":"le-petit-prince-2cd-44-035","lineIndex":35,"speaker":"Le Petit Prince","original":"Tu regarderas la nuit les étoiles.","ipa":"/ty ʁəɡaʁdəʁa la nyi lez etwal/","zh":"夜里你仰望星空吧","en":"You will look at the stars at night.","note":"","sourceLineIndex":35},{"id":"le-petit-prince-2cd-44-036","lineIndex":36,"speaker":"Le Petit Prince","original":"C'est trop petit chez moi","ipa":"/sɛ tʁo pəti ʃe mwa/","zh":"我的那颗星太渺小","en":"My place is too small","note":"","sourceLineIndex":36},{"id":"le-petit-prince-2cd-44-037","lineIndex":37,"speaker":"Le Petit Prince","original":"pour que je te montre où se trouve la mienne.","ipa":"/puʁ kə ʒə tə mɔ̃tʁ u sə tʁuv la mjɛn/","zh":"没法子告诉你它在哪儿","en":"for me to show you where mine is.","note":"","sourceLineIndex":37},{"id":"le-petit-prince-2cd-44-038","lineIndex":38,"speaker":"Le Petit Prince","original":"Mon étoile, ce sera pour toi une des étoiles.","ipa":"/mɔ̃n etwal sə səʁa puʁ twa yn dez etwal/","zh":"你就把我的星看做万千星星中的一颗吧","en":"My star, it will be one of the stars for you.","note":"","sourceLineIndex":38},{"id":"le-petit-prince-2cd-44-039","lineIndex":39,"speaker":"Le Petit Prince","original":"Et puisque je rirai dans l'une d'elles","ipa":"/e pyiskə ʒə ʁiʁe dɑ̃ lyn dɛl/","zh":"既然我会在其中一颗星星里笑","en":"And since I will laugh in one of them","note":"","sourceLineIndex":39},{"id":"le-petit-prince-2cd-44-040","lineIndex":40,"speaker":"Le Petit Prince","original":"alors ce sera pour toi comme si riaient toutes les étoiles.","ipa":"/alɔʁ sə səʁa puʁ twa kɔm si ʁjɛ tut lez etwal/","zh":"这就如同所有的星星都在冲你笑","en":"then it will be for you as if all the stars were laughing.","note":"","sourceLineIndex":40},{"id":"le-petit-prince-2cd-44-041","lineIndex":41,"speaker":"Le Petit Prince","original":"Ce sera comme si je t'avais donné au lieu d'étoiles des tas de petits grelots qui savent rire.","ipa":"/sə səʁa kɔm si ʒə tavɛ dɔne o ljø detwal de ta də pəti ɡʁəlo ki sav ʁiʁ/","zh":"就仿佛我送给你的不是星星，而是一大堆会笑的小铃铛。","en":"It will be as if, instead of stars, I had given you heaps of little bells that know how to laugh.","note":"","sourceLineIndex":41}],"sourceOrder":44,"displayOrder":42},{"order":45,"id":"45-on-aura-toujours-rendez-vous","title":"On Aura Toujours Rendez-Vous","titleZh":"我们终将重逢","lines":[{"id":"le-petit-prince-2cd-45-001","lineIndex":1,"speaker":"L'Aviateur","original":"Mon Petit Prince qui viens du ciel","ipa":"/mɔ̃ pəti pʁɛ̃s ki vjɛ̃ dy sjɛl/","zh":"我那来自天空、","en":"My Little Prince who comes from the sky","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-45-002","lineIndex":2,"speaker":"L'Aviateur","original":"Des étoiles et des hirondelles","ipa":"/dez etwalz e dez iʁɔ̃dɛl/","zh":"来自星辰与燕群的小王子","en":"of stars and swallows","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-45-003","lineIndex":3,"speaker":"L'Aviateur","original":"Tu as su redonner des ailes","ipa":"/ty a sy ʁədɔne dez ɛl/","zh":"你让翅膀重新生长","en":"You knew how to give wings again","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-45-004","lineIndex":4,"speaker":"L'Aviateur","original":"À mes illusions de mortel","ipa":"/a mez ilyzjɔ̃ də mɔʁtɛl/","zh":"在我凡人的幻想之上","en":"to my mortal illusions","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-45-005","lineIndex":5,"speaker":"Le Petit Prince","original":"Moi, je suis tombé de nulle part","ipa":"/mwa ʒə syi tɔ̃be də nyl paʁ/","zh":"我仿佛从无处坠落而来","en":"I fell from nowhere","note":"","sourceLineIndex":5},{"id":"le-petit-prince-2cd-45-006","lineIndex":6,"speaker":"Le Petit Prince","original":"Ou d'une planète inconnue","ipa":"/u dyn planɛt ɛ̃kɔny/","zh":"或来自一颗陌生的星球","en":"or from an unknown planet","note":"","sourceLineIndex":6},{"id":"le-petit-prince-2cd-45-007","lineIndex":7,"speaker":"Le Petit Prince","original":"Je repartirai par hasard","ipa":"/ʒə ʁəpaʁtiʁe paʁ azaʁ/","zh":"我又将偶然离去","en":"I will leave again by chance","note":"","sourceLineIndex":7},{"id":"le-petit-prince-2cd-45-008","lineIndex":8,"speaker":"Le Petit Prince","original":"Mais je ne t'oublierai jamais plus","ipa":"/mɛ ʒə nə tubliʁe ʒamɛ ply/","zh":"但从今以后我永远不会忘记你","en":"But from now on I will never forget you","note":"","sourceLineIndex":8},{"id":"le-petit-prince-2cd-45-009","lineIndex":9,"speaker":"Ensemble","original":"On aura toujours rendez-vous","ipa":"/ɔ̃n oʁa tuʒuʁ ʁɑ̃devu/","zh":"我们永远都会有约","en":"We will always have our rendezvous","note":"","sourceLineIndex":9},{"id":"le-petit-prince-2cd-45-010","lineIndex":10,"speaker":"Ensemble","original":"Dans ces étendues de cailloux","ipa":"/dɑ̃ sez etɑ̃dy də kaju/","zh":"就在这广袤沙漠","en":"In these expanses of stones","note":"","sourceLineIndex":10},{"id":"le-petit-prince-2cd-45-011","lineIndex":11,"speaker":"Ensemble","original":"Où l'essentiel est invisible","ipa":"/u lesɑ̃sjɛl ɛt ɛ̃vizibl/","zh":"事物的本质不可见","en":"Where the essential is invisible","note":"","sourceLineIndex":11},{"id":"le-petit-prince-2cd-45-012","lineIndex":12,"speaker":"Ensemble","original":"Pour les yeux des âmes insensibles","ipa":"/puʁ lez jø dez aːmz ɛ̃sɑ̃sibl/","zh":"于麻木灵魂的双眼","en":"For the eyes of insensitive souls","note":"","sourceLineIndex":12},{"id":"le-petit-prince-2cd-45-013","lineIndex":13,"speaker":"Le Petit Prince","original":"Et même si je sors du décor","ipa":"/e mɛm si ʒə sɔʁ dy dekɔʁ/","zh":"即使我即将消失","en":"And even if I step out of the scene","note":"","sourceLineIndex":13},{"id":"le-petit-prince-2cd-45-014","lineIndex":14,"speaker":"Le Petit Prince","original":"Et même si j'ai l'air d'être mort","ipa":"/e mɛm si ʒe lɛʁ dɛtʁ mɔʁ/","zh":"即使我似要死亡","en":"And even if I seem to be dead","note":"","sourceLineIndex":14},{"id":"le-petit-prince-2cd-45-015","lineIndex":15,"speaker":"Le Petit Prince","original":"Tu sais ce ne sera pas vrai","ipa":"/ty sɛ sə nə səʁa pa vʁɛ/","zh":"你晓得这不是真的","en":"You know it won't be true","note":"","sourceLineIndex":15},{"id":"le-petit-prince-2cd-45-016","lineIndex":16,"speaker":"Le Petit Prince","original":"Puisqu'on a tous l'éternité","ipa":"/pyiskɔ̃n a tus letɛʁnite/","zh":"因为你我拥有永恒","en":"Since we all have eternity","note":"","sourceLineIndex":16},{"id":"le-petit-prince-2cd-45-017","lineIndex":17,"speaker":"L'Aviateur","original":"On a tous une rose dans le cœur","ipa":"/ɔ̃n a tus yn ʁɔz dɑ̃ lə kœʁ/","zh":"我们心中都有一株玫瑰","en":"We all have a rose in our hearts","note":"","sourceLineIndex":17},{"id":"le-petit-prince-2cd-45-018","lineIndex":18,"speaker":"L'Aviateur","original":"Ses volcans qui nous faisaient peur","ipa":"/se vɔlkɑ̃ ki nu fəzɛ pœʁ/","zh":"那儿的火山令我们害怕","en":"Its volcanoes that scared us","note":"","sourceLineIndex":18},{"id":"le-petit-prince-2cd-45-019","lineIndex":19,"speaker":"L'Aviateur","original":"Des tas de couchers de soleil","ipa":"/de ta də kuʃe də solɛj/","zh":"那儿有好多好多日落","en":"Lots of sunsets","note":"","sourceLineIndex":19},{"id":"le-petit-prince-2cd-45-020","lineIndex":20,"speaker":"L'Aviateur","original":"Nos vieux démons et nos merveilles","ipa":"/no vjø demɔ̃z e no mɛʁvɛj/","zh":"还有我们旧日的心魔与奇迹","en":"Our old demons and our wonders","note":"","sourceLineIndex":20},{"id":"le-petit-prince-2cd-45-021","lineIndex":21,"speaker":"Ensemble","original":"On aura toujours rendez-vous","ipa":"/ɔ̃n oʁa tuʒuʁ ʁɑ̃devu/","zh":"我们永远都会有约","en":"We will always have our rendezvous","note":"","sourceLineIndex":21},{"id":"le-petit-prince-2cd-45-022","lineIndex":22,"speaker":"Ensemble","original":"Dans ces étendues de cailloux","ipa":"/dɑ̃ sez etɑ̃dy də kaju/","zh":"就在这广袤沙漠","en":"In these expanses of stones","note":"","sourceLineIndex":22},{"id":"le-petit-prince-2cd-45-023","lineIndex":23,"speaker":"Ensemble","original":"Où l'essentiel est invisible","ipa":"/u lesɑ̃sjɛl ɛt ɛ̃vizibl/","zh":"事物的本质不可见","en":"Where the essential is invisible","note":"","sourceLineIndex":23},{"id":"le-petit-prince-2cd-45-024","lineIndex":24,"speaker":"Ensemble","original":"Pour les yeux des âmes insensibles","ipa":"/puʁ lez jø dez aːmz ɛ̃sɑ̃sibl/","zh":"于麻木灵魂的双眼","en":"For the eyes of insensitive souls","note":"","sourceLineIndex":24},{"id":"le-petit-prince-2cd-45-025","lineIndex":25,"speaker":"L'Aviateur","original":"Mais nous qui comprenons la vie","ipa":"/mɛ nu ki kɔ̃pʁənɔ̃ la vi/","zh":"然而我们理解生活","en":"But we who understand life","note":"","sourceLineIndex":25},{"id":"le-petit-prince-2cd-45-026","lineIndex":26,"speaker":"L'Aviateur","original":"Nous nous moquons bien de compter","ipa":"/nu nu mokɔ̃ bjɛ̃ də kɔ̃te/","zh":"我们根本不在乎计数","en":"We do not care about counting","note":"","sourceLineIndex":26},{"id":"le-petit-prince-2cd-45-027","lineIndex":27,"speaker":"Le Petit Prince","original":"Nous on voulait juste un ami","ipa":"/nuz ɔ̃ vulɛ ʒyst œ̃n ami/","zh":"我们只求一个朋友","en":"We just wanted a friend","note":"","sourceLineIndex":27},{"id":"le-petit-prince-2cd-45-028","lineIndex":28,"speaker":"Le Petit Prince","original":"Même s'il faut un jour le laisser","ipa":"/mɛm sil fot œ̃ ʒuʁ lə lɛse/","zh":"哪怕有一天必须离开他","en":"Even if one must leave him one day","note":"","sourceLineIndex":28},{"id":"le-petit-prince-2cd-45-029","lineIndex":29,"speaker":"Ensemble","original":"On aura toujours rendez-vous","ipa":"/ɔ̃n oʁa tuʒuʁ ʁɑ̃devu/","zh":"我们永远都会有约","en":"We will always have our rendezvous","note":"","sourceLineIndex":29},{"id":"le-petit-prince-2cd-45-030","lineIndex":30,"speaker":"Ensemble","original":"Dans ces étendues de cailloux","ipa":"/dɑ̃ sez etɑ̃dy də kaju/","zh":"就在这广袤沙漠","en":"In these expanses of stones","note":"","sourceLineIndex":30},{"id":"le-petit-prince-2cd-45-031","lineIndex":31,"speaker":"Ensemble","original":"Où l'essentiel est invisible","ipa":"/u lesɑ̃sjɛl ɛt ɛ̃vizibl/","zh":"事物的本质不可见","en":"Where the essential is invisible","note":"","sourceLineIndex":31},{"id":"le-petit-prince-2cd-45-032","lineIndex":32,"speaker":"Ensemble","original":"Pour les yeux des âmes insensibles","ipa":"/puʁ lez jø dez aːmz ɛ̃sɑ̃sibl/","zh":"于麻木灵魂的双眼","en":"For the eyes of insensitive souls","note":"","sourceLineIndex":32},{"id":"le-petit-prince-2cd-45-033","lineIndex":33,"speaker":"L'Aviateur","original":"Je suis tombé de nulle part","ipa":"/ʒə syi tɔ̃be də nyl paʁ/","zh":"我仿佛从无处坠落而来","en":"I fell from nowhere","note":"","sourceLineIndex":33},{"id":"le-petit-prince-2cd-45-034","lineIndex":34,"speaker":"L'Aviateur","original":"Ou d'une planète inconnue","ipa":"/u dyn planɛt ɛ̃kɔny/","zh":"或来自一颗陌生的星球","en":"or from an unknown planet","note":"","sourceLineIndex":34},{"id":"le-petit-prince-2cd-45-035","lineIndex":35,"speaker":"Le Petit Prince","original":"Je repartirai par hasard","ipa":"/ʒə ʁəpaʁtiʁe paʁ azaʁ/","zh":"我又将偶然离去","en":"I will leave again by chance","note":"","sourceLineIndex":35},{"id":"le-petit-prince-2cd-45-036","lineIndex":36,"speaker":"Ensemble","original":"Mais je ne t'oublierai jamais plus","ipa":"/mɛ ʒə nə tubliʁe ʒamɛ ply/","zh":"但从今以后我永远不会忘记你","en":"But from now on I will never forget you","note":"","sourceLineIndex":36}],"sourceOrder":45,"displayOrder":43},{"order":46,"id":"46-le-depart","title":"Le DÉPart","titleZh":"离别","lines":[{"id":"le-petit-prince-2cd-46-001","lineIndex":1,"speaker":"Le Petit Prince","original":"Ne viens pas","ipa":"/nə vjɛ̃ pa/","zh":"你不要来了","en":"Don't come","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-46-002","lineIndex":2,"speaker":"Le Petit Prince","original":"J'aurai l'air d'avoir mal","ipa":"/ʒoʁe lɛʁ davwaʁ mal/","zh":"我会显得很痛苦","en":"I will look as though I am in pain","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-46-003","lineIndex":3,"speaker":"Le Petit Prince","original":"Tu auras de la peine","ipa":"/ty oʁa də la pɛn/","zh":"你会难过的","en":"You will be sad","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-46-004","lineIndex":4,"speaker":"Le Petit Prince","original":"J'aurai l'air d'être mort","ipa":"/ʒoʁe lɛʁ dɛtʁ mɔʁ/","zh":"我会像个死人","en":"I'll look like I'm dead","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-46-005","lineIndex":5,"speaker":"Le Petit Prince","original":"et ce ne sera pas vrai","ipa":"/e sə nə səʁa pa vʁɛ/","zh":"其实我不是真的死","en":"and that won't be true","note":"","sourceLineIndex":5},{"id":"le-petit-prince-2cd-46-006","lineIndex":6,"speaker":"Le Petit Prince","original":"Tu comprends","ipa":"/ty kɔ̃pʁɑ̃/","zh":"你知道吧","en":"You understand","note":"","sourceLineIndex":6},{"id":"le-petit-prince-2cd-46-007","lineIndex":7,"speaker":"Le Petit Prince","original":"C'est trop loin","ipa":"/sɛ tʁo lwɛ̃/","zh":"路途太远","en":"It's too far","note":"","sourceLineIndex":7},{"id":"le-petit-prince-2cd-46-008","lineIndex":8,"speaker":"Le Petit Prince","original":"Je ne peux pas emporter ce corps","ipa":"/ʒə nə pø paz ɑ̃pɔʁte sə kɔʁ/","zh":"我拖不动这副躯壳","en":"I can't take this body","note":"","sourceLineIndex":8},{"id":"le-petit-prince-2cd-46-009","lineIndex":9,"speaker":"Le Petit Prince","original":"C'est trop lourd","ipa":"/sɛ tʁo luʁ/","zh":"它太沉了","en":"It's too heavy","note":"","sourceLineIndex":9},{"id":"le-petit-prince-2cd-46-010","lineIndex":10,"speaker":"Le Petit Prince","original":"Mais ce sera comme une vieille écorce que l'on abandonne","ipa":"/mɛ sə səʁa kɔm yn vjɛj ekɔʁs kə lɔ̃n abɑ̃dɔn/","zh":"但那就像一层被抛下的旧壳。","en":"But it will be like an old shell that one leaves behind.","note":"","sourceLineIndex":10},{"id":"le-petit-prince-2cd-46-011","lineIndex":11,"speaker":"L'Aviateur","original":"Je ne te quitterai pas","ipa":"/ʒə nə tə kitʁe pa/","zh":"我不会离开你的","en":"I will not leave you","note":"","sourceLineIndex":11},{"id":"le-petit-prince-2cd-46-012","lineIndex":12,"speaker":"Le Petit Prince","original":"Ce n'est pas triste","ipa":"/sə nɛ pa tʁist/","zh":"这并不可悲","en":"It is not sad","note":"","sourceLineIndex":12},{"id":"le-petit-prince-2cd-46-013","lineIndex":13,"speaker":"Le Petit Prince","original":"les vieilles écorces","ipa":"/le vjɛjz ekɔʁs/","zh":"不过是些旧壳。","en":"the old shells.","note":"","sourceLineIndex":13},{"id":"le-petit-prince-2cd-46-014","lineIndex":14,"speaker":"Le Petit Prince","original":"Ce sera gentil, tu sais","ipa":"/sə səʁa ʒɑ̃ti ty sɛ/","zh":"你知道，那会很美好。","en":"It will be lovely, you know.","note":"","sourceLineIndex":14},{"id":"le-petit-prince-2cd-46-015","lineIndex":15,"speaker":"Le Petit Prince","original":"Moi aussi, je regarderai les étoiles","ipa":"/mwa osi ʒə ʁəɡaʁdəʁe lez etwal/","zh":"以后 我也会仰望星空","en":"Me too, I will look at the stars","note":"","sourceLineIndex":15},{"id":"le-petit-prince-2cd-46-016","lineIndex":16,"speaker":"Le Petit Prince","original":"Toutes les étoiles seront des puits avec une poulie rouillée","ipa":"/tut lez etwal səʁɔ̃ de pyi avɛk yn puli ʁuje/","zh":"所有的星星会变成带有生锈辘轳的井","en":"All the stars will be wells with a rusty pulley","note":"","sourceLineIndex":16},{"id":"le-petit-prince-2cd-46-017","lineIndex":17,"speaker":"Le Petit Prince","original":"Toutes les étoiles me verseront à boire","ipa":"/tut lez etwal mə vɛʁsəʁɔ̃t a bwaʁ/","zh":"所有的星星都会给我倒水喝。","en":"All the stars will pour me water to drink.","note":"","sourceLineIndex":17},{"id":"le-petit-prince-2cd-46-018","lineIndex":18,"speaker":"Le Petit Prince","original":"Ma fleur, j'en suis responsable","ipa":"/ma flœʁ ʒɑ̃ syi ʁɛspɔ̃sabl/","zh":"我的花—我要对她负责。","en":"My flower—I am responsible for her.","note":"","sourceLineIndex":18},{"id":"le-petit-prince-2cd-46-019","lineIndex":19,"speaker":"Le Petit Prince","original":"Elle est tellement faible","ipa":"/ɛl ɛ tɛlmɑ̃ fɛbl/","zh":"她弱不禁风","en":"She is so weak","note":"","sourceLineIndex":19},{"id":"le-petit-prince-2cd-46-020","lineIndex":20,"speaker":"Le Petit Prince","original":"Elle a quatre épines de rien du tout pour la protéger contre le monde","ipa":"/ɛl a katʁ epin də ʁjɛ̃ dy tu puʁ la pʁoteʒe kɔ̃tʁ lə mɔ̃d/","zh":"她只有四根微不足道的刺，用来保护自己、抵御这个世界。","en":"She has only four insignificant thorns to protect herself against the world.","note":"","sourceLineIndex":20},{"id":"le-petit-prince-2cd-46-021","lineIndex":21,"speaker":"Le Petit Prince","original":"Voilà... C'est tout","ipa":"/vwala sɛ tu/","zh":"就这样……全说完了。","en":"There... That is all.","note":"","sourceLineIndex":21}],"sourceOrder":46,"displayOrder":44},{"order":47,"id":"47-le-plus-beau-et-le-plus-triste-paysage-du-monde","title":"Le Plus Beau Et Le Plus Triste Paysage Du Monde","titleZh":"世上最凄美的景象","lines":[{"id":"le-petit-prince-2cd-47-001","lineIndex":1,"speaker":"L'Aviateur","original":"Le plus beau et le plus triste paysage du monde","ipa":"/lə ply bo e lə ply tʁist pɛizaʒ dy mɔ̃d/","zh":"世界上最凄美的景象","en":"The most beautiful and saddest landscape in the world","note":"","sourceLineIndex":1},{"id":"le-petit-prince-2cd-47-002","lineIndex":2,"speaker":"L'Aviateur","original":"C'est celui où il n'est plus","ipa":"/sɛ səlyi u il nɛ ply/","zh":"就在他消失之处","en":"It is the place where he is no more","note":"","sourceLineIndex":2},{"id":"le-petit-prince-2cd-47-003","lineIndex":3,"speaker":"L'Aviateur","original":"Cette lumière qui se perd","ipa":"/sɛt lymjɛʁ ki sə pɛʁ/","zh":"那道消逝的光","en":"That light which vanishes","note":"","sourceLineIndex":3},{"id":"le-petit-prince-2cd-47-004","lineIndex":4,"speaker":"L'Aviateur","original":"En un éclair","ipa":"/ɑ̃n œ̃n eklɛʁ/","zh":"转瞬即逝","en":"In a flash","note":"","sourceLineIndex":4},{"id":"le-petit-prince-2cd-47-005","lineIndex":5,"speaker":"L'Aviateur","original":"L'espace d'une seconde","ipa":"/lɛspas dyn səɡɔ̃d/","zh":"倏忽之间","en":"The space of a second","note":"","sourceLineIndex":5},{"id":"le-petit-prince-2cd-47-006","lineIndex":6,"speaker":"L'Aviateur","original":"Comme quand il est apparu","ipa":"/kɔm kɑ̃t il ɛt apaʁy/","zh":"正如他出现时那样","en":"just as when he appeared","note":"","sourceLineIndex":6},{"id":"le-petit-prince-2cd-47-007","lineIndex":7,"speaker":"L'Aviateur","original":"Mais si un jour","ipa":"/mɛ si œ̃ ʒuʁ/","zh":"倘若有一日","en":"But if one day","note":"","sourceLineIndex":7},{"id":"le-petit-prince-2cd-47-008","lineIndex":8,"speaker":"L'Aviateur","original":"Vos voyages vous emmenaient","ipa":"/vo vwajaʒ vuz ɑ̃mnɛ/","zh":"你们的旅途将你们带到","en":"your travels were to take you","note":"","sourceLineIndex":8},{"id":"le-petit-prince-2cd-47-009","lineIndex":9,"speaker":"L'Aviateur","original":"Dans ce désert","ipa":"/dɑ̃ sə dezɛʁ/","zh":"这片沙漠","en":"In this desert","note":"","sourceLineIndex":9},{"id":"le-petit-prince-2cd-47-010","lineIndex":10,"speaker":"L'Aviateur","original":"Si vous vous trouvez","ipa":"/si vu vu tʁuve/","zh":"要是你们恰好","en":"If you find yourself","note":"","sourceLineIndex":10},{"id":"le-petit-prince-2cd-47-011","lineIndex":11,"speaker":"L'Aviateur","original":"Juste sous l'étoile","ipa":"/ʒyst su letwal/","zh":"就在这颗星下面","en":"Right under the star","note":"","sourceLineIndex":11},{"id":"le-petit-prince-2cd-47-012","lineIndex":12,"speaker":"L'Aviateur","original":"Attendez un peu","ipa":"/atɑ̃dez œ̃ pø/","zh":"请稍待片刻！","en":"Wait a bit","note":"","sourceLineIndex":12},{"id":"le-petit-prince-2cd-47-013","lineIndex":13,"speaker":"L'Aviateur","original":"Si alors un enfant vient à vous","ipa":"/si alɔʁ œ̃n ɑ̃fɑ̃ vjɛ̃ a vu/","zh":"如果有个孩子向你们走来","en":"If then a child comes to you","note":"","sourceLineIndex":13},{"id":"le-petit-prince-2cd-47-014","lineIndex":14,"speaker":"L'Aviateur","original":"S'il a des cheveux d'or","ipa":"/sil a de ʃəvø dɔʁ/","zh":"如果他长着金灿灿的头发","en":"If he has golden hair","note":"","sourceLineIndex":14},{"id":"le-petit-prince-2cd-47-015","lineIndex":15,"speaker":"L'Aviateur","original":"Vous devinerez qui il est","ipa":"/vu dəvinʁe ki il ɛ/","zh":"你们就能猜到他是谁了","en":"You will guess who he is","note":"","sourceLineIndex":15},{"id":"le-petit-prince-2cd-47-016","lineIndex":16,"speaker":"L'Aviateur","original":"Alors soyez gentils","ipa":"/alɔʁ swaje ʒɑ̃ti/","zh":"若果真如此 请你们行行好","en":"So be kind","note":"","sourceLineIndex":16},{"id":"le-petit-prince-2cd-47-017","lineIndex":17,"speaker":"L'Aviateur","original":"Ne me laissez pas tellement triste","ipa":"/nə mə lɛse pa tɛlmɑ̃ tʁist/","zh":"别眼睁睁看我为思念他而悲伤","en":"Don't leave me so sad","note":"","sourceLineIndex":17},{"id":"le-petit-prince-2cd-47-018","lineIndex":18,"speaker":"L'Aviateur","original":"Écrivez-moi vite qu'il est revenu...","ipa":"/ekʁivemwa vit kil ɛ ʁəvny/","zh":"请赶快写信告诉我，他回来了……","en":"Write to me at once to tell me that he has returned...","note":"","sourceLineIndex":18},{"id":"le-petit-prince-2cd-47-019","lineIndex":19,"speaker":"L'Aviateur","original":"Le plus beau et le plus triste paysage du monde","ipa":"/lə ply bo e lə ply tʁist pɛizaʒ dy mɔ̃d/","zh":"世界上最凄美的景象","en":"The most beautiful and saddest landscape in the world","note":"","sourceLineIndex":19},{"id":"le-petit-prince-2cd-47-020","lineIndex":20,"speaker":"L'Aviateur","original":"C'est celui où tu n'es plus...","ipa":"/sɛ səlyi u ty nɛ ply/","zh":"就在你消失之处……","en":"It is the place where you are no more...","note":"","sourceLineIndex":20}],"sourceOrder":47,"displayOrder":45}];
